export default {"1":{"html":"<p>اپنے والدین سے پوچھیں کہ جب وہ آپ کی عمر کے تھے تو اڈلی کی پلیٹ یا ایک لیٹر پیٹرول کی قیمت کیا تھی، اور آپ کو ایک ایسا نمبر سننے کو ملے گا جو آج مذاق لگتا ہے۔ قیمتوں میں اس خاموش، بے لگام اضافے کا ایک نام ہے، <strong>افراط زر</strong>، اور یہ اس کورس کے موجود ہونے کی واحد سب سے اہم وجہ ہے۔ بیٹھا رہ گیا پیسہ اب بھی قدر میں نہیں رہتا۔ یہ آہستہ آہستہ سکڑتا ہے. سرمایہ کاری کرنا سیکھنا صرف اپنا پیسہ بڑھانا سیکھنا ہے۔ <em>تیز تر</em> قیمتوں میں اضافے سے، تاکہ آپ کا مستقبل آپ کے حال سے زیادہ امیر ہو، غریب نہیں۔</p>\n<p>یہ اچھی خبر ہے، اور حیران کن حصہ: آپ کو ایک باصلاحیت ہونے کی ضرورت نہیں ہے، اگلے حادثے کی پیشین گوئی کریں، یا یہ اچھی طرح سے کرنے کے لیے اگلے ملٹی بیگر کو چنیں۔ آپ کو دو غیر مہذب چیزوں کی ضرورت ہے <strong>وقت</strong> اور <strong>صبر</strong>، اور جتنی جلدی آپ شروع کریں گے، آپ کی ضرورت میں سے کسی ایک کی بھی کم ہوگی۔ یہ پہلا باب اس بارے میں ہے۔ <em>کیوں</em>. کورس میں باقی سب کچھ ہے۔ <em>کس طرح</em>.</p>\n<h2 id=\"saving-is-not-the-same-as-investing\">بچت سرمایہ کاری کے مترادف نہیں ہے۔</h2>\n<p>زیادہ تر لوگوں کو سکھایا جاتا ہے۔ <em>محفوظ کریں</em>، خرچ نہ کرنا۔ یہ ایک اچھی عادت ہے، لیکن صرف بچت کرنا ہی آدھا کام ہے۔ ریگولر سیونگ اکاؤنٹ میں رکھی ہوئی رقم سے سالانہ تقریباً 3% کما جاتا ہے، جبکہ قیمتوں میں تقریباً 5-6% سالانہ اضافہ ہوتا ہے۔ لہذا ایک \"محفوظ\" بچت اکاؤنٹ، حقیقی معنوں میں، ایک سست رساو ہے۔</p>\n<ul>\n<li><strong>محفوظ کرنا</strong> پیسے کو الگ کر رہا ہے. یہ روپے کی رقم کی حفاظت کرتا ہے۔</li>\n<li><strong>سرمایہ کاری</strong> اس بچائے ہوئے پیسے کو ڈال رہا ہے۔ <em>کام</em> بڑھنے والے اثاثوں میں۔ یہ روپے کی حفاظت کرتا ہے (اور بڑھتا ہے) <em>قوت خرید</em>.</li>\n</ul>\n<p>فرق چھوٹا لگتا ہے۔ زندگی بھر میں سکریپنگ اور آرام دہ ہونے کے درمیان فرق ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>بچت کرنے سے آپ کی رقم اتنی ہی رقم رہتی ہے۔ سرمایہ کاری کا مقصد یہ ہے کہ وہ روپے اصل میں کیا کر سکتے ہیں، برقرار رکھنا اور بڑھنا ہے۔ <em>خریدیں</em>. مہنگائی کو مارنا اختیاری نہیں ہے۔ یہ پورا نقطہ ہے.</p>\n</div></div>\n<h2 id=\"the-silent-thief-inflation\">خاموش چور: مہنگائی</h2>\n<p>تصور کریں کہ آپ نے سال 2000 میں ایک گدے کے نیچے 1,00,000 روپے رکھے تھے۔ نوٹوں کا نمبر کبھی نہیں بدلا۔ لیکن تقریباً 6 فیصد اوسط مہنگائی پر، وہ 1,00,000 روپے کیا ہو سکتا ہے۔ <em>خریدیں</em> سال بہ سال سکڑتا گیا، یہاں تک کہ تقریباً 25 سال بعد، یہ وہی خریدتا ہے جو اس وقت تقریباً 23,000 روپے میں خریدا گیا تھا۔ آپ نے ایک روپیہ خرچ کیے بغیر اپنی قوت خرید کا تین چوتھائی سے زیادہ کھو دیا۔ وہ کام پر خاموش چور ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch01-inflation-erosion.png\" alt=\"100 روپے کی قوت خرید 25 سالوں میں 6 فیصد مہنگائی پر پگھل گئی، جو 100 روپے آج خریدتا ہے کل اس کی قیمت بہت کم ہے\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">ڈیٹا یعنی</span>100 روپے کی قوت خرید 25 سالوں میں 6% مہنگائی پر پگھل گئی، جو 100 روپے آج خریدتا ہے کل اس کی قیمت بہت کم ہے</figcaption></figure>\n<p>یہی وجہ ہے کہ صرف نقد اور بچت کھاتوں کے ساتھ \"محفوظ طریقے سے کھیلنا\"، متضاد طور پر، ان میں سے ایک ہے۔ <em>سب سے خطرناک</em> وہ چیزیں جو آپ پیسے سے کر سکتے ہیں آپ کو کئی سالوں تک ضرورت نہیں ہوگی۔ خطرہ یہ نہیں ہے کہ نمبر گر جائے، یہ ہے کہ نمبر ساکن رہے جب کہ دنیا زیادہ مہنگی ہو جاتی ہے۔</p>\n<h2 id=\"compounding-the-eighth-wonder\">مرکب: آٹھواں عجوبہ</h2>\n<p>اب وہ جادو جو آپ کے حق میں کام کرتا ہے۔ جب آپ سرمایہ کاری کرتے ہیں تو آپ کو واپسی حاصل ہوتی ہے۔ اگلے سال آپ اپنی اصل رقم پر واپسی حاصل کرتے ہیں۔ <em>پلس</em> گزشتہ سال کی واپسی. سال بعد، اس سب پر دوبارہ۔ آپ کا پیسہ پیسہ کمانے لگتا ہے، جو پیسہ کماتا ہے. اس سنو بال کو کہتے ہیں۔ <strong>مرکب</strong>اور لمبے عرصے تک یہ ایسی چیزیں کرتا ہے جو تقریباً غیر منصفانہ محسوس کرتے ہیں۔</p>\n<p>ایک سادہ، حقیقی دنیا کی عادت پر غور کریں: ایک انڈیکس فنڈ میں ہر ماہ 5,000 روپے کی سرمایہ کاری کرنا جو سال میں تقریباً 12% (Nifty 50 کی طویل مدتی اوسط کے قریب) بنتا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>سال کی سرمایہ کاری</th>\n<th align=\"right\">آپ نے ڈال دیا۔</th>\n<th align=\"right\">یہ بڑھ سکتا ہے (تقریبا)</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>10 سال</td>\n<td align=\"right\">6,00,000 روپے</td>\n<td align=\"right\">11.6 لاکھ روپے</td>\n</tr>\n<tr>\n<td>20 سال</td>\n<td align=\"right\">12,00,000 روپے</td>\n<td align=\"right\">50 لاکھ روپے</td>\n</tr>\n<tr>\n<td>30 سال</td>\n<td align=\"right\">18,00,000 روپے</td>\n<td align=\"right\">1.76 کروڑ روپے</td>\n</tr>\n</tbody></table>\n<p>قریب سے دیکھیں۔ وقت (10 سے 30 سال) کو تین گنا کرنے سے نتیجہ تین گنا نہیں ہوا، اس نے اسے کئی گنا زیادہ کر دیا۔ <em>پندرہ</em> اوقات یہ کمپاؤنڈنگ کا دستخط ہے: طویل ترین سال سب سے زیادہ وزن اٹھاتے ہیں، اور وہ ہمیشہ <em>آخری</em> والے جو اس پورے کورس میں سب سے اہم سبق کی طرف لے جاتا ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch01-compounding-snowball.png\" alt=\"دو دوست، ایک ہی 5000 روپے ماہانہ SIP، جو 25 سے شروع ہوتا ہے وہ 35 سال سے شروع ہونے والے سے دگنا ہوتا ہے، خالصتاً دس سال کے آغاز سے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">ڈیٹا یعنی</span>دو دوست، ایک ہی 5000 روپے ماہانہ SIP، جو 25 سے شروع ہوتا ہے وہ 35 سے شروع ہونے والے سے دگنا ہوتا ہے، خالصتاً دس سال کی شروعات سے۔</figcaption></figure>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>البرٹ آئن سٹائن کو اکثر مرکب سود کہتے ہوئے کہا جاتا ہے \"دنیا کا آٹھواں عجوبہ، جو اسے سمجھتا ہے، وہ اسے کماتا ہے؛ جو نہیں سمجھتا، وہ ادا کرتا ہے۔\" چاہے اس نے واقعی یہ کہا ہو یا نہیں، ہر طویل مدتی سرمایہ کار بالآخر سیکھتا ہے کہ وہ صحیح تھا۔</p>\n</div></div>\n<h2 id=\"start-young-time-beats-timing\">نوجوان شروع کریں: وقت وقت کو دھڑکتا ہے۔</h2>\n<p>دو دوستوں کی تصویر بنائیں۔ <strong>ریا</strong> 25 سال کی عمر میں ماہانہ 5,000 روپے کی سرمایہ کاری شروع کرتی ہے اور 35 سال کی عمر میں، صرف دس سال، مجموعی طور پر 6 لاکھ روپے پر رک جاتی ہے، پھر کبھی ایک اور روپیہ نہیں جوڑتی، جب تک وہ 60 سال کی نہ ہو جائے، اسے جمع ہونے دیتی ہے۔ <strong>آراو</strong> 35 سال تک کچھ نہیں کرتا، پھر اگلے 25 سالوں کے لیے اسی 5,000 روپے ماہانہ لگاتار لگاتا ہے، کل 15 لاکھ روپے۔ 60 کی عمر میں زیادہ سے کون ختم ہوتا ہے؟</p>\n<p>ریا سرمایہ کاری کے باوجود آرام سے کرتی ہے۔ <em>نصف سے کم</em> جتنا پیسہ. اس کا راز مہارت یا قسمت نہیں تھا۔ یہ دس سال کا آغاز تھا جو مرکب سازی کو زیادہ دیر تک چلنے دیتا ہے۔ مارکیٹ میں وقت نے وہ کیا جو ہوشیار وقت کی کوئی مقدار نہیں کر سکتی تھی۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>ایک نوجوان سرمایہ کار کے طور پر آپ کا واحد سب سے بڑا فائدہ ہے۔ <strong>وقت</strong>، ذہانت نہیں۔ 32 کے بجائے 22 سے شروع کرنا ہر اس اسٹاک سے زیادہ اہمیت رکھتا ہے جسے آپ کبھی چنیں گے۔ شروع کرنے کا بہترین دن برسوں پہلے تھا۔ دوسرا بہترین آج ہے.</p>\n</div></div>\n<h2 id=\"why-you-can-t-and-needn-t-predict-the-market\">آپ مارکیٹ کی پیشین گوئی کیوں نہیں کر سکتے (اور ضرورت نہیں)</h2>\n<p>یہ وہ جال ہے جس میں تقریبا ہر ایک ابتدائی آتا ہے: یقین کرنا مقصد ہے۔ <em>پیشن گوئی</em> اگلے ہفتے مارکیٹ کیا کرے گی، نیچے کا اندازہ لگائیں، اور کامل اندراج کا وقت لگائیں۔ رک جاؤ۔ سچی بات تو یہ ہے کہ <strong>کوئی بھی نہیں، فنڈ مینیجرز نہیں، TV ماہرین نہیں، بلند ترین یوٹیوب چینل والا شخص نہیں، قلیل مدتی مارکیٹ کی نقل و حرکت کی قابل اعتماد انداز میں پیش گوئی کر سکتا ہے۔</strong> مارکیٹیں لاکھوں لوگوں کے ذریعہ چلتی ہیں جو ان خبروں پر ردعمل ظاہر کرتے ہیں جو ابھی تک نہیں ہوئی ہیں۔ وہ، مختصر مدت میں، حقیقی طور پر غیر متوقع ہیں۔</p>\n<p>اور خوبصورت حصہ یہ ہے۔ <em>آپ کو کسی بھی چیز کی پیشن گوئی کرنے کی ضرورت نہیں ہے۔</em>. دولت بنانے والا انجن پیش گوئی نہیں کر رہا ہے۔ یہ ہے <strong>اچھے اثاثوں کا مالک ہونا اور اتار چڑھاؤ کے دوران سرمایہ کاری میں رہنا۔</strong> مطالعات بار بار یہ ظاہر کرتے ہیں کہ جو سرمایہ کار اندر اور باہر کودنے کی کوشش کرتے ہیں، خوف کے مارے بیچتے ہیں، لالچ میں خریدتے ہیں، ان لوگوں کو بری طرح سے کم کارکردگی کا مظاہرہ کرتے ہیں جنہوں نے صرف مستقل سرمایہ کاری کرتے رہے اور کچھ نہیں کیا۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>ہر اس شخص سے ہوشیار رہو جو اگلے ہفتے آپ کو بتانے کا وعدہ کرتا ہے کہ مارکیٹ کہاں جا رہی ہے، یا واپسی کی ضمانت دیتا ہے۔ پیشن گوئی اعتماد بیچتی ہے، نتائج نہیں۔ ایک ابتدائی کا کام مارکیٹ کی پیشن گوئی کرنا نہیں ہے، یہ کرنا ہے۔ <em>حصہ لینا</em> اس میں صبر کے ساتھ، مہینے کے بعد اثاثوں کی تعمیر، دہائی کے بعد دہائی. ہم خطرے اور سرمایہ کار کے ذہن کے بعد کے باب میں اس نظم و ضبط کی طرف لوٹتے ہیں۔</p>\n</div></div>\n<h2 id=\"real-returns-the-number-that-actually-matters\">حقیقی واپسی: وہ نمبر جو اصل میں اہمیت رکھتا ہے۔</h2>\n<p>جب کوئی کہتا ہے کہ سرمایہ کاری نے \"9% دیا\"، ہمیشہ پوچھیں: 9% <em>پہلے</em> یا <em>کے بعد</em> مہنگائی؟ سرخی کا اعداد و شمار ہے۔ <strong>برائے نام واپسی</strong>. افراط زر کو گھٹائیں اور آپ کو مل جائے گا۔ <strong>حقیقی واپسی</strong>، صرف وہی جو آپ کی حقیقی قوت خرید کو بڑھاتا ہے۔</p>\n<ul>\n<li>7% پر فکسڈ ڈپازٹ 6% مہنگائی کے ساتھ صرف ~1% کا حقیقی منافع دیتا ہے۔</li>\n<li>اسی افراط زر کے ساتھ اوسطاً ~12% ایکویٹیز ~6% کی حقیقی واپسی دیتی ہیں، چھ گنا زیادہ <em>مفید</em> ترقی، راستے میں اتار چڑھاو کو قبول کرنے کے بدلے میں۔</li>\n</ul>\n<p>وہ تجارت، طویل مدتی حقیقی نمو کے بدلے قلیل مدتی جھڑپوں کو قبول کرنا، اسٹاک میں سرمایہ کاری کا مرکزی سودا ہے۔ چند مہینوں میں، ایکوئٹیز ایک رولر کوسٹر ہیں۔ چند دہائیوں کے دوران، وہ ہندوستان کے سب سے طاقتور دولت بنانے والے ہیں۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch01-asset-returns.png\" alt=\"ہندوستان میں تقریباً طویل مدتی سالانہ منافع، ایکویٹی بمقابلہ گولڈ بمقابلہ فکسڈ ڈپازٹ بمقابلہ بچت کھاتہ، یہ سب 6% افراط زر کی لائن کے خلاف ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">ڈیٹا یعنی</span>ہندوستان میں تقریباً طویل مدتی سالانہ منافع، ایکویٹی بمقابلہ گولڈ بمقابلہ فکسڈ ڈپازٹ بمقابلہ بچت کھاتہ، یہ سب 6% افراط زر کی لائن کے خلاف ہے۔</figcaption></figure>\n<h2 id=\"india-is-investing-like-never-before\">ہندوستان اس طرح سرمایہ کاری کر رہا ہے جس طرح پہلے کبھی نہیں تھا۔</h2>\n<p>یہ اب کوئی طاق تعاقب نہیں ہے۔ بھارت پار کر گیا۔ <strong>21 کروڑ ڈیمیٹ اکاؤنٹس</strong>، اور ماہانہ <strong>SIP میوچل فنڈز میں شراکت 25,000 کروڑ روپے سے زیادہ ہے۔</strong>وہ ریکارڈ جو ٹوٹتے رہتے ہیں۔ نوجوان ہندوستانیوں کی ایک پوری نسل یہ سمجھ چکی ہے کہ صرف تنخواہ سے دولت نہیں بنتی۔ سرمایہ کاری کی بچت کرتے ہیں. آپ بالکل صحیح خیال کے ساتھ بالکل صحیح وقت پر اس شفٹ میں شامل ہو رہے ہیں: جلد شروع کریں، صبر کریں، پیچیدہ کام کرنے دیں۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>اس پورے کورس کے دوران، \"مارکیٹ\" کا مطلب ہندوستانی اسٹاک مارکیٹ، نیشنل اسٹاک ایکسچینج (NSE) اور بمبئی اسٹاک ایکسچینج (BSE) ہے، اور اعداد و شمار روپے اور ہندوستانی مثالوں کا استعمال کرتے ہیں۔ یہاں کچھ بھی نہیں سرمایہ کاری کا مشورہ ہے۔ یہ تعلیم ہے کہ آپ کو یہ سمجھنے میں مدد ملے کہ یہ سب کیسے کام کرتا ہے اور آپ خود باخبر فیصلے کرتے ہیں۔</p>\n</div></div>\n<h2 id=\"quick-recap\">فوری خلاصہ</h2>\n<ul>\n<li><strong>مہنگائی</strong> خاموشی سے بیکار نقدی کی قوت خرید کو ختم کر دیتا ہے، \"محفوظ\" بچت خاموشی سے وقت کے ساتھ قدر کھو دیتی ہے۔</li>\n<li><strong>محفوظ کرنا</strong> روپے محفوظ <strong>سرمایہ کاری</strong> بڑھتا ہے جو وہ روپے خرید سکتے ہیں۔ آپ کو دونوں کی ضرورت ہے۔</li>\n<li><strong>مرکب کرنا</strong> پیسہ پیسہ کماتا ہے، اور اس کا سب سے بڑا فائدہ آخری، طویل ترین سالوں میں آتا ہے۔</li>\n<li><strong>نوجوانی شروع ہو رہی ہے۔</strong> ایک ابتدائی کا سب سے بڑا کنارہ ہے: مارکیٹ میں وقت مارکیٹ کے وقت کو پیچھے چھوڑ دیتا ہے۔</li>\n<li>آپ <strong>پیش گوئی نہیں کر سکتے اور ضرورت نہیں ہے۔</strong> مختصر مدت کے اقدامات، مریض کی شرکت، پیش گوئی نہیں، دولت پیدا کرتی ہے۔</li>\n<li>کی طرف سے جج سرمایہ کاری <strong>حقیقی (مہنگائی کے بعد) واپسی</strong>، اور طویل مدتی نمو کے لیے قلیل مدتی گڑبڑ کو قبول کریں۔</li>\n</ul>\n<p>اگلا، ہم دیکھتے ہیں <em>کہاں</em> آپ اصل میں اپنا پیسہ، اہم اثاثہ کلاسز، ایکویٹی اور قرض سے لے کر گولڈ اور کرپٹو تک رکھ سکتے ہیں، اور کیوں ایکویٹیز نے تاریخی طور پر سب سے زیادہ دولت بنائی ہے۔</p>\n","toc":[{"level":2,"text":"بچت سرمایہ کاری کے مترادف نہیں ہے۔","id":"saving-is-not-the-same-as-investing"},{"level":2,"text":"خاموش چور: مہنگائی","id":"the-silent-thief-inflation"},{"level":2,"text":"مرکب: آٹھواں عجوبہ","id":"compounding-the-eighth-wonder"},{"level":2,"text":"نوجوان شروع کریں: وقت وقت کو دھڑکتا ہے۔","id":"start-young-time-beats-timing"},{"level":2,"text":"آپ مارکیٹ کی پیشین گوئی کیوں نہیں کر سکتے (اور ضرورت نہیں)","id":"why-you-can-t-and-needn-t-predict-the-market"},{"level":2,"text":"حقیقی واپسی: وہ نمبر جو اصل میں اہمیت رکھتا ہے۔","id":"real-returns-the-number-that-actually-matters"},{"level":2,"text":"ہندوستان اس طرح سرمایہ کاری کر رہا ہے جس طرح پہلے کبھی نہیں تھا۔","id":"india-is-investing-like-never-before"},{"level":2,"text":"فوری خلاصہ","id":"quick-recap"}],"imgCount":3,"hasContent":true},"2":{"html":"<p>پیسہ صرف وہاں نہیں بیٹھ سکتا۔ جس لمحے آپ کے پاس کچھ بچت ہوتی ہے، آپ کو ایک خاموش لیکن ناگزیر سوال کا سامنا کرنا پڑتا ہے: <em>اسے کہاں رہنا چاہئے؟</em> ایک بینک اکاؤنٹ، ایک فکسڈ ڈپازٹ، لاکر میں سونا، ایک فلیٹ، چند شیئرز، شاید کرپٹو کا ایک سلور، ہر ایک آپ کے پیسے کے لیے الگ گھر ہے، اس کی اپنی شخصیت ہے۔ کچھ گھر پرسکون اور محفوظ ہیں لیکن بمشکل آپ کے پیسے بڑھتے ہیں۔ دوسرے اسے کئی دہائیوں میں طاقتور طریقے سے اگاتے ہیں لیکن راستے میں اوپر نیچے ہوتے ہیں۔</p>\n<p>ان گھروں کا ایک مناسب نام ہے: <strong>اثاثہ کلاسز</strong>. واقعی میں صرف ایک مٹھی بھر چیزیں ہیں، اور ایک بار جب آپ ان کے درمیان تجارت کو سمجھ لیتے ہیں، تو سرمایہ کاری کی پوری دنیا جوئے بازی کے اڈوں کی طرح نظر آنا بند ہو جاتی ہے اور سمجھدار انتخاب کے سیٹ کی طرح نظر آنا شروع ہو جاتی ہے۔ یہ باب آپ کے علاقے کا نقشہ ہے، ہر اثاثہ کی کلاس کیا ہے، یہ کتنا خطرناک ہے، اس نے تاریخی طور پر کیا واپس کیا ہے، اور کتنی جلدی آپ اسے نقد رقم میں واپس کر سکتے ہیں۔</p>\n<h2 id=\"the-handful-of-homes-for-your-money\">آپ کے پیسے کے لیے مٹھی بھر گھر</h2>\n<p>جرگن کو ہٹا دیں اور تقریبا ہر وہ چیز جس میں آپ سرمایہ کاری کر سکتے ہیں چھ بالٹیوں میں سے ایک میں آتا ہے:</p>\n<ul>\n<li><strong>ایکویٹی (اسٹاک)</strong>، ایک حقیقی کاروبار کی جزوی ملکیت۔ جیسا کہ کاروبار بڑھتا ہے آپ کو فائدہ ہوتا ہے۔</li>\n<li><strong>قرض (FDs اور بانڈز)</strong>، آپ <em>قرض دینا</em> بینک، کمپنی یا حکومت کو پیسے دیں اور بدلے میں مقررہ سود حاصل کریں۔</li>\n<li><strong>سونا</strong>, ایک حقیقی، نایاب دھات لوگوں نے 5,000 سالوں سے بھروسہ کیا ہے۔ ایک ہیج جب باقی سب کچھ ڈوب جاتا ہے۔</li>\n<li><strong>رئیل اسٹیٹ</strong>، زمین اور جائیداد، جو کرایہ کما سکتی ہے اور قیمت میں اضافہ کر سکتی ہے۔</li>\n<li><strong>نقد (اور بچت کھاتوں)</strong>, پیسہ آپ فوری طور پر خرچ کر سکتے ہیں، تقریبا کچھ بھی نہیں کماتے ہیں.</li>\n<li><strong>کرپٹو</strong>ڈیجیٹل اثاثے جیسے بٹ کوائن؛ نیا، بے سرحد، اور جنگلی طور پر غیر مستحکم۔</li>\n</ul>\n<p>یہ پورا مینو ہے۔ فینسیر، میوچل فنڈز، ETFs، انڈیکس فنڈز، بس ایک آسان ہے <em>ٹوکری</em> انہی بلڈنگ بلاکس میں سے۔</p>\n<h2 id=\"the-one-rule-that-explains-everything-risk-vs-return\">ایک اصول جو ہر چیز کی وضاحت کرتا ہے: خطرہ بمقابلہ واپسی۔</h2>\n<p>یہاں سرمایہ کاری کا واحد سب سے اہم خیال ہے، اور یہ اوپر کے ہر اثاثے کو کنٹرول کرتا ہے: <strong>زیادہ ممکنہ واپسی ہمیشہ زیادہ خطرے کے ساتھ بنڈل آتی ہے۔</strong> ایسا کوئی اثاثہ نہیں ہے جو دونوں بالکل محفوظ ہو۔ <em>اور</em> انتہائی فائدہ مند. اگر کوئی آپ کو پیشکش کرتا ہے، تو وہ یا تو غلط ہے یا جھوٹ بول رہا ہے۔</p>\n<p>یہاں \"خطرے\" کا مطلب یہ نہیں ہے کہ \"آپ یقینی طور پر پیسے کھو دیں گے۔\" اس کا مطلب ہے۔ <em>بے یقینی</em>, قدر کتنا اچھالتی ہے، اور نتائج کی حد کتنی وسیع ہے۔ فکسڈ ڈپازٹ کی ایک چھوٹی سی حد ہوتی ہے (آپ تقریباً جانتے ہیں کہ آپ کو کیا ملے گا)۔ ایکویٹی ایک سال کے دوران بہت بڑی رینج رکھتی ہے (یہ 30% بڑھ سکتی ہے یا 20% گر سکتی ہے) لیکن ایک دہائی کے دوران اس سے کہیں زیادہ تنگ، بہت زیادہ رینج ہے۔</p>\n<p>اثاثوں کی کلاسوں کی تصویر سیڑھی پر لگے ہوئے ہیں۔ سب سے نچلے حصے پرسکون اور محفوظ ہیں لیکن اپنے پیسے کو آہستہ آہستہ بڑھائیں۔ اوپر چڑھنا اور ممکنہ انعام دونوں <em>اور</em> گڑبڑ ایک ساتھ بڑھ جاتی ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch02-risk-return-ladder.png\" alt=\"خطرے کی واپسی کی سیڑھی، نچلے حصے میں محفوظ، سست نقدی سے لے کر اعلیٰ واپسی، اعلیٰ اتار چڑھاؤ والی ایکویٹی اور اوپری حصے میں کرپٹو؛ انعام اور خطرہ ایک ساتھ بڑھتے ہیں، ایک دوسرے کے ساتھ\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>خطرے کی واپسی کی سیڑھی، نچلے حصے میں محفوظ، سست نقدی سے لے کر اعلیٰ واپسی، اعلیٰ اتار چڑھاؤ والی ایکویٹی اور اوپری حصے میں کرپٹو؛ انعام اور خطرہ ایک ساتھ بڑھتے ہیں، ایک دوسرے کے ساتھ</figcaption></figure>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>سرمایہ کاری میں کوئی مفت لنچ نہیں ہے۔ متوقع واپسی کا ہر اضافی روپیہ خطرے کے اضافی یونٹ کے ساتھ ادا کیا جاتا ہے۔ مہارت خطرے سے گریز نہیں کر رہی ہے، یہ لے رہی ہے۔ <em>صحیح رقم</em> آپ کے اہداف اور آپ کی ٹائم لائن کے لیے خطرہ۔</p>\n</div></div>\n<h2 id=\"liquidity-how-fast-can-you-get-your-cash-back\">لیکویڈیٹی: آپ کتنی تیزی سے اپنا کیش واپس حاصل کر سکتے ہیں؟</h2>\n<p>واپسی اور خطرہ صرف وہی چیزیں نہیں ہیں جو مختلف ہیں۔ <strong>لیکویڈیٹی</strong>، آپ کتنی جلدی اور سستے طریقے سے کسی اثاثے کو قابل خرچ نقدی میں تبدیل کر سکتے ہیں، اتنا ہی اہم ہے، خاص طور پر ہنگامی صورت حال میں۔</p>\n<ul>\n<li><strong>کیش</strong> بالکل مائع ہے، یہ <em>ہے</em> نقد</li>\n<li><strong>اسٹاکس</strong> انتہائی مائع ہوتے ہیں، بازار کے اوقات میں فروخت ہوتے ہیں اور رقم ایک یا دو دن میں آپ کے بینک تک پہنچ جاتی ہے۔</li>\n<li><strong>گولڈ ای ٹی ایف اور ایف ڈی</strong> کافی مائع ہیں؛ جسمانی سونے کو خریدار اور قیمت پر بال کٹوانے کی ضرورت ہے۔</li>\n<li><strong>رئیل اسٹیٹ</strong> سب سے کم مائع ہے، فلیٹ بیچنے میں مہینوں اور بھاری کاغذی کارروائی لگ سکتی ہے۔</li>\n</ul>\n<p>اگر آپ کو اچانک ضرورت پڑنے پر آپ کا پیسہ کسی پراپرٹی میں بند ہو تو ایک اعلی واپسی ٹھنڈا سکون ہے۔ یہی وجہ ہے کہ آپ کی <em>ہنگامی فنڈ</em> ہمیشہ نقد یا مائع کے اختیارات میں بیٹھتا ہے، جائیداد میں کبھی نہیں.</p>\n<h2 id=\"a-one-line-note-on-tax\">ٹیکس پر ایک سطری نوٹ</h2>\n<p>ٹیکس خاموشی سے ہر ریٹرن میں کھاتا ہے، اور یہ اثاثے کے لحاظ سے مختلف ہوتا ہے (قواعد تخمینی ہیں اور ہر بجٹ کے ساتھ تبدیل ہوتے ہیں):</p>\n<table>\n<thead>\n<tr>\n<th>اثاثہ</th>\n<th>حاصلات پر ٹیکس کیسے لگایا جاتا ہے (تقریباً، ہندوستان)</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>ایکویٹی / ایکویٹی فنڈز</td>\n<td>12.5% ​​طویل مدتی (1 سال سے زیادہ، 1.25 لاکھ روپے سے زیادہ)؛ 20% قلیل مدتی</td>\n</tr>\n<tr>\n<td>ایف ڈیز/ڈیٹ فنڈز</td>\n<td>آپ کی آمدنی میں شامل، آپ کے سلیب کی شرح پر ٹیکس</td>\n</tr>\n<tr>\n<td>گولڈ ( ETF/funds)</td>\n<td>24 ماہ کے انعقاد کے بعد 12.5% ​​طویل مدتی</td>\n</tr>\n<tr>\n<td>رئیل اسٹیٹ</td>\n<td>24 ماہ کے بعد 12.5% ​​طویل مدتی</td>\n</tr>\n<tr>\n<td>کرپٹو</td>\n<td>فلیٹ <strong>30%</strong> فوائد پر، نیز 1% TDS، بغیر کسی نقصان کے سیٹ آف</td>\n</tr>\n</tbody></table>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>ہندوستان میں کرپٹو پر تقریباً کسی بھی دوسرے اثاثے کے مقابلے میں زیادہ سختی سے ٹیکس لگایا جاتا ہے: ہر منافع پر 30% فلیٹ، ہر فروخت پر منبع پر 1% ٹیکس کٹوتی، اور منفرد طور پر، آپ اپنے کریپٹو کو آفسیٹ نہیں کر سکتے۔ <em>نقصانات</em> آپ کے کرپٹو کے خلاف <em>فوائد</em>. ٹیکس دینے والا آپ کے منافع میں شریک ہے لیکن آپ کا درد نہیں۔</p>\n</div></div>\n<h2 id=\"the-big-comparison-side-by-side\">بڑا موازنہ، شانہ بہ شانہ</h2>\n<p>اب یہ سب ایک ساتھ ڈال دیں۔ نیچے دی گئی جدول اس باب کا دل ہے، اسے اپنی دیوار پر لگائیں۔ (واپسی طویل مدتی ہیں۔ <em>تاریخی</em> روپے میں اوسط، تخمینی ہیں، اور کبھی ضمانت نہیں دی جاتی۔)</p>\n<table>\n<thead>\n<tr>\n<th>اثاثہ کلاس</th>\n<th>عام خطرہ</th>\n<th>عام طویل مدتی واپسی (تقریباً)</th>\n<th>لیکویڈیٹی</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>نقد / بچت</td>\n<td>بہت کم</td>\n<td>3-4%</td>\n<td>فوری</td>\n</tr>\n<tr>\n<td>قرض (FDs، بانڈز)</td>\n<td>کم</td>\n<td>6-7%</td>\n<td>متوسط ​​اعلیٰ</td>\n</tr>\n<tr>\n<td>سونا</td>\n<td>درمیانہ</td>\n<td>8-10%</td>\n<td>متوسط ​​اعلیٰ</td>\n</tr>\n<tr>\n<td>رئیل اسٹیٹ</td>\n<td>متوسط ​​اعلیٰ</td>\n<td>7-9% (کرائے کے علاوہ)</td>\n<td>بہت کم</td>\n</tr>\n<tr>\n<td>ایکویٹی (اسٹاک)</td>\n<td>اعلی (مختصر مدت)</td>\n<td>~12%</td>\n<td>اعلی</td>\n</tr>\n<tr>\n<td>کرپٹو</td>\n<td>بہت اعلیٰ</td>\n<td>نامعلوم، انتہائی جھولے۔</td>\n<td>اعلی</td>\n</tr>\n</tbody></table>\n<p>ایکویٹی قطار کو غور سے پڑھیں۔ یہ سب سے زیادہ اٹھاتا ہے۔ <em>مختصر مدت</em> خطرے کے باوجود سب سے زیادہ طویل مدتی واپسی، اور یہ بالکل وہی سودا ہے جس سے ہم نے باب 1 میں ملاقات کی تھی: مہینوں میں ہونے والے ٹکراؤ کو قبول کریں، اور ایکویٹی نے آپ کو کئی دہائیوں کے دوران تاریخی طور پر سب سے زیادہ انعام دیا ہے۔</p>\n<h2 id=\"why-equity-has-built-the-most-wealth\">ایکویٹی نے سب سے زیادہ دولت کیوں بنائی ہے۔</h2>\n<p>طویل عرصے کے دوران، کوئی بھی مرکزی دھارے کا ہندوستانی اثاثہ ایکویٹی سے مماثل نہیں ہے۔ وجہ سادہ اور طاقتور ہے: جب آپ اسٹاک کے مالک ہوتے ہیں، تو آپ کے پاس ایک ٹکڑا ہوتا ہے۔ <em>رہنا، بڑھتا ہوا کاروبار</em> جو اپنے منافع کی دوبارہ سرمایہ کاری کرتا ہے، پھیلتا ہے، مہنگائی کے ساتھ قیمتوں میں اضافہ کرتا ہے، اور سال بہ سال اپنی کمائی کو مرکب کرتا ہے۔ سونا صرف ایک والٹ میں بیٹھتا ہے۔ ایک اچھی کمپنی <em>کام کرتا ہے</em> آپ کے لیے</p>\n<p>اس کا ثبوت ہیڈ لائن انڈیکس میں ہی موجود ہے۔ BSE سینسیکس 1979 میں 100 کی بنیادی قیمت سے شروع ہوا۔ آج یہ 76,000-77,000 کے قریب تجارت کرتا ہے۔ ایک فلیٹ جس کی قیمت 1979 میں چند لاکھ تھی اس سے کہیں زیادہ نہیں بڑھی۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch02-asset-returns.png\" alt=\"ہندوستان میں اثاثہ طبقے کے لحاظ سے تقریباً طویل مدتی سالانہ منافع، ایکویٹی لیڈنگ، پھر سونا اور رئیل اسٹیٹ، قرض اور نقدی کے پیچھے مہنگائی کے ساتھ\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">ڈیٹا یعنی</span>ہندوستان میں اثاثہ طبقے کے لحاظ سے تقریباً طویل مدتی سالانہ منافع، ایکویٹی لیڈنگ، پھر سونا اور رئیل اسٹیٹ، قرض اور نقدی کے پیچھے مہنگائی کے ساتھ</figcaption></figure>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>1979 میں 100 کی بنیاد سے آج تقریباً 77,000 تک، سینسیکس تقریباً کئی گنا بڑھ چکا ہے۔ <strong>770 مرتبہ</strong> تقریبا 45 سالوں میں. یہ کاروبار کے مالک ہونے اور انہیں کمپاؤنڈ کرنے کی خاموش طاقت ہے، جس طرح کی ترقی سونے سے بھرے کسی لاکر نے کبھی نہیں کی ہے۔</p>\n</div></div>\n<h2 id=\"the-recent-picture-gold-s-golden-run-and-crypto-s-wild-ride\">حالیہ تصویر: سونے کی سنہری دوڑ اور کرپٹو کی جنگلی سواری۔</h2>\n<p>سرمایہ کاری میوزیم نہیں ہے، اثاثہ جات کی کلاسز زندہ اور متحرک ہیں، اور پچھلے دو سال ڈرامائی رہے ہیں۔</p>\n<p><strong>سونا</strong> ایک شاندار دوڑ رہا ہے. 2024 میں اس میں تقریباً 27 فیصد کا اضافہ ہوا اور 2025 تک مزید اضافہ ہوا، ریکارڈ کے بعد ریکارڈ توڑتے ہوئے، MCX سونا 1,23,000 روپے فی 10 گرام سے تجاوز کر گیا، اور بین الاقوامی سطح پر سونا تاریخ میں پہلی بار $4,000 فی اونس سے تجاوز کر گیا۔ ڈرائیورز: عالمی غیر یقینی صورتحال، جنگیں، اور دنیا بھر کے مرکزی بینک US ڈالر پر کم جھکاؤ رکھنے کے لیے سونا خرید رہے ہیں۔ پورٹ فولیو میں سونے کا کام بالکل ایسا ہی ہوتا ہے، جب گھبراہٹ بڑھ جاتی ہے تو چمکنا۔</p>\n<p>نوٹ کرنے کے لئے ایک تبدیلی: مقبول <strong>خودمختار گولڈ بانڈز (SGBs)</strong>، سرکاری بانڈز جو سونے کی قیمت کو ٹریک کرتے ہیں۔ <em>اور</em> 2.5٪ سالانہ سود ادا کیا، 2025 کے بجٹ میں بند کر دیا گیا، کوئی نئی قسط جاری نہیں کی گئی۔ وہ سرمایہ کار جو پہلے سے انہیں رکھتے ہیں میچورٹی تک سود حاصل کرتے رہتے ہیں، لیکن نئے خریداروں کو اب اس کی بجائے گولڈ ETFs یا گولڈ فنڈز استعمال کرنا ہوں گے۔</p>\n<p><strong>کرپٹو</strong>, دریں اثنا، سیڑھی پر سب سے جنگلی دھڑا بنی ہوئی ہے۔ Bitcoin ایک دن میں 10% جھول سکتا ہے اور ماضی کے چکروں میں، ٹھیک ہونے سے پہلے اپنی چوٹیوں سے 70%+ گر چکا ہے۔ یہ کوئی منافع پیدا نہیں کرتا، کوئی منافع نہیں دیتا، اور اس کا کوئی طویل مدتی ٹریک ریکارڈ نہیں ہے، اس لیے اسے ایک چھوٹی، قیاس آرائی پر مبنی ٹکڑا سمجھیں جسے آپ کھونے کے متحمل ہوسکتے ہیں، کبھی بھی آپ کی دولت کی بنیاد نہیں۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>ایک عام ابتدائی غلطی جو بھی پچھلے سال سب سے زیادہ گلاب کا پیچھا کرتی ہے۔ گولڈ کی 2024-25 کی بڑی دوڑ دوبارہ دہرانے کی ضمانت نہیں دیتی، بالکل اسی طرح جیسے کرپٹو کی ماضی کی ریلیوں کے بعد وحشیانہ کریش ہوئے۔ ماضی کی کارکردگی ایک کہانی ہے، وعدہ نہیں۔ تازہ ترین فاتح کے بعد سپرنٹنگ کے بجائے تنوع پیدا کریں۔</p>\n</div></div>\n<h2 id=\"building-a-simple-mix\">ایک سادہ مرکب بنانا</h2>\n<p>آپ کو اپنے تمام پیسوں کے لیے ایک گھر لینے کی ضرورت نہیں ہے، درحقیقت، آپ کو ایسا نہیں کرنا چاہیے۔ اثاثوں کی کلاسوں میں پیسہ پھیلانا کہا جاتا ہے۔ <strong>اثاثوں کی تقسیم</strong>، اور یہ آپ کی سیٹ بیلٹ ہے: جب ایک زگ لگاتا ہے تو دوسرا اکثر زگ جاتا ہے۔ ایک عام، سمجھدار سٹارٹنگ فریم ورک (ایک مثال، مشورہ نہیں) آپ کے ایکویٹی شیئر کو آپ کی ٹائم لائن سے جوڑتا ہے، جب تک آپ کو پیسے کی ضرورت نہ ہو، آپ اتنی ہی زیادہ ایکویٹی کو پیٹ سکتے ہیں۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch02-simple-mix.png\" alt=\"ایک سادہ مثالی اثاثہ مکس، طویل مدتی نمو کے لیے ایک بڑی ایکویٹی سلائس، استحکام کے لیے قرض کا کشن، اور سونے کا ایک چھوٹا ہیج، نقد میں ایک اچھوتا ہنگامی فنڈ کے ساتھ\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">انفوگرافک</span>ایک سادہ مثالی اثاثہ مکس، طویل مدتی نمو کے لیے ایک بڑی ایکویٹی سلائس، استحکام کے لیے قرض کا کشن، اور سونے کا ایک چھوٹا ہیج، نقد میں ایک اچھوتا ہنگامی فنڈ کے ساتھ</figcaption></figure>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>انگوٹھے کا ایک کلاسک اصول کہتا ہے کہ ایکویٹی میں تقریبا \"(100 مائنس آپ کی عمر)٪\" رکھیں، لہذا ایک 25 سالہ نوجوان ایکویٹی میں ~ 75٪ رکھ سکتا ہے، باقی قرض میں اور تھوڑا سا سونا۔ یہ صرف ایک نقطہ آغاز ہے، کوئی قانون نہیں، لیکن یہ صحیح جبلت کو حاصل کرتا ہے: نوجوان، وقت کے ساتھ ساتھ، ایکویٹی کی لہروں پر سوار ہونے کے متحمل ہوسکتے ہیں۔</p>\n</div></div>\n<p>درست فیصد عادت سے بہت کم اہمیت رکھتے ہیں: ایمرجنسی فنڈ کو نقد میں رکھیں، طویل مدتی ترقی کے لیے ایکویٹی پر انحصار کریں، استحکام کے لیے کچھ قرض رکھیں، اور بیمہ کے طور پر تھوڑا سا سونا شامل کریں۔</p>\n<h2 id=\"quick-recap\">فوری خلاصہ</h2>\n<ul>\n<li>آپ کا پیسہ رہتا ہے۔ <strong>اثاثہ کلاسز</strong>، ایکویٹی، قرض، سونا، رئیل اسٹیٹ، نقد اور کرپٹو، ہر ایک کی اپنی شخصیت۔</li>\n<li>ماسٹر رول ہے۔ <strong>خطرہ بمقابلہ واپسی</strong>: اعلی ممکنہ انعام ہمیشہ زیادہ خطرے کے ساتھ ساتھ سوار ہوتا ہے۔ مفت دوپہر کا کھانا نہیں ہے۔</li>\n<li><strong>لیکویڈیٹی</strong> فیصلہ کرتا ہے کہ آپ کتنی تیزی سے کیش بیک حاصل کر سکتے ہیں، اسٹاک اور ایف ڈی فوری ہیں، رئیل اسٹیٹ سست ہے؛ ہنگامی صورتحال کو نقد رقم میں رکھیں۔</li>\n<li><strong>ایکویٹی</strong> سب سے زیادہ قلیل مدتی گڑبڑ ہے لیکن تاریخی طور پر سب سے زیادہ دولت بنائی ہے، کیونکہ آپ بڑھتے ہوئے کاروبار کے مالک ہیں۔</li>\n<li><strong>سونا</strong> ایک محفوظ پناہ گاہ کے طور پر 2024-25 کا ریکارڈ تھا (نوٹ: SGBs اب بند ہو چکے ہیں)، جبکہ <strong>کرپٹو</strong> انتہائی غیر مستحکم رہتا ہے اور اس پر فلیٹ 30% ٹیکس لگایا جاتا ہے۔</li>\n<li><strong>اثاثوں کی تقسیم</strong>کلاسوں میں سمجھداری سے پیسے پھیلانا، آپ کی سیٹ بیلٹ ہے۔ عادت صحیح فیصد سے زیادہ اہمیت رکھتی ہے۔</li>\n</ul>\n<p>اب جب کہ آپ جانتے ہیں۔ <em>کہاں</em> پیسہ بڑھ سکتا ہے، آئیے ہم سب کے سب سے طاقتور گھر، اسٹاک مارکیٹ میں زوم کریں، اور سب سے بنیادی سوال کا جواب دیں: کیا <em>ہے</em> ایک حصہ، واقعی؟</p>\n","toc":[{"level":2,"text":"آپ کے پیسے کے لیے مٹھی بھر گھر","id":"the-handful-of-homes-for-your-money"},{"level":2,"text":"ایک اصول جو ہر چیز کی وضاحت کرتا ہے: خطرہ بمقابلہ واپسی۔","id":"the-one-rule-that-explains-everything-risk-vs-return"},{"level":2,"text":"لیکویڈیٹی: آپ کتنی تیزی سے اپنا کیش واپس حاصل کر سکتے ہیں؟","id":"liquidity-how-fast-can-you-get-your-cash-back"},{"level":2,"text":"ٹیکس پر ایک سطری نوٹ","id":"a-one-line-note-on-tax"},{"level":2,"text":"بڑا موازنہ، شانہ بہ شانہ","id":"the-big-comparison-side-by-side"},{"level":2,"text":"ایکویٹی نے سب سے زیادہ دولت کیوں بنائی ہے۔","id":"why-equity-has-built-the-most-wealth"},{"level":2,"text":"حالیہ تصویر: سونے کی سنہری دوڑ اور کرپٹو کی جنگلی سواری۔","id":"the-recent-picture-gold-s-golden-run-and-crypto-s-wild-ride"},{"level":2,"text":"ایک سادہ مرکب بنانا","id":"building-a-simple-mix"},{"level":2,"text":"فوری خلاصہ","id":"quick-recap"}],"imgCount":3,"hasContent":true},"3":{"html":"<p>جب آپ ریلائنس یا TCS کا حصہ خریدتے ہیں، تو یہ تصور کرنا آسان ہے کہ آپ اسکرین پر ایک چمکتا ہوا نمبر خرید رہے ہیں، ایک قسم کی لاٹری ٹکٹ جس کی آپ کو امید ہے کہ بڑھ جائے گی۔ وہ ذہنی تصویر تقریباً ہر ابتدائی غلطی کی جڑ ہے۔ سچائی کہیں زیادہ بنیاد پر ہے اور کہیں زیادہ یقین دہانی کراتی ہے: ایک حصہ ایک حقیقی، قانونی ہے۔ <strong>ایک حقیقی کاروبار میں ملکیت کا ٹکڑا</strong>. ریلائنس کے ایک حصے کے مالک ہیں اور آپ، بالکل لفظی طور پر، ریفائنریز، پیٹرول پمپس، جیو نیٹ ورک اور ریلائنس ریٹیل اسٹورز کے ایک حصے کے مالک ہیں، ایک چھوٹے سے مالک ہیں، لیکن ایک حقیقی۔</p>\n<p>اس پر کلک کرنے کے بعد، سٹاک مارکیٹ جوئے کا ایک پراسرار اڈہ بننا بند کر دیتی ہے اور ایسی چیز بن جاتی ہے جسے آپ پہلے ہی سمجھتے ہیں: ایک ایسا بازار جہاں لوگ کمپنیوں کی ملکیت خریدتے اور بیچتے ہیں۔ یہ باب پوری چیز کو بے نقاب کرتا ہے، اصل میں آپ کی ملکیت کیا ہے، کمپنیاں پہلے اپنے ٹکڑے کیوں فروخت کرتی ہیں، اور مارکیٹ کو کس طرح تار تار کیا جاتا ہے تاکہ لاکھوں اجنبی ہر سیکنڈ میں ان ٹکڑوں کی تجارت کر سکیں۔</p>\n<h2 id=\"a-share-is-a-slice-of-ownership\">ایک حصہ ملکیت کا ایک ٹکڑا ہے۔</h2>\n<p>تصور کریں کہ ایک کمپنی ایک بڑا پیزا ہے۔ پیسہ اکٹھا کرنے کے لیے، بانیوں نے اس پیزا کو ایک مقررہ تعداد میں ایک جیسی ٹکڑوں میں کاٹا اور ان میں سے کچھ کو عوام کو بیچ دیا۔ ہر ایک ٹکڑا a <strong>شیئر کریں</strong>، اور سلائسوں کی کل تعداد کمپنی کی ہے۔ <strong>بقایا حصص</strong>. ایک ٹکڑا خریدیں اور آپ کے اس حصے کے مالک ہیں۔ <em>پوری</em> کاروبار، اس کی فیکٹریاں، اس کا برانڈ، اس کا نقد، اس کا مستقبل کا منافع۔</p>\n<p>اگر کسی کمپنی نے 100 کروڑ حصص جاری کیے ہیں اور آپ ان میں سے 100 کے مالک ہیں، تو آپ کمپنی کی ہر چیز کے دس لاکھویں حصے کے مالک ہیں اور کبھی بھی کمائے گی۔ یہ چھوٹا لگتا ہے، لیکن ریلائنس جیسی کمپنی کے لیے، جس کی مالیت 15 لاکھ کروڑ روپے سے زیادہ ہے، یہاں تک کہ ایک سلور بھی حقیقی، کام کرنے والے ادارے سے منسلک حقیقی قدر کی نمائندگی کرتا ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch03-company-slices.png\" alt=\"ایک ہی کمپنی کو کئی حصص میں کاٹ دیا گیا، ہر ایک حصہ مختلف شیئر ہولڈر، بانیوں، بڑے اداروں اور عام خوردہ سرمایہ کاروں کے پاس ہے جو ایک ہی کاروبار کے ٹکڑوں کے مالک ہیں۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>ایک ہی کمپنی کو کئی حصص میں کاٹ دیا گیا، ہر ایک حصہ مختلف شیئر ہولڈر، بانیوں، بڑے اداروں اور عام خوردہ سرمایہ کاروں کے پاس ہے جو ایک ہی کاروبار کے ٹکڑوں کے مالک ہیں۔</figcaption></figure>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>ایک حصہ بیٹنگ پرچی نہیں ہے۔ یہ کمپنی کی جزوی ملکیت ہے۔ قیمت اوپر اور نیچے ہوتی ہے، لیکن ہر ٹکر کے نیچے ملازمین، مصنوعات، گاہکوں اور منافع کے ساتھ ایک حقیقی کاروبار ہوتا ہے۔ آپ کسی نمبر پر شرط نہیں لگا رہے ہیں، آپ ایک انٹرپرائز کے ایک ٹکڑے کے مالک ہیں۔</p>\n</div></div>\n<h2 id=\"what-you-actually-own\">جو آپ اصل میں مالک ہیں۔</h2>\n<p>ایک حصہ کا مالک ہونا، a <strong>شیئر ہولڈر</strong>, تین ٹھوس چیزوں کے ساتھ آتا ہے، نہ صرف ایک عدد جو ہلتا ​​ہے۔</p>\n<ul>\n<li><strong>منافع پر دعویٰ۔</strong> جب کوئی کمپنی پیسہ کماتی ہے، تو وہ ان منافع کا ایک حصہ مالکان کو واپس دے سکتی ہے۔ <strong>ڈیویڈنڈ</strong>, نقد فی حصص ادا کیا جاتا ہے، صرف اس کی ملکیت کے لیے۔ ایک کمپنی جو منافع میں 8 روپے فی شیئر ادا کرتی ہے وہ آپ کو 800 روپے بھیجتی ہے اگر آپ کے پاس 100 حصص ہیں، قیمت میں جیت یا ہار۔</li>\n<li><strong>کمپنی کی قیمت پر دعویٰ۔</strong> آپ کے حصص ہر اس چیز کے ایک حصے کی نمائندگی کرتے ہیں جو کمپنی اپنے قرضوں کے بعد مالک ہے۔ جیسا کہ کاروبار زیادہ قیمتی ہوتا ہے، اسی طرح آپ کا ٹکڑا بھی بڑھتا ہے۔</li>\n<li><strong>ووٹنگ کے حقوق۔</strong> شیئر ہولڈرز بڑے فیصلوں، ڈائریکٹرز کو منتخب کرنے، انضمام کی منظوری، بڑے پے پیکجز، عام طور پر فی شیئر ایک ووٹ پر ووٹ دیتے ہیں۔ کچھ شیئرز کے مالک ہیں اور آپ کا ووٹ چھوٹا ہے، لیکن یہ حقیقی ہے، اور آپ کو کمپنی کی سالانہ جنرل میٹنگ ( AGM) میں ووٹ دینے کے لیے نوٹس موصول ہوں گے۔</li>\n</ul>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>یہاں تک کہ ایک حصہ کا مالک ہونا آپ کو ایک باضابطہ شریک مالک بناتا ہے جس میں ارب پتی سرمایہ کاروں کی طرح، اسی کمرے میں، اسی قانونی بنیادوں پر، AGM میں شرکت کرنے اور انتظامیہ سے سوال کرنے کا حق ہے۔ ریلائنس انڈسٹریز کے 35 لاکھ سے زیادہ انفرادی شیئر ہولڈرز ہیں۔ ایک حصہ کے ساتھ ایک اسکول کا طالب علم، کاغذ پر، اتنا ہی مالک ہے جتنا کہ ان میں سے کوئی بھی۔</p>\n</div></div>\n<h2 id=\"why-companies-sell-pieces-of-themselves\">کمپنیاں خود کے ٹکڑے کیوں بیچتی ہیں۔</h2>\n<p>یہاں فطری سوال پیدا ہوتا ہے: اگر کوئی کاروبار اچھا ہے تو اس کے بانی اجنبیوں کو ملکیت کیوں بیچیں گے؟ جواب ہے <strong>بڑھنے کے لئے پیسہ</strong>.</p>\n<p>فرض کریں کہ کوئی کمپنی 500 کروڑ روپے کی لاگت سے ایک نئی فیکٹری بنانا چاہتی ہے۔ اس رقم کو اکٹھا کرنے کے دو طریقے ہیں:</p>\n<ol>\n<li><strong>اسے (قرض) ادھار لینا۔</strong> قرض لیں اور سود کے ساتھ واپس کریں، چاہے کاروبار اچھا ہو یا برا۔ ادائیگیوں میں کمی اور قرض دہندہ کمپنی کو دیوالیہ پن کی طرف لے جا سکتا ہے۔ قرض ایک بھاری، مقررہ ذمہ داری ہے۔</li>\n<li><strong>ملکیت بیچیں (ایکویٹی)۔</strong> نئے حصص جاری کریں اور انہیں سرمایہ کاروں کو فروخت کریں۔ کمپنی کو نقد رقم ملتی ہے اور اسے کبھی واپس نہیں کرنا پڑتا ہے۔ بدلے میں، نئے شیئر ہولڈرز کاروبار کے ایک حصے کے مالک ہوتے ہیں اور اس کے مستقبل کے منافع میں حصہ لیتے ہیں۔</li>\n</ol>\n<p>ایکویٹی خاص طور پر طاقتور ہے کیونکہ یہ ہے۔ <em>نہیں</em> ایک قرض کوئی سود نہیں ہے، ادائیگی کی آخری تاریخ نہیں ہے، ڈیفالٹ کا کوئی خطرہ نہیں ہے۔ کمپنی صرف نئے شریک مالکان سے مقابلہ کرتی ہے جو جیتنے پر جیت جاتے ہیں۔ یہی وجہ ہے کہ تقریباً ہر بڑی کمپنی جو آپ جانتے ہیں، انفوسس سے لے کر زوماٹو تک، آخرکار ایکویٹی بیچ کر پیسہ اکٹھا کرتی ہے۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>ایکویٹی بیچنے کی قیمت ہوتی ہے: <strong>کم کرنا</strong>. جاری کردہ ہر نئے شیئر کا مطلب ہے کہ پیزا کا موجودہ مالکان کا ٹکڑا تھوڑا پتلا ہو جاتا ہے۔ بانی اسے قبول کرتے ہیں کیونکہ ایک بہت بڑی، تیزی سے ترقی کرنے والی کمپنی کے چھوٹے ٹکڑے کا مالک ہونا ایک چھوٹے سے بڑے ٹکڑے سے زیادہ قیمتی ہے۔</p>\n</div></div>\n<h2 id=\"primary-market-vs-secondary-market\">پرائمری مارکیٹ بمقابلہ سیکنڈری مارکیٹ</h2>\n<p>یہ وہ جگہ ہے جہاں زیادہ تر ابتدائی لوگ الجھن میں پڑ جاتے ہیں، لہذا آئیے اسے آسان بنائیں۔ دو الگ الگ مراحل ہیں، اور ان کو ملانا آسان ہے۔</p>\n<p>دی <strong>بنیادی مارکیٹ</strong> جہاں حصص ہیں۔ <em>پیدا ہوا</em>. کمپنی خود بالکل نئے حصص براہ راست سرمایہ کاروں کو فروخت کرتی ہے اور پیسے جیب میں ڈالتی ہے۔ کلاسیکی مثال ایک ہے۔ <strong>IPO (ابتدائی عوامی پیشکش)</strong>، پہلی بار جب کوئی کمپنی اپنے حصص عوام کو پیش کرتی ہے۔ پرائمری مارکیٹ میں کیش بہتا ہے۔ <em>کمپنی کو</em> اور کاروبار کو بڑھانے کے لیے استعمال کیا جاتا ہے۔</p>\n<p>دی <strong>ثانوی مارکیٹ</strong> وہ جگہ ہے جہاں وہ موجودہ حصص ہیں۔ <em>تجارت کی</em> اس کے بعد، سرمایہ کار سے سرمایہ کار۔ یہ وہ اسٹاک ایکسچینج ہے جو آپ خبروں میں دیکھتے ہیں۔ جب آپ آج TCS کے 10 حصص خریدتے ہیں، تو آپ ہیں۔ <em>نہیں</em> TCS کو رقم دینا؛ آپ انہیں کسی دوسرے سرمایہ کار سے خرید رہے ہیں جو بیچنا چاہتا ہے۔ TCS کو اس تجارت سے کچھ حاصل نہیں ہوتا، رقم دو سرمایہ کاروں کے درمیان بہہ جاتی ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch03-primary-vs-secondary.png\" alt=\"پرائمری مارکیٹ (کمپنی سرمایہ کاروں کو نقد بڑھنے کے لیے نئے حصص جاری کرتی ہے) بمقابلہ ثانوی مارکیٹ (سرمایہ کار ان موجودہ حصص کو ایکسچینج پر آپس میں تجارت کرتے ہیں)\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">فلو چارٹ</span>پرائمری مارکیٹ (کمپنی سرمایہ کاروں کو نقد بڑھنے کے لیے نئے حصص جاری کرتی ہے) بمقابلہ ثانوی مارکیٹ (سرمایہ کار ان موجودہ حصص کو ایکسچینج پر آپس میں تجارت کرتے ہیں)</figcaption></figure>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>ایک کار کے بارے میں سوچو۔ دی <strong>بنیادی مارکیٹ</strong> شو روم ہے: آپ بالکل نئی کار خریدتے ہیں اور رقم مینوفیکچرر کو جاتی ہے۔ دی <strong>ثانوی مارکیٹ</strong> استعمال شدہ کار مارکیٹ ہے: آپ وہی کار اس کے پچھلے مالک سے بعد میں خریدتے ہیں، مینوفیکچرر کو دوبارہ فروخت سے کچھ نہیں ملتا ہے۔ ایک کمپنی کا IPO شوروم ہے۔ روزانہ اسٹاک ٹریڈنگ استعمال شدہ کاروں کا بازار ہے۔</p>\n</div></div>\n<p>ثانوی مارکیٹ اتنی اہمیت کیوں رکھتی ہے؟ کیونکہ اس کے بغیر، کوئی بھی پہلی جگہ حصص نہیں خریدے گا۔ جب بھی آپ چاہیں اپنا ٹکڑا بیچنے کی صلاحیت، ملکیت کو سیکنڈوں میں نقد رقم میں تبدیل کرنے کی صلاحیت، کمپنیوں میں سرمایہ کاری کو عملی بناتی ہے۔ ثانوی مارکیٹ وہ اہم جزو فراہم کرتی ہے: <strong>لیکویڈیٹی</strong>.</p>\n<h2 id=\"how-you-actually-make-money\">آپ اصل میں پیسہ کیسے کماتے ہیں۔</h2>\n<p>ایک شیئر ہولڈر کے طور پر، آپ کا پیسہ دو طریقوں سے بڑھتا ہے، اور ایک عقلمند سرمایہ کار دونوں کا خیال رکھتا ہے:</p>\n<ul>\n<li><strong>قیمت میں اضافہ (سرمایہ کاری میں اضافہ)۔</strong> 500 روپے میں ایک شیئر خریدیں اور بعد میں اسے 800 روپے میں بیچیں، اور آپ 300 روپے کا فرق رکھیں گے۔ جیسے جیسے کاروبار بڑھتا ہے اور زیادہ کماتا ہے، خریدار اس کے ایک ٹکڑے کے لیے زیادہ قیمت ادا کرنے کو تیار ہوتے ہیں، اور قیمت بڑھ جاتی ہے۔ یہ وہ جگہ ہے جہاں سے سب سے بڑے طویل مدتی فوائد عام طور پر آتے ہیں۔</li>\n<li><strong>منافع</strong> منافع بانٹنے والے نقد کا مستحکم سلسلہ، وقتاً فوقتاً ادائیگی کی جاتی ہے جب کہ آپ صرف شیئر رکھتے ہیں۔ کچھ بالغ کمپنیاں فراخ دلانہ منافع ادا کرتی ہیں۔ تیزی سے ترقی کرنے والے اکثر بہت کم ادائیگی کرتے ہیں اور تیزی سے بڑھنے کے لیے ہر چیز کی دوبارہ سرمایہ کاری کرتے ہیں۔</li>\n</ul>\n<p>ایک طویل انعقاد کی مدت میں، ایک زبردست کاروبار آپ کو دونوں محاذوں پر انعام دے سکتا ہے: بڑھتی ہوئی قیمت <em>اور</em> ایک بڑھتا ہوا منافع، سال بہ سال، ایکویٹی دولت کے جڑواں انجن۔</p>\n<h2 id=\"the-market-as-a-giant-auction\">ایک بڑی نیلامی کے طور پر مارکیٹ</h2>\n<p>تو کیا کسی بھی لمحے قیمت کا فیصلہ کرتا ہے؟ کمیٹی نہیں، کمپنی نہیں، بس <strong>طلب اور رسد</strong>, ایک نیلامی کی طرح مسلسل آباد. ہر لمحہ، کچھ لوگ حصہ خریدنا چاہتے ہیں اور دوسرے اسے بیچنا چاہتے ہیں۔ قیمت صرف وہ سطح ہے جہاں ایک تیار خریدار اور ایک تیار بیچنے والا ابھی کاروبار کرنے پر راضی ہے۔</p>\n<p>اگر زیادہ لوگ اسے فروخت کرنے کے بجائے TCS خریدنا چاہتے ہیں، تو خریدار اپنی پیشکشوں کو آگے بڑھاتے ہیں اور قیمت بڑھ جاتی ہے۔ اگر بیچنے والوں کی تعداد خریداروں سے زیادہ ہو تو قیمت کم ہو جاتی ہے۔ آپ جو چمکتا ہوا نمبر دیکھتے ہیں وہ خریدار اور بیچنے والے کے درمیان تازہ ترین متفقہ قیمت سے زیادہ کچھ نہیں ہے، مارکیٹ کا فیصلہ ہے کہ اس کاروبار کا ایک ٹکڑا اس سیکنڈ کی کیا قیمت ہے۔</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>ہندوستان کا سب سے مہنگا اسٹاک، MRF، نے 1,50,000 روپے سے اوپر ٹریڈ کیا ہے۔ <em>اکیلا</em> حصہ، بہت سے دو پہیوں کی قیمت سے زیادہ. کمپنی نے کبھی بھی اپنے حصص کو چھوٹے، سستے یونٹوں میں تقسیم نہیں کیا، اس لیے اس کے پیزا کا ایک ٹکڑا مشہور طور پر بڑا رہتا ہے۔</p>\n</div></div>\n<h2 id=\"quick-recap\">فوری خلاصہ</h2>\n<ul>\n<li>اے <strong>شیئر کریں</strong> کمپنی میں ملکیت کا ایک حقیقی، قانونی ٹکڑا ہے، لاٹری ٹکٹ یا چمکتا ہوا نمبر نہیں۔</li>\n<li>شیئر ہولڈر کے طور پر آپ کاروبار کے ایک حصے کے مالک ہیں اور ایک حاصل کرتے ہیں۔ <strong>منافع پر دعویٰ</strong>، اس کی قیمت پر دعوی، اور <strong>ووٹنگ کے حقوق</strong>.</li>\n<li>کمپنیاں فروخت کرتی ہیں۔ <strong>مساوات</strong> رقم اکٹھا کرنے کے لیے انہیں کبھی واپس نہیں کرنا پڑتا، قرض کے برعکس، کوئی سود یا طے شدہ خطرہ نہیں ہے، صرف نئے شریک مالکان۔</li>\n<li>دی <strong>بنیادی مارکیٹ</strong> جہاں نئے حصص پیدا ہوتے ہیں ( IPO؛ نقد کمپنی کو جاتا ہے)؛ دی <strong>ثانوی مارکیٹ</strong> وہ جگہ ہے جہاں سرمایہ کار آپس میں موجودہ حصص کی تجارت کرتے ہیں۔</li>\n<li>آپ دو طریقوں سے پیسہ کماتے ہیں: <strong>قیمت کی تعریف</strong> جیسے جیسے کاروبار بڑھتا ہے، اور <strong>منافع</strong> آپ کے پاس رکھنے کے دوران ادائیگی کی گئی۔</li>\n<li>قیمتیں ایک مسلسل کی طرح حرکت کرتی ہیں۔ <strong>نیلامی</strong>، تازہ ترین نمبر صرف وہ ہے جہاں خریدار اور بیچنے والے نے اتفاق کیا۔</li>\n</ul>\n<p>اب آپ سمجھ گئے ہیں کہ آپ کیا اور کہاں خرید رہے ہیں۔ اس کے بعد، ہم ریفریز سے ملتے ہیں جو اس پورے بازار کو قابل بھروسہ بناتے ہیں، SEBI، RBI اور ایسے قوانین جو ماضی کے اسکینڈلز سے پیدا ہونے والے ہر سرمایہ کار کی حفاظت کرتے ہیں۔</p>\n","toc":[{"level":2,"text":"ایک حصہ ملکیت کا ایک ٹکڑا ہے۔","id":"a-share-is-a-slice-of-ownership"},{"level":2,"text":"جو آپ اصل میں مالک ہیں۔","id":"what-you-actually-own"},{"level":2,"text":"کمپنیاں خود کے ٹکڑے کیوں بیچتی ہیں۔","id":"why-companies-sell-pieces-of-themselves"},{"level":2,"text":"پرائمری مارکیٹ بمقابلہ سیکنڈری مارکیٹ","id":"primary-market-vs-secondary-market"},{"level":2,"text":"آپ اصل میں پیسہ کیسے کماتے ہیں۔","id":"how-you-actually-make-money"},{"level":2,"text":"ایک بڑی نیلامی کے طور پر مارکیٹ","id":"the-market-as-a-giant-auction"},{"level":2,"text":"فوری خلاصہ","id":"quick-recap"}],"imgCount":2,"hasContent":true},"4":{"html":"<p>ایک کرکٹ میچ کا تصور کریں جس میں امپائر نہ ہو۔ کوئی بھی نو بال کو پکارنے والا نہیں، بلے باز کو آؤٹ کرنے والا کوئی نہیں، گیند کو چھیڑ چھاڑ سے روکنے والا کوئی نہیں۔ چند منٹوں میں کھیل ختم ہو جائے گا، اس لیے نہیں کہ کھلاڑی برے لوگ ہیں، بلکہ اس لیے کہ بغیر کسی منصفانہ ریفری کے، <em>کوئی بھی نتیجہ پر اعتماد نہیں کر سکتا</em>. اسٹاک مارکیٹ بھی بالکل ایسی ہی ہے۔ یہ لاکھوں اجنبیوں کے درمیان کھربوں روپے منتقل کرتا ہے جو کبھی نہیں ملیں گے۔ صرف ایک وجہ ہے کہ آپ اپنی محنت سے کمائی گئی رقم کو اسکرین میں بھیجنے کے لیے تیار ہیں اور اس بات پر بھروسہ کرتے ہیں کہ آپ کے اکاؤنٹ میں حقیقی حصص موجود ہیں کہ کوئی دیکھ رہا ہے، قوانین کو نافذ کر رہا ہے، اور دھوکہ دہی کو سزا دے رہا ہے۔</p>\n<p>کہ کوئی، ہندوستان میں، بنیادی طور پر <strong>SEBI</strong>، سیکورٹیز اینڈ ایکسچینج بورڈ آف انڈیا، کی طرف سے حمایت یافتہ <strong>RBI</strong>. یہ باب مارکیٹ کے سرپرستوں کا تعارف کراتا ہے: وہ کون ہیں، وہ دراصل سادہ انگریزی میں کیا کرتے ہیں، وہ آپ جیسے عام سرمایہ کاروں کی حفاظت کیسے کرتے ہیں، اور ڈرامائی اسکینڈل جس نے SEBI کو اس کے حقیقی اختیارات فراہم کیے ہیں۔ کیونکہ یہاں ناگوار سچائی ہے، مارکیٹ کا ضابطہ ماضی کی آفات کی سیاہی میں لکھا جاتا ہے۔</p>\n<h2 id=\"why-markets-must-be-regulated\">مارکیٹوں کو کیوں ریگولیٹ کیا جانا چاہئے۔</h2>\n<p>اعتماد ہر بازار کی پوشیدہ بنیاد ہے۔ آپ خوشی سے حصص صرف اسی صورت میں خریدیں گے جب آپ کو یقین ہو کہ مٹھی بھر چیزیں درست ہیں: یہ کہ کمپنی کے بتائے گئے منافع حقیقی ہیں اور من گھڑت نہیں، یہ کہ قیمت کسی ہیرا پھیری کے بجائے ایماندارانہ رسد اور طلب سے طے کی جاتی ہے، یہ کہ آپ کا بروکر آپ کے پیسے لے کر نہیں بھاگے گا، اور یہ کہ آپ نے جن حصص کی ادائیگی کی ہے وہ آپ کے اکاؤنٹ میں ظاہر ہوں گے۔</p>\n<p>ان میں سے کسی ایک کو بھی لے لیں، اور پورا نظام منجمد ہو جاتا ہے۔ کوئی بھی اس کھیل میں سرمایہ کاری نہیں کرتا ہے جس کا شبہ ہے کہ دھاندلی ہوئی ہے۔ لہذا ریگولیشن ریڈ ٹیپ نہیں ہے جو مارکیٹ کے راستے میں ہو جاتا ہے، ریگولیشن <em>وہی ہے جو مارکیٹ کو بالکل ممکن بناتا ہے۔</em>. یہ شک کے اڈے کو ایک ایسی جگہ میں بدل دیتا ہے جہاں ایک چھوٹے سے قصبے میں ایک 22 سالہ نوجوان پورے اعتماد کے ساتھ ہندوستان کی سب سے بڑی کمپنیوں کا مالک بن سکتا ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>ضابطہ سب سے بڑھ کر ایک وجہ سے موجود ہے: <strong>اعتماد</strong>. منصفانہ اصول، دیانت دار قیمتیں اور محفوظ سرمایہ کار کوئی اچھی اضافی چیز نہیں ہیں، یہ وہ آکسیجن ہیں جو مارکیٹ سانس لیتی ہے۔ ان کے بغیر، کوئی عقلمند شخص کبھی سرمایہ کاری نہیں کرے گا، اور بات کرنے کے لیے کوئی بازار نہیں ہوگا۔</p>\n</div></div>\n<h2 id=\"meet-sebi-the-market-s-chief-referee\">مارکیٹ کے چیف ریفری SEBI سے ملیں۔</h2>\n<p><strong>SEBI</strong> ہندوستان کی سیکیورٹیز مارکیٹس، اسٹاکس، بانڈز، میوچل فنڈز، ڈیریویٹیوز، لاٹ کا مرکزی ریگولیٹر ہے۔ اس کے بارے میں سوچیں کہ امپائر، حکمرانی کرنے والا اور بازار کی پولیس فورس ایک ہو گئی۔ اس کا کام، سادہ الفاظ میں، مارکیٹ کو برقرار رکھنا ہے۔ <strong>منصفانہ، شفاف اور محفوظ</strong> عام سرمایہ کاروں کے لیے۔ یہ تین وسیع کرداروں کے ذریعے کرتا ہے:</p>\n<ul>\n<li><strong>سرمایہ کاروں کی حفاظت۔</strong> SEBI کی بیان کردہ پہلی ترجیح چھوٹے سرمایہ کار ہیں، اس بات کو یقینی بناتے ہوئے کہ آپ کے ساتھ منصفانہ برتاؤ کیا جائے اور زیادہ معلومات یا طاقت رکھنے والوں کی طرف سے آپ کو نقصان نہ پہنچے۔</li>\n<li><strong>کھلاڑیوں کو منظم کرنا۔</strong> اسٹاک ایکسچینجز، بروکرز، میوچل فنڈز، ریٹنگ ایجنسیاں، سرمایہ کاری کے مشیر، سبھی کو SEBI کے ساتھ رجسٹر ہونا چاہیے اور اس کے قواعد پر عمل کرنا چاہیے۔ ان کو توڑ دیں اور SEBI آپ کو جرمانہ کر سکتا ہے، آپ پر پابندی لگا سکتا ہے، یا کیس عدالتوں کے حوالے کر سکتا ہے۔</li>\n<li><strong>مارکیٹ کو ترقی دینا۔</strong> SEBI تیزی سے تصفیہ، الیکٹرانک شیئر ہولڈنگ اور سخت افشاء جیسی اصلاحات کو آگے بڑھاتے ہوئے، مارکیٹ کو بھی جدید بناتا ہے، اس لیے ہندوستان کی مارکیٹیں عالمی معیار کی رہیں۔</li>\n</ul>\n<p>SEBI کی طاقت کا ایک بہت بڑا حصہ اصول ہے۔ <strong>انکشاف</strong>: کمپنیاں <em>ضروری ہے</em> اپنے مالیاتی نتائج، بڑے فیصلوں اور خطرات کو عوامی طور پر ظاہر کریں، تاکہ ہر سرمایہ کار انہی حقائق کو استعمال کرتے ہوئے فیصلہ کرے۔ اندرونیوں کے لیے کوئی خفیہ معلومات، کوئی بری خبر چھپانے کی ضرورت نہیں۔ سورج کی روشنی، SEBI کا خیال ہے، بہترین جراثیم کش ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch04-regulatory-structure.png\" alt=\"ریگولیٹری درجہ بندی، SEBI اور RBI سب سے اوپر، ایکسچینجز، بروکرز، ڈپازٹریز اور لسٹڈ کمپنیوں کی نگرانی، یہ سب بیس پر سرمایہ کار کی حفاظت کے لیے\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>ریگولیٹری درجہ بندی، SEBI اور RBI سب سے اوپر، ایکسچینجز، بروکرز، ڈپازٹریز اور لسٹڈ کمپنیوں کی نگرانی کرتے ہیں، یہ سب بیس پر سرمایہ کار کی حفاظت کے لیے ہیں۔</figcaption></figure>\n<h2 id=\"the-rbi-guardian-of-money-and-banks\">RBI: رقم اور بینکوں کا سرپرست</h2>\n<p>اگر SEBI کی حفاظت کرتا ہے۔ <em>بازار</em>, the <strong>ریزرو بینک آف انڈیا (RBI)</strong> کی حفاظت کرتا ہے <em>پیسہ</em> اور <em>بینکوں</em> ان کے پیچھے. RBI ہندوستان کا مرکزی بینک ہے، اور جب کہ یہ آپ کے اسٹاک کی تجارت کو پولیس نہیں کرتا، اس کے فیصلے ہر مارکیٹ میں پھیلتے ہیں۔</p>\n<p>RBI کے اہم کام روپیہ جاری کرنا، شرح سود طے کرکے مہنگائی کو کنٹرول کرنا، بینکوں کو ریگولیٹ کرنا (بشمول آپ کا اکاؤنٹ رکھنے والا)، اور ملک کے زرمبادلہ کا انتظام کرنا ہے۔ جب RBI کو بڑھاتا ہے یا کاٹتا ہے۔ <strong>ریپو ریٹ</strong>، یہ پوری معیشت میں قرض لینے کی لاگت کو تبدیل کرتا ہے، جس سے FD کی شرح، قرض کی EMIs اور بالواسطہ طور پر، اسٹاک کی قیمتیں بدل جاتی ہیں۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>تقسیم کو یاد رکھنے کا ایک آسان طریقہ: <strong>SEBI شیئر مارکیٹ کو دیکھتا ہے۔ RBI بینکنگ اور منی سسٹم کو دیکھتا ہے۔</strong> وہ کناروں پر اوورلیپ ہوتے ہیں، مثال کے طور پر، مارکیٹ کے بنیادی ڈھانچے میں دونوں کا کہنا ہے، لیکن ان کی بنیادی دھڑکنیں مختلف ہیں۔ SEBI آپ کی حفاظت کرتا ہے۔ <em>سرمایہ کاری</em>; RBI آپ کی حفاظت کرتا ہے۔ <em>روپیہ</em> اور بینک جو اسے رکھتے ہیں۔</p>\n</div></div>\n<h2 id=\"how-investors-are-protected\">سرمایہ کاروں کی حفاظت کیسے کی جاتی ہے۔</h2>\n<p>SEBI کی سرمایہ کاروں کے تحفظ کا ٹول کٹ حقیقی طور پر مفید ہے، اور ایک ابتدائی کے طور پر آپ کو معلوم ہونا چاہیے کہ آپ اور شارک کے درمیان کیا کھڑا ہے:</p>\n<ul>\n<li><strong>منصفانہ قواعد</strong> جو اندرونی تجارت، قیمتوں میں ہیرا پھیری اور گمراہ کن اشتہارات پر پابندی لگاتا ہے۔</li>\n<li><strong>لازمی انکشاف</strong>لہذا کمپنیاں اپنی حقیقی مالی حالت کو چھپا نہیں سکتیں۔</li>\n<li><strong>آپ کے اثاثوں کی علیحدگی</strong>آپ کے حصص ڈیپازٹری میں آپ کے اپنے ڈیمیٹ اکاؤنٹ میں رکھے جاتے ہیں، ایسے جمع نہیں ہوتے جہاں کوئی بروکر ان کا غلط استعمال کر سکتا ہو۔</li>\n<li><strong>فراڈ کے خلاف کارروائی</strong>، تحقیقات، بھاری جرمانے، بازار سے پابندی اور قانونی چارہ جوئی کے حوالے۔</li>\n<li><strong>شکایت کا نظام</strong>، اہلکار <strong>SCORES</strong> پلیٹ فارم، جہاں کوئی بھی سرمایہ کار رسمی طور پر شکایت اٹھا سکتا ہے اور اس کا سراغ لگا سکتا ہے۔</li>\n</ul>\n<h3 id=\"scores-your-formal-complaint-channel\">SCORES: آپ کا باقاعدہ شکایتی چینل</h3>\n<p>اگر کوئی بروکر، کمپنی یا میوچل فنڈ آپ کو غلط کرتا ہے اور اسے ٹھیک نہیں کرتا ہے، تو آپ کو بھیک مانگنے یا ہار ماننے کی ضرورت نہیں ہے۔ <strong>SCORES</strong> (SEBI شکایات کے ازالے کا نظام) ایک مفت آن لائن پورٹل ہے جہاں آپ شکایت درج کراتے ہیں، جو SEBI پھر جواب دینے کے لیے ایک آخری تاریخ کے ساتھ ناگوار ہستی کے پاس جاتا ہے، اور آپ پوری طرح سے اسٹیٹس کو ٹریک کرسکتے ہیں۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch04-scores-flow.png\" alt=\"کس طرح ایک سرمایہ کار کی شکایت SCORES سے گزرتی ہے، آن لائن درج کی جاتی ہے، SEBI کے ذریعے ایک ڈیڈ لائن کے ساتھ ادارے کو بھیجی جاتی ہے، حل یا بڑھایا جاتا ہے، سرمایہ کار ہر قدم پر نظر رکھتا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">فلو چارٹ</span>کس طرح ایک سرمایہ کار کی شکایت SCORES سے گزرتی ہے، آن لائن درج کی جاتی ہے، SEBI کے ذریعے ایک ڈیڈ لائن کے ساتھ ہستی کو بھیجی جاتی ہے، حل یا بڑھایا جاتا ہے، جس میں سرمایہ کار ہر قدم پر نظر رکھتا ہے۔</figcaption></figure>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>ایک روپیہ کی سرمایہ کاری کرنے سے پہلے، چیک کریں کہ آپ جس کے ساتھ کام کر رہے ہیں، بروکر، مشیر، میوچل فنڈ، ہے <strong>SEBI کے ساتھ رجسٹرڈ</strong> (آپ اس کی تصدیق SEBI کی ویب سائٹ پر کر سکتے ہیں)۔ SEBI رجسٹریشن نمبر منافع کی ضمانت نہیں ہے، لیکن رجسٹرڈ، جوابدہ اداروں کے ساتھ ڈیل کرنا دھوکہ دہی کے خلاف آپ کے دفاع کی پہلی اور سستی لائن ہے۔</p>\n</div></div>\n<h2 id=\"written-in-the-ink-of-scandal-the-harshad-mehta-story\">اسکینڈل کی سیاہی میں لکھا گیا: ہرشد مہتا کی کہانی</h2>\n<p>یہ وہ حصہ ہے جس کے بارے میں زیادہ تر لوگ نہیں جانتے: SEBI 1988 سے کاغذ پر موجود تھا لیکن اس میں تقریباً کوئی حقیقی طاقت نہیں تھی، یہ ایک بغیر دانتوں کا مشاورتی ادارہ تھا۔ جس چیز نے اسے دانت دیا وہ ایک تباہی تھی۔</p>\n<p>1992 میں، اسٹاک بروکر <strong>ہرشد مہتا</strong>، جسے \"بگ بُل\" کا عرفی نام دیا گیا ہے، ایک اندازے کے مطابق گھونپ دیا گیا تھا۔ <strong>4،000 کروڑ روپے</strong> جعلی رسیدوں کا استعمال کرتے ہوئے بینکنگ سسٹم سے باہر ہو گئے، اور اسے مٹھی بھر سٹاک میں شامل کر دیا، جس سے ان کی قیمتیں بلندیوں تک پہنچ گئیں۔ جب اس گھوٹالے کا پردہ فاش ہوا، مارکیٹ کریش ہو گئی، عام سرمایہ کاروں کا صفایا ہو گیا، اور عوام کا اعتماد ختم ہو گیا۔ ملک کو دردناک طور پر احساس ہوا کہ اس کے پاس کوئی حقیقی پولیس اہلکار نہیں تھا۔</p>\n<p>جواب تھا <strong>SEBI ایکٹ آف 1992</strong>جس نے SEBI کو ایک بے اختیار کمیٹی سے ایک قانونی ریگولیٹر میں تبدیل کر دیا جس کے پاس تفتیش، جرمانہ اور پابندی کا اختیار ہے۔ تقریباً ہر اہم تحفظ جس سے آپ آج لطف اندوز ہوتے ہیں، ڈیمٹیریلائزڈ حصص، تیز تر تصفیہ، سخت انکشاف، اس اسکینڈل کے اسباق کو براہ راست یا بالواسطہ طور پر تلاش کرنا۔</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>تقریباً ہر بڑی ہندوستانی مارکیٹ کی اصلاحات ایک آفت سے جنم لیتی ہیں۔ 1992 کے ہرشد مہتا گھوٹالے نے SEBI کو اس کے قانونی دانت دیے۔ 2001 کیتن پاریکھ گھوٹالے نے تصفیہ کو سخت کیا اور خطرناک \"بدلا\" نظام پر پابندی لگا دی۔ 2009 کے ستیم فراڈ نے کارپوریٹ گورننس کے قوانین کو نظر انداز کیا۔ آج آپ کی حفاظت کرنے والی اصولی کتاب، بالکل لفظی طور پر، کل کے گھوٹالوں کی سیاہی میں لکھی ہوئی ہے۔</p>\n</div></div>\n<h2 id=\"the-modern-frontier-finfluencers-and-f-o\">جدید فرنٹیئر: فن فلوینسر اور ایف اینڈ او</h2>\n<p>سرپرست اب بھی بہت زیادہ کام پر ہیں، اور میدان جنگ آپ کے فون پر منتقل ہو گیا ہے۔ دو حالیہ کریک ڈاؤنز SEBI کو نئے خطرات کے مطابق ڈھالتے ہوئے دکھاتے ہیں۔</p>\n<p>پہلے، <strong>فنونسر</strong>. جیسا کہ سوشل میڈیا خود ساختہ \"ماہرین\" کو آگے بڑھانے والے اسٹاک ٹپس، کورسز اور \"گارنٹیڈ\" حکمت عملیوں سے بھرا ہوا ہے، SEBI آگے بڑھا۔ 2025 کے اوائل سے اس نے رجسٹرڈ اداروں (بروکرز، میوچل فنڈز، مشیروں) کو اس کے ساتھ منسلک کرنے سے روک دیا۔ <em>غیر رجسٹرڈ</em> finfluencers، اور معلموں کو حالیہ لائیو مارکیٹ ڈیٹا کو استعمال کرنے سے روک دیا تاکہ تجاویز کو \"تعلیم\" کا روپ دھار سکیں۔ پیغام دو ٹوک ہے: SEBI رجسٹریشن کے بغیر مخصوص اسٹاک مشورہ دینا غیر قانونی ہے، اگرچہ آپ کے بہت سے پیروکار ہوں۔</p>\n<p>دوسرا، <strong>فیوچر اینڈ آپشنز (F&amp;O) کی بندش</strong>. SEBI کی اپنی تحقیق نے ایک سنجیدہ فیصلہ دیا: تقریباً <strong>91% انفرادی F&amp;O تاجروں نے رقم کھو دی۔</strong> FY25 میں، ایک سال میں تقریباً 1.05 لاکھ کروڑ روپے کے خالص نقصان کے ساتھ۔ اس کے جواب میں، SEBI نے قواعد کو سخت کیا، ہفتہ وار کم میعاد ختم ہونے، بڑے کم از کم کنٹریکٹ سائزز اور سخت نگرانی، خاص طور پر چھوٹے سرمایہ کاروں کو اس کھیل کی طرف راغب ہونے سے روکنے کے لیے جہاں بھاری اکثریت ہار جاتی ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>کسی بھی آن لائن \"یقینی طور پر شاٹ\" ٹپس، گارنٹی شدہ واپسی یا فوری دولت مند F&amp;O حکمت عملیوں سے ہوشیار رہیں، خاص طور پر نجی WhatsApp یا ٹیلی گرام گروپس میں۔ SEBI کا ڈیٹا بے دردی سے واضح ہے: فاسٹ ٹریڈنگ ریٹیل شرکاء کی اکثریت <em>کھونا</em> پیسہ ایک ریگولیٹر حقیقت کے بعد دھوکہ دہی کی سزا دے سکتا ہے، لیکن صرف <em>آپ</em> پہلی جگہ میں نیٹ ورک سے بچ سکتے ہیں. شکوک و شبہات آپ کا سب سے مضبوط تحفظ ہے۔</p>\n</div></div>\n<h2 id=\"quick-recap\">فوری خلاصہ</h2>\n<ul>\n<li>مارکیٹیں چلتی ہیں۔ <strong>اعتماد</strong>، اور ضابطہ وہی ہے جو اسے تخلیق کرتا ہے، منصفانہ اصولوں اور دیانت دار قیمتوں کے بغیر، کوئی بھی سرمایہ کاری نہیں کرے گا۔</li>\n<li><strong>SEBI</strong> ہندوستان کی سیکورٹیز مارکیٹوں کا چیف ریفری ہے، سرمایہ کاروں کی حفاظت کرتا ہے، بروکرز اور ایکسچینج کو ریگولیٹ کرتا ہے، اور سختی سے نافذ کرتا ہے۔ <strong>انکشاف</strong>.</li>\n<li>دی <strong>RBI</strong> پیسے اور بینکوں کی حفاظت کرتا ہے، سود کی شرحیں طے کرتا ہے جو ہر مارکیٹ میں پھیلتی ہے۔ SEBI حصص دیکھتا ہے، RBI روپے کو دیکھتا ہے۔</li>\n<li>سرمایہ کاروں کو منصفانہ قواعد، لازمی انکشاف، الگ الگ ڈیمیٹ ہولڈنگز، اینٹی فراڈ ایکشن، اور <strong>SCORES</strong> شکایت پلیٹ فارم.</li>\n<li>SEBI کو اس کی اصلیت مل گئی۔ <strong>1992 کے SEBI ایکٹ سے قانونی اختیارات</strong>، ہرشد مہتا گھوٹالے کے بعد منظور کیا گیا، اصلاحات ماضی کے گھوٹالوں کی سیاہی میں لکھی گئی ہیں۔</li>\n<li>آج SEBI غیر رجسٹرڈ کے خلاف کریک ڈاؤن کر رہا ہے۔ <strong>فنونسر</strong> اور سخت <strong>ایف اینڈ او</strong> یہ معلوم کرنے کے بعد کہ ~91% انفرادی مشتق تاجر رقم کھو دیتے ہیں۔</li>\n</ul>\n<p>اب آپ جانتے ہیں کہ مارکیٹ کو کون ایماندار رکھتا ہے۔ اس کے بعد، ہم خود مشینری، ایکسچینجز، بروکرز اور ڈپازٹریز کا دورہ کرتے ہیں جو آپ کے کلک کو لے کر اسے حقیقی، محفوظ ملکیت میں تبدیل کر دیتے ہیں۔</p>\n","toc":[{"level":2,"text":"مارکیٹوں کو کیوں ریگولیٹ کیا جانا چاہئے۔","id":"why-markets-must-be-regulated"},{"level":2,"text":"مارکیٹ کے چیف ریفری SEBI سے ملیں۔","id":"meet-sebi-the-market-s-chief-referee"},{"level":2,"text":"RBI: رقم اور بینکوں کا سرپرست","id":"the-rbi-guardian-of-money-and-banks"},{"level":2,"text":"سرمایہ کاروں کی حفاظت کیسے کی جاتی ہے۔","id":"how-investors-are-protected"},{"level":3,"text":"SCORES: آپ کا باقاعدہ شکایتی چینل","id":"scores-your-formal-complaint-channel"},{"level":2,"text":"اسکینڈل کی سیاہی میں لکھا گیا: ہرشد مہتا کی کہانی","id":"written-in-the-ink-of-scandal-the-harshad-mehta-story"},{"level":2,"text":"جدید فرنٹیئر: فن فلوینسر اور ایف اینڈ او","id":"the-modern-frontier-finfluencers-and-f-o"},{"level":2,"text":"فوری خلاصہ","id":"quick-recap"}],"imgCount":2,"hasContent":true},"5":{"html":"<p>جب آپ ریلائنس کے 10 حصص پر \"خریدیں\" کو تھپتھپاتے ہیں اور آرڈر ایک سیکنڈ کے اندر اندر بھر جاتا ہے، تو ایسا محسوس ہوتا ہے جیسے جادو، ایک تھپتھپا، مکمل ہو گیا۔ لیکن وہ ایک نل خاموشی سے چار بہت مختلف اداروں کے درمیان ریلے کی دوڑ شروع کر دیتا ہے، ہر ایک کے پاس ایک کام ہوتا ہے، ہر ایک دوسرے کو ڈنڈا سونپتا ہے۔ ان میں سے کوئی بھی آپ نہیں ہیں، ان میں سے کوئی بھی وہ کمپنی نہیں ہے جسے آپ نے ابھی خریدا ہے، اور پھر بھی چاروں ایک ساتھ کام کیے بغیر آپ کی تجارت نہیں ہو سکتی تھی، اور آپ کے حصص کو محفوظ طریقے سے منعقد نہیں کیا جا سکتا تھا۔</p>\n<p>اس باب میں کرداروں کی اس کاسٹ کا تعارف کرایا گیا ہے۔ <strong>تبادلے</strong> جہاں خریدار اور بیچنے والے ملتے ہیں، <strong>بروکر</strong> جو وہاں آپ کا آرڈر لے کر جاتا ہے۔ <strong>ڈپازٹری</strong> جو آپ کے حصص کو الیکٹرانک طور پر رکھتا ہے، اور <strong>کلیئرنگ کارپوریشن</strong> جو اس بات کی ضمانت دیتا ہے کہ کسی کو دھوکہ نہیں دیا جائے گا۔ ان چاروں کو سمجھیں اور اسٹاک مارکیٹ ایک بلیک باکس کی طرح محسوس کرنا بند کر دیتی ہے اور ایک اچھی طرح سے منظم اسمبلی لائن کی طرح نظر آنے لگتی ہے۔</p>\n<h2 id=\"the-exchange-a-giant-organised-marketplace\">تبادلہ: ایک بڑا منظم بازار</h2>\n<p>ایک اسٹاک <strong>تبادلہ</strong> صرف ایک بازار ہے، لیکن سبزیوں یا سونے کے بجائے، جو چیز خریدی اور بیچی جا رہی ہے وہ کمپنیوں میں ملکیت ہے۔ یہ وہ جگہ ہے جہاں کوئی شخص جو ریلائنس کے 10 حصص بیچنا چاہتا ہے، کسی ایسے شخص سے ملتا ہے جو انہیں خریدنا چاہتا ہے، اس قیمت پر دونوں متفق ہیں۔ ایکسچینج حصص کی ملکیت یا قیمت مقرر نہیں کرتا؛ یہ نیلامی چلاتا ہے، آرڈرز سے میل کھاتا ہے، اور ہر تجارت کو شائع کرتا ہے تاکہ پوری مارکیٹ ایک ہی مناسب قیمت دیکھے۔</p>\n<p>ہندوستان کے پاس دو اہم اسٹاک ایکسچینج ہیں، اور ان میں زیادہ مختلف بیک اسٹوریز نہیں ہوسکتی ہیں۔</p>\n<ul>\n<li>دی <strong>بمبئی اسٹاک ایکسچینج (BSE)</strong>، میں قائم کیا گیا تھا۔ <strong>1875</strong>، ہے <strong>ایشیا کا قدیم ترین اسٹاک ایکسچینج</strong>. یہ ایک برگد کے درخت کے نیچے شروع ہوا جہاں مٹھی بھر اسٹاک بروکرز تجارت کے لیے ملتے تھے، اور آج ہزاروں کمپنیوں کی فہرست ہے، جو ہندوستان میں کسی بھی دوسرے تبادلے سے زیادہ ہے۔</li>\n<li>دی <strong>نیشنل اسٹاک ایکسچینج (NSE)</strong>میں شروع کیا گیا۔ <strong>1994</strong>، نیا، مکمل طور پر الیکٹرانک ایکسچینج ہے۔ یہ ہے <strong>تجارتی حجم کے لحاظ سے دونوں میں سے بڑا</strong>، ہندوستان کی نقدی مارکیٹ اور مشتقات کے کاروبار کی اکثریت یہاں ہوتی ہے۔</li>\n</ul>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch05-trade-relay.png\" alt=\"ایک نل کے پیچھے ریلے کی دوڑ، آپ کا آرڈر آپ سے آپ کے بروکر تک، ایکسچینج تک، کلیئرنگ کارپوریشن کے ذریعے، اور آخر میں آپ کے حصص ڈپازٹری میں پہنچ جاتے ہیں۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">فلو چارٹ</span>ایک نل کے پیچھے ریلے کی دوڑ، آپ کا آرڈر آپ سے آپ کے بروکر تک، ایکسچینج تک، کلیئرنگ کارپوریشن کے ذریعے، اور آخر میں آپ کے حصص ڈپازٹری میں پہنچ جاتے ہیں۔</figcaption></figure>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>BSE 1875 میں ایک برگد کے درخت کے نیچے شروع ہوا جو اب ممبئی میں دلال اسٹریٹ ہے، جہاں دلال کھلے عام تجارت کے لیے جمع ہوتے تھے۔ \"دلال اسٹریٹ\" تب سے پوری ہندوستانی اسٹاک مارکیٹ کے لیے شارٹ ہینڈ بن گئی ہے، جس طرح \"وال اسٹریٹ\" امریکہ کے لیے کھڑا ہے۔</p>\n</div></div>\n<h2 id=\"when-the-market-is-open\">جب بازار کھلا۔</h2>\n<p>آپ اپنی پسند کے مطابق کسی بھی وقت شیئر خرید یا فروخت نہیں کر سکتے۔ تجارت صرف اس وقت ہوتی ہے جب ایکسچینج ہو۔ <strong>کھلا</strong>، اور ہندوستان کی ایکویٹی مارکیٹ باقاعدہ دفتری اوقات رکھتی ہے ( IST):</p>\n<ul>\n<li><strong>عمومی تجارت: 9:15 AM سے 3:30 PM</strong>، پیر سے جمعہ۔ یہ تب ہوتا ہے جب تقریباً تمام خرید و فروخت ہوتی ہے۔</li>\n<li><strong>پری اوپن: 9:00 سے 9:15 AM</strong>, ایک مختصر کھڑکی جہاں آرڈرز اکٹھے کیے جاتے ہیں اور ایک میلہ <em>افتتاحی قیمت</em> نیلامی کے ذریعے دریافت کیا جاتا ہے، اس لیے دن کا آغاز افراتفری سے نہیں ہوتا۔</li>\n<li><strong>بند ہونے کے بعد: 3:40 سے 4:00 PM</strong>دن کی اختتامی قیمت پر آرڈر دینے کے لیے ایک مختصر ونڈو۔</li>\n<li>بازار ہے۔ <strong>اختتام ہفتہ پر بند اور تعطیلات کا تبادلہ</strong>، اگرچہ آپ کبھی کبھار ایک خاص ایک گھنٹے کے بارے میں سنیں گے۔ <em>مہورت</em> دیوالی کی شام کو سیشن۔</li>\n</ul>\n<p>لہذا اگر آپ 9 PM پر خریدیں یا اتوار کو تھپتھپائیں، تو کچھ بھی نہیں ہوتا، آپ کا آرڈر صرف <em>انتظار کرتا ہے</em>. زیادہ تر ایپس آپ کو ایک جگہ دینے دیتی ہیں۔ <strong>مارکیٹ کے بعد آرڈر (AMO)</strong> جو قطار میں کھڑا ہو جاتا ہے اور اگلے بازار کھلنے کے فوراً بعد بھیج دیا جاتا ہے۔ آپ کو آخر کار جو قیمت ملتی ہے وہ وہی ہے جو مارکیٹ اس وقت کر رہی ہے، نہ کہ جب آپ نے اسے رکھا تھا۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>بازار بند ہونے کے دوران شیئر کی کوئی لائیو قیمت نہیں ہوتی۔ آپ رات کو جو \"آخری تجارت کی قیمت\" دیکھتے ہیں وہ آخری اوپن سیشن کی آخری قیمت ہے، جو اگلے تجارتی دن 9:15 AM تک منجمد ہے۔ حقیقی خرید و فروخت صرف بازار کے اوقات میں ہو سکتی ہے۔</p>\n</div></div>\n<h2 id=\"who-is-trading-the-market-participants\">کون تجارت کر رہا ہے: مارکیٹ کے شرکاء</h2>\n<p>جب آپ حصہ خریدتے ہیں تو دوسری طرف سے کوئی اسے بیچ رہا ہوتا ہے، لیکن کون؟ <em>ہیں</em> یہ سب خریدار اور بیچنے والے؟ ایکویٹی مارکیٹ بہت مختلف کھلاڑیوں کا ایک ہجوم ہے، ہر ایک مختلف اہداف، سائز اور وقت کے افق کے ساتھ۔</p>\n<table>\n<thead>\n<tr>\n<th>حصہ لینے والا</th>\n<th>وہ کون ہیں؟</th>\n<th>جو وہ بازار میں کرتے ہیں۔</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><strong>خوردہ سرمایہ کار</strong></td>\n<td>آپ جیسے افراد، فون یا لیپ ٹاپ سے تجارت کرتے ہیں۔</td>\n<td>چھوٹی مقدار میں خرید و فروخت، فی تجارت بہت کم، لیکن کل تعداد میں بہت زیادہ</td>\n</tr>\n<tr>\n<td><strong>HNIs / Ultra-HNIs</strong></td>\n<td>زیادہ مالیت والے افراد جو بڑی رقم کی سرمایہ کاری کرتے ہیں۔</td>\n<td>بڑی ٹکٹ کی تجارت، اکثر PMS یا AIFs کے ذریعے؛ اپنے طور پر چھوٹے اسٹاک منتقل کر سکتے ہیں</td>\n</tr>\n<tr>\n<td><strong>میوچل فنڈز</strong></td>\n<td>بہت سے لوگوں کے پیسے کے پول پروفیشنل مینیجرز چلاتے ہیں۔</td>\n<td>اپنے SIPs اور یکمشت رقم کو تمام سٹاک میں سرمایہ کاری کریں، یہ ایک بہت بڑی، مستحکم گھریلو قوت ہے۔</td>\n</tr>\n<tr>\n<td><strong>ڈی آئی آئیز</strong> (ملکی ادارے)</td>\n<td>ہندوستانی میوچل فنڈز، بیمہ کنندگان (جیسے LIC)، بینک، پنشن فنڈز</td>\n<td>گھریلو بچت کو تعینات کریں؛ حالیہ برسوں میں ان کے پاس ہے <em>تکیا</em> مارکیٹ جب غیر ملکی فروخت کرتے ہیں۔</td>\n</tr>\n<tr>\n<td><strong>FIIs/FPIs</strong> (غیر ملکی سرمایہ کار)</td>\n<td>بھارت میں سرمایہ کاری کرنے والے بڑے بیرون ملک فنڈز</td>\n<td>بڑی رقم اندر اور باہر منتقل کریں؛ ان کا \"رسک آن / رسک آف\" موڈ انڈیکس کو تیزی سے بدل سکتا ہے۔</td>\n</tr>\n<tr>\n<td><strong>ملکیتی (پروپ) ڈیسک</strong></td>\n<td>بروکریجز اور تجارتی فرمیں ان کی تجارت کرتی ہیں۔ <em>اپنے</em> سرمایہ</td>\n<td>تیز، اعلیٰ حجم کی تجارت اور ثالثی جو لیکویڈیٹی میں اضافہ کرتی ہے، اس لیے آپ کے آرڈر کو ملی سیکنڈز میں مماثلت ملتی ہے</td>\n</tr>\n</tbody></table>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch05-market-participants.png\" alt=\"ایکویٹی مارکیٹ کے اہم کھلاڑی، خوردہ سرمایہ کار، HNIs، میوچل فنڈز، گھریلو ادارے (DIIs)، غیر ملکی سرمایہ کار (FIIs) اور ملکیتی ڈیسک، ایکسچینج کے ارد گرد ترتیب دیئے گئے، ہر ایک کے کردار کے ساتھ\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>ایکویٹی مارکیٹ کے اہم کھلاڑی، خوردہ سرمایہ کار، HNIs، میوچل فنڈز، گھریلو ادارے (DIIs)، غیر ملکی سرمایہ کار (FIIs) اور ملکیتی ڈیسک، ایکسچینج کے ارد گرد ترتیب دیئے گئے، ہر ایک کے کردار کے ساتھ</figcaption></figure>\n<p>چند نمونے یاد رکھنے کے قابل ہیں۔ <strong>FIIs اور DII ہیوی ویٹ ہیں۔</strong>، جب یہ ادارے اربوں کو منتقل کرتے ہیں، تو پورا انڈیکس اسے محسوس کرتا ہے ( FII-بمقابلہ-DIIمیکرو باب میں ٹگ آف وار ریٹرن)۔ <strong>ریٹیل تعداد میں زبردست ہے۔</strong> لیکن فی تجارت چھوٹا۔ اور <strong>سہارا دینے والے اور اعلی تعدد ڈیسک</strong> وہ پرسکون پلمبنگ ہیں جو قیمتوں کو سخت رکھتی ہے اور فوری طور پر تجارت کرتی ہے۔ جب بھی آپ خریدتے ہیں، آپ ان میں سے کسی ایک کھلاڑی کے خلاف تجارت کر رہے ہوتے ہیں، عام طور پر یہ جانے بغیر کہ کون سا۔</p>\n<h2 id=\"the-broker-your-gateway-to-the-exchange\">بروکر: ایکسچینج کے لیے آپ کا گیٹ وے</h2>\n<p>یہ ایک کیچ ہے: آپ NSE یا BSE تک نہیں چل سکتے اور خود آرڈر نہیں دے سکتے۔ صرف رجسٹرڈ ممبران، <strong>دلال</strong>، کو ایکسچینج کو آرڈر بھیجنے کی اجازت ہے۔ تو ایک بروکر آپ کا گیٹ وے ہے۔ جب آپ کسی ایپ میں خریدیں پر ٹیپ کرتے ہیں، تو وہ آرڈر آپ کے بروکر تک پہنچ جاتا ہے، جو اسے ملی سیکنڈز میں ایکسچینج تک لے جاتا ہے۔ بروکر آپ کا لائسنس یافتہ مڈل مین ہے، اور اس سروس کے لیے وہ ایک فیس لیتا ہے جسے کہتے ہیں۔ <strong>دلالی</strong>.</p>\n<p>بروکرز دو وسیع ذائقوں میں آتے ہیں:</p>\n<table>\n<thead>\n<tr>\n<th></th>\n<th>ڈسکاؤنٹ بروکر</th>\n<th>مکمل سروس بروکر</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>جو وہ پیش کرتے ہیں۔</td>\n<td>تجارت کرنے کے لیے ایک نون فریلز ایپ</td>\n<td>تجارت کے علاوہ تحقیق، ٹپس، ایک رشتہ مینیجر، مشورہ</td>\n</tr>\n<tr>\n<td>دلالی</td>\n<td>فلیٹ، کم (اکثر ایک چھوٹی مقررہ فیس فی آرڈر، یا ڈیلیوری پر صفر)</td>\n<td>عام طور پر ہر تجارت کی قیمت کا فیصد</td>\n</tr>\n<tr>\n<td>کے لیے بہترین</td>\n<td>خود ہدایت کرنے والے سرمایہ کار جو خود فیصلہ کرتے ہیں۔</td>\n<td>وہ لوگ جو ہاتھ پکڑنا اور مشورہ چاہتے ہیں۔</td>\n</tr>\n</tbody></table>\n<p>کم لاگت کا اضافہ <strong>ڈسکاؤنٹ بروکرز</strong>فی صد کے بجائے تقریباً 20 روپے فی عملدرآمد آرڈر جیسی فلیٹ فیس وصول کرنا، ایک بڑی وجہ ہے کہ نوجوان ہندوستانیوں کی پوری نسل نے سرمایہ کاری شروع کردی۔ اس نے کچھ حصص خریدنا واقعی سستا بنا دیا۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>ایک عام ابتدائی غلطی یہ سوچ رہی ہے کہ بروکریج صرف قیمت ہے۔ یہ عام طور پر ہے <em>سب سے چھوٹا</em> حصہ ہر تجارت میں قانونی چارجز بھی ہوتے ہیں، اور چھوٹی تجارتوں کے لیے، یہ بروکریج سے زیادہ کا اضافہ کر سکتے ہیں۔ کو ہمیشہ دیکھیں <em>کل</em> لاگت، نہ صرف بروکریج لائن.</p>\n</div></div>\n<h3 id=\"what-you-actually-pay-on-a-trade\">آپ اصل میں ایک تجارت پر کیا ادا کرتے ہیں</h3>\n<p>دلالی سے پرے، ایک چھوٹی ٹوکری <strong>چارجز اور ٹیکس</strong> ہر تجارت کے ساتھ ساتھ سواری. آپ یہ اپنے بروکر کو منافع کے طور پر ادا نہیں کرتے ہیں، بروکر ان میں سے زیادہ تر کو صرف جمع کرتا ہے اور حکومت یا ایکسچینج کو بھیج دیتا ہے۔ اہم، تمام تخمینی:</p>\n<ul>\n<li><strong>سیکیورٹیز ٹرانزیکشن ٹیکس (STT)</strong>تجارتی قیمت پر حکومتی ٹیکس۔</li>\n<li><strong>ایکسچینج ٹرانزیکشن چارجز</strong>، ایک چھوٹی سی فیس جس کا تبادلہ میچ کے لیے لیتا ہے۔</li>\n<li><strong>GST</strong>بروکریج اور ٹرانزیکشن چارجز پر 18% چارج کیا جاتا ہے۔</li>\n<li><strong>سٹیمپ ڈیوٹی</strong>، خرید پر ایک چھوٹا سا ریاستی محصول۔</li>\n<li><strong>SEBI ٹرن اوور فیس</strong>، ریگولیٹر کو فنڈ فراہم کرنے والا ایک معمولی چارج۔</li>\n<li><strong>DP چارجز</strong>, ایک فلیٹ فیس (اکثر تقریباً 13-20 روپے) جب حصص آپ کے ڈیمیٹ اکاؤنٹ کو فروخت پر چھوڑ دیتے ہیں۔</li>\n</ul>\n<p>سرخی ٹیک وے: بروکریج کی تشہیر \"صفر\" کے طور پر کی جا سکتی ہے، لیکن تجارت کبھی بھی واقعی مفت نہیں ہوتی۔ اچھی خبر یہ ہے کہ ایک طویل مدتی سرمایہ کار خریدنے اور ہولڈنگ کے لیے، یہ اخراجات شاذ و نادر ہی ادا کیے جاتے ہیں اور بہت کم اہمیت رکھتے ہیں۔</p>\n<h2 id=\"the-depository-a-bank-for-your-shares\">ڈیپازٹری: آپ کے حصص کے لیے ایک بینک</h2>\n<p>ایک بار جب آپ حصص خریدتے ہیں، تو وہ اصل میں کہاں ہوتے ہیں۔ <em>زندہ</em>? آپ کے بروکر کی ایپ میں نہیں، یہ صرف ایک ونڈو ہے۔ وہ ایک میں رہتے ہیں۔ <strong>ڈیمیٹ اکاؤنٹ</strong>، ایک میں منعقد <strong>ڈپازٹری</strong>. ڈپازٹری کو ایک بینک کے طور پر سوچیں، لیکن یہ روپے رکھنے کے بجائے آپ کے حصص کو الیکٹرانک طور پر رکھتا ہے۔ جس طرح آپ کا بینک اکاؤنٹ آپ کی رقم کو اسکرین پر ایک نمبر کے طور پر دکھاتا ہے، اسی طرح آپ کا ڈیمیٹ اکاؤنٹ آپ کے حصص کو الیکٹرانک اندراجات کے طور پر دکھاتا ہے۔ \"ڈیمیٹ\" کے لیے مختصر ہے۔ <strong>ڈی میٹریلائزڈ</strong>، یعنی حصص ڈیٹا کے طور پر موجود ہیں، کاغذ نہیں۔</p>\n<p>بھارت کے پاس بالکل ہے۔ <strong>دو ذخیرے</strong>:</p>\n<ul>\n<li><strong>NSDL</strong>نیشنل سیکیورٹیز ڈپازٹری لمیٹڈ، ہندوستان کی پہلی، 1996 میں قائم کی گئی۔</li>\n<li><strong>CDSL</strong>سینٹرل ڈپازٹری سروسز لمیٹڈ۔</li>\n</ul>\n<p>آپ کبھی بھی ان کے ساتھ براہ راست معاملہ نہیں کرتے۔ آپ کا بروکر بطور کام کرتا ہے۔ <strong>ڈپازٹری شرکت کنندہ ( DP)</strong>، آپ اور ڈپازٹری کے درمیان پل، اور دونوں میں سے ایک پر آپ کا ڈیمیٹ اکاؤنٹ کھولتا ہے۔ اس بات سے قطع نظر کہ آپ کے بروکر کی ایپ کے ساتھ کیا ہوتا ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch05-demat-ecosystem.png\" alt=\"ڈیمیٹ ایکو سسٹم، آپ اور آپ کا بروکر ایک طرف، دو ڈپازٹری NSDL اور CDSL دوسری طرف آپ کے حصص کو الیکٹرانک طور پر تھامے ہوئے ہیں۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">انفوگرافک</span>ڈیمیٹ ایکو سسٹم، آپ اور آپ کا بروکر ایک طرف، دو ڈپازٹری NSDL اور CDSL دوسری طرف آپ کے حصص کو الیکٹرانک طور پر تھامے ہوئے ہیں۔</figcaption></figure>\n<h3 id=\"the-demat-revolution\">ڈیمیٹ انقلاب</h3>\n<p>یہ الیکٹرانک دنیا حیرت انگیز طور پر حالیہ ہے۔ 1990 کی دہائی کے اواخر تک، ایک حصہ کا مالک ہونے کا مطلب تھا a <strong>جسمانی کاغذ سرٹیفکیٹ</strong>. فروخت کرنے کا مطلب تھا کہ اس سرٹیفکیٹ کو ملک بھر میں ایک دستخط شدہ ٹرانسفر فارم کے ساتھ کورئیر کرنا، اس کے رجسٹر ہونے کے لیے ہفتوں کا انتظار کرنا، اور دعا کرنا کہ یہ گم، پھٹا، جعلی یا \"خراب ترسیل\" کے تنازعات میں پھنس نہ جائے۔ تصفیہ میں مہینے لگ سکتے ہیں۔ دھوکہ دہی عروج پر تھی۔</p>\n<p>1996 میں NSDL کا آغاز ہوا۔ <strong>ڈیمیٹ انقلاب</strong>کاغذی سرٹیفکیٹ کو الیکٹرانک ریکارڈ میں تبدیل کرنا۔ اس نے ہندوستانی بازاروں کو سست اور پرخطر سے تیز اور محفوظ میں بدل دیا، اور یہ سب سے بڑی وجوہات میں سے ایک ہے جس کی وجہ سے عام لوگ اب چند نلکے سے سرمایہ کاری کر سکتے ہیں۔ آج، فزیکل شیئر سرٹیفکیٹ کا انعقاد بنیادی طور پر ناپید ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>آپ کے حصص ڈپازٹری میں رکھے گئے ہیں ( NSDL یا CDSL)، <strong>نہیں</strong> آپ کے بروکر کی طرف سے. بروکر صرف ایکسیس پوائنٹ ہے۔ یہ علیحدگی ایک جان بوجھ کر حفاظتی ڈیزائن ہے: یہاں تک کہ اگر آپ کا بروکر کل بند ہوجاتا ہے، تب بھی آپ کے حصص ڈپازٹری میں آپ کے ڈیمیٹ اکاؤنٹ میں محفوظ رہیں گے۔</p>\n</div></div>\n<h3 id=\"types-of-demat-account\">ڈیمیٹ اکاؤنٹ کی اقسام</h3>\n<p>ہر ڈیمیٹ اکاؤنٹ ایک جیسا نہیں ہوتا۔ آپ کون ہیں اور آپ کو کس چیز کی ضرورت ہے اس پر منحصر ہے، آپ مٹھی بھر معیاری اقسام میں سے ایک کھولتے ہیں۔ یہاں ہندوستان میں عام ہیں:</p>\n<table>\n<thead>\n<tr>\n<th>ڈیمیٹ اکاؤنٹ کی قسم</th>\n<th>کے لیے موزوں ہے۔</th>\n<th>کلیدی خصوصیت</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><strong>باقاعدہ</strong></td>\n<td>رہائشی افراد</td>\n<td>لامحدود ہولڈنگز</td>\n</tr>\n<tr>\n<td><strong>مشترکہ</strong></td>\n<td>خاندانی / کاروباری شراکت دار</td>\n<td>مشترکہ کنٹرول</td>\n</tr>\n<tr>\n<td><strong>کارپوریٹ</strong></td>\n<td>کمپنیاں، ایل ایل پی</td>\n<td>قانونی ہستی کی تعمیل</td>\n</tr>\n<tr>\n<td><strong>NRI قابل واپسی</strong></td>\n<td>NRE بینک اکاؤنٹ والے NRIs</td>\n<td>رقوم بیرون ملک منتقل کی جا سکتی ہیں۔</td>\n</tr>\n<tr>\n<td><strong>NRI ناقابل واپسی</strong></td>\n<td>NRO اکاؤنٹ والے NRIs</td>\n<td>فنڈز ہندوستان کے اندر رہتے ہیں۔</td>\n</tr>\n<tr>\n<td><strong>BSDA (بنیادی خدمات)</strong></td>\n<td>چھوٹے / ابتدائی سرمایہ کار</td>\n<td>کم یا صفر AMC، ہولڈنگ کی حد کے ساتھ</td>\n</tr>\n<tr>\n<td><strong>حراستی</strong></td>\n<td>نابالغ، سرپرست کے ذریعے</td>\n<td>ایک سرپرست کے ذریعہ چلایا جاتا ہے۔</td>\n</tr>\n<tr>\n<td><strong>پریمیم</strong></td>\n<td>HNIs اور اکثر تاجر</td>\n<td>اضافی خدمات اور تعاون</td>\n</tr>\n</tbody></table>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>اگر آپ ابھی شروعات کر رہے ہیں اور صرف ایک چھوٹی سی رقم رکھیں گے تو ایک کے لیے پوچھیں۔ <strong>BSDA، ایک بنیادی سروسز ڈیمیٹ اکاؤنٹ</strong>. SEBI نے اسے چھوٹے سرمایہ کاروں کے لیے ڈیزائن کیا ہے: سالانہ دیکھ بھال کا چارج (AMC) ہے <strong>4 لاکھ روپے تک کے ہولڈنگز کے لیے صفر</strong> اور صرف ایک چھوٹی سی فیس 10 لاکھ روپے تک، لہذا آپ سالانہ فیس ادا نہیں کر رہے ہیں جب کہ آپ کا پورٹ فولیو ابھی بھی چھوٹا ہے۔ آپ کے پاس صرف ایک BSDA ہو سکتا ہے اور یہ آپ کا واحد ڈیمیٹ اکاؤنٹ ہونا چاہیے، جو ایک ابتدائی کے لیے بالکل درست ہے۔</p>\n</div></div>\n<h2 id=\"the-clearing-corporation-the-guarantor-in-the-middle\">کلیئرنگ کارپوریشن: بیچ میں ضامن</h2>\n<p>ایک آخری، خاموش ہیرو ہے۔ جب آپ خریدتے ہیں اور کوئی اور بیچتا ہے تو آپ کیسے کرتے ہیں؟ <em>جانتے ہیں</em> بیچنے والا اصل میں حصص فراہم کرے گا، اور بیچنے والے کو کیسے معلوم ہوگا کہ آپ اصل میں ادائیگی کریں گے؟ پرانے دنوں میں، اعتماد کی یہ خلیج ڈیفالٹس کا سبب بنتی تھی۔ آج اس کا حل ہے۔ <strong>کلیئرنگ کارپوریشن</strong>.</p>\n<p>کلیئرنگ کارپوریشن ہر تجارت کے بیچ میں قدم رکھتی ہے اور بن جاتی ہے۔ <strong>خریدار ہر بیچنے والے کو اور بیچنے والا ہر خریدار کو</strong>. یہ تجارت کی ضمانت دیتا ہے: خریدار کو ہمیشہ شیئرز ملتے ہیں، بیچنے والے کو ہمیشہ پیسے ملتے ہیں، چاہے ایک طرف ڈیفالٹ ہو۔ یہ ہٹاتا ہے۔ <strong>ہم منصب کا خطرہ</strong>، خطرہ کہ آپ کی تجارت کے دوسری طرف کا شخص ختم ہو جاتا ہے۔ NSE کا کلیئرنگ بازو NSE کلیئرنگ ہے۔ BSE انڈین کلیئرنگ کارپوریشن کے ذریعے کلیئر تجارت کرتا ہے۔ ہم اگلے باب میں اس بات کا جائزہ لیں گے کہ یہ کیسے کام کرتا ہے۔</p>\n<h2 id=\"india-is-opening-demat-accounts-like-never-before\">ہندوستان ڈیمیٹ اکاؤنٹ کھول رہا ہے جیسا کہ پہلے کبھی نہیں تھا۔</h2>\n<p>ان چاروں کو ایک ساتھ رکھیں اور نتیجہ یہ نکلا کہ ایک نظام اتنا سستا اور قابل بھروسہ ہے کہ ہندوستانی اس میں بڑی تعداد میں شامل ہو رہے ہیں۔ کی تعداد <strong>ڈیمیٹ اکاؤنٹس 21.6 کروڑ یعنی تقریباً 216 ملین سے تجاوز کر گئے ہیں۔</strong> (مشترکہ NSDL اور CDSL، دسمبر 2025 تک)، وبائی مرض سے ٹھیک پہلے 4 کروڑ سے کم۔ یہ چند مختصر سالوں میں پانچ گنا سے زیادہ چھلانگ ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch05-demat-account-growth.png\" alt=\"ریٹیل میں تیزی، ہندوستان کے کل ڈیمیٹ اکاؤنٹس 2019 میں 4 کروڑ سے کم ہو کر 2025 کے آخر تک تقریباً 21.6 کروڑ (216 ملین) تک پہنچ گئے، جو کہ مارکیٹ کو دریافت کرنے والی نسل کی ایک تخمینی تصویر ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>ریٹیل میں تیزی، ہندوستان کے کل ڈیمیٹ اکاؤنٹس 2019 میں 4 کروڑ سے کم ہو کر 2025 کے آخر تک تقریباً 21.6 کروڑ (216 ملین) تک پہنچ گئے، جو کہ مارکیٹ کو دریافت کرنے والی نسل کی ایک تخمینی تصویر ہے۔</figcaption></figure>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>ان اکاؤنٹس میں سے، <strong>CDSL بڑی اکثریت رکھتا ہے۔ <em>نمبر</em>ہر پانچ میں سے تقریباً چار اکاؤنٹس، تقریباً 17 کروڑ، جبکہ NSDL اس سے کہیں کم، تقریباً 4 کروڑ رکھتے ہیں۔</strong> اس کے باوجود NSDL اس سے کہیں زیادہ بڑا حصہ رکھتا ہے۔ <em>قدر</em> اثاثوں کا، کیونکہ بڑے ادارے اور سب سے زیادہ قیمت والے ہولڈنگز اس کے ساتھ بیٹھتے ہیں۔ دو ذخیرے، کشش ثقل کے دو بالکل مختلف مراکز۔</p>\n</div></div>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>لیکن ایک اکاؤنٹ <em>کھول دیا</em> ایک سرمایہ کار نہیں ہے <em>کام پر</em>. ان تقریباً 21.6 کروڑ اکاؤنٹس میں سے، NSE کا شمار صرف <strong>4.9 کروڑ بطور فعال</strong>, گزشتہ سال میں ایک بھی تجارت رکھی ہے. بہت سے لوگوں کو نکال باہر کریں جو بروکرز میں کئی اکاؤنٹ رکھتے ہیں (اکثر IPO - الاٹمنٹ کی مشکلات کو بہتر بنانے کے لیے) اور ان کی تعداد <em>الگ</em> سرمایہ کاروں کے قریب ہے <strong>12 کروڑ</strong>. اکاؤنٹس کا ایک بڑا حصہ صرف غیر فعال یا نقل شدہ ہوتا ہے۔ حساب صرف ایک دروازہ ہے۔ <strong>دراصل سرمایہ کاری، صبر اور باقاعدگی سے، اصل قدم ہے۔</strong>اور یہ وہ سفر ہے جسے ہم نقشہ بناتے ہیں جب آپ بطور سرمایہ کار اپنے پہلے قدم اٹھاتے ہیں۔</p>\n</div></div>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>ایک ڈیمیٹ اکاؤنٹ (جس میں حصص ہوتے ہیں) عام طور پر a کے ساتھ جوڑا جاتا ہے۔ <strong>تجارتی اکاؤنٹ</strong> (جو آرڈر دیتا ہے) اور آپ کا <strong>بینک اکاؤنٹ</strong> (جس میں نقدی ہوتی ہے)۔ تینوں مل کر کام کرتے ہیں: بینک خرید کو فنڈ دیتا ہے، ٹریڈنگ اکاؤنٹ اسے رکھتا ہے، ڈیمیٹ اکاؤنٹ شیئرز کو اسٹور کرتا ہے۔ جب آپ ایک سرمایہ کار کے طور پر اپنے پہلے قدم اٹھائیں گے تو ہم ان کو کھولیں گے۔</p>\n</div></div>\n<h2 id=\"quick-recap\">فوری خلاصہ</h2>\n<ul>\n<li>اے <strong>اسٹاک ایکسچینج</strong> (NSE یا BSE) وہ بازار ہے جو خریداروں اور بیچنے والوں سے ملتا ہے، <strong>BSE ایشیا کا سب سے قدیم ہے۔</strong> (1875), <strong>NSE حجم کے لحاظ سے سب سے بڑا ہے۔</strong>.</li>\n<li>اے <strong>بروکر</strong> ایکسچینج کے لیے آپ کا لائسنس یافتہ گیٹ وے ہے؛ <strong>ڈسکاؤنٹ بروکرز</strong> کم فلیٹ فیس چارج کریں، <strong>مکمل سروس بروکرز</strong> مشورہ کے لئے زیادہ چارج کریں.</li>\n<li>بروکریج سے آگے، ہر تجارت چھوٹی ہوتی ہے۔ <strong>چارجز اور ٹیکس</strong> (STT، GST، اسٹامپ ڈیوٹی، ایکسچینج اور DP فیس)، لہذا کوئی بھی تجارت واقعی مفت نہیں ہے۔</li>\n<li>اے <strong>ڈپازٹری</strong> (NSDL یا CDSL) آپ کے حصص کے لیے ایک بینک ہے؛ آپ کا <strong>ڈیمیٹ اکاؤنٹ</strong> انہیں الیکٹرانک طور پر رکھتا ہے، محفوظ ہے چاہے آپ کا بروکر غائب ہو جائے۔</li>\n<li>دی <strong>ڈیمیٹ انقلاب</strong> پرخطر کاغذی سرٹیفکیٹس کو الیکٹرانک ریکارڈ سے تبدیل کر دیا گیا، اور اب بھارت کے پاس تقریباً <strong>21.6 کروڑ ڈیمیٹ اکاؤنٹس</strong> (دسمبر 2025)، اگرچہ صرف ایک حصہ فعال طور پر تجارت کرتا ہے۔</li>\n<li>دی <strong>کلیئرنگ کارپوریشن</strong> ہر تجارت کی ضمانت دیتا ہے، اس خطرے کو دور کرتا ہے جو دوسری طرف ڈیفالٹ کرتا ہے۔</li>\n</ul>\n<p>اگلا، ہم آپ کے آرڈر کی پیروی کرتے ہیں خریدیں کے کلک کے بعد اور پلمبنگ میں، تجارت کیسی ہوتی ہے۔ <em>صاف اور آباد</em>اور کیوں، T+1 کی بدولت، آپ کے حصص تقریباً اگلے ہی دن ظاہر ہوتے ہیں۔</p>\n","toc":[{"level":2,"text":"تبادلہ: ایک بڑا منظم بازار","id":"the-exchange-a-giant-organised-marketplace"},{"level":2,"text":"جب بازار کھلا۔","id":"when-the-market-is-open"},{"level":2,"text":"کون تجارت کر رہا ہے: مارکیٹ کے شرکاء","id":"who-is-trading-the-market-participants"},{"level":2,"text":"بروکر: ایکسچینج کے لیے آپ کا گیٹ وے","id":"the-broker-your-gateway-to-the-exchange"},{"level":3,"text":"آپ اصل میں ایک تجارت پر کیا ادا کرتے ہیں","id":"what-you-actually-pay-on-a-trade"},{"level":2,"text":"ڈیپازٹری: آپ کے حصص کے لیے ایک بینک","id":"the-depository-a-bank-for-your-shares"},{"level":3,"text":"ڈیمیٹ انقلاب","id":"the-demat-revolution"},{"level":3,"text":"ڈیمیٹ اکاؤنٹ کی اقسام","id":"types-of-demat-account"},{"level":2,"text":"کلیئرنگ کارپوریشن: بیچ میں ضامن","id":"the-clearing-corporation-the-guarantor-in-the-middle"},{"level":2,"text":"ہندوستان ڈیمیٹ اکاؤنٹ کھول رہا ہے جیسا کہ پہلے کبھی نہیں تھا۔","id":"india-is-opening-demat-accounts-like-never-before"},{"level":2,"text":"فوری خلاصہ","id":"quick-recap"}],"imgCount":4,"hasContent":true},"6":{"html":"<p>آپ نے آج صبح 10:15 پر ریلائنس کے 10 شیئرز خریدے۔ جب تک آپ نے اپنا فون لاک کیا، آرڈر میں کہا گیا کہ \"عمل درآمد\" ہو گیا اور حصص آپ کے پورٹ فولیو میں ظاہر ہو گئے۔ کیا اور خاک، ٹھیک ہے؟ بالکل نہیں۔ اس وقت، کوئی حصص اور کوئی پیسہ نہیں اصل میں ہاتھ بدلا ہے۔ جو آپ نے دیکھا وہ تھا۔ <em>وعدہ</em>، ایک پابند معاہدہ جسے آپ ادا کریں گے اور بیچنے والا فراہم کرے گا۔ حصص کے لیے پیسے کا حقیقی تبادلہ بعد میں، پردے کے پیچھے، نامی عمل کے ذریعے ہوتا ہے۔ <strong>تصفیہ</strong>.</p>\n<p>یہ بازار کی غیر مسحور کن پلمبنگ ہے، اور یہ ایک وجہ سے سمجھنے کے قابل ہے: یہ وہ حصہ ہے جو ہر چیز کو بناتا ہے۔ <em>قابل اعتماد</em>. جب یہ مشینری کام کرتی ہے، اور ہندوستان میں یہ تقریباً ہمیشہ ہی کام کرتی ہے، تو آپ ملک کے دوسری طرف کسی مکمل اجنبی سے خرید سکتے ہیں اور یقین رکھ سکتے ہیں کہ آپ کو آپ کے حصص مل جائیں گے، اور انہیں ان کے پیسے مل جائیں گے۔ آئیے ہڈ کھولیں۔</p>\n<h2 id=\"a-trade-is-a-promise-settlement-is-the-delivery\">تجارت ایک وعدہ ہے۔ تصفیہ ترسیل ہے</h2>\n<p>اس باب میں واحد سب سے مفید خیال یہ ہے کہ a <strong>تجارت</strong> اور اس کے <strong>تصفیہ</strong> وقت میں دو الگ الگ لمحات ہیں۔</p>\n<ul>\n<li>دی <strong>تجارت</strong> یہ معاہدہ ہے: 10:15 پر، ایک خریدار اور بیچنے والے نے 10 حصص کی قیمت پر اتفاق کیا۔ تبادلہ ان سے ملا۔ ایک معاہدہ موجود ہے، لیکن صرف کاغذ پر.</li>\n<li>دی <strong>تصفیہ</strong> یہ تکمیل ہے: خریدار کا پیسہ دراصل بیچنے والے کے پاس جاتا ہے، اور بیچنے والے کے حصص دراصل خریدار کے پاس جاتے ہیں۔ یہ گھنٹوں یا ایک دن بعد ہوتا ہے۔</li>\n</ul>\n<p>ان دو لمحوں کے درمیان دو چیزوں کا پتہ لگانا اور پھر ان پر عمل کرنا ہے۔ کام کرنا <em>کس کا مقروض ہے</em> کہا جاتا ہے <strong>صاف کرنا</strong>. اصل میں <em>رقم اور حصص کو منتقل کرنا</em> کہا جاتا ہے <strong>تصفیہ</strong>.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch06-trade-lifecycle.png\" alt=\"تجارت کی زندگی، T کے دن مماثل آرڈر سے لے کر، کلیئرنگ اور اوبلی گیشن نیٹنگ کے ذریعے، T+1 پر رقم اور حصص کی تصفیہ تک۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">فلو چارٹ</span>تجارت کی زندگی، T کے دن مماثل آرڈر سے لے کر، کلیئرنگ اور اوبلی گیشن نیٹنگ کے ذریعے، T+1 پر رقم اور حصص کی تصفیہ تک۔</figcaption></figure>\n<h2 id=\"clearing-working-out-who-owes-what\">کلیئرنگ: یہ معلوم کرنا کہ کس کا واجب الادا ہے۔</h2>\n<p>کسی بھی دن، آپ ریلائنس کے 10 حصص خرید سکتے ہیں، 5 بیچ سکتے ہیں، اور 8 مزید خرید سکتے ہیں۔ اس کو کروڑوں سرمایہ کاروں کی کروڑوں تجارت سے ضرب دیں، اور تبادلے میں ذمہ داریوں کا ایک الجھا ہوا جال ہے۔ <strong>صاف کرنا</strong> ہر شریک کے لیے اسے الجھانے، حساب لگانے کا عمل ہے۔ <em>نیٹ</em> رقم اور حصص کی رقم جو ان پر واجب الادا ہیں یا دن کے اختتام پر واجب الادا ہیں۔</p>\n<p>یہاں کلیدی چال ہے۔ <strong>جال</strong>. ہر ایک تجارت کو انفرادی طور پر طے کرنے کے بجائے، کلیئرنگ کارپوریشن آپ کی تمام خرید و فروخت کو اسٹاک میں شامل کرتی ہے اور آپ کے <em>نیٹ</em> پوزیشن اگر آپ نے اسی حصص میں سے 10 خریدے اور 5 بیچے، تو آپ کو صرف 5 خالص حصص حاصل کرنے کی ضرورت ہے، 15 کو الگ سے شفل کرنے کی ضرورت نہیں۔ نیٹنگ انفرادی تجارت کے ایک پہاڑ کو فی سیکورٹی فی سرمایہ کار ایک صاف ستھرا اعداد و شمار میں ڈھا دیتی ہے۔ یہ کروڑوں کی تجارت کو طے کرنے اور مٹھی بھر خالص ذمہ داریوں کو طے کرنے کے درمیان فرق ہے، ایک بہت بڑی کارکردگی۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p><strong>کلیئرنگ جوابات \"کس کا مقروض ہے؟\" تصفیہ کے جوابات \"اب آئیے اصل میں ادائیگی کریں اور ڈیلیور کریں۔\"</strong> کلیئرنگ اکاؤنٹنگ ہے؛ تصفیہ عمل ہے. کلیئرنگ کارپوریشن پہلا کام کرتی ہے اور دوسرا آرکیسٹریٹ کرتی ہے۔</p>\n</div></div>\n<h2 id=\"settlement-the-actual-swap\">تصفیہ: اصل تبادلہ</h2>\n<p>ایک بار جب کلیئرنگ نے ہر ایک کی خالص ذمہ داریاں پیدا کر دیں، <strong>تصفیہ</strong> انہیں پھانسی دیتا ہے. تصفیہ کے دن، نظام بیک وقت دو کام کرتا ہے:</p>\n<ul>\n<li><strong>ادائیگی میں</strong>خریداروں کے پیسے اور بیچنے والوں کے حصص جمع کیے جاتے ہیں۔ خریداروں کے بینک کھاتوں سے رقم ڈیبٹ کی جاتی ہے۔ حصص بیچنے والوں کے ڈیمیٹ اکاؤنٹس سے ڈیبٹ کیے جاتے ہیں۔</li>\n<li><strong>پے آؤٹ</strong>حصص خریداروں کے ڈیمیٹ اکاؤنٹس میں جمع کیے جاتے ہیں، اور رقم بیچنے والوں کے بینک اکاؤنٹس میں جمع کر دی جاتی ہے۔</li>\n</ul>\n<p>یہ بیک وقت تبادلہ مکمل نقطہ ہے۔ خریدار کے حصے نقدی کے ساتھ <em>کے طور پر</em> وہ حصص وصول کرتے ہیں؛ حصص کے ساتھ بیچنے والے حصے <em>کے طور پر</em> وہ نقد وصول کرتے ہیں. کسی بھی فریق کو براہ راست دوسرے پر بھروسہ نہیں کرنا چاہئے، کیونکہ کلیئرنگ کارپوریشن دونوں ٹانگوں کو ایک ساتھ ہینڈل کرتی ہے۔</p>\n<h2 id=\"rolling-settlement-and-the-road-to-t-1\">رولنگ سیٹلمنٹ اور T+1 کی سڑک</h2>\n<p>اس میں کتنا وقت لگتا ہے؟ ایک میں <strong>رولنگ تصفیہ</strong> نظام، تجارت تجارتی تاریخ کے بعد کاروباری دنوں کی ایک مقررہ تعداد کو طے کرتی ہے۔ تجارتی دن کہا جاتا ہے۔ <strong>ٹی</strong>، اور تصفیہ کچھ دنوں کے بعد ہوتا ہے۔</p>\n<p>ہندوستان نے سالوں کے دوران اس فرق کو مستقل طور پر کم کیا ہے، اور یہ ایک حقیقی فخر کی بات ہے:</p>\n<table>\n<thead>\n<tr>\n<th>دور</th>\n<th>سائیکل</th>\n<th>اس کا کیا مطلب تھا۔</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>2001 تک</td>\n<td>ہفت روزہ \"بدلہ\" بستی۔</td>\n<td>ہفتے میں ایک بار تجارت کا ڈھیر لگا اور آباد ہو گئے۔</td>\n</tr>\n<tr>\n<td>2002</td>\n<td>T+3</td>\n<td>تجارت کے بعد تین کام کے دنوں میں طے کریں۔</td>\n</tr>\n<tr>\n<td>2003</td>\n<td>T+2</td>\n<td>دو دن، دو دہائیوں کے لئے عالمی معیار</td>\n</tr>\n<tr>\n<td><strong>جنوری 2023</strong></td>\n<td><strong>T+1</strong></td>\n<td><strong>اگلے ہی کام کے دن طے کریں۔</strong></td>\n</tr>\n<tr>\n<td>2024-25</td>\n<td>اختیاری T+0</td>\n<td>اسی دن کا تصفیہ، مرحلہ وار کیا جا رہا ہے۔</td>\n</tr>\n</tbody></table>\n<p>میں <strong>جنوری 2023، ہندوستان نے T+1 میں اپنا قدم مکمل کیا۔</strong>یعنی آج کی جانے والی تجارت کل طے پاتی ہے۔ اہم طور پر، <strong>ہندوستان T+1 کو مکمل طور پر اپنانے والی دنیا کی پہلی بڑی منڈیوں میں شامل تھا۔</strong> امریکہ، سیاق و سباق کے لیے، صرف T+1 میں منتقل ہوا۔ <strong>مئی 2024</strong>، ایک سال سے زیادہ <em>کے بعد</em> انڈیا ایک دفعہ کے لیے، انڈیا کی مارکیٹ پلمبنگ وال سٹریٹ سے آگے تھی۔</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>جنوری 2023 میں جب ہندوستان مکمل طور پر T+1 میں تبدیل ہوا، تو اس نے ترقی یافتہ دنیا کو پیچھے چھوڑ دیا۔ US، UK اور یورپ اس وقت بھی سست T+2 سائیکل پر تھے۔ ایک مارکیٹ جسے اکثر \"ابھرتی ہوئی\" کے طور پر دیکھا جاتا ہے، سیٹلمنٹ کی رفتار پر، سیارے کی قیادت کر رہا تھا۔</p>\n</div></div>\n<h3 id=\"what-t-1-actually-feels-like\">اصل میں T+1 کیسا محسوس ہوتا ہے۔</h3>\n<p>آپ کے لیے بطور سرمایہ کار، T+1 کا مطلب حقیقی سہولت ہے۔ آج ہی اپنے حصص بیچیں، اور پیسے اگلے کام کے دن آپ کے اکاؤنٹ میں قابل استعمال ہوں گے۔ آج ہی خریدیں، اور حصص مضبوطی سے آپ کے ہیں، اگلے دن ڈیلیوری کے قابل۔ تیز تر تصفیہ کا مطلب یہ بھی ہے کہ چیزوں کے درمیان غلط ہونے میں کم وقت ہوتا ہے، جو نہ صرف تیز بلکہ پورے نظام کو محفوظ بناتا ہے۔</p>\n<h2 id=\"t-0-the-same-day-experiment\">T+0: ایک ہی دن کا تجربہ</h2>\n<p>ہندوستان T+1 پر نہیں رکا۔ میں <strong>مارچ 2024</strong>، SEBI نے شروع کیا a <strong>اختیاری T+0 تصفیہ کا بیٹا</strong>, اسی دن کی تصفیہ، جہاں پیسے اور حصص اسی دن بدل جاتے ہیں جس دن آپ تجارت کرتے ہیں۔ سے <strong>ابتدائی 2025</strong>، اس نے ایک مرحلہ وار رول آؤٹ شروع کیا۔ <strong>سب سے اوپر 500 اسٹاک</strong> مارکیٹ ویلیو کے لحاظ سے، ایک وقت میں تقریباً 100 اسٹاک کا اضافہ کرنا۔</p>\n<p>سیدھا رکھنے کے لیے چند چیزیں:</p>\n<ul>\n<li>T+0 ہے۔ <strong>اختیاری</strong>، چل رہا ہے۔ <em>ساتھ ساتھ</em> T+1، اس کی جگہ نہیں لے رہا ہے۔ آپ اور آپ کا بروکر انتخاب کرتے ہیں۔</li>\n<li>یہ بڑے اسٹاک کی ایک متعین فہرست پر لاگو ہوتا ہے، آہستہ آہستہ پھیلتا ہے۔</li>\n<li>مقصد ایک ہی دن کی لیکویڈیٹی ہے، صبح فروخت کریں، اسی دوپہر میں نقد رقم حاصل کریں۔</li>\n</ul>\n<p>یہ ایک ایسا تجربہ ہے جو، اگر یہ کامیاب ہو جاتا ہے، تو ہندوستان کو ایک ہی دن کے مرکزی دھارے کے ساتھ کہیں بھی پہلی منڈیوں میں سے ایک بنا سکتا ہے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>روزہ کو الجھن میں نہ ڈالیں۔ <em>تصفیہ</em> انٹرا ڈے ٹریڈنگ کے ساتھ سائیکل۔ T+1 اور T+0 اس بارے میں ہیں کہ کتنی جلدی a <em>مکمل</em> تجارت کو حتمی شکل دیتا ہے۔ آپ پہلے سے ہی ایک ہی اسٹاک کو ایک ہی دن (انٹرا ڈے) میں خرید سکتے ہیں اور بیچ سکتے ہیں، قطع نظر کہ یہ ایک مختلف خصوصیت ہے۔ تصفیہ اس وقت ہوتا ہے جب دھول آخر کار ملکیت اور نقدی پر جم جاتی ہے۔</p>\n</div></div>\n<h2 id=\"the-clearing-corporation-the-guarantor-in-the-middle\">کلیئرنگ کارپوریشن: بیچ میں ضامن</h2>\n<p>اب سب کا سب سے اہم حفاظتی خیال۔ جب آپ خریدتے ہیں، تو آپ کیسے ہوسکتے ہیں <em>یقینی طور پر</em> گمنام بیچنے والے فراہم کرے گا؟ آپ نہیں کر سکتے، اور آپ کو کرنے کی ضرورت نہیں ہے۔ دی <strong>کلیئرنگ کارپوریشن</strong> ہر تجارت کے مرکز میں قدم رکھتا ہے اور قانونی طور پر بن جاتا ہے۔ <strong>خریدار ہر بیچنے والے کو اور بیچنے والا ہر خریدار کو</strong>. اسے کہتے ہیں۔ <strong>جدت</strong>.</p>\n<p>اس کی وجہ سے، آپ کبھی بھی دوسری طرف کے اجنبی پر بھروسہ نہیں کر رہے ہیں۔ آپ کلیئرنگ کارپوریشن پر انحصار کر رہے ہیں، اور یہ تجارت کی ضمانت دیتا ہے۔ خریدار کو ان کے حصص کی ضمانت دی جاتی ہے۔ بیچنے والے کو ان کے پیسے کی ضمانت دی جاتی ہے۔ دوسرا فریق ختم ہونے کا خطرہ <strong>ہم منصب کا خطرہ</strong>، مکمل طور پر ہٹا دیا گیا ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch06-clearing-guarantor.png\" alt=\"کلیئرنگ کارپوریشن بیچ میں ضامن کے طور پر بیٹھتی ہے، وہ ہر بیچنے والے کے لیے خریدار اور ہر خریدار کے لیے بیچنے والی بن جاتی ہے، اس لیے کسی بھی فریق کو دوسرے پر اعتماد نہیں کرنا پڑتا۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>کلیئرنگ کارپوریشن بیچ میں ضامن کے طور پر بیٹھتی ہے، وہ ہر بیچنے والے کے لیے خریدار اور ہر خریدار کے لیے بیچنے والی بن جاتی ہے، اس لیے کسی بھی فریق کو دوسرے پر اعتماد نہیں کرنا پڑتا۔</figcaption></figure>\n<h3 id=\"why-settlement-failures-are-vanishingly-rare\">تصفیہ کی ناکامیاں نایاب کیوں ہیں؟</h3>\n<p>اگر کلیئرنگ کارپوریشن ہر چیز کی ضمانت دیتی ہے، تو کیا ہوتا ہے جب کوئی حقیقی طور پر ادائیگی یا ڈیلیور کرنے میں ناکام ہو جاتا ہے؟ یہ آرمر کی تہوں سے محفوظ ہے۔ <em>پہلے</em> یہاں تک کہ تجارت کی اجازت ہے:</p>\n<ul>\n<li><strong>حاشیہ</strong>، تاجروں کو حفاظتی کشن کے طور پر رقم پیشگی جمع کرنی چاہیے، تاکہ گیم میں ان کی جلد موجود ہو۔</li>\n<li><strong>سیٹلمنٹ گارنٹی فنڈ (SGF)</strong>, رقم کا ایک بڑا پول خاص طور پر ایک سیٹلمنٹ مکمل کرنے کے لیے رکھا جاتا ہے اگر کوئی ممبر ڈیفالٹ کرتا ہے۔</li>\n<li><strong>نیلامی اور جرمانے</strong>اگر کوئی بیچنے والا حصص کی فراہمی میں ناکام ہو جاتا ہے، تو نظام خریدار کو پورا کرنے کے لیے انہیں کھلی مارکیٹ میں خریدتا ہے، اور ڈیفالٹر کو جرمانہ کرتا ہے۔</li>\n</ul>\n<p>ایک ساتھ جمع، یہ ہندوستان میں غیر معمولی طور پر ایک حقیقی تصفیہ کی ناکامی کا باعث بنتے ہیں۔ گارنٹی کی تقریباً کبھی جانچ نہیں کرنی پڑتی ہے، یہی وجہ ہے کہ سرمایہ کار بغیر سوچے سمجھے مکمل اجنبیوں کے ساتھ تجارت کر سکتے ہیں۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>آپ کسی ایسے شخص سے حصص خرید سکتے ہیں جس سے آپ کبھی نہیں ملیں گے، ایک دور دراز شہر میں، پورے اعتماد کے ساتھ، <strong>کلیئرنگ کارپوریشن کی گارنٹی</strong>. یہ خاموشی سے اس خطرے کو جذب کر لیتا ہے جو دوسری طرف ڈیفالٹ ہو جاتا ہے، ایمان کی چھلانگ کو معمول، بورنگ، محفوظ لین دین میں بدل دیتا ہے۔</p>\n</div></div>\n<h2 id=\"closing-price-is-not-the-settlement-cycle-vwap-and-cas\">اختتامی قیمت سیٹلمنٹ سائیکل نہیں ہے: VWAP اور CAS</h2>\n<p>لفظ <strong>تصفیہ</strong> مشتقات میں بھی استعمال ہوتا ہے جب کوئی ایکسچینج آفیشل کلوزنگ ویلیو کا انتخاب کرتا ہے جس کے خلاف میعاد ختم ہونے والے معاہدے کی پیمائش کی جاتی ہے۔ یہ اس باب میں بیان کردہ حصص اور رقم کی T+1 یا T+0 کی نقل و حرکت سے مختلف ہے۔</p>\n<p>سے <strong>3 اگست 2026</strong>، بھارت استعمال کرتا ہے a <strong>اختتامی نیلامی سیشن ( CAS)</strong> ان اسٹاکس کی آفیشل کیش-مارکیٹ بند ہونے والی قیمت کا تعین کرنے کے لیے جن پر مشتق معاہدے دستیاب ہیں۔ ان کی مسلسل کیش ٹریڈنگ 15:15 پر رک جاتی ہے۔ ایکسچینج اسٹاک کی 15:00-15:15 VWAP سے ایک حوالہ قیمت کا حساب لگاتا ہے، CAS کے دوران آرڈر جمع کرتا ہے، اور ایک متوازن قیمت کا انتخاب کرتا ہے جو قابل عمل مقدار کو زیادہ سے زیادہ بناتا ہے۔ آرڈر کا اندراج 15:28 اور 15:30 کے درمیان تصادفی طور پر بند ہوجاتا ہے، 15:35 تک مماثلت ختم ہوجاتی ہے، اور عام CAS بینڈ حوالہ قیمت کے ارد گرد جمع یا مائنس 3% ہوتا ہے۔</p>\n<p>اگر کوئی متوازن قیمت دریافت نہیں ہوتی ہے، تو حوالہ قیمت قریب ہو جاتی ہے۔ CAS میں شامل سیکیورٹیز 15:30 تک ٹریڈنگ جاری رکھیں اور پچھلے آخری 30 منٹ VWAP بند کرنے کا طریقہ برقرار رکھیں۔ ایکویٹی ڈیریویٹوز CAS میں داخل نہیں ہوتے ہیں۔ وہ 15:40 تک تجارت کرتے ہیں اور ان کا اپنا معاہدہ 15:10-15:40 VWAP تک رہتا ہے۔ ایک انڈیکس بھی علیحدہ نیلامی میں داخل نہیں ہوتا ہے، لیکن اس کی حتمی قیمت اس کے جزوی اسٹاک کی سرکاری بند ہونے والی قیمتوں کی عکاسی کرتی ہے۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>CAS تبدیلیاں <strong>اختتامی قیمت کی دریافت</strong>، T+1/T+0 سیٹلمنٹ سائیکل نہیں۔ دیکھیں <a href=\"https://www.sebi.gov.in/legal/circulars/jan-2026/introduction-of-closing-auction-session-cas-in-the-equity-cash-segment-and-certain-modifications-in-the-pre-open-auction-session_99122.html\">SEBI CAS سرکلر</a>, the <a href=\"https://nsearchives.nseindia.com/web/mediaattachment/2026-07/FAQs_on_Closing_Auction_Session_CAS_in_the_CM_and_changes_in_FO_Segment_ver1_20260706173436.pdf\">NSECASFAQ</a>، اور <a href=\"https://groww.in/blog/closing-auction-session\">Groww کی کام کی وضاحت</a>.</p>\n</div></div>\n<h2 id=\"closing-price-is-not-the-settlement-cycle-vwap-and-cas\">اختتامی قیمت سیٹلمنٹ سائیکل نہیں ہے: VWAP اور CAS</h2>\n<p>لفظ <strong>تصفیہ</strong> مشتقات میں بھی استعمال ہوتا ہے جب کوئی ایکسچینج آفیشل کلوزنگ ویلیو کا انتخاب کرتا ہے جس کے خلاف میعاد ختم ہونے والے معاہدے کی پیمائش کی جاتی ہے۔ یہ اس باب میں بیان کردہ حصص اور رقم کی T+1 یا T+0 کی نقل و حرکت سے مختلف ہے۔</p>\n<p>سے <strong>3 اگست 2026</strong>، بھارت استعمال کرتا ہے a <strong>اختتامی نیلامی سیشن ( CAS)</strong> ان اسٹاکس کی آفیشل کیش-مارکیٹ بند ہونے والی قیمت کا تعین کرنے کے لیے جن پر ڈیریویٹیو کنٹریکٹس دستیاب ہیں۔ ان کی مسلسل کیش ٹریڈنگ 15:15 پر رک جاتی ہے۔ ایکسچینج اسٹاک کی 15:00-15:15 VWAP سے ایک حوالہ قیمت کا حساب لگاتا ہے، CAS کے دوران آرڈر جمع کرتا ہے، اور ایک متوازن قیمت کا انتخاب کرتا ہے جو قابل عمل مقدار کو زیادہ سے زیادہ بناتا ہے۔ آرڈر کا اندراج 15:28 اور 15:30 کے درمیان تصادفی طور پر بند ہوجاتا ہے، مماثل 15:35 تک ختم ہوجاتا ہے، اور عام CAS بینڈ حوالہ قیمت کے ارد گرد جمع یا مائنس 3% ہوتا ہے۔</p>\n<p>اگر کوئی متوازن قیمت دریافت نہیں ہوتی ہے، تو حوالہ قیمت قریب ہو جاتی ہے۔ CAS میں شامل سیکیورٹیز 15:30 تک ٹریڈنگ جاری رکھیں اور پچھلے آخری 30 منٹ VWAP بند کرنے کا طریقہ برقرار رکھیں۔ ایکویٹی ڈیریویٹوز CAS میں داخل نہیں ہوتے ہیں۔ وہ 15:40 تک تجارت کرتے ہیں اور ان کا اپنا معاہدہ 15:10-15:40 VWAP تک رہتا ہے۔ ایک انڈیکس بھی علیحدہ نیلامی میں داخل نہیں ہوتا ہے، لیکن اس کی حتمی قیمت اس کے جزوی اسٹاک کی سرکاری بند ہونے والی قیمتوں کی عکاسی کرتی ہے۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>CAS تبدیلیاں <strong>اختتامی قیمت کی دریافت</strong>، T+1/T+0 سیٹلمنٹ سائیکل نہیں۔ دیکھیں <a href=\"https://www.sebi.gov.in/legal/circulars/jan-2026/introduction-of-closing-auction-session-cas-in-the-equity-cash-segment-and-certain-modifications-in-the-pre-open-auction-session_99122.html\">SEBI CAS سرکلر</a>, the <a href=\"https://nsearchives.nseindia.com/web/mediaattachment/2026-07/FAQs_on_Closing_Auction_Session_CAS_in_the_CM_and_changes_in_FO_Segment_ver1_20260706173436.pdf\">NSECASFAQ</a>، اور <a href=\"https://groww.in/blog/closing-auction-session\">Groww کی کام کی وضاحت</a>.</p>\n</div></div>\n<h2 id=\"quick-recap\">فوری خلاصہ</h2>\n<ul>\n<li>اے <strong>تجارت</strong> خریدار اور بیچنے والے کے مماثل ہونے پر کیا جانے والا وعدہ ہے۔ <strong>تصفیہ</strong> جب پیسہ اور حصص حقیقت میں ہاتھ بدلتے ہیں، دو الگ الگ لمحات۔</li>\n<li><strong>صاف کرنا</strong> کام کرتا ہے کہ کس کا واجب الادا ہے (استعمال کرتے ہوئے <strong>جال</strong> بہت ساری تجارتوں کو صاف ستھرا اعداد و شمار میں سمیٹنا؛ <strong>تصفیہ</strong> اصل ادائیگی اور ادائیگی کو انجام دیتا ہے۔</li>\n<li>بھارت استعمال کرتا ہے۔ <strong>رولنگ تصفیہ</strong> اور اپنی حرکت مکمل کر لی <strong>جنوری 2023 میں T+1</strong>دنیا کی پہلی بڑی منڈیوں میں، US سے آگے۔</li>\n<li>SEBI نے متعارف کرایا <strong>اختیاری T+0 (اسی دن) تصفیہ</strong> 2024-25 سے، ٹاپ 500 اسٹاکس میں مرحلہ وار کیا جا رہا ہے۔</li>\n<li>دی <strong>کلیئرنگ کارپوریشن</strong> ہر بیچنے والے کے لیے خریدار بن جاتا ہے اور ہر خریدار کو بیچنے والا، ہٹاتا ہے۔ <strong>ہم منصب کا خطرہ</strong> اور تجارت کی ضمانت دیتا ہے۔</li>\n<li>کا شکریہ <strong>مارجن، سیٹلمنٹ گارنٹی فنڈ اور نیلامی</strong>، تصفیہ کی ناکامیاں انتہائی نایاب ہیں۔</li>\n</ul>\n<p>اس کے بعد، ہم ایک کمپنی کی زندگی کے آغاز کے تمام راستے کو ریوائنڈ کرتے ہیں، کہ کس طرح ایک چھوٹا سا سٹارٹ اپ پیسہ اکٹھا کرتا ہے، ایک خیال سے اتنا بڑا کاروبار بنتا ہے کہ ایک دن آپ کو اس کے حصص فروخت کر دے۔</p>\n","toc":[{"level":2,"text":"تجارت ایک وعدہ ہے۔ تصفیہ ترسیل ہے","id":"a-trade-is-a-promise-settlement-is-the-delivery"},{"level":2,"text":"کلیئرنگ: یہ معلوم کرنا کہ کس کا واجب الادا ہے۔","id":"clearing-working-out-who-owes-what"},{"level":2,"text":"تصفیہ: اصل تبادلہ","id":"settlement-the-actual-swap"},{"level":2,"text":"رولنگ سیٹلمنٹ اور T+1 کی سڑک","id":"rolling-settlement-and-the-road-to-t-1"},{"level":3,"text":"اصل میں T+1 کیسا محسوس ہوتا ہے۔","id":"what-t-1-actually-feels-like"},{"level":2,"text":"T+0: ایک ہی دن کا تجربہ","id":"t-0-the-same-day-experiment"},{"level":2,"text":"کلیئرنگ کارپوریشن: بیچ میں ضامن","id":"the-clearing-corporation-the-guarantor-in-the-middle"},{"level":3,"text":"تصفیہ کی ناکامیاں نایاب کیوں ہیں؟","id":"why-settlement-failures-are-vanishingly-rare"},{"level":2,"text":"اختتامی قیمت سیٹلمنٹ سائیکل نہیں ہے: VWAP اور CAS","id":"closing-price-is-not-the-settlement-cycle-vwap-and-cas"},{"level":2,"text":"اختتامی قیمت سیٹلمنٹ سائیکل نہیں ہے: VWAP اور CAS","id":"closing-price-is-not-the-settlement-cycle-vwap-and-cas"},{"level":2,"text":"فوری خلاصہ","id":"quick-recap"}],"imgCount":2,"hasContent":true},"7":{"html":"<p>ہر وہ بڑی کمپنی جس کے حصص کی قیمت آپ کی سکرین پر اسکرول کرتی ہے، Infosys، Zomato، Reliance، ایک زمانے میں تقریباً ہنسنے والی چھوٹی چیز تھی: چند لوگ، ایک آئیڈیا، اور اسے حقیقی بنانے کے لیے اتنی رقم نہیں تھی۔ کوئی بھی ایک لاکھ کروڑ روپے کی کمپنی میں پیدا نہیں ہوتا۔ وہ وہاں چڑھتے ہیں، ایک وقت میں ایک فنڈنگ ​​راؤنڈ، نقد بڑھنے کے لیے ملکیت کے ٹکڑوں کی تجارت کرتے ہیں۔ اس وقت تک جب کمپنی کے حصص آپ کے خریدنے کے لیے NSE یا BSE پر آتے ہیں، یہ عام طور پر ایک طویل، ڈرامائی مالی زندگی گزار چکی ہے جسے آپ نے کبھی نہیں دیکھا۔</p>\n<p>اس باب میں اس چھپے ہوئے سفر کا پتہ لگایا گیا ہے۔ <strong>فنڈنگ ​​سیڑھی</strong> ایک کاروبار خیال سے IPO پر چڑھتا ہے۔ اسے سمجھنے سے دو کام ہوتے ہیں۔ یہ ظاہر کرتا ہے کہ درج کمپنیاں اصل میں کہاں سے آتی ہیں۔ اور یہ وضاحت کرتا ہے۔ <em>کیوں</em> ایک کمپنی بالآخر عوام کو حصص فروخت کرنے کا فیصلہ کرتی ہے، جو کہ آخر کار اس لمحے ہے جب آپ کو اس کا ایک حصہ مل جائے گا۔</p>\n<h2 id=\"the-funding-ladder\">فنڈنگ ​​سیڑھی۔</h2>\n<p>ایک سیڑھی کی تصویر بنائیں۔ نیچے ایک خیال ہے جس میں پیسے نہیں ہیں۔ سب سے اوپر ایک کمپنی ہے جو عوام کو حصص فروخت کرتی ہے۔ ہر ایک قدرے بڑے، زیادہ پیشہ ور ذریعہ سے تھوڑا سا زیادہ پیسہ اکٹھا کرتا ہے، اور ہر دوڑ پر، بانی بدلے میں ملکیت کا ایک ٹکڑا چھوڑ دیتے ہیں۔ یہاں چڑھائی ہے.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch07-funding-ladder.png\" alt=\"فنڈنگ ​​کی سیڑھی، ایک آئیڈیا اور بانی کی اپنی بچت سے، فرشتوں اور وینچر کیپیٹل راؤنڈز کے ذریعے، پرائیویٹ ایکویٹی تک، اور آخر میں ایک عوامی فہرست\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">فلو چارٹ</span>فنڈنگ ​​کی سیڑھی، ایک آئیڈیا اور بانی کی اپنی بچت سے، فرشتوں اور وینچر کیپیٹل راؤنڈز کے ذریعے، پرائیویٹ ایکویٹی تک، اور آخر میں ایک عوامی فہرست</figcaption></figure>\n<h3 id=\"rung-0-the-idea\">رنگ 0، خیال</h3>\n<p>یہ ایک ایسے مسئلے سے شروع ہوتا ہے جسے کوئی حل کرنا چاہتا ہے اور تقریباً کوئی رقم نہیں ہے۔ اس مرحلے پر \"کمپنی\" صرف ایک پچ ڈیک اور اختتام ہفتہ پر بنایا گیا ایک پروٹو ٹائپ ہو سکتا ہے۔</p>\n<h3 id=\"rung-1-bootstrapping\">رنگ 1، بوٹسٹریپنگ</h3>\n<p><strong>بوٹسٹریپنگ</strong> مطلب بانی کے ساتھ کاروبار کو فنڈ دینا <em>اپنے</em> رقم، بچت، کریڈٹ کارڈ، آمدنی پہلے صارفین سے ختم کر دی گئی۔ کوئی بیرونی سرمایہ کار نہیں، کوئی کمزوری نہیں: بانی 100٪ کا مالک ہے۔ منفی پہلو محدود ایندھن ہے۔ آپ صرف اتنی تیزی سے ترقی کر سکتے ہیں جتنی آپ کا اپنا بٹوہ اجازت دیتا ہے۔</p>\n<h3 id=\"rung-2-friends-family-and-angels\">رنگ 2، دوست، خاندان اور فرشتے</h3>\n<p>جب ذاتی بچت خشک ہو جاتی ہے تو بانی ان لوگوں کی طرف رجوع کرتے ہیں جو یقین رکھتے ہیں۔ <em>انہیں</em>: دوست اور خاندان پہلے، پھر <strong>فرشتہ سرمایہ کار</strong>, دولت مند افراد جو اپنے ہی پیسوں سے بہت ابتدائی اسٹارٹ اپ کی پشت پناہی کرتے ہیں، اکثر 25 لاکھ سے چند کروڑ روپے، ملکیت کے چھوٹے حصے کے بدلے میں۔ فرشتے بہت زیادہ خطرہ مول لیتے ہیں (زیادہ تر ابتدائی آغاز ناکام ہو جاتے ہیں) اس امید میں کہ ایک جیتنے والا تمام ہارنے والوں کے لیے ادائیگی کرے گا۔</p>\n<h3 id=\"rung-3-venture-capital\">رنگ 3، وینچر کیپیٹل</h3>\n<p>یہ وہ جگہ ہے جہاں یہ سنجیدہ ہو جاتا ہے۔ <strong>وینچر کیپیٹل (VC)</strong> فرمیں پیشہ ورانہ سرمایہ کار ہیں جو بڑے اداروں سے رقم جمع کرتی ہیں اور اسے مراحل میں امید افزا سٹارٹ اپس میں لگاتی ہیں <strong>چکر</strong>:</p>\n<ul>\n<li><strong>بیج</strong>, پہلا ادارہ جاتی چیک، یہ ثابت کرنے کے لیے کہ خیال کام کرتا ہے۔</li>\n<li><strong>سیریز اے</strong>، ایک بار دہرائے جانے کے قابل کاروبار کی تعمیر کے لئے ایک بار جب وہاں ابتدائی کرشن ہے۔</li>\n<li><strong>سیریز B, C, D...</strong>، تیزی سے پیمانہ حاصل کرنے، نئے شہروں میں داخل ہونے، فوجوں کی خدمات حاصل کرنے، اور حریفوں کو کچلنے کے لیے آہستہ آہستہ بڑے راؤنڈز۔</li>\n</ul>\n<p>ہر حرف والا راؤنڈ عام طور پر آخری سے زیادہ قیمت پر زیادہ رقم اکٹھا کرتا ہے۔ VCs خیراتی ادارے نہیں ہیں، وہ چاہتے ہیں کہ کمپنی بہت زیادہ قیمتی بن جائے تاکہ ان کا حصہ بڑھ جائے۔</p>\n<h3 id=\"rung-4-private-equity\">رنگ 4، پرائیویٹ ایکویٹی</h3>\n<p>جیسا کہ کمپنی پختہ ہوتی ہے، اس سے بھی بڑی <strong>نجی ایکویٹی (PE)</strong> فرمیں سرمایہ کاری کر سکتی ہیں، ایک اب قائم شدہ، اکثر منافع بخش کاروبار میں بہت بڑے چیک لکھ کر۔ PE رقم بعد میں، بڑی مقدار میں، جنگلی ابتدائی دنوں کے مقابلے میں کم خطرے میں آتی ہے۔</p>\n<h3 id=\"rung-5-the-ipo\">رنگ 5، IPO</h3>\n<p>آخر میں، کمپنی کو حصص فروخت کر سکتے ہیں <em>عوامی</em> ایک کے ذریعے پہلی بار <strong>ابتدائی عوامی پیشکش (IPO)</strong>، اور تبادلے پر فہرست۔ یہ سیڑھی کا سب سے اوپر ہے، جس لمحے ایک نجی کمپنی عوامی بن جاتی ہے جس کے آپ اور لاکھوں دوسرے مالک ہوسکتے ہیں۔ ہم پورا اگلا باب اس کے لیے وقف کرتے ہیں۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>جیسے جیسے آپ چڑھتے ہیں نام سائز میں بڑھتے ہیں: فرشتے سرمایہ کاری کرتے ہیں۔ <strong>لاکھوں سے چند کروڑ</strong>، VCs سرمایہ کاری کرتے ہیں۔ <strong>کروڑوں سے سینکڑوں کروڑ</strong>، PE فرمز اور IPOs ڈیل کرتے ہیں۔ <strong>سینکڑوں سے ہزاروں کروڑ</strong>. بڑا سلسلہ، بڑا چیک، بڑی کمپنی۔</p>\n</div></div>\n<h2 id=\"valuation-what-is-a-company-worth\">تشخیص: ایک کمپنی \"قابل\" کیا ہے؟</h2>\n<p>ہر دوڑ پر، دو جماعتیں ایک جادوئی نمبر پر جھگڑا کرتی ہیں: کمپنی کا <strong>تشخیص</strong>، پورے کاروبار کی قیمت کا اندازہ <em>آج</em>. یہ ایک قطعی حقیقت نہیں ہے بلکہ ایک گفت و شنید رائے ہے، جس کی بنیاد پر آمدنی، شرح نمو، مارکیٹ کا سائز، ٹیم اور سرمایہ کار کتنی بری طرح چاہتے ہیں۔</p>\n<p>قدر ایک سادہ اصول کے ذریعے کام کرتی ہے۔ اگر سرمایہ کار 10 کروڑ روپے لگاتے ہیں اور کمپنی کا 20٪ وصول کرتے ہیں، تو انہوں نے واضح طور پر اس کی قدر کی ہے۔ <em>پوری</em> کمپنی 50 کروڑ روپے میں (کیونکہ 10 کروڑ روپے 50 کروڑ کا 20 فیصد ہے)۔ یہ بار بار کریں، اور ایک سٹارٹ اپ کی قیمت چند کروڑ سے ہزاروں کروڑ تک ہو سکتی ہے، کیونکہ ہر نیا سرمایہ کار آخری سے زیادہ فی ٹکڑا ادا کرتا ہے، شرط لگانے سے کاروبار بڑھتا رہتا ہے۔</p>\n<p>ایک سٹارٹ اپ جو قدر کو عبور کرتا ہے۔ <strong>ایک بلین US ڈالر</strong> (تقریباً 8,000-8,500 کروڑ روپے) ایک خاص لقب حاصل کرتا ہے: a <strong>ایک تنگاوالا</strong>اس لیے کہا جاتا ہے کہ ایسی کمپنیاں کبھی افسانوی حیوان کی طرح نایاب سمجھی جاتی تھیں۔</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>\"یونیکورن\" کی اصطلاح 2013 میں بنائی گئی تھی کیونکہ اربوں ڈالر کے اسٹارٹ اپس کو افسانوی طور پر نایاب سمجھا جاتا تھا۔ وہ اب اتنے نایاب نہیں رہے، <strong>اکیلے ہندوستان ہی 100 سے زیادہ ایک تنگاوالا کا گھر ہے۔</strong> 2026 تک، زمین پر سب سے بڑے اسٹارٹ اپ ماحولیاتی نظام میں سے ایک۔ جانور ہے، یہ پتہ چلتا ہے، ضرب.</p>\n</div></div>\n<h2 id=\"dilution-giving-up-a-slice-to-grow-the-pie\">کم کرنا: پائی اگانے کے لیے ایک ٹکڑا ترک کرنا</h2>\n<p>یہاں ہر فنڈنگ ​​راؤنڈ کے مرکز میں تجارت ہے۔ ایک سرمایہ کار کی رقم حاصل کرنے کے لیے، بانی کو حوالے کرنا ضروری ہے۔ <strong>نئے حصص</strong>، جس کا مطلب ہے ان کا <em>اپنے</em> ملکیت کا فیصد سکڑ جاتا ہے۔ اس سکڑنے کو کہتے ہیں۔ <strong>کم کرنا</strong>.</p>\n<p>یہ تکلیف دہ لگتا ہے، اور شروعات کرنے والے اکثر پیچھے ہٹ جاتے ہیں: بانی ملکیت کیوں دیتے رہیں گے؟ جواب یہ ہے کہ اسٹارٹ اپ فنانس میں عقلمند ترین آئیڈیا ہے: <strong>ایک چھوٹے سے بڑے ٹکڑے کے مقابلے میں ایک بڑی پائی کا ایک چھوٹا ٹکڑا رکھنا بہتر ہے۔</strong> ہر دور بانی کے فیصد کو کم کرتا ہے لیکن ایندھن میں ڈالتا ہے جو (اگر یہ کام کرتا ہے) کمپنی کو اتنا بڑھتا ہے کہ <em>قدر</em> ان کا چھوٹا ٹکڑا بڑھتا رہتا ہے۔</p>\n<p>دیکھیں کہ یہ ایک بانی کے لیے کیسا چلتا ہے جو ہر چیز کا مالک ہونا شروع کر دیتا ہے:</p>\n<table>\n<thead>\n<tr>\n<th>اسٹیج</th>\n<th align=\"right\">کمپنی کی تشخیص (تقریباً)</th>\n<th align=\"right\">بانی کی ملکیت</th>\n<th align=\"right\">بانی کے داؤ کی قیمت</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>بوٹسٹریپڈ</td>\n<td align=\"right\">2 کروڑ روپے</td>\n<td align=\"right\">100%</td>\n<td align=\"right\">2 کروڑ روپے</td>\n</tr>\n<tr>\n<td>بیج راؤنڈ کے بعد</td>\n<td align=\"right\">20 کروڑ روپے</td>\n<td align=\"right\">75%</td>\n<td align=\"right\">15 کروڑ روپے</td>\n</tr>\n<tr>\n<td>سیریز اے کے بعد</td>\n<td align=\"right\">100 کروڑ روپے</td>\n<td align=\"right\">55%</td>\n<td align=\"right\">55 کروڑ روپے</td>\n</tr>\n<tr>\n<td>سیریز بی کے بعد</td>\n<td align=\"right\">500 کروڑ روپے</td>\n<td align=\"right\">40%</td>\n<td align=\"right\">200 کروڑ روپے</td>\n</tr>\n<tr>\n<td>IPO پر</td>\n<td align=\"right\">4،000 کروڑ روپے</td>\n<td align=\"right\">30%</td>\n<td align=\"right\">1200 کروڑ روپے</td>\n</tr>\n</tbody></table>\n<p>بانی کا <em>فیصد</em> 100٪ سے 30٪ تک گر گیا، لیکن <em>قدر</em> اس کا حصہ 2 کروڑ روپے سے بڑھ کر 1,200 کروڑ روپے ہو گیا۔ یہ مقصد کے مطابق کام کرنا ہے: ایک بہت بڑی کمپنی کا ایک چھوٹا حصہ۔ (اعداد و شمار مثالی ہیں، میکانزم کو دکھانے کے لیے۔)</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch07-valuation-dilution.png\" alt=\"ایک کہانی بتانے والی دو سطریں، فنڈنگ ​​راؤنڈز میں کمپنی کی ویلیویشن تیزی سے بڑھ رہی ہے جبکہ بانی کی ملکیت کا فیصد مسلسل گرتا جا رہا ہے، پھر بھی ان کے حصص کی قدر بڑھ رہی ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>ایک کہانی بتانے والی دو سطریں، فنڈنگ ​​راؤنڈز میں کمپنی کی ویلیویشن تیزی سے بڑھ رہی ہے جبکہ بانی کی ملکیت کا فیصد مسلسل گرتا جا رہا ہے، پھر بھی ان کے حصص کی قدر بڑھ رہی ہے۔</figcaption></figure>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p><strong>Dilution آپ کے سکڑتا ہے <em>فیصد</em> لیکن آپ کی ترقی کر سکتے ہیں <em>قدر</em>.</strong> 4,000 کروڑ روپے کی کمپنی کا 30% حصہ رکھنے والا بانی اس سے کہیں زیادہ امیر ہوتا ہے جب وہ 2 کروڑ روپے کی کمپنی کا 100% مالک ہو۔ پیسہ اکٹھا کرنے سے کمپنی کا نقصان نہیں ہو رہا ہے، یہ پوری چیز کو بڑا بنانے کے لیے ایندھن کے لیے ملکیت کی تجارت کر رہا ہے۔</p>\n</div></div>\n<h2 id=\"why-go-public-at-all\">سرعام کیوں جاتے ہیں؟</h2>\n<p>اگر وینچر کیپیٹل اور پرائیویٹ ایکویٹی پہلے ہی رقم فراہم کرتی ہے، تو عوامی فہرست کے شور اور چھان بین سے کیوں پریشان ہوں؟ کمپنیاں مٹھی بھر طاقتور وجوہات کی بنا پر عوام میں جاتی ہیں:</p>\n<ul>\n<li><strong>بڑا سرمایہ اکٹھا کریں۔</strong>، ایک IPO ایک ساتھ سینکڑوں یا ہزاروں کروڑ لا سکتا ہے، زیادہ تر نجی راؤنڈز سے کہیں زیادہ، توسیع کو فنڈ دینے یا قرض کی ادائیگی کے لیے۔</li>\n<li><strong>ابتدائی سرمایہ کاروں اور ملازمین کو باہر نکلنے دیں۔</strong>, فرشتوں، VCs اور اسٹاک کے اختیارات والے عملے کو آخر کار ایک عوامی مارکیٹ مل جاتی ہے جہاں وہ اپنے حصص بیچ سکتے ہیں اور سالوں کے کاغذی منافع کا احساس کر سکتے ہیں۔</li>\n<li><strong>وقار اور مرئیت</strong>، درج ہونے سے ساکھ، میڈیا کی توجہ، اور صارفین، قرض دہندگان اور مستقبل کی خدمات حاصل کرنے والوں کا اعتماد حاصل ہوتا ہے۔</li>\n</ul>\n<p>دوسری طرف حقیقی ہے: عوامی کمپنیوں کو ہر سہ ماہی میں نتائج کا انکشاف کرنا چاہیے، ہزاروں شیئر ہولڈرز کو جواب دینا چاہیے، اور حصص کی قیمت کے ساتھ رہنا چاہیے جو روزانہ ان کا فیصلہ کرتی ہے۔ عوام میں جانا سرمایہ اور لیکویڈیٹی کے لیے رازداری کی تجارت ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>ایک بڑھتی ہوئی نجی تشخیص ہے۔ <em>نہیں</em> ایک وعدہ کہ ایک IPO عوامی سرمایہ کاروں کو انعام دے گا۔ بہت سے قابل قدر اسٹارٹ اپس نے فہرست دی ہے اور پھر ان کے حصص کی قیمت میں سخت کمی دیکھی ہے جب عوامی سرمایہ کاروں نے نہ صرف ترقی کی کہانیوں کے بجائے منافع کا مطالبہ کیا۔ ایک اعلی آخری راؤنڈ کی تشخیص اندرونی لوگوں کی رائے ہے، آپ کے لیے ضمانت نہیں۔ ہم اگلے باب میں آئی پی او کو بغور جائزہ لیں گے۔</p>\n</div></div>\n<h2 id=\"india-s-startup-decade\">ہندوستان کی شروعات کی دہائی</h2>\n<p>یہ پوری سیڑھی ہندوستان میں شاندار طور پر زندہ ہو گئی ہے۔ ایک ہی دہائی میں سٹارٹ اپس کی ایک لہر آئیڈیا سے لسٹنگ تک چڑھ گئی ہے۔ <strong>زوماٹو</strong>2008 میں قائم کیا گیا، 2021 میں اس کے بلاک بسٹر IPO سے پہلے برسوں تک فرشتہ اور VC رقم کی سواری کی۔ <strong>سوئگی</strong> 2024 کے آخر میں ایکسچینج پر اپنے حریف کی پیروی کی۔ نتیجہ ایک ماحولیاتی نظام ہے <strong>100 سے زیادہ ایک تنگاوالا</strong> اور ایک مستحکم پائپ لائن عوامی مارکیٹ کی طرف پختہ ہو رہی ہے۔ آپ کے لیے، سرمایہ کار، یہ اہم ہے: آج کے نجی سفر کل کے درج کردہ اسٹاک ہیں۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p><strong>Zomato کی آرک ایک لائن میں:</strong> 2008 کی ایک ریستوراں کی فہرست سازی کی ویب سائٹ، جو برسوں کے نقصانات کے دوران فرشتوں اور VCs کے ذریعے راؤنڈ کے بعد فنڈ فراہم کی گئی، 2021 میں ہندوستان کے سب سے زیادہ دیکھے جانے والے IPOs میں عوامی طور پر درج کی گئی، ابتدائی نجی حمایتیوں کو عوامی حصص یافتگان میں تبدیل کرنے اور عام سرمایہ کاروں کو آخر کار ایک ٹکڑا کا مالک بننے دیا۔ مکمل فنڈنگ ​​سیڑھی، عوام کی نظر میں چڑھ گئی۔</p>\n</div></div>\n<h2 id=\"quick-recap\">فوری خلاصہ</h2>\n<ul>\n<li>ہر درج دیو چھوٹا شروع ہوا اور چڑھ گیا۔ <strong>فنڈنگ ​​سیڑھی</strong>: آئیڈیا، بوٹسٹریپنگ، دوستوں/family اور <strong>فرشتے</strong>, <strong>وینچر کیپٹل</strong> (بیج، سیریز A/B/C...)، <strong>نجی ایکوئٹی</strong>، اور آخر میں ایک <strong>IPO</strong>.</li>\n<li>ہر ایک بڑے ذریعہ سے زیادہ پیسہ اکٹھا کرتا ہے، لاکھوں میں فرشتے، کروڑوں میں VCs، PE اور آئی پی اوز سینکڑوں سے ہزاروں کروڑ میں۔</li>\n<li><strong>قدر</strong> پوری کمپنی کی قیمت کا ایک گفت و شنید تخمینہ ہے۔ یہ راؤنڈ میں غبارہ پھونک سکتا ہے، اور ایک ارب ڈالر کے آغاز کو a کہا جاتا ہے۔ <strong>ایک تنگاوالا</strong>.</li>\n<li><strong>کم کرنا</strong> بانیوں کو سکڑتا ہے <em>فیصد</em> لیکن بڑھ سکتے ہیں <em>قدر</em> ان کے داؤ پر، ایک بڑی پائی کا ایک چھوٹا ٹکڑا ایک چھوٹے سے بڑے ٹکڑے کو مارتا ہے۔</li>\n<li>کمپنیاں عوام کے پاس جاتی ہیں۔ <strong>بڑا سرمایہ اکٹھا کریں، ابتدائی سرمایہ کاروں کو باہر نکلنے دیں، اور وقار حاصل کریں۔</strong>، مسلسل انکشاف اور جانچ پڑتال کی قیمت پر۔</li>\n<li>بھارت نے اب <strong>100 سے زیادہ ایک تنگاوالا</strong>، اور Zomato اور Swiggy جیسے حالیہ سفر شروع سے اسٹاک تک مکمل سیڑھی چڑھتے دکھاتے ہیں۔</li>\n</ul>\n<p>اگلا، ہم آخری دھارے پر زوم ان کرتے ہیں۔ <strong>IPO</strong> بذات خود: ایک کمپنی حقیقت میں عوامی کیسے ہوتی ہے، پرائس بینڈ اور لاٹ سائز کا کیا مطلب ہے، اور آپ حصص کے لیے کیسے درخواست دے سکتے ہیں۔</p>\n","toc":[{"level":2,"text":"فنڈنگ ​​سیڑھی۔","id":"the-funding-ladder"},{"level":3,"text":"رنگ 0، خیال","id":"rung-0-the-idea"},{"level":3,"text":"رنگ 1، بوٹسٹریپنگ","id":"rung-1-bootstrapping"},{"level":3,"text":"رنگ 2، دوست، خاندان اور فرشتے","id":"rung-2-friends-family-and-angels"},{"level":3,"text":"رنگ 3، وینچر کیپیٹل","id":"rung-3-venture-capital"},{"level":3,"text":"رنگ 4، پرائیویٹ ایکویٹی","id":"rung-4-private-equity"},{"level":3,"text":"رنگ 5، IPO","id":"rung-5-the-ipo"},{"level":2,"text":"تشخیص: ایک کمپنی \"قابل\" کیا ہے؟","id":"valuation-what-is-a-company-worth"},{"level":2,"text":"کم کرنا: پائی اگانے کے لیے ایک ٹکڑا ترک کرنا","id":"dilution-giving-up-a-slice-to-grow-the-pie"},{"level":2,"text":"سرعام کیوں جاتے ہیں؟","id":"why-go-public-at-all"},{"level":2,"text":"ہندوستان کی شروعات کی دہائی","id":"india-s-startup-decade"},{"level":2,"text":"فوری خلاصہ","id":"quick-recap"}],"imgCount":2,"hasContent":true},"8":{"html":"<p>آپ نے تقریباً یقینی طور پر ہنڈائی کار میں سواری کی ہے، سوئگی پر ڈنر کا آرڈر دیا ہے، یا وشال میگا مارٹ سے گزرے ہیں۔ سالوں تک ان میں سے ہر ایک تھا۔ <em>نجی</em> کمپنی، اس کے بانیوں اور سرمایہ کاروں کے ایک چھوٹے سے حلقے کی ملکیت ہے، اس کے حصص ایک عام آدمی کے لیے خریدنا ناممکن ہے۔ پھر، ایک مخصوص صبح، جو بدل گیا: ان کے حصص NSE اور BSE پر ظاہر ہوئے، اور ڈیمیٹ اکاؤنٹ والا کوئی بھی شخص ایک سلائس کا مالک ہوسکتا ہے۔ اس صبح کو کہا جاتا ہے۔ <strong>لسٹنگ</strong>اور مہینوں طویل سفر جو اس تک لے جاتا ہے، اس کا ایک نام ہے جو آپ نے یقیناً سنا ہو گا۔ <strong>IPO</strong>، یا ابتدائی عوامی پیشکش۔</p>\n<p>ایک IPO مارکیٹ میں سب سے زیادہ دلچسپ اور سب سے زیادہ غلط فہمی والے واقعات میں سے ایک ہے۔ اخبارات \"لسٹنگ کے فوائد\" کے بارے میں چیختے ہیں، واٹس ایپ گروپس \"گرے مارکیٹ پریمیم\" کے بارے میں سرگوشی کرتے ہیں، اور ابتدائی افراد فوری دوگنا کی امید میں ڈھیر ہوتے ہیں۔ یہ باب آپ کو پورے عمل میں پرسکون انداز میں لے جاتا ہے، کمپنی کی فائل کی پہلی موٹی دستاویز سے لے کر اسٹاک کے ٹریڈنگ شروع ہونے تک، تاکہ آپ سمجھ جائیں کہ آپ اصل میں کس چیز کے لیے درخواست دے رہے ہیں۔</p>\n<h2 id=\"what-an-ipo-actually-is\">IPO اصل میں کیا ہے۔</h2>\n<p>ایک کمپنی \"عوامی ہو جاتی ہے\" جب وہ اپنے حصص پہلی بار عام لوگوں کو فروخت کرتی ہے۔ اس وقت تک اس نے بانیوں، فرشتوں، وینچر کیپیٹل، پرائیویٹ ایکویٹی (جس سفر کا ہم نے آخری باب میں سراغ لگایا) سے نجی طور پر پیسہ اکٹھا کیا۔ ایک IPO اس ملکیت کو ہر ایک کے لیے کھول دیتا ہے اور اس کے بدلے میں، کمپنی تمام جانچ، انکشاف اور نظم و ضبط کے ساتھ اسٹاک ایکسچینج میں شامل ہوتی ہے۔</p>\n<p>دو الگ چیزیں ہیں جو ایک IPO کے اندر ہو سکتی ہیں، اور وہ بہت اہم ہیں:</p>\n<ul>\n<li><strong>تازہ مسئلہ۔</strong> کمپنی بالکل نئے حصص بناتی ہے اور انہیں فروخت کرتی ہے، اس لیے <em>کمپنی میں پیسہ آتا ہے</em> ترقی کو فنڈ دینے، قرض کی ادائیگی یا فیکٹریاں بنانے کے لیے۔</li>\n<li><strong>فروخت کے لیے پیشکش (OFS)۔</strong> موجودہ مالکان، بانی، ابتدائی سرمایہ کار، کچھ فروخت کرتے ہیں۔ <em>ان کا</em> حصص، تو <em>پیسہ ان کے پاس جاتا ہے</em>، کمپنی نہیں۔ کاروبار کو کوئی نئی چیز نہیں ملتی۔ بیچنے والا صرف کیش آؤٹ کرتا ہے۔</li>\n</ul>\n<p>بہت سے IPO دونوں کا مرکب ہیں۔ یہ جاننے کے قابل ہے کہ کون سا ہے: ایک تازہ شمارہ کمپنی کے مستقبل کو فنڈ دیتا ہے۔ ایک خالص OFS بڑی عمر کے سرمایہ کار ہیں جو باہر نکلنے کی طرف بڑھ رہے ہیں۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>ایک IPO میں ہوتا ہے۔ <strong>بنیادی مارکیٹ</strong>، حصص پہلی بار فروخت ہوئے۔ ہر تجارت <em>کے بعد</em> فہرست سازی میں ہوتی ہے۔ <strong>ثانوی مارکیٹ</strong>, سرمایہ کاروں کے درمیان، کمپنی کے پاس کوئی پیسہ نہیں جا رہا ہے۔ لسٹنگ کے دن خریدنا پہلے سے ہی سیکنڈری مارکیٹ ہے۔</p>\n</div></div>\n<h2 id=\"the-paperwork-drhp-and-rhp\">کاغذی کارروائی: DRHP اور RHP</h2>\n<p>اس سے پہلے کہ کوئی کمپنی آپ سے پیسے مانگے، اسے آپ کو اپنے بارے میں تقریباً سب کچھ بتانا چاہیے۔ یہ SEBI کے ساتھ دائر ایک موٹی دستاویز میں کرتا ہے۔</p>\n<ul>\n<li>دی <strong>DRHP</strong> (ڈرافٹ ریڈ ہیرنگ پراسپیکٹس) ہے۔ <em>مسودہ</em> ورژن، پہلے فائل کیا اور عوامی تبصرے کے لیے آن لائن ڈال دیا۔ SEBI اس کا جائزہ لیتا ہے اور سوالات واپس بھیجتا ہے۔</li>\n<li>دی <strong>RHP</strong> (ریڈ ہیرنگ پراسپیکٹس) ایشو کے کھلنے سے ٹھیک پہلے فائل کردہ قریب ترین ورژن ہے، جس میں اب پرائس بینڈ اور تاریخیں ہیں۔</li>\n</ul>\n<p>فقرہ \"ریڈ ہیرنگ\" زندہ رہتا ہے کیونکہ دستاویز جان بوجھ کر <em>آخری لمحے تک ایک اہم حقیقت کو چھوڑ دیتے ہیں۔</em>، حتمی قیمت۔ وہ لاپتہ قیمت \"ریڈ ہیرنگ\" ہے۔</p>\n<p>آپ کو تمام 600 صفحات پڑھنے کی ضرورت نہیں ہے۔ ان حصوں کو سکیم کریں:</p>\n<ul>\n<li><strong>مسئلے کے اعتراضات</strong>، بالکل جہاں پیسہ جاتا ہے (حقیقی ترقی، یا زیادہ تر OFS باہر نکلنا؟)</li>\n<li><strong>خطرے کے عوامل</strong>، کیا غلط ہو سکتا ہے کی کمپنی کی اپنی ایماندار فہرست.</li>\n<li><strong>مالیات</strong>کیا آمدنی بڑھ رہی ہے؟ کیا یہ واقعی منافع بخش ہے، یا نقد رقم جلا رہا ہے؟</li>\n<li><strong>پروموٹر ہولڈنگ</strong>، بانیوں نے فہرست کے بعد کتنی جلد رکھی ہے۔</li>\n<li><strong>ایشو قیمت کی بنیاد</strong>، تشخیص، اور اس کا P/E درج کردہ ہم عمروں کے ساتھ کس طرح موازنہ کرتا ہے۔</li>\n</ul>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>خطرے کے عوامل پڑھیں <em>پہلے</em>، آخری نہیں۔ وہ کمپنی کے اپنے وکیلوں نے کمپنی کی حفاظت کے لیے لکھے ہیں، اس لیے وہ غیر معمولی طور پر بے تکلف ہیں۔ اگر کوئی خطرہ آپ کو حقیقی طور پر پریشان کرتا ہے، تو فہرست سازی کے دن کی کسی قسم کی ہائپ کو آپ کا ذہن نہیں بدلنا چاہیے۔</p>\n</div></div>\n<h2 id=\"book-building-and-the-price-band\">بک بلڈنگ اور پرائس بینڈ</h2>\n<p>زیادہ تر بڑے IPO استعمال کرتے ہیں۔ <strong>کتاب سازی</strong>: ایک قیمت طے کرنے کے بجائے، کمپنی پیشکش کرتی ہے a <strong>قیمت بینڈ</strong>700 روپے سے 740 روپے فی شیئر (2025 میں HDB فنانشل سروسز کے لیے اصلی بینڈ)، اور آخری نمبر دریافت کرنے کا مطالبہ کرنے دیں۔ تین دن کی ونڈو میں، سرمایہ کار بینڈ کے اندر قیمتوں پر بولیاں لگاتے ہیں۔ ایک بار جب یہ بند ہوجاتا ہے، کمپنی سنگل سیٹ کرتی ہے۔ <strong>کٹ آف قیمت</strong> جس پر شیئرز الاٹ کیے جاتے ہیں۔</p>\n<p>ایک خوردہ سرمایہ کار کے طور پر آپ آسانی سے \"کٹ آف پر\" بولی لگا سکتے ہیں، یعنی آپ جو بھی حتمی قیمت طے کی جائے اسے ادا کرنے پر اتفاق کرتے ہیں۔ اس طرح آپ کی درخواست درست رہتی ہے چاہے قیمت بینڈ کے اوپری حصے میں مقرر ہو۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch08-ipo-process-flow.png\" alt=\"IPO ایک نجی کمپنی کی طرف سے اپنا DRHP کو SEBI کے ساتھ فائل کرنے کا سفر، RHP اور پرائس بینڈ کے ذریعے، تین دن کی بک بلڈنگ ونڈو، الاٹمنٹ، اور آخر میں ایکسچینج پر لسٹنگ کا دن۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">فلو چارٹ</span>IPO ایک نجی کمپنی کی طرف سے اپنا DRHP کو SEBI کے ساتھ فائل کرنے کا سفر، RHP اور پرائس بینڈ کے ذریعے، تین دن کی بک بلڈنگ ونڈو، الاٹمنٹ، اور آخر میں ایکسچینج پر لسٹنگ کا دن۔</figcaption></figure>\n<h2 id=\"lot-size-upi-and-the-money-that-gets-blocked\">لاٹ سائز، UPI اور رقم جو بلاک ہوجاتی ہے۔</h2>\n<p>آپ ایک حصہ کے لیے درخواست نہیں دے سکتے۔ IPOs a میں فروخت ہوتے ہیں۔ <strong>بہت</strong>، ایک مقررہ بنڈل۔ SEBI ایک ریٹیل لاٹ کو تقریباً قابل قدر رکھتا ہے۔ <strong>14,000-15,000 روپے</strong> (تقریباً)، اس لیے 740 روپے کا شیئر 20 میں بہت زیادہ آ سکتا ہے۔ یہ آپ کی کم از کم درخواست ہے۔ آپ مزید لاٹ کے لیے درخواست دے سکتے ہیں، 2 لاکھ روپے تک کی ریٹیل سیلنگ۔</p>\n<p>یہ وہ حصہ ہے جو ابتدائی طور پر اسے سمجھنے کے بعد پسند کرتا ہے۔ آپ کے ذریعے اپلائی کریں۔ <strong>ASBA</strong>, بلاک شدہ رقم کے ذریعے سپورٹ کردہ درخواست۔ استعمال کرتے ہوئے a <strong>UPI مینڈیٹ</strong>، آپ کی درخواست <em>بلاکس</em> آپ کے اپنے بینک اکاؤنٹ میں رقم؛ یہ ہے <strong>ڈیبٹ نہیں</strong>. جب تک الاٹمنٹ کا فیصلہ نہیں ہو جاتا، نقد رقم منجمد رہتی ہے، پھر بھی آپ کی بچت کا سود حاصل کر رہا ہے۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>چونکہ رقم صرف بلاک ہوتی ہے، ادا نہیں کی جاتی، اگر آپ کو شیئرز نہیں ملتے ہیں تو IPO کے لیے درخواست دینے سے آپ کو کچھ نہیں ہوگا۔ اگر آپ ہیں۔ <strong>نہیں</strong> الاٹ ہو گیا، بلاک آسانی سے جاری ہو گیا اور رقم دوبارہ آپ کی ہو گئی۔ اگر آپ <em>ہیں</em> الاٹ کیا جاتا ہے، تب ہی اسے ڈیبٹ کیا جاتا ہے۔ کوئی الاٹمنٹ، کوئی نقصان نہیں۔</p>\n</div></div>\n<h2 id=\"allotment-and-oversubscription\">الاٹمنٹ اور اوور سبسکرپشن</h2>\n<p>اچھے آئی پی اوز حصص کی نسبت کہیں زیادہ مانگ کو راغب کرتے ہیں، یہ ہے۔ <strong>اوور سبسکرپشن</strong>. ایک IPO \"40 بار سبسکرائب کیا\" نے پیشکش پر حصص کے چالیس گنا کے لیے بولی حاصل کی۔ جب ایسا ہوتا ہے، خوردہ سرمایہ کار سبھی مطمئن نہیں ہو سکتے، اس لیے الاٹمنٹ a کے ذریعے کی جاتی ہے۔ <strong>کمپیوٹرائزڈ لاٹری</strong>: ہر درخواست دہندہ کے ساتھ فی لاٹ ایک اندراج سمجھا جاتا ہے، اور بے ترتیب قرعہ اندازی فیصلہ کرتی ہے کہ کم از کم ایک لاٹ کس کو ملے گا۔ دس لاٹوں کے لیے درخواست دینے سے اس پہلی لاٹ کی آپ کی مشکلات میں بہتری نہیں آتی، ہر کوئی اس کے لیے برابر کا مقابلہ کرتا ہے۔</p>\n<h2 id=\"listing-day-and-listing-gains\">فہرست سازی کا دن اور \"لسٹنگ کے فوائد\"</h2>\n<p>لسٹنگ کے دن اسٹاک ٹریڈنگ شروع کرتا ہے، اور ایشو پرائس اور اوپننگ پرائس کے درمیان فرق مشہور ہے۔ <strong>فہرست سازی کا فائدہ</strong> (یا نقصان)۔ اس کے بعد آنے والی سرخیاں حقیقی ہیں، لیکن خطرہ بھی ایسا ہی ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>IPO (ایشو کی قیمت -&gt; لسٹنگ کی قیمت)</th>\n<th align=\"right\">فہرست سازی دن کی حرکت (تقریباً)</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>بجاج ہاؤسنگ فنانس (70 روپے -&gt; 150 روپے)</td>\n<td align=\"right\">تقریباً +114%</td>\n</tr>\n<tr>\n<td>LG الیکٹرانکس انڈیا (2025)</td>\n<td align=\"right\">تقریباً %50</td>\n</tr>\n<tr>\n<td>وشال میگا مارٹ (78 روپے -&gt; 112 روپے)</td>\n<td align=\"right\">تقریباً +44%</td>\n</tr>\n<tr>\n<td>HDB فنانشل سروسز (740 روپے -&gt; 835 روپے)</td>\n<td align=\"right\">تقریباً 13%</td>\n</tr>\n<tr>\n<td>سوئگی (420 روپے کے قریب درج)</td>\n<td align=\"right\">تقریباً +8%</td>\n</tr>\n<tr>\n<td>ہنڈائی موٹر انڈیا (1,960 روپے -&gt; 1,934 روپے)</td>\n<td align=\"right\">تقریبا -1% (ایک فلاپ)</td>\n</tr>\n</tbody></table>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>ہنڈائی موٹر انڈیا کی 2024 IPO تھی۔ <strong>ہندوستانی تاریخ میں تقریباً 27,860 کروڑ روپے میں سب سے بڑا</strong>، اور یہ <em>گر گیا</em> لسٹنگ کے دن. اسی دوران بجاج ہاؤسنگ فنانس نے ڈیبیو پر دگنا سے بھی زیادہ اضافہ کیا، پھر اگلے مہینوں میں تقریباً 26 فیصد تک گر گیا۔ سبق ایک ہی میز پر بیٹھا ہے: بڑا نام پاپ کی کوئی گارنٹی نہیں ہے، اور پاپ اس کے قائم رہنے کی کوئی ضمانت نہیں ہے۔</p>\n</div></div>\n<h2 id=\"the-grey-market-premium-handle-with-care\">گرے مارکیٹ پریمیم، احتیاط کے ساتھ ہینڈل کریں۔</h2>\n<p>لسٹنگ سے پہلے، ایک غیر سرکاری <strong>گرے مارکیٹ</strong> حوالہ جات a <strong>GMP</strong> (گرے مارکیٹ پریمیم)، ایک افواہ کی قیمت جس پر ابھی تک درج نہیں کیے گئے حصص \"ٹریڈنگ\" کر رہے ہیں۔ فوائد کی فہرست کے لیے اسے کرسٹل بال کے طور پر ٹیلیگرام گروپس میں سرگوشی کی جاتی ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>گرے مارکیٹ ہے۔ <strong>غیر سرکاری، غیر منظم اور SEBI کے ذریعے نگرانی نہیں کی گئی۔</strong>. کوئی تبادلہ نہیں ہے، کوئی تصفیہ کی ضمانت نہیں ہے، کوئی شکایت کا ازالہ نہیں ہے، صرف گمنام ڈیلرز کے درمیان اعتماد ہے۔ GMP کے اعداد و شمار میں آسانی سے دھاندلی کی جاتی ہے تاکہ ہائپ تیار کیا جاسکے، اور SEBI نے سرمایہ کاروں کو غیر مجاز پلیٹ فارمز پر غیر فہرست شدہ حصص کی تجارت کے خلاف بار بار خبردار کیا ہے۔ GMP کو گپ شپ سمجھیں، کبھی بھی سرمایہ کاری کی وجہ کے طور پر۔ SEBI یہاں تک کہ اس گھناؤنے کونے کو تبدیل کرنے کے لیے ایک آفیشل \"جب فہرست میں\" ٹریڈنگ ونڈو بنا رہا ہے۔</p>\n</div></div>\n<h2 id=\"decoding-the-ipo-jargon\">IPO لفظ کو ڈی کوڈ کرنا</h2>\n<p>ہر IPO کو مختلف قسم کے سرمایہ کاروں کے لیے مخصوص بالٹیوں میں تقسیم کیا جاتا ہے۔ معیاری کتاب سے بنا ہوا تقسیم اس طرح لگتا ہے:</p>\n<table>\n<thead>\n<tr>\n<th>زمرہ</th>\n<th>وہ کون ہیں؟</th>\n<th>عام بکنگ</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><strong>QIB</strong> (قابل ادارہ خریدار)</td>\n<td>میوچل فنڈز، بینک، بیمہ کنندگان، ایف آئی آئی</td>\n<td>50% تک</td>\n</tr>\n<tr>\n<td><strong>NII / HNI</strong> (غیر ادارہ جاتی سرمایہ کار)</td>\n<td>2 لاکھ روپے سے زیادہ کی درخواست دینے والے افراد</td>\n<td>کم از کم 15%</td>\n</tr>\n<tr>\n<td><strong>ریٹیل (RII)</strong></td>\n<td>آپ، 2 لاکھ روپے تک کی درخواستیں</td>\n<td>کم از کم 35%</td>\n</tr>\n</tbody></table>\n<p><strong>اینکر سرمایہ کار</strong> QIB کوٹہ (اس کے 60% تک) سے کھدی ہوئی ایک خاص سلائس ہیں۔ یہ بڑے، مارکی ادارے ہیں جنہیں عہد کرنے کے لیے مدعو کیا گیا ہے۔ <em>ایک دن پہلے</em> IPO کھلتا ہے، ان کی شرکت ہر کسی کے لیے اعتماد کا اشارہ دیتی ہے۔ انہیں فوری منافع کے لیے پلٹنا روکنے کے لیے، ان کے حصص ہیں۔ <strong>میں بند</strong> (آدھا 30 دن کے لیے، آدھا 90 دن کے لیے)۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch08-investor-categories.png\" alt=\"کتاب سے بنی IPO کو کس طرح تقسیم کیا جاتا ہے، اینکر اور QIB اداروں، غیر ادارہ جاتی HNIs، اور ریٹیل کوٹہ، ہر زمرے کو حاصل ہونے والے ناقص حصہ کو ظاہر کرتا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">انفوگرافک</span>کتاب سے بنی IPO کو کس طرح تقسیم کیا جاتا ہے، اینکر اور QIB اداروں، غیر ادارہ جاتی HNIs، اور خوردہ کوٹہ، ہر زمرے کو حاصل ہونے والے ناقص حصہ کو ظاہر کرتا ہے۔</figcaption></figure>\n<p>ایک آخری امتیاز۔ اے <strong>مین بورڈ IPO</strong> مکمل انکشاف کے ساتھ مرکزی NSE/BSE پلیٹ فارمز پر لسٹنگ کرنے والی ایک بڑی کمپنی ہے۔ ایک <strong>SME IPO</strong> ہلکے اصولوں اور بہت بڑی کم از کم ایپلی کیشن (اکثر ایک لاکھ سے زیادہ) کے ساتھ وقف کردہ NSE Emerge یا BSE SME پلیٹ فارمز پر ایک چھوٹی کاروباری فہرست ہے۔ SME IPOs ڈرامائی حرکتیں، اوپر اور نیچے، اور تجربہ کار سرمایہ کاروں کے لیے موزوں کر سکتے ہیں، نہ کہ پہلی بار آنے والے۔</p>\n<p>انماد کو تناظر میں رکھنے کے لیے: 2024 ایک ریکارڈ سال تھا جس میں تقریباً 91 مین بورڈ آئی پی اوز نے تقریباً 1.6 لاکھ کروڑ روپے اکٹھے کیے، اور 2025 100 سے زیادہ مین بورڈ ایشوز کے ساتھ اب بھی بڑا ہوا۔ جب اتنی زیادہ رقم نئی فہرستوں کا پیچھا کرتی ہے، تو ہائپ گرم ہوجاتی ہے، اور آپ کا واحد حقیقی دفاع بورنگ چیزیں ہیں: RHP، مالیات، اور قیمت۔</p>\n<h2 id=\"quick-recap\">فوری خلاصہ</h2>\n<ul>\n<li>ایک <strong>IPO</strong> میں پہلی بار کسی کمپنی کے حصص عوام کو فروخت کرتا ہے۔ <strong>بنیادی مارکیٹ</strong>; لسٹنگ کے بعد تمام تجارت ثانوی ہے۔</li>\n<li>اے <strong>تازہ مسئلہ</strong> کمپنی کو فنڈز ایک <strong>OFS</strong> صرف موجودہ مالکان کو کیش آؤٹ کرتا ہے، ہمیشہ چیک کریں کہ کون سا غالب ہے۔</li>\n<li>دی <strong>DRHP</strong> (مسودہ) اور <strong>RHP</strong> (حتمی، پرائس بینڈ کے ساتھ) آپ کو سب کچھ بتاتا ہوں؛ اشیاء، خطرات، مالیات اور تشخیص کو کم کریں۔</li>\n<li><strong>کتاب سازی ۔</strong> ایک بینڈ کے اندر قیمت کا پتہ لگاتا ہے؛ آپ درخواست دیں <strong>بہت</strong> کے ذریعے <strong>UPI/ASBA</strong>، جہاں پیسہ ہے۔ <em>مسدود، ڈیبٹ نہیں</em>، الاٹمنٹ تک۔</li>\n<li><strong>فہرست سازی کے فوائد کی کبھی ضمانت نہیں دی جاتی ہے۔</strong>یہاں تک کہ ہندوستان کا اب تک کا سب سے بڑا IPO پہلی بار گر گیا، اور <strong>گرے مارکیٹ پریمیم غیر منظم افواہ ہے۔</strong>.</li>\n<li>IPO حصص کے درمیان تقسیم ہیں۔ <strong>QIB، NII اور ریٹیل</strong>کے ساتھ <strong>اینکر سرمایہ کار</strong> اعتماد کا اشارہ دینے کے لیے بند کر دیا گیا۔</li>\n</ul>\n<p>فہرست آنے کے بعد کوئی کمپنی مارکیٹ کو چھونا بند نہیں کرتی۔ یہ حق کے مسائل، FPOs، OFS، بونس، تقسیم اور بائ بیکس کے ذریعے تازہ سرمایہ اور حصص یافتگان کو انعام دیتا رہتا ہے، اور ہر ایک حصص کی قیمت کو ان طریقوں سے منتقل کرتا ہے جس سے کسی ابتدائی کو غیر ضروری طور پر خوفزدہ کیا جا سکتا ہے۔ ان کارپوریٹ اعمال کو ڈی کوڈ کرنا بالکل وہی ہے جہاں ہم آگے بڑھتے ہیں۔</p>\n","toc":[{"level":2,"text":"IPO اصل میں کیا ہے۔","id":"what-an-ipo-actually-is"},{"level":2,"text":"کاغذی کارروائی: DRHP اور RHP","id":"the-paperwork-drhp-and-rhp"},{"level":2,"text":"بک بلڈنگ اور پرائس بینڈ","id":"book-building-and-the-price-band"},{"level":2,"text":"لاٹ سائز، UPI اور رقم جو بلاک ہوجاتی ہے۔","id":"lot-size-upi-and-the-money-that-gets-blocked"},{"level":2,"text":"الاٹمنٹ اور اوور سبسکرپشن","id":"allotment-and-oversubscription"},{"level":2,"text":"فہرست سازی کا دن اور \"لسٹنگ کے فوائد\"","id":"listing-day-and-listing-gains"},{"level":2,"text":"گرے مارکیٹ پریمیم، احتیاط کے ساتھ ہینڈل کریں۔","id":"the-grey-market-premium-handle-with-care"},{"level":2,"text":"IPO لفظ کو ڈی کوڈ کرنا","id":"decoding-the-ipo-jargon"},{"level":2,"text":"فوری خلاصہ","id":"quick-recap"}],"imgCount":2,"hasContent":true},"9":{"html":"<p>تصور کریں کہ آپ نے ایک صبح اپنا پورٹ فولیو کھولا اور ایک اسٹاک جو آپ کے پاس ہے، کہہ لیں کہ یہ کل 2,900 روپے کے قریب بند ہوا، اچانک تقریباً 1,450 روپے ظاہر ہو رہا ہے۔ آپ کا پیٹ گرتا ہے۔ کیا کمپنی راتوں رات گر گئی؟ کیا آپ نے اپنی آدھی رقم کھو دی؟ تقریباً یقیناً نہیں۔ آپ کیا دیکھ رہے ہیں a <strong>کارپوریٹ کارروائی</strong>اس معاملے میں ایک بونس کا مسئلہ ہے، اور آپ کی دولت بالکل وہی ہے جو کل رات تھی۔ آپ صرف آدھی قیمت پر دو گنا زیادہ حصص کے مالک ہیں۔</p>\n<p>یہ واحد غلط فہمی کسی بھی حقیقی بری خبر سے زیادہ ابتدائی افراد کو اچھے اسٹاک سے ڈراتی ہے۔ لسٹڈ کمپنیاں اپنے حصص کے لیے مسلسل کام کر رہی ہیں: تازہ رقم جمع کرنا، نقد رقم واپس کرنا، اپنے اسٹاک کو تقسیم کرنا، مفت دینا۔ یہ باب ہر عام کارپوریٹ ایکشن کو ڈی کوڈ کرتا ہے، اور، سب سے اہم، آپ کو دکھاتا ہے۔ <em>کیوں قیمت میں تبدیلی عام طور پر گھبرانے کی کوئی بات نہیں ہے۔</em></p>\n<h2 id=\"two-families-of-corporate-action\">کارپوریٹ ایکشن کے دو خاندان</h2>\n<p>اس باب میں سب کچھ دو بالٹیوں میں سے ایک میں آتا ہے:</p>\n<ul>\n<li><strong>مزید رقم جمع کرنا</strong>کمپنی (یا اس کے بڑے شیئر ہولڈرز) کو سرمائے کی ضرورت ہے: <strong>حقوق کا مسئلہ، FPO، OFS</strong>.</li>\n<li><strong>بدلہ دینا یا نئی شکل دینا</strong>، کمپنی قیمت واپس کرتی ہے یا اپنے حصص کی تعداد کو دوبارہ ترتیب دیتی ہے: <strong>منافع، بونس، اسٹاک کی تقسیم، بائ بیک</strong>.</li>\n</ul>\n<p>آئیے ان کو باری باری لے لیں۔</p>\n<h2 id=\"raising-more-money\">مزید رقم جمع کرنا</h2>\n<h3 id=\"rights-issue\">حقوق کا مسئلہ</h3>\n<p>اے <strong>حقوق کا مسئلہ</strong> پیشکش <em>نیا</em> کو شیئر کرتا ہے۔ <em>موجودہ</em> شیئر ہولڈرز، عام طور پر مارکیٹ کی قیمت پر ایک مقررہ تناسب میں رعایت پر۔ \"200 روپے پر 1:5 رائٹس\" کا مطلب ہے کہ آپ کے پاس ہر 5 شیئرز کے لیے آپ 200 روپے میں 1 نیا شیئر خرید سکتے ہیں (چاہے مارکیٹ کی قیمت 300 روپے ہو)۔ آپ کو اپنی ملکیت کو سکڑنے سے بچانے کا پہلا حق دیا جا رہا ہے۔</p>\n<p>آپ کو خریدنے پر مجبور نہیں کیا جاتا ہے۔ اگر آپ نئے حصص نہیں چاہتے ہیں تو، آپ کے <strong>حقوق کا استحقاق</strong> ایکسچینج پر کسی اور کو فروخت کیا جا سکتا ہے (یہ ایک علیحدہ عارضی ٹکر کے طور پر تجارت کرتا ہے)، اس لیے حق کی ہی قدر ہوتی ہے۔ اگر آپ اسے صرف نظر انداز کرتے ہیں، تو آپ کا داؤ تھوڑا سا پتلا ہوجاتا ہے۔</p>\n<h3 id=\"fpo-follow-on-further-public-offer\">FPO (فالو آن / مزید عوامی پیشکش)</h3>\n<p>ایک <strong>FPO</strong> ایک سیکنڈ کی طرح ہے IPO: ایک <em>پہلے سے درج</em> کمپنی کو تازہ حصص جاری کرتا ہے۔ <em>ہر کوئی</em> زیادہ سرمایہ اکٹھا کرنے کے لیے مارکیٹ میں۔ حقوق کے مسئلے کے برعکس، یہ عام لوگوں کے لیے کھلا ہے، نہ صرف موجودہ حاملین کے لیے۔</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>ووڈافون آئیڈیا کے 2024 FPO کے بارے میں اٹھایا گیا۔ <strong>18،000 کروڑ روپے</strong>، ہندوستانی تاریخ کی سب سے بڑی فالو آن پیشکش۔ ایک سال پہلے، اڈانی انٹرپرائزز نے 20,000 کروڑ روپے کا ایک اور بھی بڑا FPO لانچ کیا، اسے مکمل طور پر سبسکرائب کیا گیا، پھر <em>اسے منسوخ کر دیا اور ہر روپیہ واپس کر دیا۔</em> ہندنبرگ کی رپورٹ کے درمیان اسٹاک کریش ہونے کے بعد۔ مکمل ہونے کے باوجود سبسکرائب شدہ پیشکشوں کو بند کیا جا سکتا ہے۔</p>\n</div></div>\n<h3 id=\"ofs-offer-for-sale\">OFS (فروخت کے لیے)</h3>\n<p>ایک میں <strong>OFS</strong>، بڑے موجودہ شیئر ہولڈرز، پروموٹرز، حکومت، ابتدائی سرمایہ کار، فروخت کرتے ہیں۔ <em>ان کا</em> تبادلے کے ذریعے عوام کو حصص۔ کوئی نئے حصص نہیں بنائے گئے ہیں، اور کمپنی کو خود کچھ نہیں ملتا ہے۔ پیسہ بیچنے والے کو جاتا ہے. حکومت عام طور پر پبلک سیکٹر کی کمپنیوں میں اپنے حصص کو کم کرنے کے لیے OFS کا استعمال کرتی ہے، اکثر چھوٹی <strong>خوردہ کے لئے رعایت</strong> درخواست دہندگان چونکہ کوئی نیا حصص نہیں بنایا گیا ہے، ایک OFS کرتا ہے۔ <strong>پتلا نہیں</strong> موجودہ ہولڈرز جس طرح ایک تازہ مسئلہ کرتا ہے، یہ صرف ملکیت کو منتقل کرتا ہے۔</p>\n<h2 id=\"rewarding-and-reshaping\">انعام دینے والا اور نئی شکل دینا</h2>\n<h3 id=\"dividends\">منافع</h3>\n<p>اے <strong>ڈیویڈنڈ</strong> یہ کمپنی کے منافع کا ایک ٹکڑا ہے جو نقد میں ادا کیا جاتا ہے، عام طور پر چند روپے فی شیئر۔ یہ جاننے کے لیے کہ یہ کس کو ملتا ہے، کمپنی ایک سیٹ کرتی ہے۔ <strong>ریکارڈ کی تاریخ</strong>: آپ کو اس سے پہلے شیئر کا مالک ہونا چاہیے۔ <strong>سابق ڈیویڈنڈ کی تاریخ</strong> (کٹ آف) اہل ہونے کے لیے۔ ہندوستان کی موجودہ T+1 تصفیہ کے تحت، سابقہ ​​تاریخ اور ریکارڈ کی تاریخ عام طور پر ایک ہی دن آتی ہے، لہذا سادہ اصول یہ ہے: <em>ڈیویڈنڈ حاصل کرنے کے لیے سابقہ ​​تاریخ سے کم از کم ایک دن پہلے خریدیں۔</em></p>\n<p>سابقہ ​​تاریخ پر، حصص کی قیمت عام طور پر کھلتی ہے۔ <strong>تقریباً ڈیویڈنڈ کی رقم سے کم</strong>کیونکہ نقد کمپنی چھوڑنے والا ہے۔ 1,000 روپے کا اسٹاک جو 10 روپے کا ڈیویڈنڈ ادا کرتا ہے وہ 990 روپے کے قریب کھلتا ہے۔ آپ نے 10 روپے کا نقصان نہیں کیا۔ یہ ابھی حصص کی قیمت سے آپ کے بینک اکاؤنٹ میں منتقل ہوا ہے۔</p>\n<h3 id=\"bonus-shares\">بونس شیئرز</h3>\n<p>اے <strong>بونس کا مسئلہ</strong> موجودہ شیئر ہولڈرز کو دیتا ہے۔ <em>مفت</em> کمپنی کے جمع کردہ ذخائر سے اضافی حصص، 1:1 جیسے تناسب میں (ہر ایک کے لیے ایک مفت حصہ)۔ کوئی پیسہ ہاتھ نہیں بدلتا۔ کمپنی کی کل قیمت میں کوئی تبدیلی نہیں آئی ہے، اس لیے قیمت متناسب طور پر کم ہوتی ہے۔</p>\n<h3 id=\"stock-split\">اسٹاک تقسیم</h3>\n<p>اے <strong>اسٹاک تقسیم</strong> ہر حصہ کو کئی حصوں میں تقسیم کرتا ہے۔ کمپنی کم کرتی ہے۔ <strong>چہرے کی قیمت</strong>کہتے ہیں 10 روپے سے 1 روپے تک، اور ایک شیئر دس ہو جاتا ہے، قیمت دسویں حصے تک گرنے کے ساتھ۔ یہ خالصتاً کاسمیٹک ہے، اکثر اس لیے کیا جاتا ہے کہ زیادہ قیمت والے شیئر کو زیادہ سستی نظر آئے اور زیادہ فعال طور پر تجارت کی جائے۔</p>\n<h3 id=\"buyback\">بائ بیک</h3>\n<p>اے <strong>واپسی</strong> یہ ایک تازہ شمارے کے برعکس ہے: کمپنی اپنی نقد رقم کا استعمال کرتی ہے۔ <em>واپس خریدیں</em> اور اس کے حصص منسوخ کریں، عام طور پر پریمیم پر، یا تو a کے ذریعے <strong>ٹینڈر کی پیشکش</strong> (آپ اپنے حصص واپس پیش کرتے ہیں) یا <strong>کھلی منڈی</strong> خریداری کم حصص باقی ہیں، لہذا ہر بچ جانے والا حصہ کمپنی کے قدرے بڑے حصے کی نمائندگی کرتا ہے۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>1 اکتوبر 2024 سے، بائ بیکس پر ٹیکس کے قوانین تبدیل ہو گئے: آپ کو بائ بیک میں ملنے والی رقم پر اب ٹیکس لگایا جاتا ہے۔ <em>آپ کا</em> پہلے کی طرح شیئر ہولڈر کی سطح پر ٹیکس سے پاک ہونے کے بجائے ڈیویڈنڈ کی آمدنی کے طور پر ہاتھ۔ بائ بیک اب بھی کمپنیوں کے لیے نقد رقم واپس کرنے کا ایک حقیقی طریقہ ہے، بس اب ٹیکس کا شارٹ کٹ نہیں ہے۔</p>\n</div></div>\n<h2 id=\"the-part-that-scares-beginners-the-price-falls-but-you-don-t-lose\">وہ حصہ جو ابتدائیوں کو ڈراتا ہے: قیمت \"گرتی ہے\" لیکن آپ ہارتے نہیں ہیں۔</h2>\n<p>یہ باب میں سب سے اہم خیال ہے، تو آئیے اسے ایک حقیقی مثال کے ساتھ ٹھوس بنائیں۔ اکتوبر 2024 میں، ریلائنس انڈسٹریز نے ایک <strong>1:1 بونس</strong>, منعقد ہر ایک کے لئے ایک مفت حصہ.</p>\n<p>فرض کریں کہ آپ کی ملکیت ہے۔ <strong>2,900 روپے میں 10 شیئرز</strong> شام سے پہلے. آپ کے ہولڈنگ کی مالیت 29,000 روپے تھی۔</p>\n<table>\n<thead>\n<tr>\n<th></th>\n<th align=\"right\">بونس سے پہلے</th>\n<th align=\"right\">1:1 بونس کے بعد</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>شیئرز آپ کی ملکیت ہے۔</td>\n<td align=\"right\">10</td>\n<td align=\"right\">20</td>\n</tr>\n<tr>\n<td>فی حصص کی قیمت</td>\n<td align=\"right\">2,900 روپے</td>\n<td align=\"right\">1,450 روپے</td>\n</tr>\n<tr>\n<td><strong>کل قدر</strong></td>\n<td align=\"right\"><strong>29,000 روپے</strong></td>\n<td align=\"right\"><strong>29,000 روپے</strong></td>\n</tr>\n</tbody></table>\n<p>آپ کے حصص دگنے ہو گئے، قیمت آدھی ہو گئی اور آپ کی دولت میں ایک روپیہ بھی نہیں بڑھا۔ اسٹاک کی تقسیم یکساں طور پر کام کرتی ہے، زیادہ حصص، متناسب طور پر کم قیمت، ایک ہی کل۔ ڈیویڈنڈ وہی خیال ہے جس کی قیمت آپ کو اضافی حصص کی بجائے نقد رقم کے طور پر دی جاتی ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>بونس، تقسیم اور ڈیویڈنڈ کرتے ہیں۔ <strong>نہیں</strong> جس دن یہ ہوتے ہیں آپ کو امیر یا غریب بنا دیتے ہیں، وہ صرف بدل جاتے ہیں۔ <em>فارم</em> جو آپ کے پاس ہے۔ اسکرین کم قیمت دکھاتی ہے کیونکہ تبادلہ خود بخود ہوجاتا ہے۔ <strong>ایڈجسٹ کرتا ہے</strong> یہ آپ کی پچھلی خریداری کی قیمت اور چارٹس کو بھی ایڈجسٹ کیا گیا ہے۔ \"Rs 1,450\" کو دیکھنا جہاں \"Rs 2,900\" ہوا کرتا تھا عام ریاضی ہے، کریش نہیں۔</p>\n</div></div>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch09-split-bonus-adjust.png\" alt=\"ایک شیئر جس کی قیمت 2,900 روپے تھی 1:1 بونس کے بعد 1,450 روپے پر دو شیئرز بنتے ہیں، شیئر کی تعداد دگنی ہو جاتی ہے، قیمت آدھی ہو جاتی ہے، اور کل دولت بالکل وہی رہتی ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>ایک شیئر جس کی قیمت 2,900 روپے تھی 1:1 بونس کے بعد 1,450 روپے پر دو شیئرز بنتے ہیں، شیئر کی تعداد دگنی ہو جاتی ہے، قیمت آدھی ہو جاتی ہے، اور کل دولت بالکل وہی رہتی ہے۔</figcaption></figure>\n<p>پھر کمپنیاں کیوں پریشان ہوتی ہیں؟ بونس اور تقسیم فی حصص کی قیمت کو کم کرتے ہیں، جو خریداروں کے پول کو وسیع کر سکتے ہیں اور تجارتی سرگرمیوں کو بہتر بنا سکتے ہیں، اور یہ مستقبل کی آمدنی میں انتظامیہ کے اعتماد کا اشارہ دیتے ہیں۔ وہ پتلی ہوا سے قدر پیدا نہیں کرتے ہیں، لیکن زیادہ مائع، زیادہ قابل رسائی اسٹاک ایک بہترین نتیجہ ہے۔</p>\n<h2 id=\"every-corporate-action-at-a-glance\">ہر کارپوریٹ ایکشن ایک نظر میں</h2>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch09-corporate-actions-grid.png\" alt=\"کارپوریٹ ایکشنز، رائٹس، FPO، OFS، ڈیویڈنڈ، بونس، اسپلٹ اور بائ بیک کا ایک موازنہ گرڈ، ہر ایک کے لیے یہ ظاہر کرتا ہے کہ آیا نئے شیئرز بنائے گئے ہیں، پیسہ کہاں سے بہہ رہا ہے، اور قیمت پر اثر\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">انفوگرافک</span>کارپوریٹ ایکشنز، رائٹس، FPO، OFS، ڈیویڈنڈ، بونس، اسپلٹ اور بائ بیک کا ایک موازنہ گرڈ، ہر ایک کے لیے یہ ظاہر کرتا ہے کہ آیا نئے شیئرز بنائے گئے ہیں، پیسہ کہاں سے بہہ رہا ہے، اور قیمت پر اثر</figcaption></figure>\n<table>\n<thead>\n<tr>\n<th>ایکشن</th>\n<th>یہ کیا ہے</th>\n<th>شیئر کی گنتی پر اثر</th>\n<th>قیمت پر اثر</th>\n<th>آپ کی دولت پر اثر</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><strong>حقوق کا مسئلہ</strong></td>\n<td>نئے حصص موجودہ ہولڈرز کو رعایت پر پیش کیے جاتے ہیں۔</td>\n<td>مزید (اگر آپ سبسکرائب کریں)</td>\n<td>تھوڑا سا نیچے ایڈجسٹ ہوتا ہے (سابق حقوق)</td>\n<td>غیر جانبدار آپ نئے حصص کی ادائیگی کرتے ہیں۔</td>\n</tr>\n<tr>\n<td><strong>FPO</strong></td>\n<td>نئے حصص عوام کو فروخت کیے گئے۔</td>\n<td>مزید (کل)</td>\n<td>dilution پر ڈبو سکتے ہیں۔</td>\n<td>جب تک آپ خریدتے ہیں تھوڑا سا کم کرنا</td>\n</tr>\n<tr>\n<td><strong>OFS</strong></td>\n<td>بڑے ہولڈر موجودہ حصص فروخت کرتے ہیں۔</td>\n<td>کوئی تبدیلی نہیں۔</td>\n<td>قلیل مدتی دباؤ</td>\n<td>کوئی کمزوری نہیں۔</td>\n</tr>\n<tr>\n<td><strong>ڈیویڈنڈ</strong></td>\n<td>منافع سے ادا کی گئی نقد رقم</td>\n<td>کوئی تبدیلی نہیں۔</td>\n<td>سابقہ ​​تاریخ پر ڈیویڈنڈ کی کمی</td>\n<td>غیر جانبدار (قیمت نقد میں منتقل ہوتی ہے)</td>\n</tr>\n<tr>\n<td><strong>بونس</strong></td>\n<td>ایک تناسب میں مفت اضافی حصص</td>\n<td>اوپر</td>\n<td>متناسب طور پر گرتا ہے۔</td>\n<td>غیر تبدیل شدہ</td>\n</tr>\n<tr>\n<td><strong>اسٹاک تقسیم</strong></td>\n<td>ایک حصہ کئی حصوں میں بٹ گیا۔</td>\n<td>اوپر</td>\n<td>متناسب طور پر گرتا ہے۔</td>\n<td>غیر تبدیل شدہ</td>\n</tr>\n<tr>\n<td><strong>بائ بیک</strong></td>\n<td>کمپنی اپنے حصص واپس خریدتی ہے۔</td>\n<td>نیچے</td>\n<td>اکثر معاون</td>\n<td>غیر جانبدار سے ہلکے مثبت</td>\n</tr>\n</tbody></table>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>جب آپ کے پورٹ فولیو میں کوئی اسٹاک بغیر کسی واضح وجہ کے تیزی سے نیچے آجاتا ہے، تو اسے چیک کریں۔ <strong>کارپوریٹ اعمال</strong> یا <strong>اعلانات</strong> رد عمل سے پہلے ٹیب. دس میں سے نو بار یہ ایک ایکس ڈیویڈنڈ، بونس یا سپلٹ ہے، اور صحیح جواب بالکل کچھ نہ کرنا ہے۔</p>\n</div></div>\n<h2 id=\"quick-recap\">فوری خلاصہ</h2>\n<ul>\n<li>کمپنیاں فہرست سازی کے بعد مارکیٹ کو چھوتی رہتی ہیں۔ <strong>سرمایہ بڑھانا</strong> (حقوق، FPO، OFS) یا کو <strong>واپس اور نئی شکل</strong> قدر (ڈیویڈنڈ، بونس، تقسیم، بائ بیک)۔</li>\n<li>اے <strong>حقوق کا مسئلہ</strong> موجودہ ہولڈرز کو رعایتی نئے حصص پیش کرتا ہے؛ ایک <strong>FPO</strong> ہر کسی کو نئے حصص فروخت کرتا ہے۔ ایک <strong>OFS</strong> بڑے ہولڈرز کو آپ کو کمزور کیے بغیر موجودہ حصص فروخت کرنے دیتا ہے۔</li>\n<li><strong>منافع</strong> منافع سے نقد ادائیگی؛ پر ڈیویڈنڈ کی طرف سے قیمت گرتی ہے <strong>سابقہ ​​تاریخ</strong>تو اس دن آپ زیادہ امیر یا غریب نہیں ہیں۔</li>\n<li><strong>بونس اور تقسیم</strong> اپنے حصص کو ضرب دیں اور قیمت کو متناسب طور پر کم کریں، <strong>آپ کی کل دولت نہیں بدلتی</strong>.</li>\n<li>اے <strong>واپسی</strong> نقد واپس کر کے حصہ کی تعداد کو کم کر دیتا ہے؛ اکتوبر 2024 سے حاصل ہونے والی آمدنی پر آپ کے ہاتھ میں بطور ڈیویڈنڈ ٹیکس لگایا جاتا ہے۔</li>\n<li>سب سے بڑی ابتدائی غلطی ہے۔ <strong>ایک ایڈجسٹ قیمت پر گھبراہٹ</strong>، رد عمل ظاہر کرنے سے پہلے ہمیشہ کارپوریٹ ایکشن کیلنڈر چیک کریں۔</li>\n</ul>\n<p>اب آپ سمجھ گئے ہیں کہ حصص کیسے بنائے جاتے ہیں، تقسیم کیے جاتے ہیں اور نئی شکل دیتے ہیں۔ اس کے بعد ہم اسکرین کا رخ کرتے ہیں جہاں یہ سب کچھ حقیقی وقت میں ظاہر ہوتا ہے۔ <strong>اسٹاک کی قیمت</strong>، اور اس پر ہر ایک نمبر کو ڈی کوڈ کریں، آخری تجارت شدہ قیمت سے لے کر پانچ سطحی آرڈر بک تک۔</p>\n","toc":[{"level":2,"text":"کارپوریٹ ایکشن کے دو خاندان","id":"two-families-of-corporate-action"},{"level":2,"text":"مزید رقم جمع کرنا","id":"raising-more-money"},{"level":3,"text":"حقوق کا مسئلہ","id":"rights-issue"},{"level":3,"text":"FPO (فالو آن / مزید عوامی پیشکش)","id":"fpo-follow-on-further-public-offer"},{"level":3,"text":"OFS (فروخت کے لیے)","id":"ofs-offer-for-sale"},{"level":2,"text":"انعام دینے والا اور نئی شکل دینا","id":"rewarding-and-reshaping"},{"level":3,"text":"منافع","id":"dividends"},{"level":3,"text":"بونس شیئرز","id":"bonus-shares"},{"level":3,"text":"اسٹاک تقسیم","id":"stock-split"},{"level":3,"text":"بائ بیک","id":"buyback"},{"level":2,"text":"وہ حصہ جو ابتدائیوں کو ڈراتا ہے: قیمت \"گرتی ہے\" لیکن آپ ہارتے نہیں ہیں۔","id":"the-part-that-scares-beginners-the-price-falls-but-you-don-t-lose"},{"level":2,"text":"ہر کارپوریٹ ایکشن ایک نظر میں","id":"every-corporate-action-at-a-glance"},{"level":2,"text":"فوری خلاصہ","id":"quick-recap"}],"imgCount":2,"hasContent":true},"10":{"html":"<p>پہلی بار جب آپ کسی اسٹاک پر ٹیپ کرتے ہیں اور اقتباس کی سکرین کھلتی ہے، تو یہ محسوس کر سکتا ہے کہ ایئر لائن کاک پٹ، نمبروں کی دیوار، تیر اور چھوٹی میزیں، سب کچھ ایک ساتھ تبدیل ہو رہا ہے۔ پھر بھی وہاں موجود ہر ایک شخصیت آپ کو ایک سوال کے بارے میں کچھ آسان اور مفید بتا رہی ہے: <em>لوگ اس وقت اس حصص کو کس قیمت پر خرید رہے ہیں اور بیچ رہے ہیں، اور وہ کتنی بری طرح چاہتے ہیں؟</em></p>\n<p>ایک بار جب آپ کوئی اقتباس پڑھ لیتے ہیں، تو بازار شور مچانا بند کر دیتا ہے اور بات چیت شروع ہو جاتا ہے۔ اس باب میں ہم ایک چلتی ہوئی مثال کا استعمال کرتے ہوئے ایک عام اسکرین پر ہر نمبر کو ڈی کوڈ کریں گے، <strong>ریلائنس انڈسٹریز</strong> NSE پر۔ ذیل کے اعداد و شمار ایک ہیں۔ <strong>تعلیم کے لیے مثالی تصویر</strong>، ایک حقیقی وقت کی قیمت نہیں ہے، لیکن وہ بالکل اسی طرح ترتیب دیے گئے ہیں جیسے ایک حقیقی اقتباس ہوگا۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch10-quote-screen-annotated.png\" alt=\"ریلائنس انڈسٹریز کے لیے ایک تشریح شدہ سٹاک کوٹ اسکرین، جس میں کال آؤٹس کے ساتھ آخری تجارت کی گئی قیمت، بولی اور پوچھنا، اوپن-ہائی لو-کلوز، دن کا حجم، اور فیصد کی تبدیلی\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>ریلائنس انڈسٹریز کے لیے ایک تشریح شدہ سٹاک کوٹ اسکرین، جس میں کال آؤٹس کے ساتھ آخری تجارت کی گئی قیمت، بولی اور پوچھنا، اوپن-ہائی لو-کلوز، دن کا حجم، اور فیصد کی تبدیلی</figcaption></figure>\n<h2 id=\"the-headline-ltp-and-last-traded-quantity\">سرخی: LTP اور آخری تجارت شدہ مقدار</h2>\n<p>اسکرین پر سب سے بڑا نمبر ہے۔ <strong>LTP، آخری تجارتی قیمت</strong>. یہ صرف قیمت ہے جس پر <em>سب سے حالیہ</em> اس اسٹاک میں تجارت اصل میں ہوا. اوسط نہیں، تخمینہ نہیں، خریدار اور بیچنے والے کے درمیان آخری حقیقی مصافحہ۔</p>\n<table>\n<thead>\n<tr>\n<th>میدان</th>\n<th align=\"right\">قدر (اسنیپ شاٹ)</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>LTP</td>\n<td align=\"right\">1,476.30 روپے</td>\n</tr>\n<tr>\n<td>آخری تجارت کی مقدار</td>\n<td align=\"right\">45 شیئرز</td>\n</tr>\n<tr>\n<td>پچھلا بند</td>\n<td align=\"right\">1,468.50 روپے</td>\n</tr>\n<tr>\n<td>تبدیلی</td>\n<td align=\"right\">+7.80 روپے (+0.53%)</td>\n</tr>\n</tbody></table>\n<p>اس کے بالکل ساتھ بیٹھا ہے۔ <strong>آخری تجارت کی مقدار</strong>، اس حتمی تجارت میں کتنے حصص نے ہاتھ بدلے (یہاں، 45)۔ دی <strong>تبدیلی</strong> LTP کا کل کے ساتھ موازنہ کرتا ہے۔ <strong>پچھلے بند</strong>، اور روپے میں اور فیصد کے طور پر دکھایا گیا ہے۔ سبز کا مطلب ہے اسٹاک کل کے قریب سے اوپر ہے، سرخ کا مطلب نیچے ہے۔ وہ فیصد، روپے کے اعداد و شمار سے نہیں، اس کا مطلب وہی ہوتا ہے جب لوگ کہتے ہیں کہ اسٹاک \"آدھا فیصد اوپر\" ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>LTP تاریخ ہے، کوئی وعدہ نہیں۔ یہ آپ کو بتاتا ہے کہ آخری تجارت کہاں ہے۔ <em>کیا</em> ہوتا ہے، نہ کہ اگلا کہاں ہوتا ہے۔ <em>مرضی</em>. اگلی تجارت ایک مختلف قیمت پر ہو سکتی ہے، جو بالکل وہی ہے جو بولی اور پوچھتی ہے، اگلے آنے سے آپ کو اندازہ لگانے میں مدد ملتی ہے۔</p>\n</div></div>\n<h2 id=\"bid-ask-and-the-spread\">بولی، پوچھو اور پھیلاؤ</h2>\n<p>اسٹاک کی ایک قیمت نہیں ہوتی۔ اس کی ہر لمحہ دو قیمتیں ہیں:</p>\n<ul>\n<li>دی <strong>بولی</strong> سب سے زیادہ قیمت ہے a <em>خریدار</em> فی الحال ادا کرنے کو تیار ہے۔</li>\n<li>دی <strong>پوچھنا</strong> (یا پیشکش) سب سے کم قیمت ہے a <em>بیچنے والا</em> فی الحال قبول کرنے کو تیار ہے۔</li>\n</ul>\n<p>ہمارے سنیپ شاٹ میں بہترین بولی ہے۔ <strong>1,476.20 روپے</strong> اور سب سے بہتر سوال ہے <strong>1,476.30 روپے</strong>. تجارت صرف اس وقت ہوتی ہے جب کوئی خریدار سوال کی ادائیگی پر راضی ہوتا ہے، یا بیچنے والا بولی لینے پر راضی ہوتا ہے، جس وقت وہ ملتے ہیں، ایک نیا LTP پیدا ہوتا ہے۔</p>\n<p>ان کے درمیان فرق، یہاں صرف <strong>0.10 روپے</strong>، ہے <strong>پھیلاؤ</strong>. یہ ایک پرسکون لیکن طاقتور کوالٹی سگنل ہے:</p>\n<ul>\n<li>اے <strong>تنگ پھیلاؤ</strong> (کچھ پیسے، جیسے ریلائنس) کا مطلب ہے اسٹاک <strong>مائع</strong>بہت سارے خریدار اور بیچنے والے، مناسب قیمت کے قریب تجارت کرنا آسان ہے۔</li>\n<li>اے <strong>وسیع پھیلاؤ</strong> (روپے کے علاوہ) کا مطلب ہے اسٹاک ہے۔ <strong>غیر مائع</strong>، کم سود، اور آپ صرف تجارت مکمل کرنے کے لیے ادائیگی کر سکتے ہیں یا فروخت کر سکتے ہیں۔</li>\n</ul>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>کوئی بھی چھوٹا یا غیر مانوس اسٹاک خریدنے سے پہلے اسپریڈ پر ایک نظر ڈالیں۔ ایک وسیع پھیلاؤ ایک انتباہ ہے کہ حاصل کرنا <em>باہر</em> بعد میں آپ کو آپ کی توقع سے زیادہ لاگت آسکتی ہے، قیمت کو آپ کے حق میں منتقل کرنا پڑتا ہے تاکہ آپ نے راستے میں جو خلا عبور کیا ہو۔</p>\n</div></div>\n<h2 id=\"open-high-low-close-the-day-s-story-in-four-numbers\">کھلا، اونچا، کم، بند: چار نمبروں میں دن کی کہانی</h2>\n<p>چار نمبر، ایک ساتھ بلایا <strong>OHLC</strong>، پورے تجارتی دن کا خلاصہ کریں:</p>\n<table>\n<thead>\n<tr>\n<th></th>\n<th align=\"right\">قدر (اسنیپ شاٹ)</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><strong>کھولیں۔</strong></td>\n<td align=\"right\">1,470.00 روپے</td>\n</tr>\n<tr>\n<td><strong>اعلی</strong></td>\n<td align=\"right\">1,482.70 روپے</td>\n</tr>\n<tr>\n<td><strong>کم</strong></td>\n<td align=\"right\">1,466.20 روپے</td>\n</tr>\n<tr>\n<td><strong>پچھلا بند</strong></td>\n<td align=\"right\">1,468.50 روپے</td>\n</tr>\n</tbody></table>\n<ul>\n<li><strong>کھولیں۔</strong>, پہلی تجارت کی قیمت جب مارکیٹ صبح 9:15 بجے کھلی۔</li>\n<li><strong>اعلی</strong>، آج اب تک کی سب سے زیادہ قیمت چھو گئی۔</li>\n<li><strong>کم</strong>، آج تک کی سب سے کم قیمت چھو گئی۔</li>\n<li><strong>بند</strong>, دن کی آخری قیمت (جب تک مارکیٹ بند نہیں ہو جاتی، <strong>پچھلے بند</strong> حوالہ کے طور پر کھڑا ہے)۔</li>\n</ul>\n<p>یہ چار ہر ایک کا خام مال ہیں۔ <strong>موم بتی</strong> قیمت کے چارٹ پر: ہر موم بتی ایک مدت کی کھلی، اونچی، کم اور قریبی شکل میں پیک کرتی ہے۔ OHLC پڑھنا سیکھیں اور آپ پہلے ہی موم بتیاں پڑھ رہے ہیں۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch10-reliance-candlestick.png\" alt=\"ریلائنس انڈسٹریز کا روزانہ کینڈل سٹک چارٹ، جہاں ہر موم بتی کا جسم کھلے اور بند تک پھیلا ہوا ہے اور پتلی وکس دن کے اونچے اور نیچے تک پہنچ جاتی ہیں۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>ریلائنس انڈسٹریز کا روزانہ کینڈل سٹک چارٹ، جہاں ہر موم بتی کا جسم کھلے اور بند تک پھیلا ہوا ہے اور پتلی وکس دن کے اونچے اور نیچے تک پہنچ جاتی ہیں۔</figcaption></figure>\n<h2 id=\"volume-how-much-conviction-is-behind-the-move\">حجم: اس اقدام کے پیچھے کتنا یقین ہے۔</h2>\n<p><strong>حجم</strong> ہمارے اسنیپ شاٹ میں، تقریباً، دن بھر ٹریڈ ہونے والے حصص کی کل تعداد ہے۔ <strong>85 لاکھ شیئرز</strong> اب تک حجم مارکیٹ کا ہے۔ <em>شدت ڈائل</em>. بھاری حجم پر قیمت کی منتقلی کا مطلب ہے کہ بہت سے شرکاء متفق ہیں اور اس پر عمل کر رہے ہیں۔ پتلی حجم پر ایک ہی اقدام مٹھی بھر تجارت ہے جو شاید قائم نہ رہے۔</p>\n<ul>\n<li><strong>قیمت میں اضافہ + زیادہ حجم</strong> = اس کے پیچھے حقیقی یقین کے ساتھ ایک اقدام۔</li>\n<li><strong>قیمت میں اضافہ + کم والیوم</strong> = ایک عارضی بہاؤ جو آسانی سے پلٹ سکتا ہے۔</li>\n</ul>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>NSE پر، ایک فعال لارج کیپ جیسا کہ ریلائنس <em>کروڑ</em> ایک ہی دن میں شیئرز، یعنی صبح 9:15 سے 3:30 بجے کے درمیان ہاتھ بدلنے والے ہزاروں کروڑ روپے کے شیئرز۔ ان تجارتوں میں سے ہر ایک نے LTP کو اپ ڈیٹ کیا۔ کوٹ اسکرین آرڈرز کے سمندر کی سطح ہے جو نیچے سے گزر رہی ہے۔</p>\n</div></div>\n<h2 id=\"market-depth-the-five-level-order-book\">مارکیٹ کی گہرائی: پانچ درجے کی آرڈر بک</h2>\n<p>یہ وہ حصہ ہے جو ایک آرام دہ ناظرین کو کسی ایسے شخص سے الگ کرتا ہے جو واقعی ایک اقتباس پڑھتا ہے، <strong>مارکیٹ کی گہرائی</strong>, بھی کہا جاتا ہے <strong>آرڈر بک</strong>. یہ دکھاتا ہے۔ <strong>پانچ بہترین خرید آرڈر اور پانچ بہترین فروخت کے آرڈر</strong> ان کی قیمتوں اور مقدار کے ساتھ قطار میں انتظار کر رہے ہیں۔ (معیاری خوردہ اسکرینیں ہر طرف پانچ سطحیں دکھاتی ہیں؛ ہمیں بس یہی ضرورت ہے۔)</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch10-market-depth-orderbook.png\" alt=\"ریلائنس کے لیے پانچ سطحی مارکیٹ کی گہرائی والی ونڈو، جس میں خرید کی طرف پانچ بولی کی قیمتیں اور مقداریں اور فروخت کی طرف پانچ قیمتیں اور مقداریں، نیز خرید و فروخت کی کل مقدار\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">ڈیٹا یعنی</span>ریلائنس کے لیے پانچ سطحی مارکیٹ کی گہرائی والی ونڈو، جس میں خرید کی طرف پانچ بولی کی قیمتیں اور مقداریں اور فروخت کی طرف پانچ قیمتیں اور مقداریں، نیز خرید و فروخت کی کل مقدار</figcaption></figure>\n<table>\n<thead>\n<tr>\n<th align=\"right\">بولی کی مقدار</th>\n<th align=\"right\">بولی کی قیمت</th>\n<th align=\"right\">قیمت پوچھیں۔</th>\n<th align=\"right\">مقدار پوچھیں۔</th>\n</tr>\n</thead>\n<tbody><tr>\n<td align=\"right\">320</td>\n<td align=\"right\">1,476.20</td>\n<td align=\"right\">1,476.30</td>\n<td align=\"right\">280</td>\n</tr>\n<tr>\n<td align=\"right\">540</td>\n<td align=\"right\">1,476.10</td>\n<td align=\"right\">1,476.40</td>\n<td align=\"right\">610</td>\n</tr>\n<tr>\n<td align=\"right\">1,250</td>\n<td align=\"right\">1,476.00</td>\n<td align=\"right\">1,476.50</td>\n<td align=\"right\">900</td>\n</tr>\n<tr>\n<td align=\"right\">410</td>\n<td align=\"right\">1,475.90</td>\n<td align=\"right\">1,476.60</td>\n<td align=\"right\">350</td>\n</tr>\n<tr>\n<td align=\"right\">760</td>\n<td align=\"right\">1,475.80</td>\n<td align=\"right\">1,476.70</td>\n<td align=\"right\">1,100</td>\n</tr>\n</tbody></table>\n<p>اسے اس طرح پڑھیں جیسے درمیان میں دو سیڑھیاں مل رہی ہوں۔ دی <strong>بائیں طرف</strong> مانگ ہے، خریدار صرف موجودہ قیمت سے نیچے جمع ہیں۔ دی <strong>دائیں طرف</strong> سپلائی ہے، بیچنے والے بالکل اوپر جمع ہیں۔ سب سے اوپر کی قطار بہترین بولی رکھتی ہے اور بہترین سوال جو ہم پہلے ہی مل چکے ہیں۔ نیچے کی ہر قطار اپنی باری کے انتظار میں قدرے بدتر قیمت ہے۔</p>\n<p>گہرائی کی کھڑکی سے پتہ چلتا ہے۔ <strong>جہاں دباؤ ہے</strong>. اگر خرید کی مقدار فروخت کی مقدار کو کم کر دیتی ہے، تو قیمت کے مقابلے میں سپلائی کے دباؤ سے زیادہ مانگ ہوتی ہے، اور اس کے برعکس۔ بہت ساری اسکرینیں بھی اس کے طور پر جمع کرتی ہیں۔ <strong>کل خرید کی مقدار</strong> اور <strong>کل فروخت کی مقدار</strong> تمام زیر التواء آرڈرز میں، مجموعی ٹگ آف وار کا فوری مطالعہ۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>مارکیٹ کی گہرائی ہے۔ <em>سپلائی اور ڈیمانڈ کو ظاہر کیا گیا۔</em>. بولی پر بیٹھا ہوا ایک بڑا آرڈر عارضی فرش کی طرح کام کر سکتا ہے۔ فروخت کے آرڈر کی ایک دیوار بالکل اوپر چھت کی طرح کام کر سکتی ہے۔ یہ کرسٹل بال نہیں ہے، وہ آرڈرز فوری طور پر منسوخ کیے جا سکتے ہیں، لیکن یہ آپ کو موجودہ قیمت کے ارد گرد خریداروں اور فروخت کنندگان کا فوری توازن دکھاتا ہے۔</p>\n</div></div>\n<h2 id=\"circuit-limits-the-market-s-safety-valve\">سرکٹ کی حدود: مارکیٹ کا حفاظتی والو</h2>\n<p>کسی اسٹاک کو ایک ہی سیشن میں بے قابو ہو کر بڑھنے یا کریش ہونے سے روکنے کے لیے، ایکسچینج ایک سیٹ کرتا ہے۔ <strong>قیمت بینڈ</strong>، اور اس بینڈ کے کنارے ہیں۔ <strong>سرکٹ کی حدود</strong>:</p>\n<ul>\n<li>دی <strong>اوپری سرکٹ</strong> آج قیمت بڑھنے کی زیادہ سے زیادہ حد ہے۔</li>\n<li>دی <strong>کم سرکٹ</strong> زیادہ سے زیادہ ہے جو آج گر سکتا ہے۔</li>\n</ul>\n<p>بینڈز عام ہیں۔ <strong>2%، 5%، 10% یا 20%</strong>اسٹاک پر منحصر ہے. جب کوئی اسٹاک اپنے اوپری سرکٹ سے ٹکرا جاتا ہے، وہاں صرف خریدار ہوتے ہیں اور کوئی بیچنے والا نہیں ہوتا، لہذا اس قیمت پر تجارت مؤثر طریقے سے منجمد ہوجاتی ہے۔ نچلے سرکٹ پر، ریورس. ان کے سرکٹس میں باقاعدگی سے چھوٹے کیپس سلیم کی تجارت کی جاتی ہے، جو ایک اور وجہ ہے کہ وہ خطرناک ہیں۔ مشتق طبقہ میں بڑے، مائع اسٹاک میں وسیع، لچکدار بینڈ ہوتے ہیں اور شاذ و نادر ہی لاک ہوتے ہیں، لیکن حفاظتی والو ہمیشہ موجود ہوتا ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>\"اوپری سرکٹ میں بند\" اسٹاک سنسنی خیز لگ سکتا ہے، لیکن یہ بے صبروں کے لیے ایک جال ہے: اگر آپ نے وہاں ایک منجمد خریدا ہے، تو آپ اس وقت تک فروخت نہیں کر سکتے جب تک کہ خریدار ظاہر نہ ہو جائیں، اور جب ایک hyped چھوٹی ٹوپی آخر میں بدل جاتی ہے، تو وہ مار سکتا ہے۔ <em>کم</em> دن بہ دن سرکٹس میں کوئی خریدار نظر نہیں آتا، جس سے آپ باہر نکلنے سے قاصر رہتے ہیں۔ سرکٹس دونوں طریقوں سے کاٹتے ہیں۔</p>\n</div></div>\n<h2 id=\"quick-recap\">فوری خلاصہ</h2>\n<ul>\n<li>دی <strong>LTP</strong> کے ساتھ آخری اصل تجارت کی قیمت ہے۔ <strong>تبدیلی</strong> کل کے مقابلے میں ماپا گیا۔ <strong>پچھلے بند</strong>، عام طور پر فیصد کے طور پر پڑھیں۔</li>\n<li>دی <strong>بولی</strong> (بہترین خریدار) اور <strong>پوچھنا</strong> (بہترین فروخت کنندہ) قیمت کو بریکٹ کریں؛ دی <strong>پھیلاؤ</strong> ان کے درمیان اشارہ کرتا ہے کہ اسٹاک کتنا مائع ہے۔</li>\n<li><strong>OHLC</strong>، کھلا، اونچا، کم، بند، دن کی کہانی کو چار نمبروں میں بتاتا ہے اور ہر ایک کی شکل دیتا ہے۔ <strong>موم بتی</strong> ایک چارٹ پر.</li>\n<li><strong>حجم</strong> یقین کے اقدامات: بھاری حجم پر اقدام کا مطلب کاروبار ہے۔ پتلی حجم پر، احتیاط کے ساتھ علاج کریں.</li>\n<li>دی <strong>پانچ سطحی مارکیٹ کی گہرائی</strong> پانچ بہترین خرید و فروخت کے آرڈرز کو دکھاتا ہے جو موجودہ قیمت کے ارد گرد نظر آنے والے انتظار، سپلائی اور ڈیمانڈ ہیں۔</li>\n<li><strong>سرکٹ کی حدود</strong> اس بات کا تعین کریں کہ ایک اسٹاک ایک دن میں کتنی دور جا سکتا ہے، منجمد بھگوڑے بڑھتے اور کریش ہوتے ہیں، اور بے صبروں کو پھنساتے ہیں۔</li>\n</ul>\n<p>اب آپ اعتماد کے ساتھ ایک اسٹاک کا اقتباس پڑھ سکتے ہیں۔ اس کے بعد ہم ان نمبروں کو زوم آؤٹ کرتے ہیں جو ہر کوئی خبروں پر حوالہ دیتا ہے۔ <strong>نفٹی اور سینسیکس</strong>، اور بالکل دیکھیں کہ ان درجنوں انفرادی اسٹاکس سے انڈیکس کیسے بنتا ہے، اور یہ کیوں بڑھتا اور گرتا ہے۔</p>\n","toc":[{"level":2,"text":"سرخی: LTP اور آخری تجارت شدہ مقدار","id":"the-headline-ltp-and-last-traded-quantity"},{"level":2,"text":"بولی، پوچھو اور پھیلاؤ","id":"bid-ask-and-the-spread"},{"level":2,"text":"کھلا، اونچا، کم، بند: چار نمبروں میں دن کی کہانی","id":"open-high-low-close-the-day-s-story-in-four-numbers"},{"level":2,"text":"حجم: اس اقدام کے پیچھے کتنا یقین ہے۔","id":"volume-how-much-conviction-is-behind-the-move"},{"level":2,"text":"مارکیٹ کی گہرائی: پانچ درجے کی آرڈر بک","id":"market-depth-the-five-level-order-book"},{"level":2,"text":"سرکٹ کی حدود: مارکیٹ کا حفاظتی والو","id":"circuit-limits-the-market-s-safety-valve"},{"level":2,"text":"فوری خلاصہ","id":"quick-recap"}],"imgCount":3,"hasContent":true},"11":{"html":"<p>کسی بھی کاروباری نیوز چینل کو آن کریں اور دس سیکنڈ کے اندر آپ کو ایک ہی نمبر سنائی دے گا جو آپ کو یہ بتاتا ہے کہ آج \"مارکیٹ\" نے کیسا کام کیا۔ \"نفٹی 120 پوائنٹس کے ساتھ بند ہوا۔\" \"سینسیکس نصف فیصد گر گیا.\" لیکن ہندوستان میں 2,000 سے زیادہ لسٹڈ کمپنیاں ہیں، اور کسی بھی دن کچھ بڑھتے ہیں اور کچھ گر جاتے ہیں۔ تو ایک نمبر ہزاروں چلتی قیمتوں کو کیسے جمع کر سکتا ہے؟ جواب ہے ایک <strong>انڈیکس</strong>، ریاضی کا ایک ہوشیار ٹکڑا جو اسٹاک کی پوری ٹوکری کو ایک شکل میں نچوڑ دیتا ہے جسے آپ ایک نظر میں ٹریک کرسکتے ہیں۔ یہ مارکیٹ کا تھرمامیٹر ہے۔</p>\n<p>اس باب میں ہم اس تھرمامیٹر کو کھولیں گے اور دیکھیں گے کہ اس کے اندر کیا ہے: یہ کون سا ذخیرہ رکھتا ہے (اس کا <strong>اجزاء</strong>)، ہر ایک کتنا شمار کرتا ہے (اس کا <strong>وزن</strong>)، اور، وہ حصہ جو زیادہ تر ابتدائی افراد کبھی بھی بالکل ٹھیک نہیں سمجھتے ہیں۔ <em>کس طرح</em> تعداد بڑھتی ہے یا گرتی ہے جب وہ اسٹاک دن بھر حرکت کرتے ہیں۔</p>\n<h2 id=\"what-an-index-actually-is\">ایک انڈیکس اصل میں کیا ہے</h2>\n<p>ایک اشاریہ صرف ایک ہے۔ <strong>اسٹاک کی ایک منتخب ٹوکری کا وزنی خلاصہ</strong>، ایک واحد نمبر کے طور پر ظاہر کیا گیا ہے۔ ہندوستان کے دو ہیڈ لائن انڈیکس ہیں:</p>\n<ul>\n<li>دی <strong>نفٹی 50</strong>، NSE کے ذریعہ چلایا جاتا ہے، یہ ٹریک کرتا ہے۔ <strong>50 بڑی کمپنیاں</strong>.</li>\n<li>دی <strong>سنسیکس</strong> (حساس انڈیکس کے لیے مختصر)، BSE کے ذریعے چلایا جاتا ہے، یہ ٹریک کرتا ہے۔ <strong>30 بڑی کمپنیاں</strong>.</li>\n</ul>\n<p>دونوں کو وسیع مارکیٹ کی نمائندگی کرنے کے لیے ڈیزائن کیا گیا ہے: بڑے شعبوں میں سب سے بڑی، سب سے زیادہ تجارت کرنے والی کمپنیوں کو چنیں، ان کو ایک ساتھ بنڈل کریں، اور نتیجے میں آنے والی تعداد \"مارکیٹ\" کی طرح اوپر نیچے ہوتی ہے۔ جب لوگ کہتے ہیں کہ \"آج مارکیٹ اوپر تھی\"، تو ان کا تقریباً ہمیشہ مطلب یہ ہوتا ہے کہ ان دو انڈیکس میں سے ایک میں اضافہ ہوا۔</p>\n<p>سطح خود، نفٹی ارد گرد منڈلا رہا ہے۔ <strong>23,800</strong> یا سینسیکس کے قریب <strong>76,200</strong> (تقریباً، وسط 2026)، روپیہ نہیں ہے اور یہ ایسی قیمت نہیں ہے جسے آپ خرید سکتے ہیں۔ یہ صرف ایک رننگ اسکور ہے، جو دہائیوں پہلے ایک بنیادی قدر سے شروع ہوا تھا اور جوں جوں جزوی کمپنیوں میں اضافہ ہوا ہے اس کو آگے بڑھایا گیا ہے۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>نفٹی اور سینسیکس بہت زیادہ اوورلیپ ہوتے ہیں، بڑے بینک، ریلائنس اور IT میجر دونوں میں بیٹھتے ہیں، یہی وجہ ہے کہ دونوں انڈیکس تقریباً ہمیشہ ایک ہی سمت میں کسی بھی دن یکساں فیصد کے ساتھ آگے بڑھتے ہیں۔ نفٹی 50 فنڈز اور ڈیریویٹیوز کے لیے زیادہ وسیع پیمانے پر ٹریک کردہ بینچ مارک ہے۔</p>\n</div></div>\n<h2 id=\"the-constituents-who-is-actually-inside\">اجزاء: اصل میں اندر کون ہے۔</h2>\n<p>ایک انڈیکس بنانے والی کمپنیاں اس کی ہیں۔ <strong>اجزاء</strong>. لیکن یہاں ایک اہم خیال ہے جو تقریباً ہر ابتدائی کو حاصل کرتا ہے: <strong>ہر حلقہ برابر شمار نہیں ہوتا۔</strong> ریلائنس جیسی دیو انڈیکس کو ایک چھوٹے ممبر سے کہیں زیادہ مشکل سے کھینچتی ہے۔ ہر اسٹاک کو تفویض کیا جاتا ہے a <strong>وزن</strong>، کل انڈیکس میں اس کا حصہ، اور اس وزن کا فیصلہ کیا جاتا ہے۔ <strong>فری فلوٹ مارکیٹ کیپٹلائزیشن</strong>.</p>\n<p>یہ جملہ خوفناک لگتا ہے۔ یہ ایک بار دو ٹکڑوں میں ٹوٹ جانے کے بعد آسان ہے:</p>\n<ul>\n<li><strong>مارکیٹ کیپٹلائزیشن</strong> = حصص کی قیمت x حصص کی کل تعداد۔ یہ پوری کمپنی کی پوری قیمت کا ٹیگ ہے۔</li>\n<li><strong>فری فلوٹ</strong> = صرف وہ حصص جو اصل میں عوام کے لیے تجارت کے لیے دستیاب ہیں، یہ <em>شامل نہیں</em> حصہ پروموٹرز، حکومت، یا اسٹریٹجک ہولڈرز کے ساتھ بند ہے۔</li>\n</ul>\n<p>لہذا کمپنی کا وزن اس کی قدر کو ظاہر کرتا ہے۔ <em>قابل تجارت</em> شیئرز فری فلوٹ ویلیو جتنی بڑی ہوگی، اس کا انڈیکس کا ٹکڑا اتنا ہی بڑا ہوگا، اور یہ اتنی ہی مشکل سے نمبر کو گھیرے گا۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch11-weighted-basket.png\" alt=\"نفٹی 50 کو ایک وزنی ٹوکری کے طور پر تیار کیا گیا ہے، ہیوی ویٹ جیسے کہ HDFC بینک، ICICI بینک اور ریلائنس زیادہ تر جگہ کو بھرتے ہیں، جب کہ سب سے چھوٹے اراکین سلیور ہیں۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">انفوگرافک</span>نفٹی 50 کو ایک وزنی ٹوکری کے طور پر تیار کیا گیا ہے، ہیوی ویٹ جیسے HDFC بینک، ICICI بینک اور ریلائنس زیادہ تر جگہ کو بھرتے ہیں، جب کہ سب سے چھوٹے اراکین سلیور ہیں۔</figcaption></figure>\n<p>یہ ہے جو نفٹی 50 کے سب سے اوپر ہے، جو NSE کی اپنی انڈیکس فیکٹ شیٹ سے لیا گیا ہے۔ ہر شخصیت کے ساتھ سلوک کریں۔ <strong>لگ بھگ</strong>قیمتیں بڑھنے کے ساتھ ہی وزن روزانہ بڑھتا ہے اور سال میں دو بار ان میں ردوبدل ہوتا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th>رینک</th>\n<th>کمپنی</th>\n<th>سیکٹر</th>\n<th align=\"right\">تقریبا وزن</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>1</td>\n<td>HDFC بینک</td>\n<td>مالیات (بینکنگ)</td>\n<td align=\"right\">~10.6%</td>\n</tr>\n<tr>\n<td>2</td>\n<td>ICICI بینک</td>\n<td>مالیات (بینکنگ)</td>\n<td align=\"right\">~8.3%</td>\n</tr>\n<tr>\n<td>3</td>\n<td>ریلائنس انڈسٹریز</td>\n<td>توانائی / خوردہ / ٹیلی کام</td>\n<td align=\"right\">~8.3%</td>\n</tr>\n<tr>\n<td>4</td>\n<td>بھارتی ایرٹیل</td>\n<td>ٹیلی کام</td>\n<td align=\"right\">~5.2%</td>\n</tr>\n<tr>\n<td>5</td>\n<td>لارسن اینڈ ٹوبرو</td>\n<td>تعمیر / انفرا</td>\n<td align=\"right\">~4.4%</td>\n</tr>\n<tr>\n<td>6</td>\n<td>انفوسس</td>\n<td>IT</td>\n<td align=\"right\">~3.8%</td>\n</tr>\n<tr>\n<td>7</td>\n<td>اسٹیٹ بینک آف انڈیا</td>\n<td>مالیات (بینکنگ)</td>\n<td align=\"right\">~3.7%</td>\n</tr>\n<tr>\n<td>8</td>\n<td>ایکسس بینک</td>\n<td>مالیات (بینکنگ)</td>\n<td align=\"right\">~3.4%</td>\n</tr>\n<tr>\n<td>9</td>\n<td>کوٹک مہندرا بینک</td>\n<td>مالیات (بینکنگ)</td>\n<td align=\"right\">~2.6%</td>\n</tr>\n<tr>\n<td>10</td>\n<td>ITC</td>\n<td>FMCG</td>\n<td align=\"right\">~2.6%</td>\n</tr>\n</tbody></table>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch11-top-weights-bar.png\" alt=\"وزن کے لحاظ سے سرفہرست دس نفٹی 50 اجزاء ( NSE فیکٹ شیٹ)، HDFC بینک سے نیچے کی ایک کھڑی سیڑھی، جس سے یہ ظاہر ہوتا ہے کہ انڈیکس واقعی کس قدر یک طرفہ ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>وزن کے لحاظ سے سرفہرست دس نفٹی 50 اجزاء ( NSE فیکٹ شیٹ)، HDFC بینک سے نیچے کی ایک سیڑھی، یہ ظاہر کرتی ہے کہ انڈیکس واقعی کتنا یک طرفہ ہے۔</figcaption></figure>\n<p>ارتکاز کو دیکھو۔ دی <strong>سب سے اوپر 10 نام اکیلے نصف سے زیادہ بناتے ہیں</strong> (تقریباً 53%) پورے 50-اسٹاک انڈیکس کا۔ باقی 40 کمپنیاں جو بچا ہے اس میں شریک ہیں۔ اور نوٹس کیسے کریں <strong>مالیات کا غلبہ</strong>، بڑے بینکوں اور دوسرے قرض دہندگان کو اکٹھا کریں اور صرف مالیاتی خدمات کے بارے میں ہے۔ <strong>35%</strong> نفٹی کا، کسی ایک شعبے میں ایک تہائی سے زیادہ۔ یہی وجہ ہے کہ بینکوں کے لیے ایک برا دن اکثر پورے انڈیکس کے لیے ایک برا دن ہوتا ہے۔</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>ایک کمپنی پوری ہندوستانی مارکیٹ کو جھول سکتی ہے۔ HDFC بینک، نفٹی کا سب سے بڑا جزو ہے جو کہ پورے انڈیکس کے تقریباً دسویں حصے پر ہے، نفٹی کو اپنے طور پر نمایاں طور پر اوپر لے جا سکتا ہے جب یہ چند فیصد بڑھتا ہے۔ اور HDFC بینک پلس ریلائنس مل کر ٹوکری کا تقریباً پانچواں حصہ ہیں، اس سے پہلے کہ دیگر 48 اراکین نے کوئی کام کیا ہو۔</p>\n</div></div>\n<h2 id=\"how-the-index-actually-rises-and-falls\">انڈیکس اصل میں کیسے بڑھتا اور گرتا ہے۔</h2>\n<p>اب وہ حصہ جو ہر کوئی چاہتا ہے اور کچھ ہی واضح طور پر بیان کرتے ہیں۔ انڈیکس کی سطح ہے <strong>اس کے تمام اجزاء کی چالوں کا وزنی مجموعہ۔</strong> ہر اسٹاک دن کی تبدیلی میں حصہ ڈالتا ہے۔ <em>اس کے وزن کے تناسب سے۔</em></p>\n<p>ذہنی فارمولا صرف یہ ہے:</p>\n<blockquote>\n<p>انڈیکس میں اسٹاک کی شراکت = (اس کا وزن) x (اس کا فیصد منتقل)</p>\n</blockquote>\n<p>آئیے کام کی مثال کے ساتھ اسے ٹھوس بنائیں۔</p>\n<p>فرض کریں۔ <strong>HDFC بینک کا وزن ~10.6% ہے اور 2% بڑھتا ہے</strong> ایک اچھے دن پر. انڈیکس پر اس کا دھکا ہے:</p>\n<p>0.106 x 2% = <strong>0.212%</strong>، اس کے بارے میں کال کریں۔ <strong>+0.21%</strong>.</p>\n<p>وہ واحد اسٹاک، ایک معمولی 2% حرکت کرتا ہے، پورے نفٹی کو تقریباً ایک فیصد کا پانچواں حصہ اٹھاتا ہے۔</p>\n<p>اب ایک لے لو <strong>صرف ایک ~0.3% وزن کے ساتھ چھوٹا جزو جو 2% بھی بڑھتا ہے۔</strong> اس کی شراکت یہ ہے:</p>\n<p>0.003 x 2% = <strong>0.006%</strong>بنیادی طور پر <strong>کچھ نہیں</strong>. تم اسے دیکھ بھی نہیں سکتے۔</p>\n<p>دونوں اسٹاک میں یکساں 2% حرکت، لیکن HDFC بینک نے انڈیکس کو تقریباً آگے بڑھایا <strong>35 گنا مشکل</strong>، خالصتاً اس لیے کہ اس کا وزن تقریباً 35 گنا بڑا ہے۔ چھوٹے اسٹاک کا ایک شاندار دن ہوسکتا ہے اور انڈیکس بمشکل اسے رجسٹر کرے گا۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>انڈیکس ہر کمپنی کے بارے میں یکساں طور پر پرواہ نہیں کرتا ہے۔ ایک ہیوی ویٹ کی چھوٹی حرکت ایک چھوٹے کی بڑی حرکت کو پیچھے چھوڑ دیتی ہے۔ لہٰذا ایک سبز دن پر، مٹھی بھر بڑے وزن والے اسٹاکس نے عموماً تقریباً تمام لفٹنگ کی، اور سرخ دن پر، وہی چند لوگ گھسیٹتے تھے۔ \"آج مارکیٹ گر گئی\" اکثر واقعی کا مطلب ہے \"آج تین یا چار جنات گرے\"۔</p>\n</div></div>\n<p>یہی وجہ ہے کہ آپ تجزیہ کاروں کو یہ کہتے ہوئے سنیں گے کہ ریلی \"تنگ\" تھی یا \"چند ہیوی وائٹس کی قیادت میں۔\" اگر صرف ریلائنس اور سرفہرست بینکوں میں اضافہ ہوا جبکہ زیادہ تر دیگر اسٹاک گر گئے، انڈیکس اب بھی سبز رنگ کے قریب ہوسکتا ہے، ہیوی وائٹس نے بھیڑ کو پیچھے چھوڑ دیا۔ ہر جزو کے وزنی شراکت کو شامل کریں، مثبت اور منفی، اور کل ٹھیک دن کے اشاریہ میں تبدیلی ہے۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>ایک چھوٹے 3 اسٹاک انڈیکس کا تصور کریں۔ اسٹاک A کا وزن 60% ہے اور 1% بڑھتا ہے۔ اسٹاک B کا وزن 30% ہے اور 1% گرتا ہے۔ اسٹاک C کا وزن 10% ہے اور 3% بڑھتا ہے۔ شراکتیں: A = +0.60%، B = -0.30%، C = +0.30%۔ نیٹ = <strong>+0.60%</strong>. اگرچہ تین میں سے دو اسٹاک نے بمشکل مدد کی، لیکن ایک بڑے رکن نے لہجہ قائم کیا۔</p>\n</div></div>\n<h2 id=\"broad-indices-vs-sector-indices\">براڈ انڈیکس بمقابلہ سیکٹر انڈیکس</h2>\n<p>نفٹی 50 اور سینسیکس ہیں۔ <strong>وسیع</strong> انڈیکس، پوری مارکیٹ کا ایک کراس سیکشن۔ لیکن اسی وزنی ٹوکری کی چال کو تنگ کرنے کے لیے استعمال کیا جاتا ہے۔ <strong>سیکٹر انڈیکس</strong> جو معیشت کا ایک ٹکڑا ٹریک کرتا ہے:</p>\n<ul>\n<li><strong>بینک نفٹی</strong>، صرف بڑے بینک ( HDFC بینک، ICICI بینک، SBI، Axis، Kotak اور دیگر)۔ یہ نفٹی کے بعد ہندوستان میں سب سے زیادہ تجارت کرنے والا انڈیکس ہے۔</li>\n<li><strong>نفٹی IT</strong>، سافٹ ویئر برآمد کنندگان جیسے TCS، Infosys، Wipro اور HCLTech۔</li>\n<li>دیگر میں نفٹی آٹو، نفٹی فارما، نفٹی FMCG اور نفٹی میٹل شامل ہیں۔</li>\n</ul>\n<p>سیکٹر انڈیکس آپ کو دیکھنے دیتے ہیں۔ <em>دن کیا چل رہا ہے</em>. اگر نفٹی فلیٹ ہے لیکن نفٹی IT 3% نیچے ہے، تو آپ کو فوری طور پر معلوم ہو جائے گا کہ سافٹ ویئر اسٹاکس کا سیشن خراب ہے جبکہ باقی مارکیٹ برقرار ہے۔ بھی ہیں۔ <strong>وسیع تر</strong> بینچ مارکس، نفٹی 100، نفٹی 500 اور مڈ کیپ اور سمال کیپ انڈیکس، جو ٹاپ 50 سے کہیں زیادہ حاصل کرتے ہیں۔</p>\n<h2 id=\"why-indices-matter-to-you\">انڈیکس آپ کے لیے کیوں اہمیت رکھتا ہے۔</h2>\n<p>اشارے صرف ٹیلی ویژن کی سجاوٹ نہیں ہیں۔ وہ حقیقی کام کرتے ہیں:</p>\n<ul>\n<li><strong>ایک بینچ مارک۔</strong> جب ایک فنڈ مینیجر کہتا ہے کہ انہوں نے \"مارکیٹ کو ہرا دیا\" تو اس کا مطلب ہے کہ انہوں نے نفٹی 50 جیسے انڈیکس کو شکست دی۔</li>\n<li><strong>بازار کا موڈ بج رہا ہے۔</strong> 2,000 قیمتوں کو اسکین کیے بغیر، ایک نظر آپ کو بتاتی ہے کہ جذبات خوف زدہ ہیں یا لالچی۔</li>\n<li><strong>کوئی ایسی چیز جس کے آپ اصل میں مالک ہوسکتے ہیں۔</strong> آپ \"نفٹی\" نہیں خرید سکتے لیکن آپ <em>کر سکتے ہیں</em> ایک خریدیں <strong>انڈیکس فنڈ</strong> یا <strong>ETF</strong> جو میکانکی طور پر تمام 50 اجزاء کو اپنے صحیح وزن میں رکھتا ہے۔ ایک یونٹ خریدیں اور آپ پوری ٹوکری کا ایک ٹکڑا، فوری تنوع کے مالک ہیں، جس میں اسٹاک چننے کی ضرورت نہیں ہے۔ یہ ابتدائی افراد کے لیے سرمایہ کاری کا واحد مقبول ترین طریقہ ہے، اور ہم کورس کے بعد اس پر واپس آتے ہیں۔</li>\n</ul>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>انڈیکس فنڈز شاندار طور پر سست ہیں اور یہی ان کی طاقت ہے۔ فنڈ صرف انڈیکس کی عکاسی کرتا ہے، کوئی اسٹار مینیجر نہیں، کوئی ریسرچ ڈیسک فاتحوں کا اندازہ نہیں لگاتا، پھر بھی طویل عرصے میں اس \"پوری ٹوکری خریدیں\" کے نقطہ نظر نے <em>اکثریت</em> فعال طور پر منظم فنڈز کا جو اسے پیچھے چھوڑنے کی کوشش کرتے ہیں، اور قیمت کے ایک حصے پر۔</p>\n</div></div>\n<h2 id=\"quick-recap\">فوری خلاصہ</h2>\n<ul>\n<li>ایک <strong>انڈیکس</strong> ایک واحد نمبر ہے جو اسٹاک کی ٹوکری کا خلاصہ کرتا ہے، مارکیٹ کا تھرمامیٹر۔ بھارت کی شہ سرخیاں ہیں۔ <strong>نفٹی 50</strong> (NSE، 50 اسٹاک) اور <strong>سنسیکس</strong> (BSE، 30 اسٹاک)۔</li>\n<li>اندر اسٹاک ہیں <strong>اجزاء</strong>, اور ہر ایک لے جاتا ہے a <strong>وزن</strong> اس کی طرف سے مقرر <strong>فری فلوٹ مارکیٹ کیپ</strong>، بڑی قابل تجارت قدر کا مطلب ہے انڈیکس کا ایک بڑا ٹکڑا۔</li>\n<li>نفٹی ہے۔ <strong>سب سے زیادہ بھاری</strong>: تقریباً سرفہرست 10 نام اس کا تقریباً نصف ہیں، اور مالیات اپنے طور پر تقریباً ایک تہائی ہیں۔</li>\n<li>انڈیکس اس طرح حرکت کرتا ہے۔ <strong>وزنی رقم</strong> اس کے اجزاء میں سے: ہر اسٹاک کی شراکت = اس کا وزن x اس کا فیصد حرکت۔</li>\n<li>اے <strong>ہیوی ویٹ کا چھوٹا اقدام ایک چھوٹے کے بڑے اقدام کو پیچھے چھوڑ دیتا ہے۔</strong>, زیادہ تر سبز دنوں میں چند جنات نے لفٹنگ کی تھی، اور سرخ دنوں میں وہی چند لوگ گھسیٹتے تھے۔</li>\n<li><strong>سیکٹر انڈیکس</strong> (بینک نفٹی، نفٹی IT) ایک سلائس میں زوم کریں، جبکہ <strong>انڈیکس فنڈز</strong> آپ کو ایک سستی، متنوع خریداری میں پوری ٹوکری کے مالک ہونے دیں۔</li>\n</ul>\n<p>اس کے بعد، ہم اس زبان کو ڈی کوڈ کرتے ہیں جو مارکیٹ بولتی ہے، بیل اور ریچھ، بڑے کیپس اور پینی اسٹاکس، سرکٹس اور شارٹ سیلنگ، لہذا آپ کی اسکرین اور TV پر حرف آخر میں واضح ہو جاتا ہے۔</p>\n","toc":[{"level":2,"text":"ایک انڈیکس اصل میں کیا ہے","id":"what-an-index-actually-is"},{"level":2,"text":"اجزاء: اصل میں اندر کون ہے۔","id":"the-constituents-who-is-actually-inside"},{"level":2,"text":"انڈیکس اصل میں کیسے بڑھتا اور گرتا ہے۔","id":"how-the-index-actually-rises-and-falls"},{"level":2,"text":"براڈ انڈیکس بمقابلہ سیکٹر انڈیکس","id":"broad-indices-vs-sector-indices"},{"level":2,"text":"انڈیکس آپ کے لیے کیوں اہمیت رکھتا ہے۔","id":"why-indices-matter-to-you"},{"level":2,"text":"فوری خلاصہ","id":"quick-recap"}],"imgCount":2,"hasContent":true},"12":{"html":"<p>ہر شعبے کی اپنی زبان ہوتی ہے، اور اسٹاک مارکیٹ سب سے بدترین مجرم ہوسکتی ہے۔ بازار کے اوقات میں بزنس چینل آن کریں اور آپ کو الفاظ کی دیوار سے ٹکرا دیا جائے گا، \"بیل واپس آ گئے ہیں،\" \"اسمال کیپس کو ہتھوڑا لگ گیا،\" \"یہ اوپری سرکٹ سے ٹکرا گیا،\" \"FIIs شارٹ ہو گیا\"، رفتار سے ڈیلیور کیا گیا، گویا ہر کوئی دیکھنے والا پہلے ہی جانتا ہے کہ ان کا کیا مطلب ہے۔ ایک ابتدائی کے لیے یہ محسوس ہو سکتا ہے کہ ایک ایسے کمرے میں چلنا جہاں ہر کوئی ایک نجی کوڈ بول رہا ہو۔</p>\n<p>یہ باب آپ کا ڈیکوڈر رنگ ہے۔ ان میں سے کوئی بھی اصطلاح مشکل نہیں ہوتی جب کوئی ان کی سادہ انگریزی میں وضاحت کرتا ہے، اور آخر تک آپ ان الفاظ کو سمجھ جائیں گے جو سب سے زیادہ پھیلتے ہیں، بشمول وہ الفاظ جو پہلی بار سنتے ہی تقریباً ہر کسی کو الجھن میں ڈال دیتے ہیں: <strong>مختصر فروخت</strong>، جہاں لوگ کسی نہ کسی طرح پیسہ کماتے ہیں جب ایک اسٹاک <em>گرتا ہے</em>.</p>\n<h2 id=\"bulls-and-bears-the-market-s-two-moods\">بیل اور ریچھ: مارکیٹ کے دو موڈ</h2>\n<p>تمام سرمایہ کاری میں دو سب سے مشہور الفاظ مارکیٹ کی مجموعی سمت کو بیان کرتے ہیں۔</p>\n<ul>\n<li>اے <strong>بیل مارکیٹ</strong> بڑھتی ہوئی قیمتوں اور امید پرستی کا ایک مستقل دور ہے۔ سرمایہ کار پراعتماد ہیں، پیسہ آتا ہے، اور رجحان اوپر جاتا ہے۔</li>\n<li>اے <strong>ریچھ مارکیٹ</strong> اس کے برعکس ہے، ایک طویل زوال، عام طور پر ایک قطرہ کے طور پر بیان کیا جاتا ہے۔ <strong>20٪ یا اس سے زیادہ</strong> خوف اور مایوسی میں لپٹی حالیہ چوٹی سے۔</li>\n</ul>\n<p>یہ دو جانور کیوں؟ مقبول وضاحت میں ہے <em>ہر مخلوق کس طرح حملہ کرتی ہے۔</em>. اے <strong>بیل</strong> اس کے سینگ مارتا ہے۔ <strong>اوپر کی طرف</strong> ایک مخالف کو مارنے کے لیے، قیمتیں بڑھ رہی ہیں۔ اے <strong>ریچھ</strong> اس کے پنجوں کو swipes <strong>نیچے کی طرف</strong> نقصان پہنچانے کے لئے، قیمتیں نیچے کی جا رہی ہیں. اوپر سینگ، نیچے پنجے۔ یہ ایک یادگار تصویر ہے، اور یہ صدیوں سے جمی ہوئی ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch12-bull-vs-bear.png\" alt=\"بڑھتے ہوئے ٹرینڈ لائن کو چارج کرنے والا بیل بمقابلہ ریچھ گرتے ہوئے نیچے کی طرف سوائپ کر رہا ہے، اوپر کی طرف سینگ اور نیچے کی طرف پنجوں کی شکل جس نے مارکیٹ کے دو موڈ کا نام دیا\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>بڑھتے ہوئے ٹرینڈ لائن کو چارج کرنے والا بیل بمقابلہ ریچھ گرتے ہوئے نیچے کی طرف سوائپ کر رہا ہے، اوپر کی طرف سینگ اور نیچے کی طرف پنجوں کی شکل جس نے مارکیٹ کے دو موڈ کا نام دیا</figcaption></figure>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>بیل اور ریچھ کی زبان حقیقی طور پر پرانی ہے۔ \"ریچھ\" سب سے پہلے آیا، 18 ویں صدی کے لندن کے تاجر جنہوں نے کوئی ایسی چیز بیچی جو ابھی تک ان کے پاس نہیں تھی وہ \"ریچھ کو پکڑنے سے پہلے ریچھ کی کھال\" بیچ رہے تھے۔ پرامید \"بیل\" کو بعد میں اس کے فطری مخالف کے طور پر وضع کیا گیا۔ یہ الفاظ دنیا کے بیشتر اسٹاک ایکسچینج سے پرانے ہیں۔</p>\n</div></div>\n<h2 id=\"large-cap-mid-cap-small-cap\">بڑی ٹوپی، مڈ کیپ، چھوٹی ٹوپی</h2>\n<p>آپ مسلسل سُنیں گے کہ اسٹاک کو ترتیب دیا گیا ہے۔ <strong>مارکیٹ کیپٹلائزیشن</strong> (قیمت x حصص کی تعداد) تین بالٹیوں میں۔ ہندوستان میں، SEBI تعریف کو درست کرتا ہے۔ <em>درجہ</em>ایک مقررہ روپے کی قدر سے نہیں، اس لیے لیبلز بامعنی رہتے ہیں جیسے جیسے بازار بڑھتا ہے:</p>\n<table>\n<thead>\n<tr>\n<th>زمرہ</th>\n<th>مارکیٹ کیپ کے لحاظ سے درجہ بندیSEBI</th>\n<th>کھردرا کردار</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><strong>بڑی ٹوپی</strong></td>\n<td>ٹاپ 100 کمپنیاں</td>\n<td>بڑا، قائم، مستحکم۔ گھریلو نام \"بلیو چپس\"، ریلائنس اور HDFC بینک۔ کم خطرہ، مستحکم ترقی.</td>\n</tr>\n<tr>\n<td><strong>مڈ کیپ</strong></td>\n<td>101ویں سے 250ویں نمبر پر</td>\n<td>درمیانے سائز کا، اکثر تیزی سے بڑھنے والا۔ زیادہ انعام، زیادہ خطرہ۔</td>\n</tr>\n<tr>\n<td><strong>چھوٹی ٹوپی</strong></td>\n<td>251 واں آگے</td>\n<td>چھوٹی، کم ثابت شدہ کمپنیاں۔ سب سے زیادہ ترقی کی صلاحیت، اور تیز گرنے کا سب سے زیادہ خطرہ۔</td>\n</tr>\n</tbody></table>\n<p>ٹریڈ آف پوری کہانی ہے: چھوٹے کیپس آپ کے پیسے کو تیزی سے بڑھا سکتے ہیں۔ <em>اور</em> سب سے مشکل گر. گرجنے والی بیل مارکیٹ میں چھوٹی ٹوپی اکثر اڑتی ہے۔ جب خوف واپس آجاتا ہے، تو وہ سب سے پہلے اور سب سے گہرے حادثے کا شکار ہوتے ہیں۔ ابتدائی افراد کو عام طور پر اسی وجہ سے بڑے ٹوپیوں کی طرف بڑھایا جاتا ہے، وہ کارگو جہاز ہیں، سپیڈ بوٹس نہیں۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>\"بلیو چپ\" کا سیدھا مطلب ہے ایک بڑی، مالی طور پر ٹھوس، معروف کمپنی جس کا طویل ٹریک ریکارڈ ہے، یہ اصطلاح پوکر سے لی گئی ہے، جہاں نیلی چپس کی قیمت سب سے زیادہ ہوتی ہے۔ دوسری انتہا پر، a <strong>پیسہ اسٹاک</strong> ایک بہت سستا، چھوٹا، اکثر بمشکل تجارت کرنے والا حصہ ہے۔ کم قیمت کوئی سودا نہیں ہے۔ یہ عام طور پر ایک چھوٹی، نازک، آسانی سے جوڑ توڑ کرنے والی کمپنی کا اشارہ کرتا ہے۔</p>\n</div></div>\n<h2 id=\"circuits-the-market-s-automatic-brakes\">سرکٹس: مارکیٹ کے خودکار بریک</h2>\n<p>گھبراہٹ یا انماد کو جنگلی چلانے سے روکنے کے لیے، ہندوستانی تبادلے نافذ کرتے ہیں۔ <strong>سرکٹ کی حدود</strong>, قیمت بینڈ کہ <em>روکنا</em> اسٹاک میں تجارت جب یہ ایک ہی دن میں بہت آگے بڑھ جاتا ہے۔</p>\n<ul>\n<li>ایک <strong>اوپری سرکٹ</strong> اس دن اسٹاک میں زیادہ سے زیادہ اضافہ ہوسکتا ہے۔ اسے مارو اور صرف خریدار ہیں، کوئی بیچنے والا نہیں، قیمت سب سے اوپر منجمد ہے۔</li>\n<li>اے <strong>کم سرکٹ</strong> یہ زیادہ سے زیادہ گر سکتا ہے۔ اسے مارو اور صرف بیچنے والے ہیں، کوئی خریدار نہیں، نیچے منجمد ہے۔</li>\n</ul>\n<p>انفرادی اسٹاک میں اسٹاک کے لحاظ سے 2%، 5%، 10% یا 20% جیسے بینڈ ہوتے ہیں۔ بھی ہیں۔ <strong>مارکیٹ وسیع سرکٹ بریکر</strong>: اگر پورا نفٹی یا سینسیکس ایک دن میں 10%، 15% یا 20% گر جاتا ہے، تو پوری مارکیٹ میں تجارت کولنگ آف مدت کے لیے رک جاتی ہے۔ سرکٹس ایک حفاظتی والو ہیں، ایک زبردستی ٹائم آؤٹ تاکہ ہر کوئی اپنی سانسیں پکڑ سکے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>میں بند ایک اسٹاک <strong>اوپری سرکٹ</strong> ایک ضمانت یافتہ فاتح کی طرح محسوس کر سکتے ہیں، ہر کوئی چاہتا ہے، کوئی نہیں بیچ رہا ہے۔ یہ ایک کلاسک ٹریپ ہے۔ جب موڈ پلٹ جاتا ہے، تو وہی اسٹاک میں پھنس سکتا ہے۔ <strong>کم سرکٹ</strong> دن بہ دن، کوئی خریدار نہیں، ہولڈرز کو کسی بھی قیمت پر فروخت کرنے کے قابل نہیں چھوڑ دیا. سرکٹس دونوں طریقوں سے کاٹتے ہیں، اور وہ پتلی، ہائپڈ چھوٹی ٹوپیوں میں سب سے مشکل کاٹتے ہیں۔</p>\n</div></div>\n<h2 id=\"volume-and-liquidity\">حجم اور لیکویڈیٹی</h2>\n<p><strong>حجم</strong> ایک مدت، ایک دن، ایک گھنٹہ، ایک منٹ میں تجارت کیے گئے حصص کی تعداد ہے۔ زیادہ حجم کا مطلب ہے بہت ساری سرگرمی اور دلچسپی۔ بھاری حجم پر قیمت کے اقدام کو تجارت کی ایک چال پر ایک ہی اقدام سے زیادہ سنجیدگی سے لیا جاتا ہے۔</p>\n<p><strong>لیکویڈیٹی</strong> یہ ہے کہ آپ کتنی آسانی سے خرید یا فروخت کر سکتے ہیں۔ <em>قیمت کو منتقل کیے بغیر</em>. ایک انتہائی مائع اسٹاک (سوچئے کہ ریلائنس یا HDFC بینک) میں اتنے زیادہ خریدار اور بیچنے والے ہوتے ہیں کہ آپ مناسب قیمت پر فوری طور پر بڑی مقدار میں تجارت کر سکتے ہیں۔ ایک غیر قانونی اسٹاک میں اتنا کم ہوتا ہے کہ ایک معمولی آرڈر سے بھی قیمت میں تبدیلی آتی ہے، اور، بدتر، آپ کو مشکلات کا سامنا کرنا پڑ سکتا ہے۔ <em>باہر نکلنا</em> جب آپ باہر چاہتے ہیں. لیکویڈیٹی چھوڑنے کی آزادی ہے۔ اسے کبھی کم نہ سمجھیں۔</p>\n<h2 id=\"long-short-and-the-magic-of-selling-first\">لمبا، مختصر، اور پہلے فروخت کرنے کا جادو</h2>\n<p>زیادہ تر لوگ صرف کبھی جاتے ہیں۔ <strong>طویل</strong>: آپ <em>خریدیں</em> ایک اسٹاک کی امید ہے کہ یہ بڑھے گا، پھر بعد میں منافع کے لیے فروخت کریں۔ کم خریدیں، زیادہ بیچیں۔ سادہ</p>\n<p><strong>مختصر فروخت</strong> اس کے سر پر حکم flips، آپ کو فروخت <em>پہلے</em> اور خریدیں <em>بعد میں واپس</em>، تو آپ کو منافع جب ایک اسٹاک <strong>گرتا ہے</strong>. یہ ناممکن لگتا ہے: آپ کسی ایسی چیز کو کیسے بیچیں گے جو آپ کے پاس نہیں ہے؟ آپ <strong>ادھار لینا</strong> یہ</p>\n<p>یہ ترتیب ہے:</p>\n<ol>\n<li>آپ کو یقین ہے کہ 100 روپے پر ٹریڈنگ کرنے والا اسٹاک ایکس گرنے والا ہے۔</li>\n<li>آپ <strong>ادھار لینا</strong> حصص (آپ کے بروکر / ایکسچینج کے قرض دینے والے پول سے) اور <strong>فروخت</strong> انہیں فوری طور پر 100 روپے میں، نقدی جیب میں ڈالی۔</li>\n<li>قیمت 80 روپے تک گر گئی، جیسا کہ آپ کی امید تھی۔</li>\n<li>آپ <strong>خریدیں</strong> 80 روپے پر حصص واپس اور <strong>واپسی</strong> قرض دہندہ کو ادھار حصص۔</li>\n<li>آپ فرق رکھیں: <strong>20 روپے فی شیئر</strong> منافع</li>\n</ol>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch12-short-selling-flow.png\" alt=\"پانچ قدموں پر مشتمل شارٹ سیل لوپ، حصص ادھار لیں، زیادہ فروخت کریں، زوال کا انتظار کریں، کم خریدیں، حصص واپس کریں، اور فرق رکھیں\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">فلو چارٹ</span>پانچ قدموں پر مشتمل شارٹ سیل لوپ، حصص ادھار لیں، زیادہ فروخت کریں، زوال کا انتظار کریں، کم خریدیں، حصص واپس کریں، اور فرق رکھیں</figcaption></figure>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>مختصر فروخت سے ایک خطرہ ہوتا ہے جو کبھی نہیں خریدتا: <strong>آپ کے نقصانات لامحدود ہوسکتے ہیں.</strong> جب آپ 100 روپے میں اسٹاک خریدتے ہیں، تو سب سے بری صورت یہ ہے کہ یہ صفر پر چلا جاتا ہے، آپ کو 100 روپے کا نقصان ہوتا ہے۔ لیکن اگر آپ <em>مختصر</em> 100 روپے پر اور اسٹاک چڑھتا رہتا ہے، 150 روپے، 300 روپے، 500 روپے، آپ کا نقصان بغیر کسی حد کے بڑھتا ہے، کیونکہ قیمت ہمیشہ کے لیے بڑھ سکتی ہے لیکن صرف صفر تک گر سکتی ہے۔ یہی وجہ ہے کہ مختصر فروخت مضبوطی سے ایک اعلی درجے کی، زیادہ خطرے والی سرگرمی ہے۔</p>\n</div></div>\n<p>ہندوستان میں، زیادہ تر خوردہ تاجروں کے لیے ایک اور اصول ہے: آپ عام طور پر صرف مختصر کر سکتے ہیں۔ <strong>انٹرا ڈے</strong>، آپ کو واپس خریدنا ہوگا اور پوزیشن کو بند کرنا ہوگا۔ <strong>مارکیٹ اسی دن بند ہونے سے پہلے</strong>. راتوں رات ایک مختصر وقت رکھنے کے لیے آپ کو باضابطہ طور پر سیکیوریٹیز لینڈنگ اینڈ بورونگ (SLB) میکانزم کے ذریعے اسٹاک کو ادھار لینا ہوگا۔ ایک ابتدائی کے لیے، مختصر فروخت ایک چیز ہے۔ <em>سمجھنا</em>، نہیں کرنا۔</p>\n<h2 id=\"the-rest-of-the-tv-vocabulary\">بقیہ TV ذخیرہ الفاظ</h2>\n<p>دوسرے الفاظ کی فوری فائر لغت جو آپ مسلسل سنیں گے:</p>\n<table>\n<thead>\n<tr>\n<th>مدت</th>\n<th>ایک سطری معنی</th>\n</tr>\n</thead>\n<tbody><tr>\n<td><strong>52-ہفتہ زیادہ/کم</strong></td>\n<td>پچھلے سال میں کسی اسٹاک نے سب سے زیادہ اور سب سے کم قیمت کو چھو لیا ہے، اس بات کا فوری اندازہ کہ یہ کہاں کھڑا ہے۔</td>\n</tr>\n<tr>\n<td><strong>ریلی</strong></td>\n<td>مختصر مدت کے دوران قیمتوں میں تیز، مسلسل اضافہ۔</td>\n</tr>\n<tr>\n<td><strong>تصحیح</strong></td>\n<td>تقریباً کا زوال <strong>10% یا اس سے زیادہ</strong> حالیہ چوٹی سے، عام، صحت مند، اور بار بار۔</td>\n</tr>\n<tr>\n<td><strong>کریش</strong></td>\n<td>ایک ہی دن یا چند دنوں میں اچانک، شدید، اکثر گھبراہٹ کا شکار ہو جانا۔</td>\n</tr>\n<tr>\n<td><strong>مارکیٹ کی وسعت</strong></td>\n<td>کتنے اسٹاک میں اضافہ ہوا بمقابلہ گرا، \"پیشگی بمقابلہ کمی۔\" مضبوط چوڑائی (زیادہ تر اسٹاک اپ) کا مطلب ہے ایک وسیع، صحت مند اقدام؛ کمزور چوڑائی کا مطلب ہے کہ چند جنات گرتے ہوئے ہجوم کو چھپا رہے ہیں۔</td>\n</tr>\n<tr>\n<td><strong>اتار چڑھاؤ</strong></td>\n<td>قیمتیں کس حد تک بڑھ رہی ہیں۔ زیادہ اتار چڑھاؤ = دونوں سمتوں میں بڑی، تیز رفتار حرکت۔</td>\n</tr>\n<tr>\n<td><strong>بولی / پوچھنا</strong></td>\n<td>بہترین قیمت جو ایک خریدار ادا کرے گا (بولی) اور بیچنے والا قبول کرے گا (پوچھے گا)۔</td>\n</tr>\n<tr>\n<td><strong>بلیو چپ</strong></td>\n<td>ایک بڑی، مستحکم، معروف کمپنی۔</td>\n</tr>\n<tr>\n<td><strong>پینی اسٹاک</strong></td>\n<td>ایک بہت ہی سستا، چھوٹا، خطرناک حصہ۔</td>\n</tr>\n</tbody></table>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>آپ کو اس لغت کو حفظ کرنے کی ضرورت نہیں ہے۔ اسے ایک حوالہ کے طور پر رکھیں اور شرائط قدرتی طور پر ڈوب جائیں گی جب آپ کچھ ہفتوں تک مارکیٹ دیکھیں گے۔ جرگن ان لوگوں کے درمیان صرف شارٹ ہینڈ ہے جو روزانہ ان خیالات کو استعمال کرتے ہیں، اور بہت جلد، اس میں آپ بھی شامل ہوں گے۔</p>\n</div></div>\n<h2 id=\"quick-recap\">فوری خلاصہ</h2>\n<ul>\n<li>اے <strong>بیل مارکیٹ</strong> طلوع (سینگ اوپر اٹھانا)؛ a <strong>ریچھ مارکیٹ</strong> اپنی چوٹی سے 20%+ گرتا ہے (پنجے نیچے سوائپ کرتے ہیں)۔ جانور بیان کرتے ہیں کہ ہر ایک کیسے حملہ کرتا ہے۔</li>\n<li>اسٹاک میں تقسیم <strong>بڑی ٹوپی</strong> (سب سے اوپر 100، سب سے محفوظ) <strong>درمیانی ٹوپی</strong> (101-250) اور <strong>چھوٹی ٹوپی</strong> (251+، سب سے زیادہ خطرہ اور انعام) SEBI کی مارکیٹ کیپ درجہ بندی کے لحاظ سے۔</li>\n<li><strong>سرکٹس</strong> خودکار پرائس بینڈ ہالٹس ہیں، <strong>اوپری</strong> (منجمد، صرف خریدار) اور <strong>کم</strong> (منجمد نیچے، صرف بیچنے والے)، نیز مارکیٹ میں وسیع بریکرز۔</li>\n<li><strong>حجم</strong> کتنی تجارت ہوتی ہے؛ <strong>لیکویڈیٹی</strong> یہ ہے کہ آپ قیمت کو منتقل کیے بغیر کتنی آسانی سے باہر نکل سکتے ہیں، اور یہ سب سے زیادہ اہمیت رکھتا ہے جب آپ باہر نکلنا چاہتے ہیں۔</li>\n<li>جا رہا ہے۔ <strong>طویل</strong> اس کا مطلب ہے خرید پھر فروخت (منافع جب بڑھتا ہے)؛ <strong>مختصر فروخت</strong> اس کا مطلب ہے ادھار بیچنا خریدنا واپس (منافع جب گرتا ہے) کے ساتھ <strong>لامحدود</strong> نقصان کا خطرہ اور، ہندوستان میں زیادہ تر خوردہ فروشوں کے لیے، صرف انٹرا ڈے۔</li>\n<li>جیسے الفاظ <strong>52-ہفتہ ہائی /low، ریلی، اصلاح، کریش، چوڑائی، بلیو چپ</strong> اور <strong>پیسہ اسٹاک</strong> صرف روزمرہ کے بازار کا شارٹ ہینڈ ہے جسے آپ جلدی سے جذب کر لیں گے۔</li>\n</ul>\n<p>اگلا، ہم اس سب کے دل تک پہنچتے ہیں: <em>اصل میں اسٹاک کو کیا حرکت دیتا ہے؟</em> ہم آرڈر بک میں قیمت کو ٹک ٹک کے ذریعے سیٹ ہوتے دیکھیں گے، اور دیکھیں گے کہ شاندار کمائی بھی اسٹاک کیوں بھیج سکتی ہے <em>نیچے</em>.</p>\n","toc":[{"level":2,"text":"بیل اور ریچھ: مارکیٹ کے دو موڈ","id":"bulls-and-bears-the-market-s-two-moods"},{"level":2,"text":"بڑی ٹوپی، مڈ کیپ، چھوٹی ٹوپی","id":"large-cap-mid-cap-small-cap"},{"level":2,"text":"سرکٹس: مارکیٹ کے خودکار بریک","id":"circuits-the-market-s-automatic-brakes"},{"level":2,"text":"حجم اور لیکویڈیٹی","id":"volume-and-liquidity"},{"level":2,"text":"لمبا، مختصر، اور پہلے فروخت کرنے کا جادو","id":"long-short-and-the-magic-of-selling-first"},{"level":2,"text":"بقیہ TV ذخیرہ الفاظ","id":"the-rest-of-the-tv-vocabulary"},{"level":2,"text":"فوری خلاصہ","id":"quick-recap"}],"imgCount":2,"hasContent":true},"13":{"html":"<p>یہاں ایک سوال ہے جو آسان لگتا ہے لیکن مارکیٹ کے بارے میں تقریبا ہر چیز کو کھول دیتا ہے: <em>اسٹاک کی قیمت کیوں بدل جاتی ہے؟</em> ایک منٹ ریلائنس 1,420 روپے پر ہے، کچھ سیکنڈ بعد یہ 1,420.50 روپے، پھر 1,419.80 روپے ہے۔ ان نمبروں کا فیصلہ کون کرتا ہے؟ کمپنی نہیں۔ تبادلہ نہیں۔ کچھ کمیٹی \"مناسب قیمت\" کا تعین نہیں کر رہی ہے۔ سچائی عاجز اور کہیں زیادہ طاقتور ہے: <strong>ایک اسٹاک کی قیمت صرف وہ سب سے حالیہ رقم ہے جس پر ایک رضامند خریدار اور ایک تیار بیچنے والے نے اتفاق کیا ہے۔</strong> مزید کچھ نہیں۔</p>\n<p>اسکرین پر آپ جو بھی ٹک دیکھتے ہیں وہ ایک تازہ مصافحہ ہے۔ قیمت اوپر سے دی گئی حقیقت نہیں ہے، یہ ایک ہے۔ <em>مذاکرات</em>، ایک سیکنڈ میں ہزاروں بار ہو رہا ہے، ان لوگوں کے درمیان جو اس بات سے متفق نہیں ہیں کہ شیئر کی قیمت کیا ہے۔ اس کو سمجھیں، اور اس باب کا باقی حصہ اپنی جگہ پر آتا ہے۔</p>\n<h2 id=\"the-order-book-a-continuous-auction\">آرڈر بک: ایک مسلسل نیلامی</h2>\n<p>ہر اسٹاک کے پیچھے ایک بیٹھتا ہے۔ <strong>آرڈر بک</strong>، ہر ایک کی لائیو فہرست جو خریدنا چاہتا ہے اور ہر وہ شخص جو بیچنا چاہتا ہے، اور کس قیمت پر۔ ایک طرف ہیں <strong>خریدار</strong> ان کے ساتھ <strong>بولیاں</strong> (قیمتیں وہ ادا کرنے کو تیار ہیں)۔ دوسری طرف ہیں <strong>بیچنے والے</strong> ان کے ساتھ <strong>پوچھتا ہے</strong> (وہ قیمتیں جو وہ وصول کرنا چاہتے ہیں)۔</p>\n<p>تجارت صرف اس وقت ہوتی ہے جب خریدار اور بیچنے والا <strong>قیمت پر متفق ہوں</strong>، جب کوئی ادا کرنے کو تیار ہے جو کوئی دوسرا قبول کرنے کو تیار ہے۔ اس مماثل تجارت کی قیمت نئی \"آخری تجارت کی قیمت\" بن جاتی ہے، جس نمبر کا آپ حوالہ دیکھتے ہیں۔ پھر اگلا میچ اگلی قیمت کا تعین کرتا ہے، اور اسی طرح، سارا دن۔ یہ ایک ہے <strong>مسلسل نیلامی</strong>، دن میں ایک بار نہیں بلکہ ایک رولنگ گفت و شنید جو بازار کے اوقات میں کبھی نہیں رکتی ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch13-order-book-auction.png\" alt=\"ایک مسلسل نیلامی کے طور پر آرڈر بک، خرید کی طرف بولیاں لگائی جاتی ہیں، بیچنے کی طرف پوچھتی ہیں، اور تازہ ترین مماثل تجارت درمیان میں لائیو قیمت طے کرتی ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>ایک مسلسل نیلامی کے طور پر آرڈر بک، خرید کی طرف بولیاں لگائی جاتی ہیں، بیچنے کی طرف پوچھتی ہیں، اور تازہ ترین مماثل تجارت درمیان میں لائیو قیمت طے کرتی ہے۔</figcaption></figure>\n<p>یہی وجہ ہے کہ قیمت ٹک ٹک کے ساتھ بڑھتی ہے، اور منطق خوبصورتی سے آسان ہے:</p>\n<ul>\n<li>جب <strong>خریدار بیچنے والوں سے زیادہ بے چین ہیں۔</strong>سپلائی سے زیادہ مانگ، خریدار اپنے حصص حاصل کرنے کے لیے زیادہ مانگیں قبول کرنا شروع کر دیتے ہیں۔ قیمت <strong>ٹک اپ</strong>.</li>\n<li>جب <strong>بیچنے والے خریداروں سے زیادہ شوقین ہیں۔</strong>طلب سے زیادہ سپلائی، بیچنے والے آف لوڈ کرنے کے لیے کم بولی قبول کرنا شروع کر دیتے ہیں۔ قیمت <strong>نیچے ticks</strong>.</li>\n</ul>\n<p>یہ پورا انجن ہے۔ اوپر یا نیچے، ہر حرکت ایک عدم توازن کی طرف اشارہ کرتی ہے: اس لمحے، کیا زیادہ بھوک تھی؟ <em>خریدیں</em> یا زیادہ بھوک لگتی ہے۔ <em>فروخت</em>?</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>اسٹاک کی قیمت وہ نہیں ہے جو کمپنی \"قابل\" ہے۔ یہ خریداروں اور بیچنے والوں کے درمیان جاری ٹگ آف وار کا لائیو سکور ہے۔ بیچنے والے سے زیادہ شوقین خریدار اسے آگے بڑھاتے ہیں۔ خریداروں سے زیادہ بیچنے والے اسے نیچے کھینچ لیتے ہیں۔ اس باب میں باقی سب کچھ واقعی کے بارے میں ہے۔ <em>جو ہجوم کو کسی نہ کسی طریقے سے جھکا دیتا ہے۔</em></p>\n</div></div>\n<h2 id=\"what-tips-the-balance\">توازن کیا تجاویز</h2>\n<p>اگر قیمت ایک ٹگ آف وار ہے، تو دلچسپ سوال یہ بن جاتا ہے: لوگوں کی ایک لہر اچانک خریدنا چاہتی ہے، یا بیچنے کے لیے جلدی کرتی ہے؟ چند بڑی قوتیں:</p>\n<ul>\n<li><strong>خبریں</strong> ایک نیا سرکاری معاہدہ، ایک فیکٹری میں آگ، ایک ریگولیٹری پابندی، ایک CEO استعفیٰ، تازہ معلومات فوری طور پر تبدیل کرتی ہے کہ لوگ کس طرح کمپنی کی قدر کرتے ہیں، اور وہ اپنی جگہ تبدیل کرتے ہیں۔</li>\n<li><strong>کمائی۔</strong> ہر سہ ماہی میں کمپنیاں اپنے منافع کی اطلاع دیتی ہیں۔ مضبوط نتائج خریداروں کو اپنی طرف کھینچتے ہیں۔ کمزور لوگ بیچنے والے کو دوڑتے ہوئے بھیجتے ہیں۔ (ذیل میں موڑ پر مزید۔)</li>\n<li><strong>توقعات۔</strong> یہ ٹھیک ٹھیک، مارکیٹ کی وضاحت کرنے والا ہے۔ قیمتیں نہ صرف آج بلکہ لوگوں کی عکاسی کرتی ہیں۔ <em>کل کی توقع</em>.</li>\n<li><strong>جذبہ</strong> کبھی کبھی پوری مارکیٹ صرف خوف زدہ یا لالچی ہوتی ہے، اور یہ مزاج انفرادی اسٹاک کو اپنی خبروں سے قطع نظر کر دیتا ہے۔</li>\n</ul>\n<h2 id=\"markets-price-the-future-not-the-present\">مارکیٹ مستقبل کی قیمت لگاتی ہے، حال کی نہیں۔</h2>\n<p>یہاں ابتدائی افراد کے لیے واحد سب سے زیادہ انسداد بدیہی سچائی ہے، اور اسے جلد حاصل کرنا آپ کو برسوں کی الجھنوں سے بچائے گا: <strong>مارکیٹ ایک آگے نظر آنے والی مشین ہے۔</strong> آج کی قیمت پہلے ہی کیا سرمایہ کاروں میں bakes <em>توقع</em> ہونے کے لیے لہذا ایک اسٹاک اس بات پر رد عمل ظاہر نہیں کرتا ہے کہ آیا مطلق شرائط میں خبر اچھی ہے یا بری، یہ اس بات پر ردعمل ظاہر کرتا ہے کہ آیا خبر <strong>اس سے بہتر یا بدتر جس کی پہلے سے توقع کی جا رہی تھی۔</strong></p>\n<p>یہی وجہ ہے کہ آپ کمپنی کی رپورٹ ریکارڈ منافع، حقیقی طور پر بہترین نمبر دیکھیں گے، اور اسٹاک دیکھیں گے۔ <em>گر</em> اسی دوپہر. کیسے؟ کیونکہ سرمایہ کاروں کو توقع تھی۔ <em>اس سے بھی بہتر</em>. عظیم نتیجہ اب بھی <strong>اس سے بھی زیادہ توقعات سے محروم</strong> پہلے سے ہی قیمت ہے، اس لیے جن خریداروں نے توقع سے اسٹاک کی بولی لگائی تھی اب مایوسی میں فروخت ہو رہے ہیں۔</p>\n<p>دوسرا پہلو بھی اتنا ہی حقیقی ہے: ایک جدوجہد کرنے والی کمپنی بدصورت نقصان اور اسٹاک کی اطلاع دے سکتی ہے۔ <em>طلوع ہوتا ہے</em>صرف اس وجہ سے کہ نقصان ہوا۔ <em>خوف سے چھوٹا</em>. مارکیٹ ہمیشہ توقع کے خلاف حقیقت کا موازنہ کرتی ہے، صفر کے خلاف نہیں۔</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>اس کے لیے تاجروں کا ایک قول ہے: <strong>\"افواہ خریدو، خبریں بیچو۔\"</strong> ایک اسٹاک اکثر ہفتوں تک چڑھتا ہے۔ <em>توقع میں</em> ایک عظیم نتیجہ کا، جیسا کہ توقع پیدا ہوتی ہے، اور پھر <em>گرتا ہے</em> جس لمحے اصل خوشخبری آتی ہے، کیونکہ جن لوگوں نے افواہ خریدی تھی وہ اب اپنا منافع لیتے ہیں۔ جس خبر کا سب کو انتظار تھا وہ فروخت کا محرک بن جاتی ہے۔ اچھی خبر، گرتی ہوئی قیمت، اور اب آپ جانتے ہیں کیوں۔</p>\n</div></div>\n<h2 id=\"sentiment-and-the-herd\">جذبات اور ریوڑ</h2>\n<p>بازار لوگوں سے بنتے ہیں، اور لوگ جذباتی اور سماجی ہوتے ہیں۔ جب قیمتیں بڑھ رہی ہوتی ہیں، رجائیت اپنے آپ کو پالتی ہے، دوسرے پیسہ کما رہے ہوتے ہیں، اس لیے مزید ڈھیر ہوتے ہیں، قیمتیں ابھی بھی بلند ہوتی جا رہی ہیں۔ یہ ہے <strong>ریوڑ کا رویہ</strong>، اور یہ الٹا بھی کام کرتا ہے: جب قیمتیں گرتی ہیں، خوف پھیل جاتا ہے، لوگ مزید تکلیف سے بچنے کے لیے فروخت کرتے ہیں، اور خود فروخت ہونے سے قیمتیں کم ہوجاتی ہیں۔</p>\n<p>جذبات حیرت انگیز طور پر طویل عرصے تک اسٹاک کو اس کے بنیادی اصولوں سے الگ کر سکتا ہے، اسے بلبلے میں جائز قرار دینے والے کسی بھی پرسکون تشخیص سے زیادہ بھیجنا، یا گھبراہٹ میں اس کے مستحق سے کم۔ اس کو پہچاننا <em>بھیڑ قیمت کا حصہ ہے</em> سب سے مفید ذہنی ماڈلز میں سے ایک ہے جسے آپ لے جا سکتے ہیں۔ ہم بعد کا ایک پورا باب آپ کی اپنی نفسیات میں مہارت حاصل کرنے کے لیے وقف کرتے ہیں تاکہ ریوڑ نہ لے <em>آپ</em> ساتھ</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>\"ہر کوئی اسے خرید رہا ہے\" خریدنے کی کوئی وجہ نہیں ہے۔ اس وقت تک جب ہر واٹس ایپ گروپ میں اسٹاک کی بات ہوتی ہے، زیادہ تر امید پہلے سے ہی قیمت میں ہوتی ہے، اور ہو سکتا ہے آپ بالکل اسی وقت خرید رہے ہوں جب ابتدائی ہجوم فروخت کرنے کی تیاری کر رہا ہو۔ ریوڑ مڑنے سے پہلے ہی سب سے بلند آواز میں ہے۔</p>\n</div></div>\n<h2 id=\"a-concrete-example-results-day\">ایک ٹھوس مثال: نتائج کا دن</h2>\n<p>ایک خیالی IT کمپنی کی تصویر بنائیں، <strong>انفارمیشن کور</strong>پر ٹریڈنگ <strong>500 روپے</strong>. تجزیہ کاروں کو سہ ماہی منافع میں 15 فیصد اضافے کی توقع ہے، اور گزشتہ ماہ کے دوران اسٹاک خاموشی سے 450 روپے سے بڑھ کر 500 روپے تک پہنچ گیا ہے کیونکہ سرمایہ کار ایک مضبوط تعداد کے لیے پوزیشن میں ہیں۔ نتائج سامنے آئے: منافع میں اضافہ ہوا۔ <strong>12%</strong>، حقیقی طور پر صحت مند ترقی، لیکن <em>نیچے</em> جس کی مارکیٹ نے 15% قیمت رکھی تھی۔ چند منٹوں میں، مایوس خریدار بیچنے والے کا رخ کرتے ہیں، آرڈر بک فروخت کی طرف جھک جاتی ہے، اور InfoCore گر جاتا ہے۔ <strong>465 روپے</strong>.</p>\n<p>ایک پڑوسی جو صرف سرخی پڑھتا ہے حیران رہ جاتا ہے: \"منافع <em>بڑھا</em> اور اسٹاک <em>گر گیا</em>\"لیکن اب آپ سمجھ گئے ہیں، مارکیٹ کا موازنہ 12% متوقع 15% کے مقابلے کر رہا تھا، صفر کے مقابلے میں نہیں۔ ترقی حقیقی تھی؛ یہ بالکل نہیں تھی۔ <em>کافی</em>. اگر InfoCore نے 18% ڈیلیور کیا ہوتا، تو وہی رپورٹ اسے بہت زیادہ بھیج دیتی۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch13-results-reaction-chart.png\" alt=\"اس کے نتائج پر رد عمل ظاہر کرنے والے اسٹاک کا کینڈل اسٹک چارٹ، اعلان میں مسلسل اضافہ، پھر جس دن توقعات چھوٹ گئیں اس دن ایک تیز فرق\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>اس کے نتائج پر رد عمل ظاہر کرنے والے اسٹاک کا کینڈل اسٹک چارٹ، اعلان میں مسلسل اضافہ، پھر جس دن توقعات چھوٹ گئیں اس دن ایک تیز فرق</figcaption></figure>\n<h2 id=\"putting-a-number-on-it-calculating-your-return\">اس پر نمبر لگانا: آپ کی واپسی کا حساب لگانا</h2>\n<p>اسٹاک جس طرح بھی چلتا ہے، آپ اس کی پیمائش کرنا چاہیں گے۔ <em>آپ</em> کیا دو نمبر اہم ہیں۔</p>\n<p><strong>مطلق واپسی۔</strong> کیا سادہ روپیہ فائدہ یا نقصان ہے:</p>\n<blockquote>\n<p>مطلق واپسی = فروخت کی قیمت، قیمت خرید</p>\n</blockquote>\n<p>400 روپے میں خریدیں، 500 روپے میں فروخت کریں، اور آپ کا مکمل فائدہ ہے۔ <strong>100 روپے</strong> فی شیئر</p>\n<p><strong>فیصد واپسی</strong> اس کو آپ کی سرمایہ کاری کے مطابق کریں، تاکہ آپ اس کا موازنہ کسی اور چیز سے کر سکیں:</p>\n<blockquote>\n<p>فی صد واپسی = (فائدہ / خرید قیمت) x 100</p>\n</blockquote>\n<p>یہاں: (100/400) x 100 = <strong>25%</strong>. 25% واپسی۔</p>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>فیصد روپے سے زیادہ اہمیت رکھتا ہے۔ 400 روپے کے سٹاک پر 100 روپے کا فائدہ a ہے۔ <strong>25%</strong> واپسی 2,000 روپے کے اسٹاک پر وہی 100 روپے کا فائدہ ہے۔ <strong>5%</strong>. ایک ہی روپے، بہت مختلف نتیجہ، ہمیشہ فیصد میں سوچیں تاکہ آپ پسند کا موازنہ لائیک کے ساتھ کر رہے ہوں۔</p>\n</div></div>\n<p>ایک اور پرت ہے: <strong>وقت</strong>. ایک سال میں 25% کی واپسی شاندار اور دس سے زیادہ معمولی ہے۔ مختلف طوالت کے لیے رکھی گئی سرمایہ کاری کا موازنہ کرنے کے لیے، لوگ واپسی کو a میں تبدیل کرتے ہیں۔ <strong>فی سال</strong> اعداد و شمار، <strong>سالانہ</strong> واپسی عین مطابق ریاضی بعد میں آتی ہے۔ ابھی کے لیے، کسی بھی واپسی کے بارے میں ہمیشہ دو سوالات پوچھنے کے لیے صرف جبلت کو بند کریں: <em>کتنا،</em> اور <em>کتنی دیر سے؟</em> ٹائم فریم کے بغیر نمبر صرف آدھی حقیقت ہے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>جب کوئی اس بات پر فخر کرتا ہے کہ اسٹاک \"دوگنا\" ہو گیا ہے، تو آپ کا پہلا سوال \"کس مدت میں؟\" ایک سال میں دوگنا ہونا غیر معمولی ہے۔ پندرہ سالوں میں دوگنا کرنا ایک سال میں 5% سے کم ہوتا ہے، جو کہ فکسڈ ڈپازٹ سے کم ہوتا ہے۔ واپسی اور وقت لازم و ملزوم ہیں۔ کبھی بھی کسی کو دوسرے کے بغیر آپ کا ایک حوالہ نہ دیں۔</p>\n</div></div>\n<h2 id=\"quick-recap\">فوری خلاصہ</h2>\n<ul>\n<li>ایک اسٹاک <strong>قیمت صرف تازہ ترین معاہدہ ہے۔</strong> ایک تیار خریدار اور تیار بیچنے والے کے درمیان، ایک تازہ مصافحہ، سیکنڈ میں ہزاروں بار، اوپر سے کوئی قیمت نہیں دی گئی۔</li>\n<li>دی <strong>آرڈر بک</strong> چلتا ہے a <strong>مسلسل نیلامی</strong>: بیچنے والے سے زیادہ شوقین خریدار قیمت پر ٹک کرتے ہیں۔ <strong>اوپر</strong>، خریداروں سے زیادہ شوقین بیچنے والے اسے ٹک ٹک کرتے ہیں۔ <strong>نیچے</strong>.</li>\n<li><strong>خبریں، کمائی، توقعات اور جذبات</strong> کیا ٹپ ہے کہ توازن اور بھیڑ کو ایک طرف جھکاؤ بھیجیں.</li>\n<li>منڈیاں <strong>مستقبل کی قیمت</strong>، لہذا ایک اسٹاک نتائج پر رد عمل ظاہر کرتا ہے۔ <em>توقعات کے مطابق</em>، ایک عظیم چوتھائی کہ <strong>اس سے بھی اونچی امیدیں ابھی بھی گر سکتی ہیں۔</strong> (\"افواہ خریدیں، خبریں بیچیں\")۔</li>\n<li><strong>ریوڑ کا سلوک</strong> قیمتوں کو منصفانہ قیمت سے کہیں زیادہ یا نیچے دھکیل سکتا ہے، یہی وجہ ہے کہ \"ہر کوئی خرید رہا ہے\" ایک انتباہ ہے، کوئی وجہ نہیں۔</li>\n<li>کے ساتھ اپنے نتائج کی پیمائش کریں۔ <strong>مطلق</strong> (روپیہ) اور <strong>فیصد</strong> واپسی، اور ہمیشہ کسی بھی واپسی کو کے ساتھ جوڑیں۔ <strong>ٹائم فریم</strong> یہ لیا.</li>\n</ul>\n<p>اس کے بعد، ہم ایک سٹاک سے پوری معیشت کی عینک کو وسیع کرتے ہیں، کہ کس طرح سود کی شرح، افراط زر، روپیہ، خام تیل اور عالمی بہاؤ اوپر سے ہندوستانی حصص پر ٹگ جاتا ہے۔</p>\n","toc":[{"level":2,"text":"آرڈر بک: ایک مسلسل نیلامی","id":"the-order-book-a-continuous-auction"},{"level":2,"text":"توازن کیا تجاویز","id":"what-tips-the-balance"},{"level":2,"text":"مارکیٹ مستقبل کی قیمت لگاتی ہے، حال کی نہیں۔","id":"markets-price-the-future-not-the-present"},{"level":2,"text":"جذبات اور ریوڑ","id":"sentiment-and-the-herd"},{"level":2,"text":"ایک ٹھوس مثال: نتائج کا دن","id":"a-concrete-example-results-day"},{"level":2,"text":"اس پر نمبر لگانا: آپ کی واپسی کا حساب لگانا","id":"putting-a-number-on-it-calculating-your-return"},{"level":2,"text":"فوری خلاصہ","id":"quick-recap"}],"imgCount":2,"hasContent":true},"14":{"html":"<p>کچھ صبحوں پر، آپ کی اسکرین پر تقریباً ہر اسٹاک ایک ہی وقت میں نیچے کھلتا ہے، عظیم کاروبار اور کمزور، وہ کمپنی جس نے صرف ریکارڈ منافع پوسٹ کیا اور وہ جس نے کوئی پوسٹ نہیں کیا۔ راتوں رات ان کمپنیوں کے بارے میں کچھ نہیں بدلا۔ جو بدلا ہے وہ ہے۔ <em>موسم</em>. ہر فرد کے حصص سے اوپر بیٹھی دیو ہیکل، سست رفتار قوتوں، شرح سود، افراط زر، روپے کی قدر، خام تیل کی قیمت، پیسہ ملک کے اندر اور باہر بہتا ہے، اور جب یہ موسم بدلتا ہے تو یہ ایک دم پوری مارکیٹ پر جھک جاتا ہے۔</p>\n<p>آخری باب میں دیکھا گیا کہ ایک اسٹاک کیا حرکت کرتا ہے۔ یہ حرکت کرنے والی قوتوں کے لیے تمام راستے زوم کرتا ہے۔ <em>تمام</em> ان میں سے ایک ساتھ. آپ اس موسم کو کبھی کنٹرول نہیں کر پائیں گے، اور، اچھی خبر، آپ کو اس کی پیش گوئی کرنے کی ضرورت نہیں ہے۔ لیکن اسے پڑھنا سیکھنا ایک خوفناک، الجھا دینے والا بازار کا دن ایک ایسی چیز میں بدل دیتا ہے جسے آپ سمجھ سکتے ہیں، اور زیادہ تر وقت، سکون سے نظر انداز کر دیتے ہیں۔</p>\n<h2 id=\"interest-rates-the-price-of-money\">سود کی شرح: رقم کی قیمت</h2>\n<p>اس کے مرکز میں سب بیٹھتا ہے۔ <strong>ریزرو بینک آف انڈیا (RBI)</strong>، ملک کا مرکزی بینک، اور واحد سب سے زیادہ طاقتور نمبر جس پر یہ کنٹرول کرتا ہے: <strong>ریپو ریٹ</strong>.</p>\n<p>ریپو ریٹ کو خود پیسے کی قیمت سمجھیں۔ یہ وہ شرح سود ہے جس پر RBI تجارتی بینکوں کو قرض دیتا ہے۔ جب یہ شرح کم ہوتی ہے، بینکوں کو سستے پیسے ملتے ہیں، اس لیے وہ سستے قرضے دیتے ہیں، ہوم لون، کار لون، بزنس لون سب زیادہ سستی ہو جاتے ہیں۔ کمپنیاں قرض لیتی ہیں اور پھیلتی ہیں، لوگ قرض لیتے ہیں اور خرچ کرتے ہیں، منافع میں اضافہ ہوتا ہے، اور اسٹاک اکثر بڑھتے ہیں۔ جب RBI <em>اٹھاتا ہے</em> ریپو ریٹ، اس کے برعکس ہوتا ہے: پیسہ مہنگا ہو جاتا ہے، قرض لینے کی رفتار سست ہو جاتی ہے، معیشت ٹھنڈی ہو جاتی ہے، اور سٹاک کو شدید مشکلات کا سامنا کرنا پڑتا ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch14-macro-forces.png\" alt=\"مارکیٹ پر جھکاؤ رکھنے والی بڑی قوتیں، شرح سود، افراط زر، خام تیل، روپیہ، FII/DII بہاؤ اور عالمی اشارے، یہ سب ایک ساتھ نفٹی پر زور دے رہے ہیں۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">انفوگرافک</span>مارکیٹ پر جھکاؤ رکھنے والی بڑی قوتیں، شرح سود، افراط زر، خام تیل، روپیہ، FII/DII بہاؤ اور عالمی اشارے، یہ سب ایک ساتھ نفٹی پر زور دے رہے ہیں۔</figcaption></figure>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>شرح سود حصص کی قیمتوں پر کشش ثقل کی طرح کام کرتی ہے۔ سستا پیسہ اسٹاک کو اٹھانے کا رجحان رکھتا ہے۔ مہنگا پیسہ ان کا وزن کم کرتا ہے۔ یہ سمجھنے کے لیے سب سے اہم میکرو لیور ہے، اور RBI اسے جان بوجھ کر، چھوٹے قدموں میں، معیشت کو دیکھنے کے بعد منتقل کرتا ہے۔</p>\n</div></div>\n<h3 id=\"why-lower-rates-often-lift-stocks\">کیوں کم شرحیں اکثر اسٹاک کو اٹھاتی ہیں۔</h3>\n<ul>\n<li><strong>سستی EMIs اور لون</strong> گھرانوں کو زیادہ خرچ کرنے کے لیے چھوڑ دیں، کمپنی کی فروخت کے لیے اچھا ہے۔</li>\n<li><strong>سستا کارپوریٹ قرضہ</strong> کاروبار کو سرمایہ کاری، توسیع اور منافع بڑھانے دیتا ہے۔</li>\n<li><strong>فکسڈ ڈپازٹ اور بانڈز کم ادائیگی کرتے ہیں۔</strong>، لہذا کچھ سرمایہ کار زیادہ منافع کی تلاش میں رقم کو ایکوئٹی کی طرف منتقل کرتے ہیں۔</li>\n<li><strong>مستقبل کے منافع آج زیادہ قابل ہیں</strong> جب شرحیں کم ہوتی ہیں، تو جو سرمایہ کاروں کو اسٹاک کے لیے کیا ادائیگی کرے گا اسے اٹھاتا ہے۔</li>\n</ul>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch14-rate-transmission.png\" alt=\"کس طرح ایک RBI کی شرح میں کمی سے باہر کی طرف لہریں آتی ہیں، سستے بینک قرضوں سے، زیادہ خرچ اور سرمایہ کاری، کمپنی کے زیادہ منافع اور شیئر کی قیمتوں تک\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">فلو چارٹ</span>کس طرح ایک RBI کی شرح میں کٹوتی، سستے بینک قرضوں سے لے کر، زیادہ خرچ اور سرمایہ کاری، کمپنی کے زیادہ منافع اور حصص کی قیمتوں تک باہر کی طرف لپکتی ہے۔</figcaption></figure>\n<p>ایک حقیقی، حالیہ مثال: 2025 تک RBI مستقل طور پر <em>کاٹنا</em> ریپو ریٹ، سال کے آغاز میں تقریباً 6.5 فیصد سے کم ہو کر دسمبر (تقریباً) تک تقریباً 5.25 فیصد رہ گیا، کیونکہ افراط زر ٹھنڈا ہوا اور مرکزی بینک نے ترقی کی حمایت کا انتخاب کیا۔ سستا پیسہ، وسیع طور پر، اس سال ہندوستانی ایکوئٹی کے لیے ایک ٹیل ونڈ تھا۔</p>\n<h2 id=\"inflation-what-the-rbi-is-really-fighting\">افراط زر: RBI واقعی لڑ رہا ہے۔</h2>\n<p>پہلے ہی باب سے افراط زر کو یاد رکھیں، قیمتوں میں خاموش اضافہ جو آپ کے پیسے کو ختم کرتا ہے۔ اس سے لڑنا RBI کا بنیادی کام ہے۔ اس کا سرکاری ہدف خوردہ افراط زر کو قریب رکھنا ہے۔ <strong>4%</strong>کے رواداری بینڈ کے اندر <strong>2% سے 6%</strong>. اس کا اصل ہتھیار وہی ریپو ریٹ ہے۔</p>\n<p>جب افراط زر بہت زیادہ گرم ہوتا ہے، RBI <em>اٹھاتا ہے</em> اخراجات اور قرض لینے کو ٹھنڈا کرنے کے لیے شرحیں۔ جب افراط زر حد کے اندر آرام سے گرتا ہے، تو RBI میں گنجائش ہوتی ہے۔ <em>کاٹنا</em> شرحیں اور معیشت کو بڑھنے میں مدد کریں۔ لہذا افراط زر اور شرح سود واقعی ایک ہی لیور کے دو سرے ہیں، یہی وجہ ہے کہ سرمایہ کار ماہانہ افراط زر کے نمبر کو اتنی قریب سے دیکھتے ہیں۔ یہ اکثر آپ کو بتاتا ہے کہ RBI آگے کیا کرے گا۔</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>2025 کے آخر میں، ہندوستان کی خوردہ افراط زر کئی سال کی کم ترین سطح پر آ گئی، ایک موقع پر پرنٹنگ 1% (تقریباً) سے کم ہو گئی، جو بالکل وہی ہے جس نے RBI کو شرحوں میں کمی کو برقرار رکھنے کا موقع فراہم کیا۔ کم افراط زر صرف آپ کے گروسری بل کے لیے اچھا نہیں ہے۔ یہ خاموشی سے مرکزی بینک کو پیسہ سستا کرنے کے لیے گرین لائٹ دے دیتا ہے۔</p>\n</div></div>\n<h2 id=\"fiis-vs-diis-the-two-great-rivers-of-money\">FIIs بمقابلہ DIIs: پیسے کے دو عظیم دریا</h2>\n<p>پیسے کے دو بڑے تالاب ہر روز ہندوستانی بازار میں آتے ہیں، اور ان کے درمیان رسہ کشی زیادہ تر موڈ سیٹ کرتی ہے۔</p>\n<ul>\n<li><strong>FIIs / FPIs (غیر ملکی ادارہ جاتی / پورٹ فولیو سرمایہ کار)</strong> بیرون ملک فنڈز، عالمی پنشن فنڈز، ہیج فنڈز، اثاثہ جات کے منتظمین، ہندوستان میں سرمایہ کاری کر رہے ہیں۔ ان کا پیسہ بڑا، تیز اور عالمی حالات کے لیے بہت حساس ہے۔ جب FIIز زیادہ فروخت ہوتے ہیں تو انڈیکس اکثر گر جاتا ہے۔</li>\n<li><strong>DIIs (گھریلو ادارہ جاتی سرمایہ کار)</strong> ہندوستانی میوچل فنڈز، بیمہ کنندگان اور پنشن فنڈز ہیں، اور ان کے پیچھے ماہانہ کی مسلسل لہر بہتی ہے۔ <em>خوردہ SIP رقم</em> آپ جیسے عام سرمایہ کاروں سے۔</li>\n</ul>\n<p>کئی دہائیوں سے پرانی کہاوت ہے: \"جب FII چھینکتے ہیں، دلال اسٹریٹ کو ٹھنڈ لگ جاتی ہے۔\" جو تیزی سے بدل رہا ہے۔</p>\n<table>\n<thead>\n<tr>\n<th></th>\n<th>FIIs/FPIs</th>\n<th>ڈی آئی آئیز</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>وہ کون ہیں؟</td>\n<td>غیر ملکی فنڈز، پنشن، ہیج فنڈز</td>\n<td>ہندوستانی میوچل فنڈز، بیمہ کنندگان، پنشن فنڈز</td>\n</tr>\n<tr>\n<td>ان کے پیچھے پیسہ</td>\n<td>عالمی سرمایہ</td>\n<td>گھریلو بچت اور SIPs</td>\n</tr>\n<tr>\n<td>رویہ</td>\n<td>بڑا، تیز، عالمی اشارے پر ردعمل ظاہر کرتا ہے۔</td>\n<td>مستحکم، ماہانہ SIPs کے ذریعے کھلایا جاتا ہے۔</td>\n</tr>\n<tr>\n<td>جب وہ بھاری فروخت کرتے ہیں۔</td>\n<td>انڈیکس اکثر تیزی سے گر جاتا ہے۔</td>\n<td>موسم خزاں کو کم کرنے کے لئے جاتا ہے</td>\n</tr>\n</tbody></table>\n<p>یہاں اس کی اسٹینڈ آؤٹ حالیہ مثال ہے۔ 2025 میں، FIIs نے a <em>ریکارڈ</em> ہندوستانی ایکوئٹی سے باہر کی رقم، تقریباً <strong>1.66 لاکھ کروڑ روپے</strong> (تقریباً 19 بلین ڈالر، تخمینہ)، ریکارڈ پر سب سے بڑا سالانہ غیر ملکی خروج۔ ایک دہائی پہلے، اس قسم کی فروخت نے مارکیٹ کو کچل دیا ہوگا۔ اس کے بجائے، گھریلو رقم نے بڑی حد تک اس دھچکے کو جذب کیا: DIIs خریدتے رہے، ریکارڈ SIP کے ذریعے طاقتور آمد جو کہ تقریباً <strong>31,000 کروڑ روپے ماہانہ</strong> دسمبر 2025 تک۔ 2025 کے اوائل کے آس پاس، پہلی بار، DIIs کی NSE درج کمپنیوں کی ملکیت ختم ہوگئی۔ <em>ماضی</em> FIIs'</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch14-fii-dii-flows.png\" alt=\"مثالی ماہانہ FII بمقابلہ DII بہاؤ، غیر ملکی سرمایہ کار بیچ رہے ہیں جبکہ ملکی ادارے اور SIP رقم خریدتے رہتے ہیں، مارکیٹ کو بڑھاتے رہتے ہیں (تمثال کے لیے، تخمینہ)\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">ڈیٹا یعنی</span>مثالی ماہانہ FII بمقابلہ DII بہاؤ، غیر ملکی سرمایہ کار بیچ رہے ہیں جبکہ ملکی ادارے اور SIP رقم خریدتے رہتے ہیں، مارکیٹ کو بڑھاتے رہتے ہیں (تمثال کے لیے، تخمینہ)</figcaption></figure>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>لاکھوں ہندوستانیوں کی ماہانہ SIP خاموشی سے مارکیٹ کا جھٹکا جذب کرنے والا بن گیا ہے۔ جب غیر ملکی باہر نکلنے کے لیے جلدی کرتے ہیں، تو سرمایہ کاری کی رقم کی وہ مستحکم گھریلو ٹپکتی تیزی سے منزل کو گرنے سے روکتی ہے۔</p>\n</div></div>\n<h2 id=\"crude-oil-and-the-rupee-india-s-imported-headache\">خام تیل اور روپیہ: ہندوستان کا درآمدی سر درد</h2>\n<p>بھارت تقریباً خریدتا ہے۔ <strong>اس کا 85% خام تیل بیرون ملک سے آتا ہے۔</strong>اور یہ ایک حقیقت تین چیزوں کو آپس میں جوڑتی ہے: تیل کی قیمت، روپیہ اور افراط زر۔</p>\n<p>جب عالمی سطح پر خام تیل کی قیمتوں میں اضافہ ہوتا ہے، تو ہندوستان کا درآمدی بل غبارے میں ہوتا ہے۔ اس سارے تیل کی ادائیگی کے لیے، ملک کو مزید US ڈالر خریدنا ہوں گے، جو روپے کو دھکیلتا ہے۔ <em>نیچے</em>. ایک کمزور روپیہ پھر بناتا ہے۔ <em>تمام</em> درآمدات، نہ صرف تیل، زیادہ مہنگی، جو افراط زر کو بڑھاتی ہیں، جو RBI کو شرحیں بلند رکھنے پر مجبور کرسکتی ہیں۔ خام تیل میں ایک اضافہ پوری زنجیر کو لپیٹ سکتا ہے۔</p>\n<p>کمزور روپیہ سب کو برابر تکلیف نہیں دیتا۔ وہ کمپنیاں جو <em>درآمد</em> (تیل کے مارکیٹرز، بہت سے مینوفیکچررز) نچوڑ جاتے ہیں، جبکہ <em>برآمد کنندگان</em> جو لوگ ڈالر میں کماتے ہیں، IT سروسز اور فارما، مثال کے طور پر، اکثر فائدہ اٹھاتے ہیں، کیونکہ ہر ایک ڈالر جو وہ کماتے ہیں وہ مزید روپوں میں بدل جاتا ہے۔</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>ہندوستان کا تیل کا سالانہ درآمدی بل کئی لاکھ کروڑ روپے بنتا ہے، لہٰذا خام تیل کی قیمت میں 10 ڈالر کا اضافہ بھی یہاں صفحہ اول کی حقیقی خبر ہے۔ یہ ان چند عالمی نمبروں میں سے ایک ہے جو آپ کے پیٹرول کی قیمت، روپیہ، مہنگائی اور شرح سود کو ایک ہی وقت میں دھکیل سکتے ہیں۔</p>\n</div></div>\n<p>ایک حالیہ مثال اس کو آپس میں جوڑتی ہے: 2025 کے اوائل میں روپیہ 85 روپے سے ڈالر کے مقابلے میں 2025 کے اوائل میں 90 سے 2026 تک کم ہوا (تقریباً)، خام تیل کی مضبوط قیمتوں اور عالمی تناؤ کی وجہ سے جزوی طور پر دباؤ، کروڈ، کرنسی اور جذبات کی ایک نصابی کتاب کا معاملہ۔</p>\n<h2 id=\"global-cues-why-india-wakes-up-reacting\">عالمی اشارے: ہندوستان کیوں جاگتا ہے ردعمل ظاہر کرتا ہے۔</h2>\n<p>مارکیٹس ٹائم زونز میں ایک دوسرے سے جڑے ہوئے ہیں۔ جب ہندوستان صبح 9:15 بجے کھلتا ہے، راتوں رات بہت کچھ ہو چکا ہے:</p>\n<ul>\n<li><strong>US فیڈرل ریزرو</strong> دنیا کی سب سے اہم شرح سود کا تعین کرتا ہے۔ جب فیڈ شرحیں بڑھاتا ہے یا محض عجیب لگتا ہے، تو عالمی پیسہ بہہ جاتا ہے۔ <em>کی طرف</em> US اور <em>دور</em> بھارت جیسی ابھرتی ہوئی منڈیوں سے۔</li>\n<li><strong>US مارکیٹس</strong> (S&amp;P 500, Nasdaq) اور وہ کیسے بند ہوئے۔ <strong>ایشیائی منڈیاں</strong> صبح، جو اکثر وال سٹریٹ کی پیروی کرتے ہیں؛ اور <strong>GIFT نفٹی</strong>، ایک ابتدائی اشارہ ہے کہ ہندوستان کیسے کھل سکتا ہے۔</li>\n<li><strong>جیو پولیٹکس</strong>جنگیں، تیل کے جھٹکے، انتخابات اور تجارتی تناؤ، گھنٹوں کے اندر سرحدوں کے پار لہریں۔</li>\n</ul>\n<p>یہ بنڈل وہی ہے جو TV اینکرز کا مطلب ہے \"عالمی اشارے\": راتوں رات سیٹ ہونے والا موڈ جس پر ہندوستان اکثر رد عمل ظاہر کرتا ہے، اس سے پہلے کہ کوئی ایک گھریلو واقعہ رونما ہو۔</p>\n<h2 id=\"reading-the-macro-mood-without-obsessing\">بغیر جنون کے میکرو موڈ کو پڑھنا</h2>\n<p>یہ وہ حصہ ہے جو ایک ابتدائی کے لیے سب سے اہم ہے: آپ کرتے ہیں۔ <em>نہیں</em> اس میں سے کسی کو بھی گھنٹے کے حساب سے ٹریک کرنے کی ضرورت ہے۔ میکرو موسم اہم موڑ پر ہوتا ہے، ہر عام صبح پر نہیں۔ ایک طویل مدتی سرمایہ کار کبھی کبھار اس پر نظر ڈالتا ہے، جس طرح ایک ملاح آسمان کو چیک کرتا ہے، مسلسل نہیں۔</p>\n<p>ایک سادہ ذہنی ڈیش بورڈ کافی ہے:</p>\n<ul>\n<li>شرح سود بڑھ رہی ہے یا گر رہی ہے؟</li>\n<li>کیا مہنگائی کنٹرول میں ہے؟</li>\n<li>کیا روپیہ بڑے پیمانے پر مستحکم ہے یا پھسل رہا ہے؟</li>\n<li>کیا خام پرسکون ہے یا تیز ہے؟</li>\n<li>کیا FII بھاری فروخت کنندہ ہیں یا مستحکم خریدار؟</li>\n<li>کیا عالمی موڈ \"رسک آن\" ہے یا \"رسک آف\"؟</li>\n</ul>\n<p>زیادہ تر دنوں میں، ایماندارانہ جواب ہے \"کچھ بھی ڈرامائی نہیں،\" اور صحیح عمل کچھ نہیں کرنا ہے۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>میکرو کے لیے ہے۔ <em>سیاق و سباق</em>، کے لیے نہیں۔ <em>ٹائمنگ</em>. کوئی بھی نہیں، ماہرین اقتصادیات، نہ فنڈ مینیجرز، فیڈ کے اگلے اقدام یا اگلے مہینے خام تیل کہاں جائے گا اس کی قابل اعتماد انداز میں پیش گوئی کرتا ہے۔ وہ سرمایہ کار جنہوں نے خاموشی سے اپنی SIPs کو 2025 کی ریکارڈ غیر ملکی فروخت کے ذریعے جاری رکھا ان لوگوں سے کہیں بہتر کارکردگی کا مظاہرہ کیا جو ہر خوفناک سرخی پر گھبرا جاتے تھے۔ میکرو کو آپ کی سمجھ سے آگاہ کرنے دیں، اپنے منصوبے کو ہائی جیک نہ کریں۔</p>\n</div></div>\n<h2 id=\"quick-recap\">فوری خلاصہ</h2>\n<ul>\n<li>دی <strong>ریپو ریٹ</strong>, کی طرف سے مقرر <strong>RBI</strong>، پیسے کی قیمت ہے، کم شرحیں عام طور پر اسٹاک کو اٹھاتی ہیں، زیادہ شرح ان پر وزن رکھتی ہے۔</li>\n<li>RBI بنیادی طور پر لڑنے کے لیے شرحوں کو منتقل کرتا ہے۔ <strong>افراط زر</strong>; 2025 میں مہنگائی کو ٹھنڈا کرنے سے یہ شرحوں کو کم کرنے دیتا ہے، ایکوئٹی کے لیے ایک ٹیل ونڈ۔</li>\n<li><strong>ایف آئی آئیز</strong> (غیر ملکی پیسہ) تیز اور عالمی ہیں؛ <strong>ڈی آئی آئیز</strong> پلس <strong>خوردہ SIPs</strong> مستحکم ہیں اور اب مارکیٹ تکیہ کر رہے ہیں، 2025 میں فروخت ہونے والی SIP کی آمد کا ریکارڈ جذب کیا گیا ہے۔</li>\n<li>بھارت اس کا زیادہ تر حصہ درآمد کرتا ہے۔ <strong>تیل</strong>, اتنا اعلی خام کمزور <strong>روپیہ</strong> اور مہنگائی کو پالتا ہے۔ روپے کی کمزوری سے برآمد کنندگان کو فائدہ، درآمد کنندگان کو نقصان۔</li>\n<li><strong>عالمی اشارے</strong>، US Fed، راتوں رات وال اسٹریٹ، جغرافیائی سیاست، موڈ سیٹ کرتا ہے جس پر انڈیا اکثر رد عمل ظاہر کرتا ہے۔</li>\n<li>میکرو موڈ کے طور پر پڑھیں <em>سیاق و سباق</em>وقت کا اشارہ نہیں؛ زیادہ تر دنوں میں، صحیح جواب یہ ہے کہ آپ اپنے منصوبے پر قائم رہیں۔</li>\n</ul>\n<p>اس کے بعد، ہم میکرو کے سست موسم سے تیز، طے شدہ اتپریرک کی طرف بڑھتے ہیں جو انفرادی اسٹاک، آمدنی کا سیزن، منافع، رہنمائی اور جھٹکا دینے والے واقعات کو ہر سرمایہ کار دیکھنا سیکھتا ہے۔</p>\n","toc":[{"level":2,"text":"سود کی شرح: رقم کی قیمت","id":"interest-rates-the-price-of-money"},{"level":3,"text":"کیوں کم شرحیں اکثر اسٹاک کو اٹھاتی ہیں۔","id":"why-lower-rates-often-lift-stocks"},{"level":2,"text":"افراط زر: RBI واقعی لڑ رہا ہے۔","id":"inflation-what-the-rbi-is-really-fighting"},{"level":2,"text":"FIIs بمقابلہ DIIs: پیسے کے دو عظیم دریا","id":"fiis-vs-diis-the-two-great-rivers-of-money"},{"level":2,"text":"خام تیل اور روپیہ: ہندوستان کا درآمدی سر درد","id":"crude-oil-and-the-rupee-india-s-imported-headache"},{"level":2,"text":"عالمی اشارے: ہندوستان کیوں جاگتا ہے ردعمل ظاہر کرتا ہے۔","id":"global-cues-why-india-wakes-up-reacting"},{"level":2,"text":"بغیر جنون کے میکرو موڈ کو پڑھنا","id":"reading-the-macro-mood-without-obsessing"},{"level":2,"text":"فوری خلاصہ","id":"quick-recap"}],"imgCount":3,"hasContent":true},"15":{"html":"<p>ایک اسٹاک ہفتوں تک خاموشی سے بہہ سکتا ہے، بمشکل حرکت کرتا ہے، اور پھر ایک ہی صبح میں 10% چھلانگ لگا سکتا ہے یا کریش کر سکتا ہے۔ ایک نئے آنے والے کو یہ بے ترتیب، غیر منصفانہ بھی لگتا ہے۔ لیکن تقریبا ہمیشہ، وہاں تھا <em>تاریخ</em> اس اقدام کے پیچھے، ایک کیلنڈر پر بیٹھا جسے کوئی بھی آتا دیکھ سکتا تھا۔ کمپنیاں اپنے منافع کی اطلاع شیڈول کے مطابق کرتی ہیں، ڈیویڈنڈ کی ادائیگی شیڈول کے مطابق کرتی ہیں، اور ملک کا بجٹ اور انتخابات کے دنوں کو سال پہلے ہی نشان زد کیا جاتا ہے۔</p>\n<p>آخری باب میکرو فورسز کے سست موسم کے بارے میں تھا۔ یہ تیز، طے شدہ جھٹکے، اتپریرک کے بارے میں ہے۔ قیمتوں کو منتقل کرنے والے واقعات کے کیلنڈر کو سیکھنا ان سب سے زیادہ عملی مہارتوں میں سے ایک ہے جو ایک سرمایہ کار بنا سکتا ہے، کیونکہ یہ بدل جاتا ہے کہ \"زمین پر یہ صرف کیوں گرا؟\" \"آہ، آج نتائج آنے والے تھے۔\" آئیے بڑے سے گزرتے ہیں۔</p>\n<h2 id=\"results-season-the-market-s-quarterly-report-card\">نتائج کا موسم: مارکیٹ کا سہ ماہی رپورٹ کارڈ</h2>\n<p>ہندوستان میں درج ہر کمپنی کو اپنے مالی نتائج کی اطلاع دینی چاہیے۔ <strong>سال میں چار بار</strong>ایک بار فی سہ ماہی:</p>\n<ul>\n<li><strong>Q1</strong> اپریل تا جون پر محیط ہے، <strong>Q2</strong> جولائی تا ستمبر، <strong>Q3</strong> اکتوبر سے دسمبر، اور <strong>Q4</strong> جنوری تا مارچ۔</li>\n<li>نتائج کا اعلان ہر سہ ماہی کے ختم ہونے کے چند ہفتوں بعد کیا جاتا ہے، اس لیے کمپنی کے اعلانات کا سیلاب تقریباً چھ ہفتے تک پھیل جاتا ہے۔ وہ کھینچا تانی کہلاتی ہے۔ <strong>نتائج کا موسم</strong> (یا کمائی کا موسم)۔</li>\n</ul>\n<p>جب نمبر سامنے آتے ہیں تو چار چیزیں سب سے اہم ہوتی ہیں:</p>\n<ul>\n<li><strong>آمدنی</strong> (\"ٹاپ لائن\")، کمپنی کی کل فروخت۔</li>\n<li><strong>خالص منافع</strong> (\"نیچے کی لکیر\")، تمام اخراجات اور ٹیکسوں کے بعد کیا بچا ہے۔</li>\n<li><strong>حاشیہ</strong>آمدنی کے فیصد کے طور پر منافع، جو ظاہر کرتا ہے کہ کمپنی فروخت کو کس قدر مؤثر طریقے سے منافع میں بدلتی ہے۔</li>\n<li><strong>نمو</strong>گزشتہ سال کی اسی سہ ماہی (سال بہ سال، یا YoY) اور پچھلی سہ ماہی (سہ ماہی بہ سہ ماہی، QoQ) کے مقابلے۔</li>\n</ul>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch15-results-timeline.png\" alt=\"ہندوستان کے سہ ماہی نتائج کا کیلنڈر، سال بھر میں رپورٹنگ کے چار سیزن اور ہر کمپنی کی جانب سے اعلان کرنے کے وقت\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">فلو چارٹ</span>ہندوستان کے سہ ماہی نتائج کا کیلنڈر، سال بھر میں رپورٹنگ کے چار سیزن اور ہر کمپنی کی جانب سے اعلان کرنے کے وقت</figcaption></figure>\n<h3 id=\"why-a-stock-can-post-record-profit-and-still-crash\">کیوں ایک اسٹاک ریکارڈ منافع پوسٹ کر سکتا ہے اور پھر بھی کریش کر سکتا ہے۔</h3>\n<p>یہ وہ حصہ ہے جو ہر ابتدائی کو حیران کر دیتا ہے: حصص کی قیمت خام نمبر پر رد عمل ظاہر نہیں کرتی ہے، یہ نمبر پر رد عمل ظاہر کرتی ہے <em>بمقابلہ جس کی مارکیٹ پہلے ہی توقع کر رہی تھی۔</em>. تجزیہ کار اور سرمایہ کار نتائج کے دن میں ایک توقع رکھتے ہیں (اکثر اسے \"تخمینہ\" یا \"سڑک کا نمبر\" کہا جاتا ہے)۔ اس توقع کے لیے اسٹاک کی قیمت پہلے ہی طے کی جاچکی ہے۔</p>\n<ul>\n<li><strong>توقعات کو مات دیں۔</strong>، منافع امید سے زیادہ آتا ہے، اور اسٹاک اکثر چھلانگ لگاتا ہے۔</li>\n<li><strong>توقعات کی کمی</strong>امید سے کم، اور یہ اکثر گر جاتا ہے۔</li>\n<li><strong>توقعات پر پورا اتریں۔</strong> بالکل، اور ردعمل عام طور پر خاموش ہے.</li>\n</ul>\n<p>لہذا ایک کمپنی اپنے اب تک کے سب سے زیادہ منافع کا اعلان کر سکتی ہے۔ <em>اب بھی</em> گر، کیونکہ مارکیٹ اس سے بھی زیادہ کی توقع رکھتی ہے۔ حیرت، تعداد نہیں، قیمت کو بڑھاتی ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch15-results-gap.png\" alt=\"سٹاک کا ایک کینڈل سٹک چارٹ جس میں نتائج کے دن تیزی سے فرق پڑتا ہے، ایک لمبی موم بتی اور قیمت کا فرق جیسے ہی مارکیٹ کسی بیٹ یا کمی پر رد عمل ظاہر کرتی ہے (مثالی)\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">چارٹ</span>سٹاک کا ایک کینڈل سٹک چارٹ جس میں نتائج کے دن تیزی سے فرق پڑتا ہے، ایک لمبی موم بتی اور قیمت کا فرق جیسے ہی مارکیٹ کسی بیٹ یا کمی پر رد عمل ظاہر کرتی ہے (مثالی)</figcaption></figure>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>حصص کی قیمتیں آگے بڑھ رہی ہیں۔ <em>حیرت</em> توقعات کے مطابق، قطعی نتیجہ پر نہیں۔ \"اچھے نتائج\" ایک اسٹاک کو ڈوب سکتے ہیں اگر مارکیٹ کو اچھے نتائج کی امید ہو، اور \"کمزور نتائج\" اسٹاک کو اٹھا سکتے ہیں اگر سب کو بدتر کا خدشہ ہو۔</p>\n</div></div>\n<p>یہ ایک پرانے بازار کی بھی وضاحت کرتا ہے کہ: <strong>\"افواہ خریدو، خبریں بیچو۔\"</strong> ایک اسٹاک اکثر دنوں میں بڑھتا ہے۔ <em>پہلے</em> اچھے نمبروں کے لیے لوگوں کی پوزیشن کے طور پر نتائج۔ جب تک خوشخبری کا حقیقت میں اعلان کیا جاتا ہے، یہ پہلے سے ہی قیمت میں پک چکی ہوتی ہے، لہذا ٹھوس رپورٹ پر بھی اسٹاک نیچے آ سکتا ہے، کیونکہ ابتدائی خریدار اپنا منافع لیتے ہیں۔</p>\n<p>اس کی ٹھوس تصویر بنائیں۔ فرض کریں کہ مارکیٹ کو توقع ہے کہ کمپنی اپنے سہ ماہی منافع میں 15% اضافہ کرے گی۔ اگر یہ 20٪ کی اطلاع دیتا ہے، تو اسٹاک تیزی سے بڑھ سکتا ہے، ایک خوشگوار حیرت۔ اگر یہ صرف 12 فیصد رپورٹ کرتا ہے، پھر بھی حقیقی نمو، اسٹاک ہو سکتا ہے۔ <em>گر</em>، کیونکہ یہ بار سے کم تھا۔ ایک ہی کمپنی، حقیقی ترقی کسی بھی طرح سے، مخالف ردعمل، سبھی توقعات کے مطابق طے ہوئے۔</p>\n<h2 id=\"dividends-getting-paid-to-hold\">منافع: ہولڈ کرنے کے لئے ادائیگی حاصل کرنا</h2>\n<p>اے <strong>ڈیویڈنڈ</strong> ایک نقد ادائیگی ہے جو کمپنی اپنے حصص یافتگان کے ساتھ اپنے منافع میں سے شیئر کرتی ہے، 10 روپے فی شیئر۔ آپ کے بینک اکاؤنٹ میں 100 شیئرز اور 1,000 روپے کی زمین ہے۔ یہ ان دو طریقوں میں سے ایک ہے جو اسٹاک آپ کو انعام دیتے ہیں (دوسرا وقت کے ساتھ قیمت بڑھنا)۔</p>\n<p>تین تاریخیں اہمیت رکھتی ہیں، اور ان کو سمجھنے سے بہت سی بے ضرورت گھبراہٹ بچ جاتی ہے:</p>\n<ul>\n<li><strong>اعلان کی تاریخ</strong>، کمپنی کا بورڈ ڈیویڈنڈ اور اس کی رقم کا اعلان کرتا ہے۔</li>\n<li><strong>سابق ڈیویڈنڈ کی تاریخ</strong>، کٹ آف. حصہ کے مالک ہیں۔ <em>پہلے</em> اس تاریخ اور آپ کو منافع ملے گا۔ اسے خرید لو <em>پر یا بعد میں</em> اس تاریخ اور آپ کو یہ خاص ادائیگی یاد آتی ہے۔</li>\n<li><strong>ریکارڈ کی تاریخ</strong>, وہ تاریخ جب کمپنی اس بات کی تصدیق کرنے کے لیے اپنی کتابیں چیک کرتی ہے کہ اہل شیئر ہولڈر کون ہیں۔</li>\n</ul>\n<p>اب وہ حصہ جو ابتدائیوں کو ڈراتا ہے۔ پر <strong>سابق ڈیویڈنڈ کی تاریخ، اسٹاک کی قیمت عام طور پر ڈیویڈنڈ کی رقم سے کم ہوتی ہے۔</strong> اگر 500 روپے کا اسٹاک 10 روپے کا ڈیویڈنڈ دے رہا ہے، تو یہ 490 روپے کے قریب کھل سکتا ہے۔ نئے سرمایہ کار سرخ نظر آتے ہیں اور سمجھتے ہیں کہ کچھ غلط ہو گیا ہے۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>سابق ڈیویڈنڈ ڈراپ ہے۔ <strong>نقصان نہیں</strong>، یہ سادہ ریاضی ہے۔ کمپنی نے نقد رقم دی ہے، لہذا کاروبار کی قیمت بالکل اتنی کم ہے، اور حصص کی قیمت تقریباً ڈیویڈنڈ کے حساب سے کم ہو جاتی ہے۔ آپ غریب نہیں ہیں: قدر صرف \"حصص کی قیمت\" سے \"آپ کے اکاؤنٹ میں نقد\" میں منتقل ہوگئی۔ گھبرائیں نہیں اور اس پر فروخت نہ کریں۔</p>\n</div></div>\n<p>ایک متعلقہ نمبر جو آپ سنیں گے۔ <strong>منافع کی پیداوار</strong>, حصص کی قیمت سے تقسیم کردہ سالانہ منافع، فیصد کے طور پر ظاہر کیا جاتا ہے۔ 400 روپے کے اسٹاک پر 20 روپے سالانہ ڈیویڈنڈ 5% پیداوار ہے۔ یہ آپ کو بتاتا ہے کہ اسٹاک اپنی قیمت کے مقابلے میں کتنی نقد آمدنی پھینکتا ہے۔</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>ہندوستان کی کچھ مستحکم بلیو چپ اور پبلک سیکٹر کمپنیوں نے بغیر کسی وقفے کے منافع ادا کیا ہے <em>دہائیوں</em>. طویل مدتی ہولڈرز کے لیے، وہ ادائیگیاں، جو سال بہ سال دوبارہ سرمایہ کاری کی جاتی ہیں، خاموشی سے کل ریٹرن کے ایک بامعنی حصے میں شامل ہو جاتی ہیں، حصص کی قیمت میں کسی بھی اضافے کے اوپر۔</p>\n</div></div>\n<h2 id=\"guidance-and-management-commentary\">رہنمائی اور انتظامی تبصرہ</h2>\n<p>اکثر، کیا انتظام <em>کہتے ہیں</em> مستقبل کے بارے میں اسٹاک کو خود نتائج سے زیادہ منتقل کرتا ہے، کیونکہ مارکیٹیں آگے کی طرف نظر آتی ہیں۔ نتائج جاری کرنے کے بعد، کمپنیوں نے ایک <strong>آمدنی کال</strong> (یا \"کنکال\") جہاں انتظامیہ سہ ماہی پر بحث کرتی ہے اور تجزیہ کاروں کے سوالات کا جواب دیتی ہے۔ سننے کے لیے دو باتیں:</p>\n<ul>\n<li><strong>رہنمائی</strong>، مستقبل کی آمدنی، مارجن یا نمو کے لیے کمپنی کی اپنی پیشن گوئی۔ رہنمائی کو بڑھانا اعتماد کا اشارہ دیتا ہے اور اکثر اسٹاک کو اٹھاتا ہے۔ اسے کاٹنے سے اسٹاک ڈوب سکتا ہے۔ <em>اچھے موجودہ نتائج پر بھی</em>.</li>\n<li><strong>لہجہ</strong>پراعتماد اور وسیع، یا محتاط اور دفاعی۔ تجربہ کار سرمایہ کار موڈ کو اتنا ہی پڑھتے ہیں جتنا کہ نمبر۔</li>\n</ul>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>جب آپ نتیجہ پڑھتے ہیں تو منافع کے اعداد و شمار پر مت روکیں۔ انتظامی تبصرے اور رہنمائی کو بھی چھوڑ دیں۔ پسماندہ نظر آنے والا نمبر آپ کو بتاتا ہے کہ کمپنی کہاں ہے۔ <em>رہا ہے</em>; رہنمائی اشارہ کرتی ہے کہ یہ کہاں ہے۔ <em>جا رہا ہے</em>، اور مارکیٹ مستقبل کے لیے ادائیگی کرتی ہے۔</p>\n</div></div>\n<h2 id=\"other-events-that-jolt-a-single-stock\">دوسرے واقعات جو ایک ہی اسٹاک کو جھٹک دیتے ہیں۔</h2>\n<p>نتائج سے آگے، مٹھی بھر یک طرفہ واقعات ایک مخصوص اسٹاک کو تیزی سے منتقل کر سکتے ہیں:</p>\n<ul>\n<li><strong>انضمام اور حصول (M&amp;A)</strong>، ایک کمپنی دوسری خرید رہی ہے۔ حاصل کی جا رہی کمپنی اکثر چھلانگ; خریدار کسی بھی طرح سے آگے بڑھ سکتا ہے۔</li>\n<li><strong>ریگولیٹری خبریں۔</strong>ایک نیا اصول، پابندی، منظوری، جرمانہ یا ٹیکس میں تبدیلی جو کمپنی یا شعبے کو متاثر کرتی ہے۔</li>\n<li><strong>انتظامی تبدیلیاں</strong>، ایک قابل احترام CEO چھوڑ رہا ہے، یا ایک مضبوط نیا لیڈر جوائن کر رہا ہے۔</li>\n<li><strong>اشاریہ کی شمولیت یا اخراج</strong>جب کوئی اسٹاک نفٹی 50 یا سینسیکس میں شامل کیا جاتا ہے، انڈیکس فنڈز اسے خریدنے پر مجبور ہوتے ہیں، جس سے مانگ پیدا ہوتی ہے۔ ہٹانے سے الٹا ہوتا ہے۔</li>\n<li><strong>بڑے احکامات، عدالتی فیصلے، کریڈٹ ریٹنگ میں تبدیلیاں</strong>, کوئی بھی خبر جو مستقبل کے منافع کے لیے نقطہ نظر کو تبدیل کرتی ہے۔</li>\n</ul>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch15-catalyst-calendar.png\" alt=\"اتپریرک کا ایک سال، نتائج کے موسم، ڈیویڈنڈ کی تاریخیں، بجٹ کا دن، انتخابات کے نتائج اور پورے کیلنڈر میں نشان زد عالمی جھٹکے\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">انفوگرافک</span>اتپریرک کا ایک سال، نتائج کے موسم، ڈیویڈنڈ کی تاریخیں، بجٹ کا دن، انتخابات کے نتائج اور پورے کیلنڈر میں نشان زد عالمی جھٹکے</figcaption></figure>\n<h2 id=\"shock-events-when-the-whole-market-lurches\">صدمے کے واقعات: جب پوری مارکیٹ میں ہلچل مچ جاتی ہے۔</h2>\n<p>کچھ واقعات حرکت میں آتے ہیں۔ <em>سب کچھ</em> ایک ساتھ، صرف ایک اسٹاک نہیں:</p>\n<ul>\n<li><strong>یونین بجٹ کا دن</strong> (1 فروری)، ٹیکس، اخراجات اور سیکٹر پالیسی میں تبدیلیاں منٹوں میں مارکیٹ کو جھول سکتی ہیں۔</li>\n<li><strong>انتخابی نتائج کا دن</strong>, قومی اور بڑے ریاستی نتائج ڈرامائی طور پر ایک دن کی حرکتیں پیدا کر سکتے ہیں کیونکہ سرمایہ کار سیاسی نقطہ نظر کو دوبارہ قیمت دیتے ہیں۔</li>\n<li><strong>غیر طے شدہ عالمی جھٹکے</strong>، ایک وبائی بیماری، ایک جنگ، ایک بینکنگ خوف، ایک حیران کن مرکزی بینک اقدام۔ یہ انتباہ کے بغیر آتے ہیں اور پورے انڈیکس کو جھٹکا دیتے ہیں۔</li>\n</ul>\n<p>آپ غیر طے شدہ لوگوں کی ڈائری نہیں کر سکتے، لیکن یہ جان کر کہ وہ موجود ہیں جب کوئی ٹکرائے تو آپ کو پرسکون رہتا ہے۔</p>\n<h2 id=\"building-a-simple-watch-routine\">ایک سادہ گھڑی کا معمول بنانا</h2>\n<p>آپ کو بلومبرگ ٹرمینل کی ضرورت نہیں ہے۔ ایک ابتدائی کا معمول ہلکا ہو سکتا ہے:</p>\n<ul>\n<li>رکھنا a <strong>چھوٹی واچ لسٹ</strong> ان چند اسٹاکس میں سے جو آپ کے مالک ہیں یا قریب سے پیروی کرتے ہیں۔</li>\n<li>ان کا نوٹ کریں۔ <strong>نتائج کی تاریخیں</strong>کمپنیاں ان کا پہلے سے اعلان کرتی ہیں، اور ایکسچینجز کیلنڈر شائع کرتے ہیں۔</li>\n<li>نتائج سے پہلے، کسی نہ کسی طرح کا احساس ہے <strong>کیا توقع ہے</strong>; نتائج کے بعد، سادہ سوال کو چیک کریں: کیا انہوں نے <em>مارو یا یاد کرو</em>، اور کیا <em>رہنمائی بہتر یا خراب</em>?</li>\n<li>نشان <strong>سابق ڈیویڈنڈ کی تاریخیں</strong> لہذا قیمت میں کمی آپ کو کبھی حیران نہیں کرتی۔</li>\n<li>سب سے اہم بات، <strong>شور کی تجارت نہ کرو.</strong> ایک سہ ماہی شاذ و نادر ہی طویل مدتی نقطہ نظر کو تبدیل کرتی ہے۔ کیلنڈر کو دیکھیں <em>سیکھیں</em> آپ کی کمپنیاں کیسا برتاؤ کرتی ہیں، کودنا اور باہر نہیں جانا۔</li>\n</ul>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>نتائج کے دن اسٹاک کے لیے سب سے زیادہ اتار چڑھاؤ والے اور غیر متوقع سیشنز میں سے ہوتے ہیں، قیمتیں منٹوں میں دونوں سمتوں میں بڑھ سکتی ہیں۔ ایک ابتدائی کے لیے، یہ تسلسل پر تجارت کرنے کا بدترین ممکنہ لمحہ ہے۔ دھول کو جمنے دیں، مکمل تصویر پڑھیں، اور کاروبار کو ایک نہیں بلکہ کئی حلقوں سے پرکھیں۔</p>\n</div></div>\n<h2 id=\"quick-recap\">فوری خلاصہ</h2>\n<ul>\n<li>لسٹڈ کمپنیوں کی رپورٹ <strong>سال میں چار بار نتائج</strong>; چھ ہفتے کا رش ہے <strong>نتائج کا موسم</strong>، آمدنی، منافع، مارجن اور نمو کے لیے دیکھا۔</li>\n<li>قیمتوں پر رد عمل ظاہر ہوتا ہے۔ <strong>حیرت بمقابلہ توقعات</strong>، خام نمبر نہیں، یہی وجہ ہے کہ ریکارڈ منافع اب بھی ایک اسٹاک کو ڈوب سکتا ہے، اور \"افواہ خریدیں، خبریں بیچیں\" چل رہا ہے۔</li>\n<li>اے <strong>ڈیویڈنڈ</strong> منافع سے نقد ہے؛ اسٹاک پر تقریباً ڈیویڈنڈ گرتا ہے۔ <strong>سابق ڈیویڈنڈ کی تاریخ</strong>عام ریاضی، <em>نہیں</em> ایک نقصان</li>\n<li><strong>رہنمائی اور انتظامی تبصرہ</strong> مستقبل کے بارے میں اکثر اسٹاک کو پچھلی سہ ماہی کے اعداد سے زیادہ منتقل کرتے ہیں۔</li>\n<li><strong>ایم اینڈ اے، ریگولیشن، انتظامی تبدیلیاں، انڈیکس کی شمولیت</strong> اور <strong>صدمے کے واقعات</strong> (بجٹ، انتخابات، عالمی بحران) جاننے کے لیے دوسرے اتپریرک ہیں۔</li>\n<li>تعمیر کرنا a <strong>روشنی کی گھڑی کا معمول</strong> نتائج کے کیلنڈر کے ارد گرد، اور ایک ہی غیر مستحکم سیشن کے شور کی تجارت کے خلاف مزاحمت کریں۔</li>\n</ul>\n<p>اب آپ سمجھ گئے ہیں کہ سست میکرو موسم سے لے کر تیز طے شدہ اتپریرک تک قیمتوں کو کیا حرکت دیتا ہے۔ اگلے باب میں ہم عملی طور پر حاصل کرتے ہیں: ایک عام سیور دراصل ایک سرمایہ کار کیسے بنتا ہے، اکاؤنٹ کھولنا، انڈیکس فنڈ ایس آئی پی کے مقابلے میں براہ راست اسٹاک کے دو راستے، اور چھوٹے اور محفوظ طریقے سے شروع کرنے کے لیے ایک سمجھدار روڈ میپ۔</p>\n","toc":[{"level":2,"text":"نتائج کا موسم: مارکیٹ کا سہ ماہی رپورٹ کارڈ","id":"results-season-the-market-s-quarterly-report-card"},{"level":3,"text":"کیوں ایک اسٹاک ریکارڈ منافع پوسٹ کر سکتا ہے اور پھر بھی کریش کر سکتا ہے۔","id":"why-a-stock-can-post-record-profit-and-still-crash"},{"level":2,"text":"منافع: ہولڈ کرنے کے لئے ادائیگی حاصل کرنا","id":"dividends-getting-paid-to-hold"},{"level":2,"text":"رہنمائی اور انتظامی تبصرہ","id":"guidance-and-management-commentary"},{"level":2,"text":"دوسرے واقعات جو ایک ہی اسٹاک کو جھٹک دیتے ہیں۔","id":"other-events-that-jolt-a-single-stock"},{"level":2,"text":"صدمے کے واقعات: جب پوری مارکیٹ میں ہلچل مچ جاتی ہے۔","id":"shock-events-when-the-whole-market-lurches"},{"level":2,"text":"ایک سادہ گھڑی کا معمول بنانا","id":"building-a-simple-watch-routine"},{"level":2,"text":"فوری خلاصہ","id":"quick-recap"}],"imgCount":3,"hasContent":true},"16":{"html":"<p>آپ نے پچھلے پندرہ ابواب یہ سیکھنے میں گزارے ہیں کہ مارکیٹ کیسے کام کرتی ہے، حصہ کیا ہے، ایکسچینج کون چلاتا ہے، قیمتوں کو کیا حرکت دیتا ہے، میکرو موسم کیسے چلتا ہے۔ اب وہ باب آتا ہے جو درحقیقت آپ کی زندگی کو بدل دیتا ہے: اس تمام تفہیم کو چند آسان کاموں میں تبدیل کرنا۔ زیادہ تر لوگ ہمیشہ کے لیے \"کسی دن سرمایہ کار\" رہتے ہیں، جاننے اور کرنے کے درمیان خلاء میں پھنسے رہتے ہیں۔ یہاں مقصد یہ ہے کہ اس خلا کو پرسکون، سستے اور محفوظ طریقے سے ختم کیا جائے، تاکہ آخر تک آپ کو معلوم ہو جائے کہ پہلے قدم کیسا نظر آتا ہے۔</p>\n<p>شروع کرنے سے پہلے ایک نرم یاد دہانی: یہ تعلیم ہے، مشورہ نہیں۔ یہ کسی ایک بروکر یا فنڈ کا نام نہیں لے گا، کیونکہ صحیح آپ پر منحصر ہے۔ یہ کیا <em>مرضی</em> آپ کو سیور سے سرمایہ کار تک ایک واضح، غیر خوفناک نقشہ فراہم کریں۔</p>\n<h2 id=\"step-one-the-demat-and-trading-account\">پہلا مرحلہ: ڈیمیٹ اور ٹریڈنگ اکاؤنٹ</h2>\n<p>حصص خریدنے اور رکھنے کے لیے، آپ کو دو منسلک اکاؤنٹس کی ضرورت ہے، اور ان دنوں وہ عام طور پر ایک یا دو دن میں، مکمل طور پر آن لائن، ایک ساتھ کھولے جاتے ہیں:</p>\n<ul>\n<li>اے <strong>ڈیمیٹ اکاؤنٹ</strong> آپ کے حصص کو الیکٹرانک شکل میں رکھتا ہے، جس طرح ایک بینک اکاؤنٹ آپ کے پیسے رکھتا ہے۔ (مارکیٹ ایکو سسٹم کے باب سے ڈپازٹریز، NSDL اور CDSL کو یاد کریں، آپ کا ڈیمیٹ اکاؤنٹ ان میں سے ایک کے ساتھ بیٹھتا ہے۔)</li>\n<li>اے <strong>تجارتی اکاؤنٹ</strong> وہی ہے جو آپ کو ایکسچینج پر خرید و فروخت کے آرڈر دینے دیتا ہے۔</li>\n</ul>\n<h3 id=\"kyc-in-plain-words\">KYC، صاف الفاظ میں</h3>\n<p>کوئی بھی اکاؤنٹ کھلنے سے پہلے، آپ کو مکمل کرنا ہوگا۔ <strong>KYC</strong>، \"اپنے گاہک کو جانیں۔\" یہ صرف قانونی جانچ ہے کہ آپ وہی ہیں جو آپ کہتے ہیں کہ آپ ہیں، اور یہ وہی تحفظ ہے جو پورے مالیاتی نظام میں دھوکہ دہی کو مشکل بنا دیتا ہے۔ آپ کو عام طور پر ضرورت ہو گی:</p>\n<ul>\n<li><strong>PAN کارڈ</strong>، آپ کا ٹیکس ID، کسی بھی ہندوستانی مالیاتی اکاؤنٹ کی ریڑھ کی ہڈی ہے۔</li>\n<li><strong>آدھار</strong>، شناخت اور پتہ کے لیے استعمال کیا جاتا ہے، اکثر OTP کے ذریعے فوری ای-تصدیق کے لیے۔</li>\n<li><strong>ایک بینک اکاؤنٹ</strong>، لنک کیا گیا تاکہ پیسہ اندر اور باہر جا سکے (ایک منسوخ شدہ چیک یا آپ کے بینک کی تفصیلات)۔</li>\n<li><strong>ایک تصویر اور دستخط</strong>، اور کبھی کبھی ایک مختصر ویڈیو تصدیق۔</li>\n</ul>\n<p>پورا عمل اب آن لائن ہے، اپ لوڈ کریں، OTP کے ساتھ تصدیق کریں، ای سائن، ہو گیا۔ پرانے زمانے کی طرح کوئی قطار نہیں، فوٹو کاپیوں کی موٹی فائلیں نہیں۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch16-account-kyc.png\" alt=\"آن لائن اکاؤنٹ کھولنا، PAN، آدھار اور ایک بینک لنک جو KYC کی تصدیق کے ذریعے تیار ڈیمیٹ اور ٹریڈنگ اکاؤنٹ میں بہہ رہا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">انفوگرافک</span>آن لائن اکاؤنٹ کھولنا، PAN، آدھار اور ایک بینک لنک جو KYC تصدیق کے ذریعے تیار ڈیمیٹ اور ٹریڈنگ اکاؤنٹ میں بہہ رہا ہے۔</figcaption></figure>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>بھارت نے حد سے تجاوز کیا ہے۔ <strong>21.6 کروڑ ڈیمیٹ اکاؤنٹس، تقریباً 216 ملین</strong> (دسمبر 2025 تک)، صرف چند سال پہلے کی تعداد سے کئی گنا زیادہ۔ ایک پوری نسل اپنے فون سے منٹوں میں اکاؤنٹ کھول رہی ہے، ایک ایسا کام جس میں ایک بار کئی ہفتوں کا کاغذی کام لگتا تھا۔</p>\n<p>:::چابی\nاکاؤنٹ کھولنا آسان حصہ ہے، اور سب سے چھوٹا۔ ان میں سے 21.6 کروڑ ڈیمیٹ اکاؤنٹس، اس سے کم <strong>5 کروڑ فعال ہیں۔</strong> کسی بھی سال میں؛ باقی میں سے بہت سے کھولے گئے تھے اور بیکار چھوڑ دیے گئے تھے، یا ڈپلیکیٹ ہیں جو ایک شخص بروکرز میں رکھتا ہے۔ اکاؤنٹ صرف ایک ہے۔ <em>دروازہ</em>. ہونا <strong>تیار</strong> سرمایہ کاری کرنے کے لیے، ایک ہنگامی فنڈ، مہنگے قرض کی منظوری، ایک سادہ منصوبہ اور ایک مستحکم SIP، حقیقی سنگ میل ہے۔ اگر آپ نے کھاتہ کھولا اور کبھی سرمایہ کاری نہیں کی، تو آپ پیچھے نہیں ہیں۔ آپ بالکل وہی ہیں جہاں زیادہ تر لوگ ہیں۔ اس باب کا باقی حصہ اس دروازے سے صحیح طریقے سے چلنے کے بارے میں ہے۔</p>\n</div></div>\n<p>:::</p>\n<h2 id=\"two-paths-from-here\">یہاں سے دو راستے</h2>\n<p>آپ کا اکاؤنٹ کھلنے کے ساتھ ہی، ایک ابتدائی شخص سڑک کے ایک کانٹے تک پہنچ جاتا ہے۔ دونوں راستے درست ہیں؛ وہ مختلف لوگوں کے مطابق ہوتے ہیں اور اکثر بہترین کام کرتے ہیں۔ <em>ایک ساتھ</em>.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch16-two-paths.png\" alt=\"انڈیکس فنڈ SIP کے ذریعے پوری مارکیٹ کا مالک ہونا بمقابلہ انفرادی اسٹاک کو خود چننا، دو ابتدائی راستے ایک ساتھ ہیں۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>انڈیکس فنڈ SIP کے ذریعے پوری مارکیٹ کا مالک ہونا بمقابلہ انفرادی اسٹاک خود چننا، دو ابتدائی راستے ایک ساتھ ہیں۔</figcaption></figure>\n<h3 id=\"path-1-buy-individual-stocks-directly\">راستہ 1: براہ راست انفرادی اسٹاک خریدیں۔</h3>\n<p>آپ تحقیق کریں اور مخصوص کمپنیوں کا انتخاب کریں، پھر ان کے حصص خود خریدیں۔</p>\n<ul>\n<li><strong>اوپر کی طرف:</strong> مکمل کنٹرول، آپ بالکل وہی چیز رکھتے ہیں جو آپ منتخب کرتے ہیں، اور اگر آپ اچھی طرح سے انتخاب کرتے ہیں تو زیادہ منافع کا امکان۔ آپ بھی اس طرح تیز ترین سیکھیں۔</li>\n<li><strong>نقصانات:</strong> یہ ہر کمپنی پر حقیقی تحقیق کا مطالبہ کرتا ہے، زیادہ خطرہ رکھتا ہے (ایک برا انتخاب نقصان پہنچا سکتا ہے)، وقت اور مستحکم مزاج کی ضرورت ہوتی ہے، اور جذباتی غلطیوں کو آسان بناتی ہے۔</li>\n</ul>\n<p>یہ راستہ آپ کے لیے بہترین ہے۔ <em>کے بعد</em> آپ نے بنیادی باتیں سیکھ لی ہیں اور ایک فعال کردار چاہتے ہیں، عام طور پر آپ کے پیسے کے صرف ایک چھوٹے سے ٹکڑے سے شروع ہوتا ہے۔</p>\n<h3 id=\"path-2-mutual-funds-and-index-funds-via-sip\">راستہ 2: میوچل فنڈز اور انڈیکس فنڈز، بذریعہ SIP</h3>\n<p>خود اسٹاک لینے کے بجائے، آپ ایک فنڈ خریدتے ہیں جس میں آپ کے لیے بہت سے اسٹاک ہوتے ہیں۔</p>\n<ul>\n<li><p>اے <strong>باہمی فنڈ</strong> ہزاروں سرمایہ کاروں سے رقم جمع کرتا ہے، اور ایک پیشہ ور اسے کئی کمپنیوں میں لگاتا ہے، جس سے آپ کو ایک ہی خریداری میں فوری تنوع ملتا ہے۔</p>\n</li>\n<li><p>ایک <strong>انڈیکس فنڈ</strong> ایک خاص، کم لاگت والا میوچل فنڈ ہے <em>آئینہ</em> ایک انڈیکس جیسا کہ نفٹی 50۔ یہ تمام 50 اسٹاک کو انڈیکس کے تناسب سے خریدتا ہے، لہذا ایک خریداری آپ کو ہندوستان کی 50 سب سے بڑی کمپنیوں کا ایک ساتھ مالک بنا دیتی ہے۔ مارکیٹ کو شکست دینے کی کوشش کرنے والا کوئی مینیجر نہیں ہے، یہ صرف خاموشی سے اسے ٹریک کرتا ہے، بہت کم فیس پر۔</p>\n</li>\n<li><p><strong>اوپر کی طرف:</strong> فوری تنوع، ہینڈ آف، کم لاگت، اور انفرادی کمپنیوں کا تجزیہ کرنے کی ضرورت نہیں، یہی وجہ ہے کہ یہ سب سے زیادہ ابتدائی افراد کے لیے موزوں ہے۔</p>\n</li>\n<li><p><strong>نقصانات:</strong> آپ انڈیکس سے میچ کریں گے، اسے شکست نہیں دیں گے، اور یہ کسی فاتح کو چننے سے کہیں کم پرجوش محسوس ہوتا ہے۔</p>\n</li>\n</ul>\n<h3 id=\"the-sip-habit\">SIP عادت</h3>\n<p>تمام سرمایہ کاری میں سب سے زیادہ ابتدائی دوستانہ عادت ہے۔ <strong>SIP، سیسٹیمیٹک انویسٹمنٹ پلان۔</strong> آپ ایک مقررہ رقم، 1,000 روپے یا 5,000 روپے ہر ماہ خود بخود ایک فنڈ میں سرمایہ کاری کرتے ہیں۔ تین خاموش سپر پاور اس کے ساتھ آتے ہیں:</p>\n<ul>\n<li><strong>آٹو پائلٹ پر نظم و ضبط</strong>، آپ اپنے موڈ یا دن کی خوفناک سرخی سے قطع نظر ہر ماہ سرمایہ کاری کرتے ہیں۔</li>\n<li><strong>روپے کی لاگت کا اوسط</strong>، قیمتیں کم ہونے پر ایک ہی مقررہ رقم زیادہ یونٹ خریدتی ہے اور زیادہ ہونے پر کم، وقت کے ساتھ ساتھ آپ کی اوسط قیمت خرید کو ہموار کرتی ہے۔</li>\n<li><strong>آپ چھوٹی شروعات کر سکتے ہیں۔</strong>، بہت سے SIPs صرف 500 روپے ماہانہ سے شروع ہوتے ہیں، لہذا انتظار کرنے کا کوئی بہانہ نہیں ہے۔</li>\n</ul>\n<p>یہ ایک فریج خیال نہیں ہے. 2025 کے آخر تک، ہندوستانی ایک ریکارڈ ڈال رہے تھے۔ <strong>31,000 کروڑ روپے ماہانہ</strong> (تقریباً) SIPs کے ذریعے میوچل فنڈز میں، تقریباً <strong>10 کروڑ</strong> SIP اکاؤنٹس، مستحکم گھریلو لہر جس سے ہم میکرو باب میں ملے۔</p>\n<table>\n<thead>\n<tr>\n<th></th>\n<th>براہ راست اسٹاک</th>\n<th>انڈیکس فنڈ SIP</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>جو آپ کے مالک ہیں۔</td>\n<td>مخصوص کمپنیاں جنہیں آپ چنتے ہیں۔</td>\n<td>پورے انڈیکس کا ایک ٹکڑا</td>\n</tr>\n<tr>\n<td>تنوع</td>\n<td>آپ کو اسے خود بنانا ہوگا۔</td>\n<td>فوری، ایک خریداری میں</td>\n</tr>\n<tr>\n<td>کوشش</td>\n<td>اعلی، ہر اسٹاک پر تحقیق کریں۔</td>\n<td>کم، خودکار ماہانہ</td>\n</tr>\n<tr>\n<td>خطرہ</td>\n<td>مرتکز، اعلیٰ</td>\n<td>بہت سارے اسٹاک میں پھیل گیا۔</td>\n</tr>\n<tr>\n<td>کے لیے بہترین</td>\n<td>ایک فعال کردار، ایک بار جب آپ سیکھ چکے ہیں۔</td>\n<td>تقریباً ہر ابتدائی، ہینڈ آف</td>\n</tr>\n</tbody></table>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>زیادہ تر ابتدائیوں کے لیے، سب سے عقلمند آغاز ایک چھوٹا، خودکار ہے۔ <strong>انڈیکس فنڈ SIP</strong>, فوری تنوع، تقریباً کوئی کوشش نہیں، بہت کم قیمت، اور پھر کچھ اضافہ کرنا <strong>براہ راست اسٹاک</strong> آہستہ آہستہ، جیسے جیسے آپ کا علم اور اعتماد بڑھتا ہے۔ دونوں راستے شراکت دار ہیں، حریف نہیں۔</p>\n</div></div>\n<h2 id=\"form-your-own-point-of-view-first\">پہلے اپنا نقطہ نظر بنائیں</h2>\n<p>اس سے پہلے کہ آپ خریدیں۔ <em>کوئی بھی</em> انفرادی اسٹاک، آپ کو اپنے سادہ الفاظ میں، تین چیزوں کی وضاحت کرنے کے قابل ہونا چاہئے:</p>\n<ul>\n<li>کاروبار اصل میں کیا کرتا ہے، اور یہ کیسے پیسہ کماتا ہے۔</li>\n<li>آپ کیوں یقین رکھتے ہیں کہ یہ پانچ سے دس سالوں میں بڑا یا زیادہ منافع بخش ہو جائے گا.</li>\n<li>اس کہانی میں کیا غلط ہو سکتا ہے۔</li>\n</ul>\n<p>اگر آپ خود \"کیوں\" کی وضاحت نہیں کر سکتے ہیں، تو آپ سرمایہ کاری نہیں کر رہے ہیں، آپ ایک ٹپ پر جوا کھیل رہے ہیں۔ پہلے کے ابواب میں موجود ہر چیز (اسٹاک کو کیا حرکت دیتا ہے، میکرو قوتیں، آمدنی کیسے کام کرتی ہے) آپ کی تشکیل میں مدد کرنے کے لیے موجود تھی۔ <em>آپ کا اپنا</em> کسی اجنبی سے ادھار لینے کے بجائے دیکھیں۔</p>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>کبھی بھی اسٹاک نہ خریدیں صرف اس وجہ سے کہ کسی نے آپ کو، ایک WhatsApp گروپ، ایک چمکدار سوشل میڈیا \"ٹپ\"، TV پر ایک پر اعتماد آواز سے کہا ہے۔ ادھار کی یقین دہانی قیمت میں کمی کے فوری طور پر گر جاتی ہے، اور یہ اس وقت ہوتا ہے جب ابتدائی گھبراہٹ میں فروخت کرتے ہیں۔ ہم بعد کے ایک باب میں ان جال اور سراسر گھوٹالوں کی کھوج کریں گے۔ (انڈیکس فنڈز قابل احترام استثناء ہیں: آپ کو کسی ایک کمپنی کے بارے میں نظریہ کی ضرورت نہیں ہے، جو اس بات کا حصہ ہے کہ وہ ابتدائی افراد کے لیے اتنے اچھے کیوں ہیں۔)</p>\n</div></div>\n<h2 id=\"a-sensible-beginner-roadmap\">ایک سمجھدار ابتدائی روڈ میپ</h2>\n<p>یہاں کارروائیوں کا ایک پرسکون ترتیب ہے، بورنگ ترتیب جو خاموشی سے کام کرتی ہے:</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch16-saver-to-investor.png\" alt=\"سیور سے سرمایہ کار تک کا راستہ، ایمرجنسی فنڈ، پھر اکاؤنٹ کھولیں اور KYC کو ختم کریں، ایک چھوٹا SIP کو خودکار بنائیں، سیکھتے رہیں، اور صرف بعد میں براہ راست اسٹاک شامل کریں۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">فلو چارٹ</span>سیور سے سرمایہ کار تک کا راستہ، ایمرجنسی فنڈ، پھر اکاؤنٹ کھولیں اور KYC کو ختم کریں، ایک چھوٹا SIP کو خودکار بنائیں، سیکھتے رہیں، اور بعد میں براہ راست اسٹاک شامل کریں۔</figcaption></figure>\n<ol>\n<li><strong>پہلے ایمرجنسی فنڈ بنائیں</strong>, ایک محفوظ، مائع جگہ میں تین سے چھ ماہ کے اخراجات، لہذا آپ کو بحران کے دوران سرمایہ کاری کبھی نہیں بیچنی پڑے گی۔</li>\n<li><strong>مہنگا قرض صاف کریں۔</strong>، کریڈٹ کارڈ بیلنس اور مہنگے ذاتی قرضوں کی قیمت اس سے کہیں زیادہ ہے جس کی واپسی کا امکان مارکیٹوں سے ہے۔</li>\n<li><strong>اپنا ڈیمیٹ اور ٹریڈنگ اکاؤنٹ کھولیں۔</strong> اور ختم KYC۔</li>\n<li><strong>ایک چھوٹا، خودکار SIP شروع کریں۔</strong> ایک وسیع انڈیکس فنڈ میں، یہاں تک کہ 500 سے 1000 روپے ماہانہ۔ واپسی کا پیچھا کرنے سے پہلے عادت بنائیں۔</li>\n<li><strong>سیکھتے رہیں</strong>ان کمپنیوں کے نتائج پڑھیں جو آپ کو دلچسپ لگتی ہیں، میکرو موڈ کی پیروی کریں، سمجھیں کہ آپ کیا مالک ہیں۔</li>\n<li><strong>آہستہ آہستہ براہ راست اسٹاک شامل کریں</strong>، صرف پیسے کے ساتھ آپ کھونے کے متحمل ہوسکتے ہیں، صرف ایک بار آپ اپنا نظریہ بنا سکتے ہیں، اور صرف ایک چھوٹے سے ٹکڑے کے ساتھ۔</li>\n<li><strong>مستقل اور صبر سے رہیں</strong>، پھر کمپاؤنڈنگ، پہلے ہی باب سے سبق، سالوں کے دوران بھاری لفٹنگ کرتے ہیں۔</li>\n</ol>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>آپ کا پہلا مقصد ہے۔ <em>نہیں</em> واپسی، یہ عادت بنا رہی ہے اور بہت کم داؤ پر لگا کر اپنا مزاج سیکھ رہی ہے۔ ایک مستحکم 1,000 روپے SIP جسے آپ کبھی نہیں روکیں گے، کئی دہائیوں کے دوران، تقریباً ہمیشہ ہی 50,000 روپے کی چالاک شرط کو ہرا دیں گے جو آپ نے ایک بار لگائی تھی اور گھبرایا ہوا تھا۔</p>\n</div></div>\n<h2 id=\"start-small-start-safe\">چھوٹی شروعات کریں، محفوظ آغاز کریں۔</h2>\n<p>آپ کو شروع کرنے کے لیے موٹے بینک بیلنس یا کامل علم کی ضرورت نہیں ہے، بس ایک ایسی رقم جس کے گرنے پر کوئی نقصان نہیں پہنچے گا، اور شروع کرنے کی خواہش کی ضرورت ہے۔ ابتدائی سال ٹیوشن ہیں: آپ سیکھ رہے ہیں کہ کیسے <em>آپ</em> جب قیمتیں ڈگمگاتی ہیں تو رد عمل ظاہر کریں، کسی ایک سال کے منافع سے کہیں زیادہ قیمت۔ چھوٹا شروع کریں، بورنگ حصے کو خودکار بنائیں، پڑھتے رہیں، اور وقت کو اپنے پیسے اور اپنی سمجھ دونوں کو ملا دیں۔</p>\n\n<div class=\"callout info\"><span class=\"callout-tag\">نوٹ</span><div><p>یہاں کوئی بھی چیز کسی خاص اسٹاک، فنڈ یا پروڈکٹ کو خریدنے کی سفارش نہیں ہے، اور کوئی بھی آپ سے واپسی کا وعدہ نہیں کر سکتا۔ یہ ایک نقشہ ہے کہ سفر عام طور پر کیسے شروع ہوتا ہے۔ مخصوص انتخاب، کون سا فراہم کنندہ، کون سا فنڈ، کتنا، ایک بار جب آپ تجارتی معاہدوں کو سمجھ لیں گے تو آپ خود کریں گے۔</p>\n</div></div>\n<h2 id=\"quick-recap\">فوری خلاصہ</h2>\n<ul>\n<li>سرمایہ کاری کرنے کے لیے آپ کو ایک کی ضرورت ہے۔ <strong>ڈیمیٹ</strong> اکاؤنٹ (حصص رکھتا ہے) اور a <strong>تجارت</strong> اکاؤنٹ (آرڈر دیتا ہے)، ایک سادہ کے بعد آن لائن کھولا جاتا ہے۔ <strong>KYC</strong> PAN، آدھار اور بینک لنک کے ساتھ۔</li>\n<li>مبتدی کو دو راستوں کا سامنا کرنا پڑتا ہے: <strong>براہ راست اسٹاک</strong> (زیادہ کنٹرول، زیادہ تحقیق، زیادہ خطرہ) یا <strong>باہمی / انڈیکس فنڈز</strong> (فوری تنوع، ہینڈ آف)۔</li>\n<li>ایک <strong>انڈیکس فنڈ</strong> سستے میں نفٹی 50 جیسے انڈیکس کی عکاسی کرتا ہے۔ a <strong>SIP</strong> ایک مقررہ ماہانہ سرمایہ کاری، نظم و ضبط کی تعمیر اور آپ کی لاگت کا اوسط خودکار کرتا ہے۔</li>\n<li>کوئی ایک اسٹاک خریدنے سے پہلے، <strong>اپنا نقطہ نظر بنائیں</strong>، کاروبار اور \"کیوں\" کو سمجھیں، اور ادھار کی تجاویز پر کبھی عمل نہ کریں۔</li>\n<li>ایک سمجھدار کی پیروی کریں۔ <strong>روڈ میپ</strong>: ایمرجنسی فنڈ، مہنگا قرض صاف کریں، اکاؤنٹ کھولیں، ایک چھوٹا SIP خودکار کریں، سیکھتے رہیں، براہ راست اسٹاک آہستہ آہستہ شامل کریں۔</li>\n<li><strong>چھوٹی اور محفوظ شروعات کریں۔</strong>پہلا مقصد عادت اور سبق ہے، واپسی نہیں۔ یہ تعلیم ہے نصیحت نہیں۔</li>\n</ul>\n<p>اب آپ جانتے ہیں کہ اپنے پہلے حقیقی قدم کیسے اٹھائے جائیں۔ لیکن اچھی طرح سے سرمایہ کاری کرنے میں سب سے بڑی رکاوٹ مارکیٹ نہیں ہے، یہ ذہن ہے جو اسے دیکھتا ہے۔ اس کے بعد، ہم خطرے، نفسیات اور عام غلطیوں کی طرف رجوع کرتے ہیں جو خاموشی سے زیادہ تر سرمایہ کاروں کو شکست دیتی ہیں، اور انہیں کیسے شکست دی جائے۔</p>\n","toc":[{"level":2,"text":"پہلا مرحلہ: ڈیمیٹ اور ٹریڈنگ اکاؤنٹ","id":"step-one-the-demat-and-trading-account"},{"level":3,"text":"KYC، صاف الفاظ میں","id":"kyc-in-plain-words"},{"level":2,"text":"یہاں سے دو راستے","id":"two-paths-from-here"},{"level":3,"text":"راستہ 1: براہ راست انفرادی اسٹاک خریدیں۔","id":"path-1-buy-individual-stocks-directly"},{"level":3,"text":"راستہ 2: میوچل فنڈز اور انڈیکس فنڈز، بذریعہ SIP","id":"path-2-mutual-funds-and-index-funds-via-sip"},{"level":3,"text":"SIP عادت","id":"the-sip-habit"},{"level":2,"text":"پہلے اپنا نقطہ نظر بنائیں","id":"form-your-own-point-of-view-first"},{"level":2,"text":"ایک سمجھدار ابتدائی روڈ میپ","id":"a-sensible-beginner-roadmap"},{"level":2,"text":"چھوٹی شروعات کریں، محفوظ آغاز کریں۔","id":"start-small-start-safe"},{"level":2,"text":"فوری خلاصہ","id":"quick-recap"}],"imgCount":3,"hasContent":true},"17":{"html":"<p>آپ نے یہ پورا کورس یہ سیکھنے میں گزارا ہے کہ مارکیٹ کیسے کام کرتی ہے، حصص اور اشاریے، آئی پی او اور سیٹلمنٹ، کیا چیز قیمت کو اوپر یا نیچے کرتی ہے۔ یہاں ایک غیر آرام دہ سچائی ہے جو اس سب کو ایک ساتھ جوڑتی ہے: مشینری کو سمجھنا <em>آسان</em> آدھا مشکل نصف پریشان، امید مند، آسانی سے ڈرنے والے انسان کا انتظام کر رہا ہے جسے اپنے پیسے کے بڑھنے اور گرنے کے دوران خاموش بیٹھنا پڑتا ہے۔ دہائیوں کے اعداد و شمار اسی نتیجے کی طرف اشارہ کرتے ہیں، زیادہ تر سرمایہ کاروں کو مارکیٹ سے شکست نہیں ہوتی۔ وہ خود مارے جاتے ہیں۔</p>\n<p>یہ باب آئینے میں اس مخالف کے بارے میں ہے۔ ہم دیکھیں گے کہ خطرہ واقعی کیا ہے، اپنے دائو کو کس طرح سائز کرنا ہے تاکہ کوئی ایک غلطی آپ کو ختم نہ کر سکے، اور مٹھی بھر ذہنی جال جو خاموشی سے ہوشیار، نیک نیت لوگوں سے واپس آتے ہیں۔ اس میں سے کسی کو بھی فنانس ڈگری کی ضرورت نہیں ہے۔ اس کے لیے ایمانداری کی ضرورت ہے کہ دباؤ میں آپ کا اپنا دماغ کیسے کام کرتا ہے۔</p>\n<h2 id=\"risk-and-reward-there-is-no-free-lunch\">خطرہ اور انعام: کوئی مفت لنچ نہیں ہے۔</h2>\n<p>ہر سرمایہ کاری دو چیزوں کے درمیان تجارت ہے: یہ کتنا بڑھ سکتا ہے، اور راستے میں کتنا گر سکتا ہے۔ یہ دونوں کولہے پر جڑے ہوئے ہیں۔ زیادہ واپسی کا امکان <em>ہمیشہ</em> ایک مشکل سواری یا نقصان کے زیادہ امکانات کے ساتھ بنڈل آتا ہے۔ کوئی بھی چیز جو بغیر کسی خطرے کے بڑے انعامات پیش کرتی نظر آتی ہے یا تو غلط سمجھا جاتا ہے یا جھوٹ، عام طور پر دوسرا۔</p>\n<ul>\n<li>ایک بینک فکسڈ ڈپازٹ بمشکل حرکت کرتا ہے۔ کم خطرہ، کم اجر۔</li>\n<li>ایک بڑی، قائم شدہ کمپنی کے حصص ہلتے ہیں۔ درمیانہ خطرہ، درمیانی انعام۔</li>\n<li>ایک چھوٹی سی نامعلوم چھوٹی ٹوپی ایک مہینے میں دوگنی یا آدھی ہو سکتی ہے۔ زیادہ خطرہ، اعلیٰ انعام۔</li>\n</ul>\n<p>یہ اس نظام میں کوئی خامی نہیں ہے کہ جس کو اوٹ سمارٹ کیا جائے۔ یہ نظام ہے. مہارت خطرے سے پاک دولت نہیں ڈھونڈ رہی ہے، وہ موجود نہیں ہے۔ مہارت فیصلہ کر رہی ہے۔ <em>کتنا</em> خطرہ آپ کے مقاصد، آپ کی ٹائم لائن، اور آپ رات کو کتنی اچھی طرح سوتے ہیں۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p>\"خطرہ\" \"نقصان\" جیسا نہیں ہے۔ خطرہ غیر یقینی صورتحال ہے، چیزوں کی حد جو ہو سکتی ہے۔ ایک اسٹاک جو جنگلی طور پر جھولتا ہے لیکن آپ بیس سال تک پکڑے ہوئے ہیں وہ دور ہوسکتا ہے۔ <em>کم</em> نقد جو خاموشی سے مہنگائی سے محروم ہو جاتا ہے اس سے زیادہ آپ کے اصل مقصد کے لیے خطرناک ہے۔ خطرے کا مقابلہ آپ کے پاس موجود وقت سے کریں، آج کے موڈ سے نہیں۔</p>\n</div></div>\n<h2 id=\"don-t-bet-the-farm-position-sizing-and-diversification\">فارم پر شرط نہ لگائیں: پوزیشن کا سائز اور تنوع</h2>\n<p>یہاں ایک سب سے مہنگی ابتدائی غلطی ہے: اپنے پیسے کا ایک بہت بڑا حصہ ایک \"یقینی چیز\" میں ڈالنا۔ یہ یقین کی طرح محسوس ہوتا ہے۔ یہ دراصل آپ کے مستقبل کے ساتھ ایک سکہ پلٹنا ہے۔ فکس کا ایک پرانا نام ہے، <strong>اپنے تمام انڈے ایک ٹوکری میں نہ ڈالیں۔</strong>، اور ایک قدرے زیادہ بالغ: <strong>پوزیشن کا سائز</strong> اور <strong>تنوع</strong>.</p>\n<p>پوزیشن کے سائز کا مطلب ہے کہ پہلے سے یہ فیصلہ کرنا کہ آپ کی کل رقم میں سے کسی ایک اسٹاک کو کتنی رقم کی اجازت ہے۔ اگر ایک کمپنی خراب نتیجہ پر 50 فیصد ڈوب سکتی ہے، اور اچھی کمپنیاں بعض اوقات ایسا کرتی ہیں، تو اسے اپنے پورٹ فولیو کا 5 فیصد رکھنے کا مطلب ہے <em>پوری</em> دولت میں صرف 2.5 فیصد کمی آئی۔ پریشان کن، زندہ رہنے کے قابل۔ اسی اسٹاک میں 80% ڈالیں اور وہی برا دن ایک تباہی بن جاتا ہے جس سے آپ کبھی بھی باز نہیں آسکتے ہیں۔</p>\n<p>تنوع ایک ہی نظریہ ہے جو وسیع تر پھیلا ہوا ہے: مختلف صنعتوں میں بہت سارے اسٹاک کے مالک ہوں، تاکہ کوئی ایک کمپنی، سیکٹر، یا بری خبر کا ٹکڑا آپ کو ڈبو نہ سکے۔ جب آپ ایک وسیع انڈیکس فنڈ کے مالک ہوتے ہیں، تو آپ کو یہ تقریباً مفت میں ملتا ہے، Nifty 50 آپ کے پیسے کو ایک درجن صنعتوں میں پچاس بڑی کمپنیوں میں ایک ساتھ پھیلا دیتا ہے۔</p>\n\n<div class=\"callout tip\"><span class=\"callout-tag\">ٹپ</span><div><p>انگوٹھے کا ایک سادہ ابتدائی اصول: آپ کے پورٹ فولیو کے بہت بڑے حصے کے طور پر کوئی ایک اسٹاک نہیں، اور آئندہ تین سے پانچ سالوں میں آپ کو درکار رقم کی کبھی بھی سرمایہ کاری نہ کریں۔ مارکیٹیں چند سال تک نیچے رہ سکتی ہیں، اور آپ نہیں بننا چاہتے <em>مجبور</em> نیچے بیچنے والا کیونکہ کرایہ واجب الادا ہے۔</p>\n</div></div>\n<h2 id=\"the-enemy-in-the-mirror\">آئینے میں دشمن</h2>\n<p>اب اس باب کا اصل موضوع۔ آپ کا دماغ ایک آباؤ اجداد کو سوانا پر زندہ رکھنے، ریوڑ کے ساتھ بھاگنے، نقصان سے ڈرنے، خوف پر تیزی سے کام کرنے کے لیے بنایا گیا تھا۔ وہ جبلتیں سرمایہ کاری کے لیے تباہ کن ہیں، جہاں جیتنے کا اقدام عام طور پر ہوتا ہے۔ <em>کچھ نہ کرو</em> جب کہ آپ کے آس پاس ہر کوئی گھبراتا ہے یا جشن مناتا ہے۔ بازاروں کی یہاں تک کہ ایک مشہور جذباتی شکل ہوتی ہے، جو ہر تیزی اور ٹوٹ پھوٹ میں دہرائی جاتی ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch17-emotion-cycle.png\" alt=\"مارکیٹ سائیکل کی نفسیات، رجائیت سب سے اوپر (زیادہ سے زیادہ مالی خطرے کا نقطہ)، پھر خوف اور گھبراہٹ کے ذریعے مایوسی کی طرف پھسل جاتی ہے (زیادہ سے زیادہ موقع کا نقطہ)\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">انفوگرافک</span>مارکیٹ سائیکل کی نفسیات، رجائیت سب سے اوپر (زیادہ سے زیادہ مالی خطرے کا نقطہ)، پھر خوف اور گھبراہٹ کے ذریعے مایوسی کی طرف پھسل جاتی ہے (زیادہ سے زیادہ موقع کا نقطہ)</figcaption></figure>\n<p>اس وکر کو دیکھو۔ وہ نقطہ جہاں ہر کوئی محسوس کرتا ہے۔ <em>زیادہ تر</em> پراعتماد، خوشی، عروج کے قریب، سب سے بڑے خطرے کا لمحہ ہے۔ وہ مقام جہاں ہر کوئی بیمار اور ناامید، مایوسی، نیچے کے قریب محسوس کرتا ہے، وہ جگہ ہے جہاں بہترین طویل مدتی سودے بازی ہوتی ہے۔ ہمارے احساسات تقریباً کامل ہیں۔ <em>معکوس</em> سگنل یہ سمجھنا آدھی جنگ ہے۔ ذیل میں نامزد ٹریپس وہ مخصوص طریقے ہیں جو آپ کو احساس دلاتے ہیں۔</p>\n<h3 id=\"fomo-and-the-herd\">FOMO اور ریوڑ</h3>\n<p>جب کوئی اسٹاک پہلے ہی 200 فیصد بڑھ چکا ہے اور آپ کا پڑوسی، آپ کا حجام، اور تین ٹیلیگرام گروپس سب اس کے بارے میں بات کر رہے ہیں، تو کودنے کا زور بہت زیادہ ہے۔ وہ ہے <strong>غائب ہونے کا خوف</strong>اور یہ کام پر ریوڑ کا رویہ ہے، ہم اپنے آپ کو محفوظ محسوس کرتے ہیں جو بھیڑ کر رہی ہے۔ ظالمانہ مذاق یہ ہے کہ جب تک کچھ ہوتا ہے۔ <em>ظاہر ہے</em> کام کر رہے ہیں اور ہر کوئی اس میں ہے، زیادہ تر فائدہ ہو چکا ہے، اور آپ سمارٹ پیسے سے خرید رہے ہیں جو خاموشی سے آپ کو فروخت کر رہا ہے۔</p>\n<h3 id=\"loss-aversion-watering-weeds-cutting-flowers\">نقصان سے بچنا: ماتمی لباس کو پانی دینا، پھول کاٹنا</h3>\n<p>ماہرین نفسیات نے دکھایا ہے کہ پیسے کھونے کا درد موٹا ہوتا ہے۔ <em>دو بار</em> اتنی ہی شدید جتنی اتنی ہی رقم حاصل کرنے کی خوشی۔ یہ واحد نرالا ایک عام غلطی کا سبب بنتا ہے: سرمایہ کار اپنے ہارنے والوں کو بہت زیادہ دیر تک روکے رکھتے ہیں (\"میں بیچوں گا جب یہ میری ادا کردہ رقم پر واپس آجائے گا\") اور اپنے جیتنے والوں کو بہت جلد بیچ دیں (\"مجھے اس چھوٹے منافع کو ختم ہونے سے پہلے بند کرنے دیں\")۔ نتیجہ ایک پورٹ فولیو ہے جہاں آپ ماتمی لباس کو پانی دیتے رہتے ہیں اور پھولوں کو بالکل پیچھے کی طرف کاٹتے رہتے ہیں۔</p>\n<h3 id=\"anchoring-the-price-you-paid-doesn-t-care-about-you\">اینکرنگ: آپ نے جو قیمت ادا کی وہ آپ کی پرواہ نہیں کرتی</h3>\n<p>آپ نے 500 روپے کا اسٹاک خریدا، اب یہ 380 روپے کا ہے۔ آپ نے فروخت کرنے سے انکار کر دیا کیونکہ آپ ہیں <em>لنگر انداز</em> اس 500 تک، یہ آپ کے دماغ میں ایک جادوئی نمبر بن گیا ہے۔ لیکن اسٹاک کو کوئی اندازہ نہیں ہے کہ آپ نے کیا ادا کیا۔ اس کا مستقبل صرف یہاں سے کاروبار پر منحصر ہے، آپ کی قیمت خرید پر نہیں۔ اپنے اندراج کی قیمت کے ساتھ فیصلوں کو جوڑنا، بجائے اس کے کہ کمپنی کی اصل قیمت کیا ہے، یہ سب سے پرسکون اور مہنگے تعصبات میں سے ایک ہے۔</p>\n<h3 id=\"overconfidence-and-recency-bias\">حد سے زیادہ اعتماد اور تازہ کاری کا تعصب</h3>\n<p>چند اچھی کالوں کے بعد، تقریباً ہر کوئی ایک باصلاحیت محسوس کرنے لگتا ہے۔ یعنی <strong>حد سے زیادہ اعتماد</strong>، اور یہ حقیقت سے پہلے آپ کو عاجز کرنے سے پہلے بڑے دائو، زیادہ تجارت اور کم احتیاط کی طرف لے جاتا ہے۔ اس کا کزن ہے۔ <strong>تجدید تعصب</strong>: یہ فرض کرنا کہ جو کچھ ہوا وہ ہوتا رہے گا۔ جب مارکیٹوں میں تین سال سے اضافہ ہوتا ہے، لوگ محسوس کرتے ہیں کہ وہ ہمیشہ رہیں گے۔ حادثے کے بعد، وہ قسم کھاتے ہیں کہ اسٹاک ایک گھوٹالہ ہیں۔ دونوں ہی دماغ ہیں جو ماضی قریب کو مستقل مستقبل کے لیے غلط سمجھتے ہیں۔</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>ایسے مطالعات جو سرمایہ کاروں کے حقیقی رویے کو ٹریک کرتے ہیں، جیسے کہ مارننگ اسٹار کی طویل عرصے سے جاری \"مائنڈ دی گیپ\" تحقیق، بار بار پتا چلا کہ اوسطاً فنڈ سرمایہ کار نمایاں طور پر کماتا ہے۔ <em>کم</em> ہر سال ان کے پاس موجود فنڈز سے، اکثر تقریباً ایک سے ڈیڑھ فیصد پوائنٹس، خالصتاً غلط لمحات پر خرید و فروخت سے۔ فنڈ نے ٹھیک کیا۔ سرمایہ کاروں نے جذبات پر تجارت کرتے ہوئے خود کو سبوتاژ کیا۔ (اعداد و شمار تخمینی ہیں اور مدت کے لحاظ سے مختلف ہوتے ہیں۔)</p>\n</div></div>\n<h2 id=\"why-most-people-who-trade-lose\">کیوں زیادہ تر لوگ جو \"تجارت\" کھوتے ہیں</h2>\n<p>یہ پورے کورس کے بنیادی پیغام سے جڑتا ہے: <strong>آپ مارکیٹ کو قابل اعتماد طریقے سے وقت نہیں دے سکتے، اور کوشش کر رہے ہیں کہ زیادہ تر لوگ کس طرح کھوتے ہیں۔</strong> جبلت یہ ہے کہ جب چیزیں خوفناک نظر آئیں تو بیچنا اور جب چیزیں دلچسپ لگتی ہیں تو خریدنا، جس کا مطلب یہ ہے کہ جذباتی وکر ظاہر کرتا ہے، اس کا مطلب ہے نیچے کے قریب بیچنا اور اوپر کے قریب خریدنا۔ ایسا کچھ بار کریں اور آپ نے بدترین ممکنہ نتیجہ نکال لیا ہے۔</p>\n<p>فعال، متواتر تاجروں کا ڈیٹا تمام ممالک میں ظالمانہ اور یکساں ہے: زیادہ تر لوگ وقت کے ساتھ پیسے کھو دیتے ہیں، خاص طور پر انٹرا ڈے اور ڈیریویٹیوز جیسی تیز مصنوعات میں، ایک بار جب آپ لاگت اور ٹیکس شمار کرتے ہیں۔ دریں اثنا، \"بورنگ\" سرمایہ کار جو ہر ماہ کم لاگت کا انڈیکس فنڈ خریدتا رہتا ہے، کریشوں کے ذریعے، تیزی کے ذریعے، شور کو نظر انداز کرتے ہوئے، عام طور پر ہوشیار ہجوم سے آگے نکل جاتا ہے۔ اس لیے نہیں کہ وہ ذہین تھے۔ کیونکہ وہ اپنے راستے سے ہٹ گئے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch17-behavioural-traps.png\" alt=\"ایک سرمایہ کار کے راستے پر لیبل والے نقصانات کے طور پر کھینچے گئے اہم رویے کے جال، FOMO، نقصان سے بچنا، اینکرنگ، حد سے زیادہ اعتماد اور رجعت پسندی، ہر ایک ایسی جگہ ہے جہاں جذبات خاموشی سے منصوبہ کو زیر کر دیتے ہیں۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>ایک سرمایہ کار کے راستے پر لیبل والے نقصانات کے طور پر کھینچے جانے والے اہم رویے کے جال، FOMO، نقصان سے بچنا، اینکرنگ، حد سے زیادہ اعتماد اور رجعت پسندی، ہر ایک ایسی جگہ ہے جہاں جذبات خاموشی سے منصوبے کو اوور رائیڈ کر دیتے ہیں۔</figcaption></figure>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>خاص طور پر کسی بڑی جیت یا بڑی ہار کے فوراً بعد اپنے آپ سے ہوشیار رہیں۔ جیتنے کے بعد آپ ناقابل تسخیر محسوس کریں گے اور ایک لاپرواہ شرط لگائیں گے۔ ہارنے کے بعد آپ مایوسی محسوس کریں گے اور تیزی سے \"واپس جیتنے\" کی کوشش کریں گے۔ دونوں ریاستیں ایسی ہوتی ہیں جب لوگ کھاتوں کو اڑا دیتے ہیں۔ ان لمحات میں سب سے مضبوط اقدام ایپ کو بند کرنا اور ایک دن کے لیے کچھ نہیں کرنا ہے۔</p>\n</div></div>\n<h2 id=\"habits-that-beat-your-own-brain\">عادات جو آپ کے اپنے دماغ کو شکست دیتی ہیں۔</h2>\n<p>آپ ان جبلتوں کو حذف نہیں کر سکتے، یہ فیکٹری میں نصب ہیں۔ لیکن آپ ایسے نظام بنا سکتے ہیں جو انہیں آپ کے لیے آپ کے فیصلے کرنے سے روکیں۔</p>\n<ul>\n<li><strong>اسے خودکار بنائیں۔</strong> ایک خودکار ماہانہ سرمایہ کاری (ایک SIP) مرتب کریں۔ جب خریداری آٹو پائلٹ پر ہوتی ہے، FOMO اور خوف کو کبھی ووٹ نہیں ملتا ہے۔</li>\n<li><strong>اپنا منصوبہ لکھیں۔</strong>آپ کے پاس کیا ہے، کیوں، اور اصل میں آپ کو کیا بیچے گا۔ جب جذبات متاثر ہوں تو ردعمل ظاہر کرنے کے بجائے اسے دوبارہ پڑھیں۔</li>\n<li><strong>اپنے پورٹ فولیو کو کم چیک کریں۔</strong> روزانہ دیکھنے سے معمول کی جھریاں تناؤ میں بدل جاتی ہیں اور آپ کو ٹنکر پر آمادہ کرتی ہے۔ ماہانہ یا سہ ماہی کافی ہے۔</li>\n<li><strong>پہلے سے قواعد طے کریں،</strong> پرسکون لمحات میں، آپ کی پوزیشن کے سائز کی حد، آپ کتنی رقم رکھتے ہیں، حادثے میں آپ کیسا برتاؤ کریں گے۔ پرسکون - آپ کو گھبراہٹ پر حکومت کرنا چاہئے۔</li>\n<li><strong>کریشوں کی توقع کریں۔</strong> مارکیٹیں ہر بار 30-50% گرتی ہیں، یہ معمول کی بات ہے، آخر نہیں۔ سرمایہ کار جو <em>توقع</em> یہ پرسکون رہے؛ اس سے چونکنے والے بدترین وقت پر فروخت ہوتے ہیں۔</li>\n</ul>\n\n<div class=\"callout example\"><span class=\"callout-tag\">حقیقی مثال</span><div><p>دو دوست تیزی سے 35% مارکیٹ کریش کے ذریعے سرمایہ کاری کر رہے ہیں۔ انجلی خوف زدہ ہو کر خبریں دیکھتی ہے، \"خون بہنے کو روکنے\" کے لیے نیچے کی ہر چیز بیچ دیتی ہے، پھر انتظار کرتی ہے، واپس خریدنے کے لیے بہت گھبراتی ہے، اور زیادہ تر صحت یابی سے محروم رہتی ہے۔ وکرم کچھ نہیں کرتا۔ اس کا خودکار SIP یہاں تک کہ سستے یونٹ خریدتا رہتا ہے۔ دو سال بعد انڈیکس مکمل طور پر ٹھیک ہو گیا ہے اور اوپر چلا گیا ہے۔ وہی بازار، وہی کریش۔ انجلی ایک مستقل نقصان میں بند; وکرم آگے نکل آیا۔ فرق صرف رویے کا تھا۔</p>\n</div></div>\n<h2 id=\"quick-recap\">فوری خلاصہ</h2>\n<ul>\n<li><strong>اعلی انعام ہمیشہ زیادہ خطرے کے ساتھ سوار ہوتا ہے۔</strong>, بغیر کسی خطرے کے بڑی واپسی کا وعدہ کرنے والی کوئی بھی چیز غلط فہمی یا جھوٹ ہے۔</li>\n<li><strong>اپنی پوزیشنوں کو سائز دیں اور متنوع بنائیں</strong> لہذا کوئی ایک اسٹاک یا شعبہ آپ کو ختم نہیں کر سکتا۔ ایک وسیع انڈیکس فنڈ تقریباً مفت میں متنوع ہوتا ہے۔</li>\n<li><strong>مارکیٹیں جذباتی چکر میں چلتی ہیں۔</strong>, چوٹی جوش سب سے زیادہ خطرہ ہے، گہری مایوسی زیادہ سے زیادہ موقع ہے؛ آپ کے احساسات ایک الٹا سگنل ہیں۔</li>\n<li><strong>بڑے جال</strong>، FOMO اور ریوڑ، نقصان سے بچنا، اینکرنگ، حد سے زیادہ اعتماد، رجعت پسندی، خاموشی سے ہوشیار لوگوں کو غریب سرمایہ کاروں میں بدل دیتے ہیں۔</li>\n<li><strong>آپ بازار کا وقت نہیں لگا سکتے۔</strong> گھبراہٹ بیچنا اور لالچ خریدنا ہے کہ کس طرح زیادہ تر لوگ ہار جاتے ہیں، جبکہ مستحکم، بورنگ، خودکار سرمایہ کار عام طور پر جیت جاتا ہے۔</li>\n<li><strong>سسٹمز بنائیں</strong>خودکار بنائیں، منصوبہ لکھیں، کم چیک کریں، پرسکون ہونے پر اصول طے کریں، تاکہ آپ کے اپنے دماغ کو فیصلے کرنے سے روکا جا سکے۔</li>\n</ul>\n<p>پیسہ کھونے کا ایک اور طریقہ ہے جس کا آپ کی نفسیات سے کوئی لینا دینا نہیں ہے اور ہر چیز کا کسی اور کے لالچ سے کوئی لینا دینا نہیں، سراسر دھوکہ۔ آخری باب میں ہم ہندوستان کے سب سے زیادہ بدنام زمانہ دھوکہ دہی سے ملتے ہیں، وہ سرخ جھنڈے جو وہ سب بانٹتے ہیں، اور یہ یقینی بنانے کے طریقے سے کہ آپ کبھی بھی شکار نہ ہوں۔</p>\n","toc":[{"level":2,"text":"خطرہ اور انعام: کوئی مفت لنچ نہیں ہے۔","id":"risk-and-reward-there-is-no-free-lunch"},{"level":2,"text":"فارم پر شرط نہ لگائیں: پوزیشن کا سائز اور تنوع","id":"don-t-bet-the-farm-position-sizing-and-diversification"},{"level":2,"text":"آئینے میں دشمن","id":"the-enemy-in-the-mirror"},{"level":3,"text":"FOMO اور ریوڑ","id":"fomo-and-the-herd"},{"level":3,"text":"نقصان سے بچنا: ماتمی لباس کو پانی دینا، پھول کاٹنا","id":"loss-aversion-watering-weeds-cutting-flowers"},{"level":3,"text":"اینکرنگ: آپ نے جو قیمت ادا کی وہ آپ کی پرواہ نہیں کرتی","id":"anchoring-the-price-you-paid-doesn-t-care-about-you"},{"level":3,"text":"حد سے زیادہ اعتماد اور تازہ کاری کا تعصب","id":"overconfidence-and-recency-bias"},{"level":2,"text":"کیوں زیادہ تر لوگ جو \"تجارت\" کھوتے ہیں","id":"why-most-people-who-trade-lose"},{"level":2,"text":"عادات جو آپ کے اپنے دماغ کو شکست دیتی ہیں۔","id":"habits-that-beat-your-own-brain"},{"level":2,"text":"فوری خلاصہ","id":"quick-recap"}],"imgCount":2,"hasContent":true},"18":{"html":"<p>جہاں پیسہ ہوتا ہے وہاں لوگ آپ سے چالاکی سے چھیننے کی کوشش کرتے ہیں۔ اسٹاک مارکیٹ، اعتماد اور اسکرین پر ہاتھ بدلنے والے پیسے کے سمندر نے ہمیشہ شاندار، دلکش بدمعاشوں کو اپنی طرف متوجہ کیا ہے۔ اچھی خبر یہ ہے کہ تقریباً ہر اسکینڈل، 1992 کے میگا فراڈ سے لے کر 2026 کے ٹیلی گرام ٹپ تک، ایک ہی مٹھی بھر چالوں پر چلتا ہے۔ کہانیاں اور نمونے ایک بار سیکھیں، اور آپ کو بے وقوف بنانا بہت مشکل ہو جائے گا۔</p>\n<p>یہ آخری باب آپ کو بڑے اور درست طریقے سے بتاتا ہے، پھر ان دھوکہ دہی کی طرف رجوع کرتا ہے جو آپ کریں گے <em>اصل میں</em> آج ہی ملیں، واٹس ایپ پر، یوٹیوب پر، ایک دوست کے \"گارنٹیڈ واپسی\" پلان میں۔ آخر تک آپ کے پاس ایک سادہ ریڈ فلیگ ریڈار اور ایک حفاظتی چیک لسٹ ہو گی جسے آپ اپنی باقی سرمایہ کاری کی زندگی کے لیے استعمال کر سکتے ہیں۔</p>\n<h2 id=\"the-big-bull-harshad-mehta-1992\">دی بگ بل: ہرشد مہتا (1992)</h2>\n<p>1990 کی دہائی کے اوائل میں، ممبئی کے ایک اسٹاک بروکر جس کا نام ہرشد مہتا تھا، ایک گھریلو نام بن گیا، چمکدار \"بگ بُل\" جو بازار کو رقص کرنے لگتا تھا۔ اس کا راز اسٹاک چننے والا ذہین نہیں تھا۔ یہ بینکنگ پلمبنگ میں ایک سوراخ تھا۔</p>\n<p>بینکوں نے ایک دوسرے کو سرکاری بانڈز کے خلاف قلیل مدتی رقم ادھار دی، کاغذی پرچیوں کا استعمال کیا۔ <strong>بینک رسیدیں (BRs)</strong> IOUs کے طور پر. مہتا نے ان سودوں کے بیچ میں بیٹھ کر بینکوں کو جاری کرنے کا بندوبست کیا۔ <strong>جعلی بی آر</strong>بانڈز کی رسیدیں جو موجود ہی نہیں تھیں، اور ان کی قیمتوں کو آسمان تک پہنچاتے ہوئے، مٹھی بھر اسٹاکس میں آنے والی نقدی کو انڈیل دیا۔ ACC، سیمنٹ کمپنی، مبینہ طور پر تقریباً ایک سال میں تقریباً 200 روپے سے تقریباً 9,000 روپے تک پہنچ گئی۔ جب صحافی سچیتا دلال نے اپریل 1992 میں اس ریکیٹ کا پردہ فاش کیا تو مارکیٹ کریش کر گئی اور بعد میں ایک سرکاری کمیٹی نے اس بے قاعدگی کے پیمانے کا اندازہ لگایا۔ <strong>4،000 کروڑ روپے</strong>، پھر ایک حیران کن رقم۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch18-harshad-mehta-mechanism.png\" alt=\"1992 کا بینک رسید اسکینڈل کس طرح کام کرتا تھا، جعلی بینک رسیدیں بینکوں سے بروکر تک پیسہ بہا دیتی ہیں، جنہوں نے اسے اپنی قیمتوں میں اضافے کے لیے چند اسٹاک میں ڈالا، یہاں تک کہ اس کے سامنے آنے سے مارکیٹ میں کریش نہیں ہوا۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">خاکہ</span>1992 کا بینک رسید اسکینڈل کس طرح کام کرتا تھا، جعلی بینک رسیدیں بینکوں سے بروکر تک پیسہ بہا دیتی ہیں، جنہوں نے اسے اپنی قیمتوں میں اضافے کے لیے چند اسٹاک میں ڈالا، یہاں تک کہ اس کے سامنے آنے سے مارکیٹ میں کریش نہیں ہوا۔</figcaption></figure>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>اپنے عروج پر، ہرشد مہتا تقریباً 15,000 مربع فٹ سمندر کی طرف ایک منی گولف کورس کے ساتھ ورلی پینٹ ہاؤس میں رہتے تھے، امپورٹڈ لگژری کاریں چلاتے تھے، اور اپنی شبیہ کو جلانے کے لیے ایک بار کروڑوں کا ایڈوانس ٹیکس ادا کرتے تھے۔ یہ لائف اسٹائل تھا، جتنا کہ حصص کی قیمتیں، جس نے عام سرمایہ کاروں کو یہ یقین دلایا کہ اس کے پاس جادوئی لمس ہے۔</p>\n</div></div>\n<p>دیرپا اچھی خبر یہ ہے کہ اسکینڈل کیا ہے۔ <em>تعمیر</em>. اس نے اپنی مارکیٹ کو ایک حقیقی پولیس فورس دینے پر ہندوستان کو چونکا دیا: <strong>SEBI کو 1992 میں قانونی دانت دیا گیا تھا۔</strong>, the <strong>نیشنل اسٹاک ایکسچینج (NSE)</strong> مکمل طور پر الیکٹرانک، شفاف سکرین پر مبنی ٹریڈنگ، اور کے ساتھ جلد ہی شروع کیا گیا تھا۔ <strong>ڈی میٹریلائزیشن</strong> بعد میں حصص کو جعلی کاغذوں سے نکال کر محفوظ الیکٹرانک کھاتوں میں منتقل کر دیا۔ آج آپ جن تحفظات پر انحصار کرتے ہیں وہ بڑی حد تک اس اسکینڈل کی وجہ سے موجود ہیں۔</p>\n<h2 id=\"the-pentafour-bull-ketan-parekh-early-2000s\">پینٹافور بل: کیتن پاریکھ (2000 کی دہائی کے اوائل)</h2>\n<p>ایک دہائی کے بعد، تاریخ کی شاعری. اسٹاک بروکر کیتن پاریکھ، جو کبھی مہتا کے حلقے کے قریب تھا، اسٹاک کا ایک سیٹ چلاتا تھا جسے مارکیٹ کا عرفی نام دیا جاتا تھا۔ <strong>\"K-10\"</strong> (نام جیسے Zee Telefilms, HFCL اور دیگر)۔ اس کا آلہ تھا۔ <strong>سرکلر ٹریڈنگ</strong>: مربوط اداروں کی ایک انگوٹھی جو آپس میں ایک ہی حصص کو تیار کرنے کے لیے خریدتی اور بیچتی ہے۔ <em>وہم</em> بہت زیادہ مانگ، قیمتوں کو مضحکہ خیز بلندیوں تک لے جانا اور حقیقی سرمایہ کاروں کو کھینچنا جن سے محروم ہونے کا خدشہ ہے۔</p>\n<p>ایندھن، پھر، بینک کے پیسے کا غلط استعمال کیا گیا، خاص طور پر مادھو پورہ مرکنٹائل کوآپریٹو بینک سے، اور گلوبل ٹرسٹ بینک سے لنکس۔ جب 2001 میں بلبلا پھٹا تو K-10 اسٹاک گر گئے، بینک تباہ ہو گئے، اور آخرکار SEBI <strong>پاریکھ کو 14 سال کے لیے بازاروں سے روک دیا۔</strong>. سبق: کوئی حقیقی خبر نہ ہونے پر قیمت میں اضافہ اکثر ایک پمپ ہوتا ہے، دریافت نہیں۔</p>\n<h2 id=\"india-s-enron-satyam-2009\">انڈیاز اینرون: ستیم (2009)</h2>\n<p>پہلے دو گھوٹالوں نے قیمتوں میں ہیرا پھیری کی۔ ستیم فراڈ گہرا تھا، بانی بس <em>ایجاد کیا</em> کمپنی کی کامیابی. جنوری 2009 میں، ستیم کمپیوٹرز کے چیئرمین راملنگا راجو نے ایک اب مشہور خط میں اعتراف کیا کہ فرم کی کتابیں افسانہ تھیں۔ اس نے سالوں سے منافع بڑھایا اور تقریباً گھڑا <strong>7,000+ کروڑ روپے</strong>کے بارے میں سمیت <strong>5,000 کروڑ روپے کی نقدی جو موجود نہیں تھی۔</strong>نقد رقم جس پر آڈیٹرز نے خوش دلی سے دستخط کیے تھے۔</p>\n\n<div class=\"callout fact\"><span class=\"callout-tag\">کیا آپ جانتے ہیں؟</span><div><p>جعلی آمدنی تیار کرنے کے لیے، ستیم نے کبھی نہیں کیے گئے کام کے لیے 7,500 سے زیادہ بوگس رسیدیں بنائیں، اور اس کے پے رول میں ایک اندازے کے مطابق 13,000 \"گھوسٹ ملازمین\" تھے، ایسے لوگ جو کبھی موجود نہیں تھے، تنخواہیں لیتے تھے جو خاموشی سے چھین لی جاتی تھیں۔ اس نے کمپنی کو ایک سنگین عرفی نام دیا: \"انڈیاز اینران۔\"</p>\n</div></div>\n<p>شیئر ہولڈرز کا تقریباً راتوں رات صفایا ہو گیا۔ لیکن ایک بار پھر نظام نے سیکھا: کارپوریٹ گورننس اور آڈیٹنگ کے قوانین کو سخت کر دیا گیا، آزاد ڈائریکٹرز اور آڈیٹرز کا کردار اور جوابدہی سخت جانچ پڑتال کی زد میں آ گئی، اور ہندوستان نے بعد میں اپنے کمپنی کے قانون میں ترمیم کی۔ خود ستیم کو کھلی نیلامی کے ذریعے بچایا گیا اور ایک اور فرم نے جذب کر لیا۔</p>\n<h2 id=\"when-the-plumbing-fails-nsel-and-karvy\">جب پلمبنگ ناکام ہوجاتی ہے: NSEL اور کاروی</h2>\n<p>دو اور حالیہ واقعات سے پتہ چلتا ہے کہ گھوٹالے صرف قیمتوں میں دھاندلی سے متعلق نہیں ہیں، بعض اوقات آپ جس ادارے پر بھروسہ کرتے ہیں وہ صرف آپ کے پیسے کا غلط استعمال کرتا ہے۔</p>\n<p>2013 میں، <strong>نیشنل اسپاٹ ایکسچینج (NSEL)</strong> اچانک ٹریڈنگ کو منجمد کر دیا، جس سے تقریباً ادائیگی کی ڈیفالٹ ظاہر ہو گئی۔ <strong>5,600 کروڑ روپے</strong>. اس نے اسپاٹ کموڈٹی ٹریڈز کے طور پر ملبوس \"جوڑی والے معاہدوں\" کی پیشکش کی تھی، قیاس کیا جاتا ہے کہ گوداموں میں سامان کی حمایت کی جاتی ہے، سوائے اس کے کہ بہت سے معاملات میں سامان بمشکل موجود تھا۔ یقین دلانے والے منافع کا پیچھا کرنے والے ہزاروں سرمایہ کار پھنسے ہوئے تھے۔</p>\n<p>2019 میں، <strong>کاروی اسٹاک بروکنگ</strong> کا غلط استعمال کرتے ہوئے پکڑا گیا۔ <strong>پاور آف اٹارنی</strong> گاہکوں نے معمول کی تجارت کے لیے دستخط کیے تھے۔ اس نے خاموشی سے اپنے کلائنٹس کے اپنے حصص کو قرض لینے کا وعدہ کیا۔ <strong>2,000 کروڑ روپے</strong> بذات خود، ایک اندازے کے مطابق 95,000 ایسے سرمایہ کاروں کو نشانہ بنایا جن کو یہ معلوم نہیں تھا کہ ان کی ہولڈنگز کولیٹرل ہیں۔ SEBI نے پھر اصولوں کو مستقل طور پر سخت کردیا تاکہ بروکرز اس طرح کلائنٹ کی سیکیورٹیز کو مزید جمع یا گروی نہ رکھ سکیں، اور آپ کے حصص اب آپ کے اپنے ڈیمیٹ اکاؤنٹ میں کہیں زیادہ محفوظ طریقے سے بیٹھے ہیں۔</p>\n<table>\n<thead>\n<tr>\n<th>اسکام</th>\n<th>سال</th>\n<th>کیا ہوا (تقریباً)</th>\n<th>کیا بدل گیا۔</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>ہرشد مہتا</td>\n<td>1992</td>\n<td>جعلی بینک رسیدوں نے ~ 4,000+ کروڑ کے اسٹاک ریمپ کو فنڈ دیا؛ مارکیٹ کریش کر گئی</td>\n<td>SEBI بااختیار؛ NSE اور الیکٹرانک ٹریڈنگ کا آغاز ہوا؛ ڈیمیٹ شروع ہوا</td>\n</tr>\n<tr>\n<td>کیتن پاریکھ</td>\n<td>2001</td>\n<td>\"K-10\" اسٹاکس کو سرکلر ٹریڈنگ کے ذریعے غلط استعمال شدہ بینک رقم پر پمپ کیا گیا۔</td>\n<td>سخت نگرانی؛ پاریکھ پر 14 سال کی پابندی</td>\n</tr>\n<tr>\n<td>ستیم</td>\n<td>2009</td>\n<td>بانی نے ~ 7,000+ کروڑ روپے منافع اور نقد کا جعلی \"انڈیا کا اینرون\"</td>\n<td>مضبوط آڈیٹنگ اور کارپوریٹ گورننس کے اصول</td>\n</tr>\n<tr>\n<td>NSEL</td>\n<td>2013</td>\n<td>~ 5,600 کروڑ روپے کی ڈیفالٹ اشیاء کے معاہدوں پر جس میں کوئی حقیقی سامان نہیں ہے۔</td>\n<td>اسپاٹ ایکسچینج کی نگرانی کی گئی</td>\n</tr>\n<tr>\n<td>کاروی</td>\n<td>2019</td>\n<td>بروکر نے رضامندی کے بغیر کلائنٹس کے حصص کے 2,000 کروڑ روپے گروی رکھے</td>\n<td>کلائنٹ کی سیکیورٹیز کی انگوٹھی پر باڑ لگی ہوئی ہے۔ عہد کے قوانین سخت</td>\n</tr>\n</tbody></table>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch18-scam-timeline.png\" alt=\"1992 میں ہرشد مہتا سے لے کر آج کے سوشل میڈیا پمپ اور ڈمپ تک ہندوستان کے سب سے بڑے بازار گھوٹالوں کی ٹائم لائن، ہر ایک کو اس کے کچے پیمانے اور اس سے شروع ہونے والی اصلاحات کے ساتھ نشان زد کیا گیا ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">انفوگرافک</span>1992 میں ہرشد مہتا سے لے کر آج کے سوشل میڈیا پمپ اور ڈمپ تک ہندوستان کے سب سے بڑے بازار گھوٹالوں کی ٹائم لائن، ہر ایک کو اس کے کچے پیمانے اور اس سے شروع ہونے والی اصلاحات کے ساتھ نشان زد کیا گیا ہے۔</figcaption></figure>\n<h2 id=\"the-new-playground-scams-you-ll-actually-meet-today\">نیا کھیل کا میدان: گھوٹالے آپ کو آج ملیں گے۔</h2>\n<p>آپ کو بینک کی جعلی رسید کے ذریعے پھنسائے جانے کا امکان نہیں ہے۔ آپ کو اپنے فون پر نشانہ بنائے جانے کا بہت امکان ہے۔ کلاسک دھوکہ دہی بڑے اور بلند ہو گئے؛ جدید آپ کے پاس ذاتی طور پر آتے ہیں، دوستانہ نظر آتے ہیں، اور آخری باب کے عین جذبات کے مطابق ہوتے ہیں۔</p>\n<h3 id=\"pump-and-dump-on-whatsapp-and-telegram\">واٹس ایپ اور ٹیلیگرام پر پمپ اینڈ ڈمپ</h3>\n<p>یہ کیتن پاریکھ کی پلے بک ہے، جسے ڈیموکریٹائز کیا گیا ہے۔ آپریٹرز خاموشی سے سستی، پتلی تجارت کی چھوٹی ٹوپی خریدتے ہیں، پھر سیلاب <strong>واٹس ایپ، ٹیلی گرام اور ایکس</strong> \"ابھی خریدیں، ہدف دوگنا\" پیغامات والے گروپس۔ چھوٹے سرمایہ کار، قیمتوں میں اضافہ، اور آپریٹرز کا ڈھیر لگا دیتے ہیں۔ <strong>ڈمپ</strong> ان کے حصص اس خرید میں شامل ہو جاتے ہیں، باقی سب کے پاس ایک اسٹاک ہو جاتا ہے جو گر جاتا ہے۔ SEBI نے بار بار کریک ڈاؤن کیا ہے: 2024-2026 کے آس پاس کے معاملات میں اس نے کروڑوں کا غیر قانونی فائدہ اٹھایا ہے، ٹیلی گرام سے چلنے والی اسکیموں جیسے درشن اورنا کیس کو جرمانہ کیا ہے، اور درجنوں اسکرپس میں دھاندلی کرنے والے آپریٹرز کو روک دیا ہے۔ اگر کسی گروپ میں کوئی اجنبی مفت دولت دے رہا ہے، تو آپ مہمان نہیں ہیں، آپ کھانا ہیں۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch18-pump-and-dump-mechanism.png\" alt=\"پمپ اینڈ ڈمپ کی اناٹومی، آپریٹرز خاموشی سے ایک سستی سمال کیپ جمع کرتے ہیں، اسے واٹس ایپ اور ٹیلی گرام پر ہائیپ کرتے ہیں، خوردہ سرمایہ کار قیمتیں بڑھاتے ہیں، پھر آپریٹرز اپنے حصص پھینک دیتے ہیں اور قیمت گر جاتی ہے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">فلو چارٹ</span>پمپ اینڈ ڈمپ کی اناٹومی، آپریٹرز خاموشی سے ایک سستی سمال کیپ جمع کرتے ہیں، اسے واٹس ایپ اور ٹیلی گرام پر ہائیپ کرتے ہیں، خوردہ سرمایہ کار قیمتیں بڑھاتے ہیں، پھر آپریٹرز اپنے حصص پھینک دیتے ہیں اور قیمت گر جاتی ہے۔</figcaption></figure>\n<h3 id=\"finfluencers-and-fake-tips\">فن فلوینسر اور جعلی \"ٹپس\"</h3>\n<p>سوشل میڈیا پراعتماد \"ماہرین\" سے بھر گیا <strong>فنونسر</strong>ادا شدہ کورسز، پریمیم ٹپ چینلز اور \"گارنٹیڈ ملٹی بیگر\" کالز کے ذریعے دولت کا وعدہ۔ زیادہ تر ہیں۔ <strong>SEBI کے ساتھ رجسٹرڈ نہیں ہے۔</strong> سرمایہ کاری کے مشورے دینے کے لیے، اور بہت سے لوگوں کو خاموشی سے ادائیگی کی جاتی ہے تاکہ وہ اس اسٹاک کو فروغ دے سکیں جسے وہ آگے بڑھاتے ہیں۔ خطرے کو پہچانتے ہوئے، <strong>SEBI نے 2024 میں قوانین کو سخت کیا۔</strong>: رجسٹرڈ بروکرز اور ایڈوائزرز کو اب غیر رجسٹرڈ فائن فلوینسر کے ساتھ منسلک ہونے سے روک دیا گیا ہے، اور حقیقی معلمین لائیو خرید /sell کالز نہیں دے سکتے ہیں۔ تعلیم ٹھیک ہے۔ ایک اجنبی آپ کو بتا رہا ہے کہ فیس کے عوض کیا خریدنا ہے، عام طور پر ایسا نہیں ہوتا ہے۔</p>\n<h3 id=\"know-your-advisers-ra-ria-and-the-fakes\">اپنے مشیروں کو جانیں: RA، RIA، اور جعلی</h3>\n<p>ہر ایک جو اسٹاک کے بارے میں بات کرتا ہے آپ کو مشورہ دینے کی اجازت نہیں ہے، اور فرق اہمیت رکھتا ہے۔ SEBI دو قسم کے حقیقی پیشہ ور کو رجسٹر کرتا ہے:</p>\n<ul>\n<li>اے <strong>تحقیقی تجزیہ کار (RA)</strong> پر رجسٹرڈ ہے۔ <em>تحقیق شائع کریں</em>، انکشافات کے ساتھ، رپورٹیں اور اسٹاکس پر خرید/فروخت/ہولڈ سفارشات۔ وہ تجزیہ کرتے ہیں اور کال کرتے ہیں؛ وہ آپ کے ذاتی پیسوں کا انتظام نہیں کرتے ہیں۔</li>\n<li>اے <strong>رجسٹرڈ انویسٹمنٹ ایڈوائزر (RIA)</strong> دینے کے لیے رجسٹرڈ ہے۔ <em>ذاتی سرمایہ کاری کا مشورہ</em> فیس کے لیے، اور اس کا پابند ہے۔ <strong>وفاداری ڈیوٹی</strong>، آپ کی دلچسپی کو پہلے رکھنے کی قانونی ذمہ داری۔ ایک حقیقی RIA ہے۔ <strong>صرف فیس</strong> اور مصنوعات کو آگے بڑھانے کے لیے چھپے ہوئے کمیشن کو جیب میں نہیں ڈالتا۔</li>\n</ul>\n<p>دونوں ایک SEBI رکھتے ہیں۔ <strong>رجسٹریشن نمبر</strong> آپ sebi.gov.in پر دیکھ سکتے ہیں۔ ایک حقیقی مشیر کا امتحان آسان ہے: <em>رجسٹرڈ، تنازعات کے بارے میں پیشگی، اور کبھی بھی ضمانت شدہ واپسی کا وعدہ نہیں کرتا۔</em></p>\n<p>اے <strong>جعلی مشورہ</strong> کیا کوئی ٹپس یا \"مشورے\" کے لیے چارج کر رہا ہے <em>بغیر</em> وہ رجسٹریشن، ٹیلی گرام \"ریسرچ\" چینل، واٹس ایپ \" SEBI-منظور شدہ\" ٹِپسٹر، ایپ جو ماہانہ 30% کی گارنٹی دیتی ہے۔ SEBI رجسٹریشن کے بغیر بامعاوضہ سرمایہ کاری کا مشورہ دینا غیر قانونی ہے، اور یہ آپریٹرز عموماً اس باب میں پمپ اور ڈمپ اور پونزی اسکیموں کے پیچھے ایک ہی ہجوم ہوتے ہیں۔ مشورہ کے لیے کسی کو ادائیگی کرنے سے پہلے، ان کا رجسٹریشن نمبر خود دیکھ لیں۔ اگر کوئی نہیں ہے تو وہ <em>ہے</em> آپ کا جواب</p>\n<h3 id=\"fake-apps-and-guaranteed-return-ponzi-schemes\">جعلی ایپس اور گارنٹیڈ ریٹرن پونزی اسکیمیں</h3>\n<p>ایک پالش ایپ آپ کی \"سرمایہ کاری\" میں ہر ہفتے 5% اضافہ دکھاتی ہے۔ ابتدائی واپسی بالکل ٹھیک کام کرتی ہے، کیونکہ ان کی ادائیگی کی جاتی ہے۔ <em>نیا</em> متاثرین کی جمع، ایک کے دستخط <strong>پونزی اسکیم</strong>. پھر ایک دن ایپ غائب ہو جاتی ہے، منتظم خاموش ہو جاتا ہے، اور پیسے ختم ہو جاتے ہیں۔ یہ اکثر کسی دوست (جسے بے وقوف بھی بنایا گیا تھا)، ڈیٹنگ ایپ کے رابطے، یا ایک ہوشیار \"پلیٹ فارم\" کے ذریعے پہنچتے ہیں جو کسی حقیقی تبادلے سے بالکل بھی جڑا نہیں ہوتا ہے۔</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch18-ponzi-mechanism.png\" alt=\"پونزی یا گارنٹیڈ ریٹرن اسکیم کیسے کام کرتی ہے، نئے سرمایہ کاروں کے ڈپازٹس کو پہلے والوں کو جعلی منافع ادا کرنے کے لیے استعمال کیا جاتا ہے، اس فریب کو برقرار رکھا جاتا ہے جب تک کہ تازہ رقم خشک نہ ہو جائے اور پوری اسکیم ختم نہ ہو جائے۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">فلو چارٹ</span>پونزی یا گارنٹیڈ ریٹرن اسکیم کیسے کام کرتی ہے، نئے سرمایہ کاروں کے ڈپازٹس کو پہلے والوں کو جعلی منافع ادا کرنے کے لیے استعمال کیا جاتا ہے، اس فریب کو برقرار رکھا جاتا ہے جب تک کہ تازہ رقم خشک نہ ہو جائے اور پوری اسکیم ختم نہ ہو جائے۔</figcaption></figure>\n<h3 id=\"dabba-trading\">ڈبہ تجارت</h3>\n<p>آخر میں، جدید چہرے کے ساتھ ایک پرانی غیر قانونی تجارت: <strong>ڈبہ (باکس) تجارت</strong>. ایک مشکوک آپریٹر آپ کو کتابوں سے \"تجارت\" کرنے دیتا ہے، کوئی حقیقی آرڈر کبھی بھی NSE یا BSE تک نہیں پہنچتا ہے۔ یہ سب اس کے پرائیویٹ لیجر میں اندراج ہے، اکثر لاپرواہی سے فائدہ اٹھانا اور \"کوئی ٹیکس نہیں، کوئی کاغذی کارروائی نہیں۔\" یہ ایک ہے <strong>مجرمانہ جرم</strong> سیکیورٹیز کنٹریکٹس (ریگولیشن) ایکٹ کے تحت، 10 سال تک کی قید یا بھاری جرمانہ۔ اور چونکہ کوئی حقیقی تجارت موجود نہیں ہے، اگر آپریٹر آپ کے پیسے لے کر غائب ہو جاتا ہے، تو آپ کے پاس ہے۔ <strong>کوئی قانونی تحفظ نہیں</strong>.</p>\n\n<figure class=\"lesson-shot\">\n<img src=\"/stocks/images/ch18-red-flags.png\" alt=\"یونیورسل ریڈ فلیگس کی ایک اسکیم اسپاٹر چیک لسٹ، گارنٹی شدہ یا فکسڈ ہائی ریٹرن، ابھی کام کرنے کا دباؤ، غیر رجسٹرڈ ایڈوائزر، غیر واضح سمال کیپس پر تجاویز، اور آپ کے OTP یا لاگ ان کے لیے درخواستیں۔\" loading=\"lazy\"/>\n<figcaption class=\"shot-cap\"><span class=\"shot-kind\">انفوگرافک</span>یونیورسل سرخ جھنڈوں کی ایک اسکیم اسپاٹر چیک لسٹ، گارنٹی شدہ یا مقررہ زیادہ منافع، ابھی کام کرنے کا دباؤ، غیر رجسٹرڈ ایڈوائزر، غیر واضح سمال کیپس پر تجاویز، اور آپ کے OTP یا لاگ ان کے لیے درخواستیں</figcaption></figure>\n<h2 id=\"the-red-flags-they-all-share\">سرخ جھنڈے وہ سب شیئر کرتے ہیں۔</h2>\n<p>دور اور ٹیکنالوجی کو ہٹا دیں، اور ان میں سے ہر ایک دھوکہ دہی ایک ہی جھنڈے لہراتا ہے۔ ایک بھی نظر آئے تو رک جاؤ۔</p>\n<ul>\n<li><strong>گارنٹیڈ، فکسڈ یا \"خطرے سے پاک\" زیادہ منافع۔</strong> حقیقی مارکیٹیں کبھی بھی واپسی کی ضمانت نہیں دیتی ہیں۔ یہ واحد سب سے بڑا بتانا ہے۔</li>\n<li><strong>عمل کرنے کا دباؤ <em>اب</em></strong>, \"آفر آج رات بند ہو رہی ہے،\" \"صرف 10 سیٹیں باقی ہیں۔\" آپ کی سوچ کو بند کرنے کی عجلت موجود ہے۔</li>\n<li><strong>غیر رجسٹرڈ مشیر یا پلیٹ فارم</strong>کوئی بھی شخص جو بغیر SEBI رجسٹریشن نمبر کے ادا شدہ اسٹاک کا مشورہ دیتا ہے۔</li>\n<li><strong>غیر واضح، غیر مائع چھوٹے کیپس پر گرم تجاویز</strong>پمپ اور ڈمپ کے لیے بہترین گولہ بارود۔</li>\n<li><strong>بہت اچھا-سچ ہونا،</strong> خفیہ \"اندرونی\" معلومات، یا ایسا نظام جو \"کھو نہیں سکتا۔\"</li>\n<li><strong>کوئی بھی جو آپ کا پاس ورڈ، OTP یا ریموٹ رسائی مانگ رہا ہے۔</strong> آپ کے اکاؤنٹ میں. کوئی بھی جائز بروکر یا ریگولیٹر کبھی نہیں کرے گا۔</li>\n</ul>\n<h2 id=\"your-protection-checklist\">آپ کی حفاظتی چیک لسٹ</h2>\n<p>آپ کو بدتمیزی کرنے کی ضرورت نہیں ہے، بس محتاط رہیں۔ چند مستقل عادتیں آپ کو تقریباً فراڈ پروف بنا دیتی ہیں۔</p>\n\n<div class=\"callout key\"><span class=\"callout-tag\">کلیدی خیال</span><div><p><strong>صرف SEBI-رجسٹرڈ بیچوانوں کے ساتھ ڈیل کریں، اور خود اس کی تصدیق کریں۔</strong> ہر جائز بروکر، مشیر اور تحقیقی تجزیہ کار کا رجسٹریشن نمبر SEBI کی آفیشل ویب سائٹ (sebi.gov.in) پر درج ہے۔ اگر آپ انہیں وہاں نہیں پا سکتے ہیں تو چلے جائیں، چاہے ان کے نتائج کتنے ہی متاثر کن کیوں نہ ہوں۔</p>\n</div></div>\n<ul>\n<li><strong>اعتماد کرنے سے پہلے تصدیق کریں۔</strong> ایک حقیقی رجسٹریشن نمبر جسے آپ SEBI سائٹ پر دیکھ سکتے ہیں منافع کے کسی بھی اسکرین شاٹ کو مات دیتا ہے۔</li>\n<li><strong>شکایت کرنے کے لیے SCORES استعمال کریں۔</strong> اگر کوئی رجسٹرڈ ادارہ آپ کو غلط کرتا ہے، تو SEBI کے آفیشل ریڈریسل پلیٹ فارم پر شکایت درج کریں، <strong>scores.sebi.gov.in</strong>، مفت اور ٹریک شدہ۔</li>\n<li><strong>\"یقینی طور پر شاٹ\" تجاویز کو نظر انداز کریں۔</strong> ہر گارنٹی شدہ کال، ہاٹ واٹس ایپ فارورڈ اور \"ڈبلنگ\" ہدف کو سیلز پچ کے طور پر سمجھیں، کیونکہ یہ ایک ہے۔</li>\n<li><strong>سوشل میڈیا ٹپس پر شک کریں۔</strong> ایک پر اعتماد ویڈیو تحقیق نہیں ہے۔ پوچھیں: کیا یہ شخص رجسٹرڈ ہے، اور اگر میں خریدتا ہوں تو اسے کیا فائدہ ہوتا ہے؟</li>\n<li><strong>اپنا لاگ ان، پاس ورڈ یا OTP کبھی بھی شیئر نہ کریں۔</strong> کسی کے ساتھ، \"بروکر\" نہیں، \"سپورٹ\" نہیں۔ OTP کا اشتراک کرنا چابیاں دے رہا ہے۔</li>\n<li><strong>ریلوں پر رہیں</strong>، حقیقی تبادلے، حقیقی ڈیمیٹ اکاؤنٹس، حقیقی معاہدے کے نوٹ۔ آف مارکیٹ شارٹ کٹ جیسے ڈبہ ٹریڈنگ میں کوئی حفاظتی جال نہیں ہے۔</li>\n</ul>\n\n<div class=\"callout warn\"><span class=\"callout-tag\">سر اپ</span><div><p>اگر پہلے ہی کچھ غلط ہو گیا ہے، جعلی ایپ پر رقم بھیجی گئی، شیئرز بغیر رضامندی کے منتقل ہو گئے، ایک ٹپ چینل جو آپ کی فیس لے کر غائب ہو گیا، تیزی سے کام کریں۔ مزید تمام ادائیگیاں روکیں، اسکرین شاٹس اور لین دین کا ریکارڈ جمع کریں، رجسٹرڈ اداروں کے لیے SCORES پر شکایت درج کریں، اور نیشنل سائبر کرائم ہیلپ لائن (1930) اور cybercrime.gov.in کے ذریعے مالی فراڈ کی اطلاع دیں۔ رفتار کے معاملات؛ منجمد فنڈز کبھی کبھی دوبارہ حاصل کیے جا سکتے ہیں۔</p>\n</div></div>\n<h2 id=\"where-to-go-from-here\">یہاں سے کہاں جانا ہے۔</h2>\n<p>آپ \"حصہ کیا ہے؟\" سے بہت طویل سفر طے کر چکے ہیں۔ ایک اقتباس کو پڑھنے کے لیے، یہ سمجھنا کہ قیمتوں کو کیا حرکت دیتا ہے، اپنے دماغ کو سنبھالنا، اور اب بھیڑیوں کو تلاش کرنا۔ یہ حقیقی طور پر ایک پراعتماد، خود انحصار سرمایہ کار کو درکار ہے۔ بازار کوئی کیسینو نہیں ہے اور یہ کوئی سازش نہیں ہے۔ یہ مریض کی بچت کو حقیقی دولت میں تبدیل کرنے کے لیے ایک طاقتور، زیادہ تر منصفانہ مشین ہے، ایک بار جب آپ جان لیں کہ یہ کیسے کام کرتی ہے اور کس پر بھروسہ کرنا ہے۔</p>\n<p>تو آہستہ سے چلتے رہیں۔ چھوٹی شروعات کریں، اپنی سرمایہ کاری کو خودکار بنائیں، متنوع رہیں، شور کو نظر انداز کریں، اور وقت اور کمپاؤنڈنگ کو بھاری لفٹنگ کرنے دیں جو وہ بہت اچھے طریقے سے کرتے ہیں۔ سیکھتے رہیں، آپ جتنا زیادہ سمجھیں گے، آپ کو بے وقوف بنانا اتنا ہی پرسکون اور مشکل ہوگا۔ جب آپ گہرائی میں جانے کے لیے تیار ہوتے ہیں، تکنیکی اور بنیادی تجزیہ، اختیارات، تاجروں کے لیے ازگر، یا الگورتھمک ٹریڈنگ، OpenAlgo کے دوسرے مفت کورسز کا انتظار کیا جاتا ہے۔ <strong>/learn</strong>.</p>\n<p>مارکیٹ میں خوش آمدید۔ اب آپ ابتدائی نہیں ہیں، آپ ایک باخبر سرمایہ کار ہیں۔ صبر سے سرمایہ کاری کریں، اپنے آپ کو سختی سے بچائیں، اور سالوں کو اپنے حق میں جمع ہونے دیں۔</p>\n","toc":[{"level":2,"text":"دی بگ بل: ہرشد مہتا (1992)","id":"the-big-bull-harshad-mehta-1992"},{"level":2,"text":"پینٹافور بل: کیتن پاریکھ (2000 کی دہائی کے اوائل)","id":"the-pentafour-bull-ketan-parekh-early-2000s"},{"level":2,"text":"انڈیاز اینرون: ستیم (2009)","id":"india-s-enron-satyam-2009"},{"level":2,"text":"جب پلمبنگ ناکام ہوجاتی ہے: NSEL اور کاروی","id":"when-the-plumbing-fails-nsel-and-karvy"},{"level":2,"text":"نیا کھیل کا میدان: گھوٹالے آپ کو آج ملیں گے۔","id":"the-new-playground-scams-you-ll-actually-meet-today"},{"level":3,"text":"واٹس ایپ اور ٹیلیگرام پر پمپ اینڈ ڈمپ","id":"pump-and-dump-on-whatsapp-and-telegram"},{"level":3,"text":"فن فلوینسر اور جعلی \"ٹپس\"","id":"finfluencers-and-fake-tips"},{"level":3,"text":"اپنے مشیروں کو جانیں: RA، RIA، اور جعلی","id":"know-your-advisers-ra-ria-and-the-fakes"},{"level":3,"text":"جعلی ایپس اور گارنٹیڈ ریٹرن پونزی اسکیمیں","id":"fake-apps-and-guaranteed-return-ponzi-schemes"},{"level":3,"text":"ڈبہ تجارت","id":"dabba-trading"},{"level":2,"text":"سرخ جھنڈے وہ سب شیئر کرتے ہیں۔","id":"the-red-flags-they-all-share"},{"level":2,"text":"آپ کی حفاظتی چیک لسٹ","id":"your-protection-checklist"},{"level":2,"text":"یہاں سے کہاں جانا ہے۔","id":"where-to-go-from-here"}],"imgCount":5,"hasContent":true}}
